const FT_CAT = { infra: ["インフラ基盤", "Infrastructure"], data: ["データ基盤", "Data platform"], ml: ["機械学習基盤", "ML platform"] };
const FT_CLOUD_COL = { "AWS": "#D8A94E", "Google Cloud": "#5FD3C2", "Azure": "#7B9FE0" };
const ftPct = (n, d) => (d ? Math.round((n / d) * 100) : 0);
// 109件のうち実際にAI・LLM・エージェントに触れているのは一部。カテゴリ（機械学習基盤=13件）では
// 取りこぼすため、本文・構成要素・タグ全体を見て別軸のフラグとして持つ。
const FT_AI_RE = /Bedrock|Vertex|OpenAI|Gemini|Claude|\bLLM\b|生成AI|エージェント|RAG|SageMaker|Langfuse|LangChain|LangGraph|\bMCP\b|推論|機械学習|Dify|Azure OpenAI/;
// 同じ企業が手書きセクション（III/IV/V）と109件エクスプローラの両方に出るため、
// どちらを見ているのか読み手が分かるように相互参照を持つ。社名は表記ゆれを吸収して突合する。
const ftNormOrg = (v) => String(v || "").replace(/株式会社|\（株\）|ホールディングス|テクノロジーズ|アジャイル開発センター|[\s・「」（）()]/g, "").toLowerCase();
const FT_XREF = (() => {
  const m = {};
  const add = (name, ja, en) => {
    const k = ftNormOrg(name);
    if (k.length < 2) return;
    (m[k] = m[k] || []).push([ja, en]);
  };
  try {
    (ARCH_AG || []).forEach((x) => add(x.n[0], "III. AIエージェントの実装事例（構成図つき）", "III. Agent systems (with diagram)"));
    (ARCH_OFC || []).forEach((x) => add(x.n[0], "IV. クラウド公式事例（一次情報）", "IV. Cloud vendor case (first-party)"));
    (ARCH_CASES || []).forEach((x) => add((x.org && x.org[0]) || x.n[0], "V. その他の公開事例", "V. Other public cases"));
  } catch (e) {}
  return m;
})();
const ftXrefFor = (org) => {
  const k = ftNormOrg(org);
  if (!k) return [];
  const out = [];
  Object.keys(FT_XREF).forEach((key) => {
    if (key && (key.indexOf(k) >= 0 || k.indexOf(key) >= 0)) FT_XREF[key].forEach((v) => { if (!out.some((o) => o[0] === v[0])) out.push(v); });
  });
  return out;
};
const FT_AI = (() => {
  const set = new Set();
  FT_ARCH.forEach((c, i) => {
    const blob = [c.pu, c.f || "", (c.t || []).join(" "), (c.n || []).join(" "), (c.ch || []).join(" "),
      c.L.map(([, ts]) => ts.join(" ")).join(" ")].join(" ");
    if (FT_AI_RE.test(blob)) set.add(i);
  });
  return set;
})();
const FT_AWS_RE = /^Amazon|^AWS|Aurora|DynamoDB|CloudFront|Fargate|\bECS\b|\bEKS\b|Lambda|Athena|Redshift|\bS3\b|Step Functions|EventBridge|CloudWatch|ElastiCache|OpenSearch Service|\bSQS\b|\bSNS\b|Glue|Kinesis|\bRDS\b|Route ?53|\bWAF\b|Bedrock|SageMaker|Cognito|\bECR\b|GuardDuty/;
const FT_GCP_RE = /^Google|^Cloud |BigQuery|\bGKE\b|\bGCS\b|Firebase|Vertex|Looker|Pub\/Sub|Dataflow|Dataproc|Dataform|Spanner|AlloyDB|Bigtable|Firestore|Gemini|Datastream|Composer|Memorystore|Workflows/;
const ftCloudOf = (t) => (/^Azure|Entra|^Microsoft/.test(t) ? "Azure" : FT_AWS_RE.test(t) ? "AWS" : FT_GCP_RE.test(t) ? "Google Cloud" : null);

function FtBar({ n, total, color, label, sub, en }) {
  const pct = ftPct(n, total);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 5 }}>
      <span style={{ fontSize: 11, color: C.text, flexShrink: 0, width: 128, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{label}</span>
      <div style={{ flex: 1, height: 9, background: C.bg, borderRadius: 5, overflow: "hidden", minWidth: 40 }}>
        <div style={{ width: `${pct}%`, height: "100%", background: color || C.teal, borderRadius: 5 }} />
      </div>
      <span style={{ fontSize: 10.5, color: C.muted, flexShrink: 0, width: 74, textAlign: "right" }}>{sub || (en ? `${n} · ${pct}%` : `${n}件・${pct}%`)}</span>
    </div>
  );
}

const FT_SRC_NOTE = [
  "出典：findy-tools.io に各社が公開したアーキテクチャ記事と、各社エンジニアが実名の職種つきで投稿したツールレビュー（2026年9月収集）。各件に出典リンクを付けてあるので、数字が気になったら原典に当たれる。件数・比率はすべて掲載データの集計値であり、日本のSaaS市場全体の統計ではない — 「この媒体に載せた企業の中では」という限定つきで読む。",
  "Source: architecture write-ups published by each company on findy-tools.io, plus tool reviews posted there by named engineers with their roles (collected September 2026). Every entry carries its source link, so any number here can be taken back to the original. Every count and share here is tallied from that published set — it is not a statistic about the Japanese SaaS market as a whole, and should be read as 'among the companies that published here'.",
];

function FtSrcNote({ en, extra }) {
  return (
    <div style={{ fontSize: 10.5, color: C.dim, lineHeight: 1.6, marginTop: 8, borderTop: `1px solid ${C.line}`, paddingTop: 6 }}>
      {FT_SRC_NOTE[en ? 1 : 0]}{extra ? ` ${extra}` : ""}
    </div>
  );
}

// ---------- VII. measured statistics ----------
function FtStatsBoard({ en }) {
  const [layer, setLayer] = useState(FT_STAT.layers.reduce((a, b) => (b.n > a.n ? b : a), FT_STAT.layers[0]).k);
  const N = FT_META.nArch;
  const cur = FT_STAT.layers.find((l) => l.k === layer) || FT_STAT.layers[0];
  const maxTop = cur.top.length ? cur.top[0][1] : 1;
  const catRow = (key) => {
    const b = FT_STAT.byCat[key];
    if (!b) return null;
    const order = ["AWS", "Google Cloud", "Azure"];
    return (
      <div key={key} style={{ background: C.surface2, borderRadius: 10, padding: "10px 12px" }}>
        <div style={{ fontSize: 12, fontWeight: 800, color: C.gold, marginBottom: 2 }}>{FT_CAT[key][en ? 1 : 0]}</div>
        <div style={{ fontSize: 10.5, color: C.dim, marginBottom: 6 }}>{en ? `${b.n} architectures` : `${b.n}件`}</div>
        {order.filter((c) => b.c[c]).map((c) => (
          <FtBar key={c} n={b.c[c]} total={b.n} color={FT_CLOUD_COL[c]} label={c} sub={`${b.c[c]}/${b.n}`} />
        ))}
      </div>
    );
  };
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en
          ? `What ${N} real production architectures at Japanese companies actually run on, counted layer by layer. These are not vendor reference diagrams — each one was written up by an engineer at the company, with the stack named. The value of this page is that you can answer 'what do teams like ours usually pick?' with a number instead of an impression.`
          : `日本企業の本番アーキテクチャ${N}件が実際に何で動いているかを、層ごとに数えたもの。ベンダーの参考構成図ではなく、各社のエンジニア自身が構成を名指しで書いたもの。ここの価値は「同じような会社はふつう何を選ぶのか」に、印象でなく数字で答えられること。`}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,250px),1fr))", gap: 10, marginBottom: 12 }}>
        <div style={{ background: C.surface2, borderRadius: 10, padding: "10px 12px" }}>
          <div style={{ fontSize: 12, fontWeight: 800, color: C.teal, marginBottom: 6 }}>{en ? `Cloud presence (of ${N})` : `クラウドの登場率（${N}件中）`}</div>
          {["AWS", "Google Cloud", "Azure"].map((c) => (
            <FtBar key={c} n={FT_STAT.cloud[c] || 0} total={N} color={FT_CLOUD_COL[c]} label={c} en={en} />
          ))}
          <div style={{ fontSize: 10.5, color: C.dim, lineHeight: 1.6, marginTop: 6 }}>
            {en ? "Shares exceed 100% because one architecture can use several clouds." : "1つの構成が複数クラウドを使うため合計は100%を超える。"}
          </div>
        </div>
        <div style={{ background: C.surface2, borderRadius: 10, padding: "10px 12px" }}>
          <div style={{ fontSize: 12, fontWeight: 800, color: C.teal, marginBottom: 6 }}>{en ? "Combination actually used" : "実際の組み合わせ"}</div>
          {FT_STAT.combo.slice(0, 6).map(([k, n]) => (
            <FtBar key={k} n={n} total={N} color={k.includes("+") ? C.wine : C.muted} label={thEn(k, en)} en={en} />
          ))}
        </div>
      </div>
      <div style={{ ...DGM_DETAIL, marginTop: 0, marginBottom: 12 }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 4 }}>{en ? "The one finding worth carrying into a meeting" : "商談に持っていく価値のある発見はこれ"}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>
          {en
            ? `Infrastructure skews AWS (${FT_STAT.byCat.infra.c["AWS"]} of ${FT_STAT.byCat.infra.n}) while data platforms skew Google Cloud (${FT_STAT.byCat.data.c["Google Cloud"]} of ${FT_STAT.byCat.data.n}) — and ${FT_STAT.combo.find((r) => r[0] === "AWS + Google Cloud")?.[1] || 0} architectures run both. "Which cloud are you on?" is therefore the wrong question; "where does the application run, and where does the analysis run?" is the one that gets a useful answer.`
            : `インフラはAWSに寄り（${FT_STAT.byCat.infra.n}件中${FT_STAT.byCat.infra.c["AWS"]}件）、データ基盤はGoogle Cloudに寄る（${FT_STAT.byCat.data.n}件中${FT_STAT.byCat.data.c["Google Cloud"]}件）。そして${FT_STAT.combo.find((r) => r[0] === "AWS + Google Cloud")?.[1] || 0}件は両方を併用している。つまり「どのクラウドですか」は問いとして粗い。「アプリはどこで動いていて、分析はどこでやっていますか」と分けて聞くと、返ってくる答えが有用になる。`}
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,200px),1fr))", gap: 10, marginBottom: 12 }}>
        {["infra", "data", "ml"].map(catRow)}
      </div>
      <div style={{ fontSize: 12, fontWeight: 800, color: C.teal, marginBottom: 6 }}>{en ? "By layer — what sits there most often" : "層ごと — そこに入っているものの頻度"}</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 9 }}>
        {FT_STAT.layers.map((l) => (
          <button key={l.k} onClick={() => setLayer(l.k)}
            style={{ background: layer === l.k ? C.gold : C.surface2, color: layer === l.k ? "#1a1204" : C.muted, border: `1px solid ${layer === l.k ? C.gold : C.line}`, borderRadius: 999, padding: "4px 11px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>
            {l[en ? "en" : "ja"]}<span style={{ opacity: 0.7, marginLeft: 5 }}>{l.n}</span>
          </button>
        ))}
      </div>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
        <div style={{ fontSize: 11.5, color: C.muted, marginBottom: 7 }}>
          {en ? `${cur.en} — appears in ${cur.n} of ${N} architectures. Bars show how many architectures name each component.` : `${cur.ja} — ${N}件中${cur.n}件に登場。棒は、その要素を名指ししているアーキテクチャの件数。`}
        </div>
        {cur.top.map(([t, n]) => (
          <FtBar key={t} n={n} total={maxTop} color={FT_CLOUD_COL[ftCloudOf(t)] || C.muted} label={t} sub={en ? `${n} cases` : `${n}件`} />
        ))}
      </div>
      <FtSrcNote en={en} />
    </div>
  );
}

// ---------- VIII. 109-case explorer ----------
function FtArchExplorer({ en }) {
  const [cat, setCat] = useState("all");
  const [cloud, setCloud] = useState("all");
  const [aiOnly, setAiOnly] = useState(false);
  const [q, setQ] = useState("");
  const [sel, setSel] = useState(0);
  const list = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return FT_ARCH.map((a, i) => ({ a, i })).filter(({ a, i }) => {
      if (aiOnly && !FT_AI.has(i)) return false;
      if (cat !== "all" && a.c !== cat) return false;
      if (cloud === "multi" && a.cl.length < 2) return false;
      if (cloud !== "all" && cloud !== "multi" && !a.cl.includes(cloud)) return false;
      if (!needle) return true;
      const hay = [a.o, a.p, a.pu, (a.t || []).join(" "), a.L.map(([, ts]) => ts.join(" ")).join(" ")].join(" ").toLowerCase();
      return hay.includes(needle);
    });
  }, [cat, cloud, q, aiOnly]);
  const cur = list.find(({ i }) => i === sel) || list[0];
  const c = cur ? cur.a : null;
  const curIdx = cur ? cur.i : -1;
  const chip = (active, on, label, key) => (
    <button key={key} onClick={on}
      style={{ background: active ? C.wine : C.surface2, color: active ? "#fff" : C.muted, border: `1px solid ${active ? C.wine : C.line}`, borderRadius: 999, padding: "4px 11px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>{label}</button>
  );
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 9 }}>
        {en
          ? `All ${FT_META.nArch} architectures, filterable. Each entry shows the stack by layer as the company published it, the flow where they described one, the reasons they gave for the choices, and what they say is still unsolved. Case text stays in Japanese — it is quoted from the original write-ups rather than machine-translated.`
          : `${FT_META.nArch}件すべてを絞り込んで見る。各件、公開されたままの層別構成、フローが書かれていればその流れ、選定理由として挙げられた言葉、そして「まだ解けていない」と書かれている課題を並べてある。`}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 6 }}>
        {chip(cat === "all", () => setCat("all"), en ? "All types" : "全種別", "c-all")}
        {Object.keys(FT_CAT).map((k) => chip(cat === k, () => setCat(k), FT_CAT[k][en ? 1 : 0], `c-${k}`))}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 6 }}>
        {chip(cloud === "all", () => setCloud("all"), en ? "Any cloud" : "全クラウド", "k-all")}
        {["AWS", "Google Cloud", "Azure"].map((k) => chip(cloud === k, () => setCloud(k), k, `k-${k}`))}
        {chip(cloud === "multi", () => setCloud("multi"), en ? "Multi-cloud" : "複数併用", "k-multi")}
        <button onClick={() => setAiOnly((v) => !v)}
          style={{ background: aiOnly ? C.teal : C.surface2, color: aiOnly ? "#0d1a18" : C.muted, border: `1px solid ${aiOnly ? C.teal : C.line}`, borderRadius: 999, padding: "4px 11px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>
          {en ? `AI / agent only (${FT_AI.size})` : `AI・エージェント関連のみ（${FT_AI.size}）`}
        </button>
      </div>
      <input value={q} onChange={(e) => setQ(e.target.value)} aria-label={en ? "Search company, product, tag or component (e.g. BigQuery, Fargate, IoT)" : "会社・プロダクト・タグ・構成要素で検索（例: BigQuery、Fargate、IoT）"} placeholder={en ? "Search company, product, tag or component (e.g. BigQuery, Fargate, IoT)" : "会社・プロダクト・タグ・構成要素で検索（例: BigQuery、Fargate、IoT）"}
        style={{ width: "100%", boxSizing: "border-box", background: C.surface, border: `1px solid ${C.line}`, borderRadius: 8, color: C.text, fontSize: 12, padding: "7px 11px", marginBottom: 8 }} />
      <div style={{ fontSize: 11, color: C.dim, marginBottom: 6 }}>
        {en ? `${list.length} of ${FT_META.nArch} match` : `${FT_META.nArch}件中 ${list.length}件が該当`}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 10, maxHeight: 148, overflowY: "auto" }}>
        {list.map(({ a, i }) => (
          <button key={i} onClick={() => setSel(i)}
            style={{ background: curIdx === i ? C.gold : C.surface, color: curIdx === i ? "#1a1204" : C.muted, border: `1px solid ${curIdx === i ? C.gold : C.line}`, borderRadius: 7, padding: "4px 9px", fontSize: 10.5, fontWeight: 700, cursor: "pointer", maxWidth: 230, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {a.p || a.o}
          </button>
        ))}
      </div>
      {!c ? (
        <div style={{ fontSize: 12, color: C.dim, padding: "14px 0" }}>{en ? "Nothing matches those filters." : "該当する事例がありません。"}</div>
      ) : (
        <div style={{ background: C.surface2, borderRadius: 10, padding: "12px 14px" }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap", marginBottom: 3 }}>
            <span style={{ fontSize: 14, fontWeight: 800, color: C.text }}>{c.p || c.o}</span>
            <span style={{ fontSize: 11.5, color: C.muted }}>{c.o}</span>
            <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: 0.6, color: "#1a1204", background: C.gold, borderRadius: 999, padding: "2px 8px" }}>{FT_CAT[c.c][en ? 1 : 0]}</span>
            {c.cl.map((k) => (
              <span key={k} style={{ fontSize: 9, fontWeight: 800, color: FT_CLOUD_COL[k] || C.muted, border: `1px solid ${FT_CLOUD_COL[k] || C.line}`, borderRadius: 999, padding: "2px 8px" }}>{k}</span>
            ))}
          </div>
          {c.pu ? <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7, marginBottom: 9 }}>{c.pu}</div> : null}
          {ftXrefFor(c.o).length ? (
            <div style={{ fontSize: 11, color: C.gold, lineHeight: 1.6, marginBottom: 9, borderLeft: `3px solid ${C.gold}`, paddingLeft: 9 }}>
              {en ? "This organization is also covered, in more depth, in " : "この企業は "}
              {ftXrefFor(c.o).map((v) => v[en ? 1 : 0]).join(en ? " / " : " / ")}
              {en ? "." : " でも扱っています（別の切り口・別の深さ。同じシステムとは限りません）"}
            </div>
          ) : null}
          <div style={{ fontSize: 11, fontWeight: 800, color: C.teal, marginBottom: 5 }}>{en ? "Stack by layer" : "層別の構成"}</div>
          <div style={{ marginBottom: 9 }}>
            {c.L.map(([k, ts]) => (
              <div key={k} style={{ display: "flex", gap: 8, alignItems: "flex-start", marginBottom: 4 }}>
                <span style={{ fontSize: 10, color: C.dim, flexShrink: 0, width: 96, paddingTop: 3, textAlign: "right" }}>{(FT_LAYER[k] || [k, k])[en ? 1 : 0]}</span>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 4, flex: 1, minWidth: 0 }}>
                  {ts.map((t, j) => (
                    <span key={j} style={{ fontSize: 10.5, color: C.text, background: C.surface, border: `1px solid ${C.line}`, borderRadius: 6, padding: "2px 7px" }}>{t}</span>
                  ))}
                </div>
              </div>
            ))}
          </div>
          {c.f ? (
            <div style={{ marginBottom: 9 }}>
              <div style={{ fontSize: 11, fontWeight: 800, color: C.teal, marginBottom: 3 }}>{en ? "Flow (as described)" : "データの流れ（記載どおり）"}</div>
              <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.7 }}>{c.f}</div>
            </div>
          ) : (
            <div style={{ fontSize: 11, color: C.dim, marginBottom: 9 }}>{en ? "No flow described — components only. The arrows are left undrawn rather than guessed." : "フローの記述なし（構成要素の列挙のみ）。矢印は推測せず引いていない。"}</div>
          )}
          {c.n.length ? (
            <div style={{ marginBottom: 9 }}>
              <div style={{ fontSize: 11, fontWeight: 800, color: C.gold, marginBottom: 3 }}>{en ? "Stated reasons for the choices" : "選定理由として書かれていること"}</div>
              {c.n.map((s, j) => (
                <div key={j} style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.65, marginBottom: 2 }}>・{s}</div>
              ))}
            </div>
          ) : null}
          {c.ch.length ? (
            <div style={{ marginBottom: 9, borderLeft: `3px solid ${C.wine}`, paddingLeft: 9 }}>
              <div style={{ fontSize: 11, fontWeight: 800, color: C.wineInk, marginBottom: 3 }}>{en ? "What they say is still unsolved" : "まだ解けていないと書かれていること"}</div>
              {c.ch.map((s, j) => (
                <div key={j} style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.65, marginBottom: 2 }}>・{s}</div>
              ))}
            </div>
          ) : null}
          <div style={{ display: "flex", flexWrap: "wrap", gap: 4, alignItems: "center" }}>
            {(c.t || []).map((t, j) => (
              <span key={j} style={{ fontSize: 9.5, color: C.dim, border: `1px solid ${C.line}`, borderRadius: 999, padding: "1px 7px" }}>{t}</span>
            ))}
            <a href={c.u} target="_blank" rel="noreferrer" style={{ marginLeft: "auto", fontSize: 10.5, color: C.teal, textDecoration: "underline" }}>{en ? "source ↗" : "出典を開く ↗"}</a>
          </div>
        </div>
      )}
      <FtSrcNote en={en} />
    </div>
  );
}

// ---------- IX. decision forks ----------
function FtForkBoard({ en }) {
  const max = FT_FORK.length ? FT_FORK[0][2] : 1;
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en
          ? `Across ${FT_META.nRev} tool reviews, teams named what else they evaluated before choosing. That pairing is more useful than any ranking: it tells you which products actually sit on the same shortlist, so when a client says "we're looking at X" you already know what Y and Z they are weighing it against — and can ask about the trade-off rather than the brand.`
          : `${FT_META.nRev}件のツールレビューには「何と比較したか」が書かれている。この対が、順位表よりずっと役に立つ。同じ検討リストに実際に並ぶ製品が分かるので、顧客が「Xを見ている」と言った瞬間に、YとZとの間で何を天秤にかけているところかが読める。ブランドでなくトレードオフの話ができる。`}
      </div>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
        <div style={{ display: "flex", gap: 8, fontSize: 10, color: C.dim, fontWeight: 800, marginBottom: 6, letterSpacing: 0.5 }}>
          <span style={{ width: 150, flexShrink: 0 }}>{en ? "CHOSE" : "選んだ方"}</span>
          <span style={{ width: 150, flexShrink: 0 }}>{en ? "EVALUATED AGAINST" : "比較した相手"}</span>
          <span style={{ flex: 1 }}>{en ? "TIMES" : "件数"}</span>
        </div>
        {FT_FORK.slice(0, 24).map(([a, b, n], i) => (
          <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 4 }}>
            <span style={{ width: 150, flexShrink: 0, fontSize: 11.5, fontWeight: 700, color: C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a}</span>
            <span style={{ width: 150, flexShrink: 0, fontSize: 11.5, color: C.muted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{b}</span>
            <div style={{ flex: 1, height: 8, background: C.bg, borderRadius: 4, overflow: "hidden", minWidth: 30 }}>
              <div style={{ width: `${ftPct(n, max)}%`, height: "100%", background: C.gold }} />
            </div>
            <span style={{ fontSize: 10.5, color: C.muted, width: 26, textAlign: "right", flexShrink: 0 }}>{n}</span>
          </div>
        ))}
      </div>
      <div style={{ ...DGM_DETAIL }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 4 }}>{en ? "Reading the table" : "この表の読み方"}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>
          {en
            ? "Pairs that appear in both directions — Datadog against New Relic and New Relic against Datadog — mark a genuinely contested choice where the decision turns on the client's own situation, not on which is better. A one-directional pair marks a default and its challenger. Neither tells you which to recommend; both tell you which conversation to prepare for."
            : "両方向に出てくる対（DatadogとNew Relic、その逆も）は、優劣でなく相手の事情で決まる本当の競合。片方向だけの対は、既定の選択肢とその挑戦者という関係。どちらも「どれを薦めるべきか」は教えてくれないが、「どの会話の準備をすべきか」を教えてくれる。"}
        </div>
      </div>
      <FtSrcNote en={en} />
    </div>
  );
}

// ---------- X. post-adoption pitfalls ----------
