// ---------- 本番系が抱える宿題：事例109件が自分で書いた未解決課題の横断 ----------
// セクションXが「買ったツールへの不満」なのに対し、こちらは「動いている本番系の宿題」。
// 集計は FT_ARCH の ch（各社が記事中で未解決と書いた項目）からその場で計算する。
const FT_OPEN_THEMES = [
  ["運用負荷・工数", "Operating effort", /運用|保守|工数|オペレーション/],
  ["移行・技術負債", "Migration & debt", /移行|レガシー|負債|老朽|リプレ|再構築/],
  ["コスト", "Cost", /コスト|費用|料金|課金/],
  ["スケール・性能", "Scale & performance", /スケール|負荷|性能|遅延|レイテンシ|パフォーマンス|上限/],
  ["データ品質・整合", "Data quality", /品質|精度|不整合|欠損|重複|鮮度/],
  ["ガバナンス・権限", "Governance & access", /ガバナンス|権限|セキュリ|統制|監査|コンプラ/],
  ["属人化・体制", "Key-person & org", /属人|人材|体制|スキル|教育|採用/],
  ["可観測性・監視", "Observability", /監視|可観測|オブザーバ|トレース|アラート/],
  ["自動化・省力化", "Automation", /自動化|手作業|手動|効率化/],
];
const FT_OPEN = (() => {
  const rows = FT_OPEN_THEMES.map(([ja, en, re]) => {
    const hits = [];
    FT_ARCH.forEach((c, i) => {
      const qs = (c.ch || []).filter((t) => re.test(t));
      if (qs.length) hits.push({ i, qs });
    });
    return { ja, en, n: hits.length, hits };
  }).filter((r) => r.n > 0).sort((a, b) => b.n - a.n);
  const withCh = FT_ARCH.filter((c) => (c.ch || []).length).length;
  const total = FT_ARCH.reduce((s, c) => s + (c.ch || []).length, 0);
  return { rows, withCh, total };
})();

function FtOpenProblems({ en }) {
  const [sel, setSel] = useState(FT_OPEN.rows.length ? FT_OPEN.rows[0].ja : null);
  const cur = FT_OPEN.rows.find((r) => r.ja === sel) || FT_OPEN.rows[0];
  const max = FT_OPEN.rows.length ? FT_OPEN.rows[0].n : 1;
  if (!cur) return null;
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en
          ? `Section X counts complaints about tools people bought. This one counts something different and more useful: what ${FT_OPEN.withCh} of the ${FT_META.nArch} architectures say is still unsolved in a system that is already running in production — ${FT_OPEN.total} stated items in total. Tool complaints tell you what to watch in a purchase; these tell you what the client's engineers are living with right now, which is the better opening question in a first meeting.`
          : `セクションXが数えているのは「買ったツールへの不満」。こちらはそれとは別物で、より使える — ${FT_META.nArch}件のうち${FT_OPEN.withCh}件が、すでに本番で動いているシステムについて「まだ解けていない」と書いた項目、計${FT_OPEN.total}件の集計。ツールの不満は購買時の注意点を教えるが、こちらは相手のエンジニアが今まさに抱えているものを教える。初回面談の問いとしては、後者の方が効く。`}
      </div>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px", marginBottom: 12 }}>
        <div style={{ fontSize: 12, fontWeight: 800, color: C.wineInk, marginBottom: 7 }}>
          {en ? `Themes across ${FT_OPEN.withCh} architectures that state an open problem` : `未解決課題を書いた${FT_OPEN.withCh}件のテーマ分布`}
        </div>
        {FT_OPEN.rows.map((r) => (
          <div key={r.ja} onClick={() => setSel(r.ja)} style={{ cursor: "pointer" }}>
            <FtBar n={r.n} total={max} color={sel === r.ja ? C.gold : C.wine} label={r[en ? "en" : "ja"]} sub={en ? `${r.n} cases` : `${r.n}件`} />
          </div>
        ))}
        <div style={{ fontSize: 10.5, color: C.dim, lineHeight: 1.6, marginTop: 6 }}>
          {en ? "Keyword match over the stated problems, so one architecture can land in several themes. Click a bar to read the actual sentences." : "課題文のキーワード一致で数えているため、1件が複数テーマに入ることがある。棒をクリックすると原文が読める。"}
        </div>
      </div>
      <div style={{ fontSize: 12, fontWeight: 800, color: C.teal, marginBottom: 7 }}>
        {en ? `"${cur.en}" — in their own words (${cur.n})` : `「${cur.ja}」と書いている${cur.n}件 — 原文のまま`}
      </div>
      <div style={{ display: "grid", gap: 7 }}>
        {cur.hits.map(({ i, qs }) => {
          const c = FT_ARCH[i];
          return (
            <div key={i} style={{ background: C.surface2, borderRadius: 9, padding: "9px 12px" }}>
              <div style={{ display: "flex", alignItems: "baseline", gap: 7, flexWrap: "wrap", marginBottom: 3 }}>
                <span style={{ fontSize: 12, fontWeight: 800, color: C.text }}>{c.p || c.o}</span>
                <span style={{ fontSize: 10.5, color: C.muted }}>{c.o}</span>
                <span style={{ fontSize: 9, fontWeight: 800, color: "#1a1204", background: C.gold, borderRadius: 999, padding: "1px 7px" }}>{FT_CAT[c.c][en ? 1 : 0]}</span>
                <a href={c.u} target="_blank" rel="noreferrer" style={{ marginLeft: "auto", fontSize: 10, color: C.teal, textDecoration: "underline" }}>{en ? "source ↗" : "出典 ↗"}</a>
              </div>
              {qs.map((q, j) => (
                <div key={j} style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.65 }}>・{q}</div>
              ))}
            </div>
          );
        })}
      </div>
      <div style={{ ...DGM_DETAIL }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 4 }}>{en ? "How to use this in a first meeting" : "初回面談での使い方"}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>
          {en
            ? `These are not complaints about a vendor — they are the things a team wrote down about its own system, in public, knowing peers would read it. That makes them safe to raise: "teams that published their architecture most often name operating effort and migration debt as what is still open — where does yours sit?" invites a real answer, where "what are your challenges?" invites a rehearsed one.`
            : `これはベンダーへの不満ではなく、各チームが自分のシステムについて、同業が読むと分かったうえで公開の場に書いたもの。だから商談で振っても角が立たない。「構成を公開している会社で最も多い宿題は運用工数と移行負債でした。御社はどのあたりですか」は具体的な答えを引き出すが、「課題は何ですか」は用意された答えしか引き出さない。`}
        </div>
      </div>
      <FtSrcNote en={en} />
    </div>
  );
}

// ---------- 2社を並べて読む：同じ問題に対する違う答え ----------
// 「どの2社を並べると学びがあるか」もデータから決める。同じ種別・構成が部分的に重なり、
// かつ主要な層で採用が完全に割れているペアを、種別×層ごとに1組ずつ提案する。
const FT_CMP_ORDER = ["front", "api", "run", "queue", "store", "src", "etl", "dwh", "bi", "ml", "orch", "obs", "cicd", "auth", "net", "meta", "other"];
const ftTechSet = (c) => { const s = new Set(); c.L.forEach(([, ts]) => ts.forEach((t) => s.add(t))); return s; };
const ftLayerSet = (c, k) => { const r = c.L.find(([lk]) => lk === k); return new Set(r ? r[1] : []); };
const FT_CMP_SUGGEST = (() => {
  const HEAD = ["dwh", "store", "run", "obs", "etl", "bi", "ml"];
  const sets = FT_ARCH.map(ftTechSet);
  const best = {};
  for (let i = 0; i < FT_ARCH.length; i++) {
    for (let j = i + 1; j < FT_ARCH.length; j++) {
      const a = FT_ARCH[i], b = FT_ARCH[j];
      if (a.c !== b.c || !sets[i].size || !sets[j].size) continue;
      let shared = 0;
      sets[i].forEach((t) => { if (sets[j].has(t)) shared++; });
      if (shared < 2) continue;
      const union = sets[i].size + sets[j].size - shared;
      if (shared / union > 0.6) continue;
      HEAD.forEach((k) => {
        const la = ftLayerSet(a, k), lb = ftLayerSet(b, k);
        if (!la.size || !lb.size) return;
        let common = 0;
        la.forEach((t) => { if (lb.has(t)) common++; });
        if (common) return;
        const key = a.c + "/" + k;
        if (!best[key] || shared > best[key].shared) best[key] = { i, j, k, shared, cat: a.c };
      });
    }
  }
  return Object.values(best).sort((x, y) => (x.cat === y.cat ? y.shared - x.shared : x.cat < y.cat ? -1 : 1));
})();

function FtCompare({ en }) {
  const first = FT_CMP_SUGGEST.length ? FT_CMP_SUGGEST[0] : { i: 0, j: 1 };
  const [li, setLi] = useState(first.i);
  const [ri, setRi] = useState(first.j);
  const A = FT_ARCH[li], B = FT_ARCH[ri];
  const sa = ftTechSet(A), sb = ftTechSet(B);
  const shared = [...sa].filter((t) => sb.has(t));
  const onlyA = [...sa].filter((t) => !sb.has(t)).length;
  const onlyB = [...sb].filter((t) => !sa.has(t)).length;
  const layers = FT_CMP_ORDER.filter((k) => ftLayerSet(A, k).size || ftLayerSet(B, k).size);
  const sel = (val, set, label) => (
    <select value={val} onChange={(e) => set(Number(e.target.value))} aria-label={label}
      style={{ width: "100%", boxSizing: "border-box", background: C.surface, border: `1px solid ${C.line}`, color: C.text, fontSize: 11.5, padding: "6px 8px", borderRadius: 7 }}>
      {FT_ARCH.map((c, i) => (
        <option key={i} value={i}>{(c.p || c.o).slice(0, 38)}（{c.o.slice(0, 16)}）</option>
      ))}
    </select>
  );
  const head = (c, side) => (
    <div style={{ background: C.surface2, borderRadius: 9, padding: "9px 11px", minWidth: 0 }}>
      <div style={{ fontSize: 9, fontWeight: 800, letterSpacing: 1, color: side === "L" ? C.teal : C.gold, marginBottom: 3 }}>{side === "L" ? "A" : "B"}</div>
      <div style={{ fontSize: 12.5, fontWeight: 800, color: C.text, lineHeight: 1.4 }}>{c.p || c.o}</div>
      <div style={{ fontSize: 10.5, color: C.muted, marginBottom: 5 }}>{c.o}</div>
      <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 5 }}>
        <span style={{ fontSize: 9, fontWeight: 800, color: "#1a1204", background: C.gold, borderRadius: 999, padding: "1px 7px" }}>{FT_CAT[c.c][en ? 1 : 0]}</span>
        {c.cl.map((k) => <span key={k} style={{ fontSize: 9, fontWeight: 800, color: FT_CLOUD_COL[k] || C.muted, border: `1px solid ${FT_CLOUD_COL[k] || C.line}`, borderRadius: 999, padding: "1px 7px" }}>{k}</span>)}
      </div>
      <div style={{ fontSize: 11, color: C.muted, lineHeight: 1.65 }}>{c.pu}</div>
    </div>
  );
  const layerChips = (c, k, other) => {
    const mine = [...ftLayerSet(c, k)], theirs = ftLayerSet(other, k);
    if (!mine.length) return <span style={{ fontSize: 10.5, color: C.dim }}>{en ? "— not stated" : "— 記載なし"}</span>;
    return mine.map((t, i) => {
      const same = theirs.has(t);
      return <span key={i} style={{ fontSize: 10.5, color: same ? C.teal : C.text, background: C.surface, border: `1px solid ${same ? C.teal : C.line}`, borderRadius: 6, padding: "2px 7px", marginRight: 4, marginBottom: 4, display: "inline-block" }}>{t}</span>;
    });
  };
  const listBlock = (title, col, items) => (
    <div style={{ minWidth: 0 }}>
      <div style={{ fontSize: 10.5, fontWeight: 800, color: col, marginBottom: 3 }}>{title}</div>
      {items.length ? items.map((s, i) => <div key={i} style={{ fontSize: 11, color: C.muted, lineHeight: 1.6, marginBottom: 2 }}>・{s}</div>)
        : <div style={{ fontSize: 10.5, color: C.dim }}>{en ? "— not stated" : "— 記載なし"}</div>}
    </div>
  );
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en
          ? "Two companies with the same kind of platform, a stack that partly overlaps, and one layer where they chose completely differently. Reading a single case tells you what is possible; reading two tells you what the constraint was — because the difference has to be explained by something, and both sides wrote down their reasons."
          : "同じ種別の基盤を持ち、構成が部分的に重なり、ある層だけ選択が完全に割れている2社を並べる。1件だけ読むと「何ができるか」しか分からないが、2件並べると制約が見えてくる — 違いには理由があるはずで、その理由を両社とも自分で書いているからだ。"}
      </div>
      <div style={{ fontSize: 11.5, fontWeight: 800, color: C.gold, marginBottom: 5 }}>
        {en ? "Pairs worth reading — computed: same category, partial overlap, one layer fully divergent" : "読む価値のある対比 — 同種別・構成が部分的に重複・ある層だけ完全に割れている組をデータから抽出"}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginBottom: 10, maxHeight: 108, overflowY: "auto" }}>
        {FT_CMP_SUGGEST.map((s, n) => {
          const on = s.i === li && s.j === ri;
          return (
            <button key={n} onClick={() => { setLi(s.i); setRi(s.j); }}
              style={{ background: on ? C.gold : C.surface, color: on ? "#1a1204" : C.muted, border: `1px solid ${on ? C.gold : C.line}`, borderRadius: 7, padding: "4px 9px", fontSize: 10, fontWeight: 700, cursor: "pointer", maxWidth: 300, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              {FT_CAT[s.cat][en ? 1 : 0]}・{(FT_LAYER[s.k] || [s.k, s.k])[en ? 1 : 0]}が割れる： {(FT_ARCH[s.i].o || "").slice(0, 10)} ↔ {(FT_ARCH[s.j].o || "").slice(0, 10)}
            </button>
          );
        })}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 8 }}>
        {sel(li, setLi, "left case")}
        {sel(ri, setRi, "right case")}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 10 }}>
        {head(A, "L")}
        {head(B, "R")}
      </div>
      <div style={{ background: C.surface2, borderRadius: 9, padding: "8px 11px", marginBottom: 10, fontSize: 11.5, color: C.muted, lineHeight: 1.7 }}>
        <span style={{ color: C.teal, fontWeight: 800 }}>{en ? `${shared.length} shared` : `共通 ${shared.length} 要素`}</span>
        {" / "}{en ? `${onlyA} only in A` : `A のみ ${onlyA}`}{" / "}{en ? `${onlyB} only in B` : `B のみ ${onlyB}`}
        {shared.length ? <span style={{ color: C.dim }}>　{en ? "Shared: " : "共通: "}{shared.slice(0, 8).join("、")}{shared.length > 8 ? "…" : ""}</span> : null}
      </div>
      <div style={{ fontSize: 11.5, fontWeight: 800, color: C.teal, marginBottom: 5 }}>{en ? "Layer by layer — teal means both run it" : "層ごとの対比 — 枠が緑の要素は両社に共通"}</div>
      <div style={{ marginBottom: 10 }}>
        {layers.map((k) => (
          <div key={k} style={{ display: "grid", gridTemplateColumns: "84px 1fr 1fr", gap: 7, alignItems: "start", padding: "5px 0", borderTop: `1px solid ${C.line}` }}>
            <span style={{ fontSize: 10, color: C.dim, paddingTop: 3 }}>{(FT_LAYER[k] || [k, k])[en ? 1 : 0]}</span>
            <div style={{ minWidth: 0 }}>{layerChips(A, k, B)}</div>
            <div style={{ minWidth: 0 }}>{layerChips(B, k, A)}</div>
          </div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
        {listBlock(en ? "A — stated reasons" : "A の選定理由", C.gold, A.n)}
        {listBlock(en ? "B — stated reasons" : "B の選定理由", C.gold, B.n)}
        {listBlock(en ? "A — still unsolved" : "A の宿題", C.wine, A.ch)}
        {listBlock(en ? "B — still unsolved" : "B の宿題", C.wine, B.ch)}
      </div>
      <div style={{ display: "flex", gap: 12, marginBottom: 4 }}>
        <a href={A.u} target="_blank" rel="noreferrer" style={{ fontSize: 10.5, color: C.teal, textDecoration: "underline" }}>{en ? "A source ↗" : "A の出典 ↗"}</a>
        <a href={B.u} target="_blank" rel="noreferrer" style={{ fontSize: 10.5, color: C.teal, textDecoration: "underline" }}>{en ? "B source ↗" : "B の出典 ↗"}</a>
      </div>
      <div style={{ ...DGM_DETAIL }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 4 }}>{en ? "The question to ask while reading" : "読みながら立てる問い"}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>
          {en
            ? "Not which choice is better — both shipped. Ask what would have to be true for the other choice to be wrong for them: team size, data volume, the cloud they were already on, a compliance requirement, or simply who was on staff. That sentence is the reusable part; the product names are not."
            : "どちらが優れているかではない（どちらも本番で動いている）。問うべきは「相手の選択が自社にとって誤りになるには、何が真である必要があるか」— 人数、データ量、既に乗っているクラウド、コンプライアンス要件、あるいは単に誰がいたか。再利用できるのはその一文であって、製品名ではない。"}
        </div>
      </div>
      <FtSrcNote en={en} />
    </div>
  );
}

function TabArchCases() {
  const lang = useLang();
  const en = lang === "en";
  // 構成パターン図で選んだ層を、下の早見表でも強調する
  const [layer, setLayer] = useState("orch");
  return (
    <div>
      <SectionTitle jp="アーキテクチャ事例 — 構成図・使うツール・選定のポイント" en="Architecture Cases — diagrams, tooling, and the choices behind them" />
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 6 }}>
        {en ? "What a production generative-AI system actually looks like, layer by layer. Five reference patterns you can draw on a whiteboard in a meeting, the components that sit in each layer, the question that decides each choice, and the trap that follows the wrong one. The patterns are composites of how these systems are commonly built — not any one company's system; the public cases with named sources sit in their own section. Sections VII to XI are measured data: 109 production architectures at Japanese companies, 735 tool reviews and 27 cross-company articles, tallied. The point is to get past 'here is how it is usually built' to 'here is how it actually was built, and here is where it hurt afterwards'." : "本番の生成AIシステムが実際どう組まれているかを、層ごとに見る。商談のホワイトボードで描ける5つの構成パターン、各層に入る要素、選択を決める問い、外したときの落とし穴。パターンは一般的な組み方の合成であって特定企業の構成そのものではない — 出典つきの公開事例は別セクションに置く。後半（VII〜XI）は実測データで、日本企業の本番アーキテクチャ109件・ツールレビュー735件・横断記事27本を集計してある。「一般にはこう組む」で終わらせず、「実際にはこう組まれていて、導入後にここでつまずいている」まで見られるようにした。"}
      </div>
      <FoldSection title={en ? "I. ARCHITECTURE PATTERNS — five shapes and their layers" : "I. 構成パターン — 5つの型と7層の中身"} color={C.teal}>
        <ArchStackDiagram en={en} layer={layer} onLayer={setLayer} />
      </FoldSection>
      <FoldSection title={en ? "II. COMPONENT MAP — what sits in each layer" : "II. 構成ツール早見表 — 各層に何が入るか"} color={C.gold}>
        <ArchToolTable en={en} layer={layer} onLayer={setLayer} />
      </FoldSection>
      <FoldSection title={en ? "III. AGENT SYSTEMS — nine published architectures" : "III. AIエージェントの実装事例 — 構成図が公開されている9件"} color={C.gold}>
        <ArchAgentCases en={en} />
      </FoldSection>
      <FoldSection title={en ? "IV. CLOUD VENDORS' OWN CASE STUDIES — four Japanese systems, first-party sources" : "IV. クラウド公式事例 — 一次情報つきの日本企業4件"} color={C.gold}>
        <SourceLegend en={en} />
        <ArchOfficialCases en={en} />
      </FoldSection>
      <FoldSection title={en ? "V. OTHER PUBLIC CASES — layer coverage" : "V. その他の公開事例 — 層ごとの開示状況"} color={C.wine}>
        <ArchCaseExplorer en={en} />
      </FoldSection>
      <FoldSection title={en ? "VI. WHAT REPEATS ACROSS THE CASES" : "VI. 事例を横断して繰り返し現れるもの"} color={C.teal}>
        <ArchCrossAnalysis en={en} />
      </FoldSection>
      <FoldSection title={en ? `VII. MEASURED — how ${FT_META.nArch} real architectures were actually built` : `VII. 実測 — 実在する${FT_META.nArch}件は実際どう組まれているか`} color={C.teal}>
        <FtStatsBoard en={en} />
      </FoldSection>
      <FoldSection title={en ? `VIII. CASE EXPLORER — all ${FT_META.nArch}, filterable` : `VIII. 事例エクスプローラ — ${FT_META.nArch}件を絞り込む`} color={C.gold}>
        <FtArchExplorer en={en} />
      </FoldSection>
      <FoldSection title={en ? `IX. SIDE BY SIDE — ${FT_CMP_SUGGEST.length} pairs that answered the same problem differently` : `IX. 2社を並べて読む — 同じ問題に違う答えを出した${FT_CMP_SUGGEST.length}組`} color={C.teal}>
        <FtCompare en={en} />
      </FoldSection>
      <FoldSection title={en ? `X. DECISION FORKS — what ${FT_META.nRev} reviews compared against` : `X. 選定の分岐点 — ${FT_META.nRev}件のレビューが挙げた比較相手`} color={C.gold}>
        <FtForkBoard en={en} />
      </FoldSection>
      <FoldSection title={en ? "XI. AFTER ADOPTION — what is still broken, in their words" : "XI. 導入後 — まだ壊れているもの、現場の言葉で"} color={C.wine}>
        <FtPitfalls en={en} />
      </FoldSection>
      <FoldSection title={en ? "XII. STILL UNSOLVED — what production systems say is open" : "XII. 本番系の宿題 — 動いている側がまだ解けていないこと"} color={C.wine}>
        <FtOpenProblems en={en} />
      </FoldSection>
      <FoldSection title={en ? `XIII. CROSS-COMPANY DIGESTS — ${FT_META.nArt} feature articles` : `XIII. 横断記事の要点 — ${FT_META.nArt}本`} color={C.teal}>
        <FtArticles en={en} />
      </FoldSection>
      <FoldSection title={en ? "XIV. HOW TO USE THIS IN A MEETING" : "XIV. 商談での使い方"} color={C.wine}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,300px),1fr))", gap: 10 }}>
          {[
            { t: ["層で聞くと会話が進む", "Ask by layer"], d: ["「どのモデルを使っていますか」より「検索はどう権限を効かせていますか」「ログはどこに残していますか」の方が、相手の実装レベルが分かる。層ごとの問い（図の各層をクリック）はそのまま診断の質問票になる", "'How do you apply permissions at retrieval?' and 'where do the logs live?' reveal implementation maturity far better than 'which model?'. The per-layer questions double as an assessment checklist"] },
            { t: ["描いて確認する", "Draw it back"], d: ["相手の説明を聞きながらこの7層に落として描き、「この理解で合っていますか」と返す。埋まらない層が、そのまま提案の入口になる", "Sketch what they describe onto the seven layers and hand it back as 'is this right?'. The layers you cannot fill are the opening for the proposal"] },
            { t: ["パターン名で合意する", "Name the pattern"], d: ["「御社がやりたいのは社内ナレッジRAGですね、エージェント型ではなく」と型の名前で合意すると、スコープ議論が一段速くなる", "Agreeing on the pattern name — internal RAG, not an action-taking agent — speeds the scope conversation by a full step"] },
          ].map((m, i) => (
            <div key={i} style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
              <div style={{ fontSize: 12.5, fontWeight: 800, color: C.teal, marginBottom: 4 }}>{m.t[en ? 1 : 0]}</div>
              <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65 }}>{m.d[en ? 1 : 0]}</div>
            </div>
          ))}
        </div>
      </FoldSection>
    </div>
  );
}

