function XfOperatingModel({ en }) {
  const [sel, setSel] = useState(0);
  const m = XF_OM[sel];
  const COLS = ["#5FD3C2", "#D8A94E", "#8FA8E8", "#9A90B4", "#B84A5E", "#C2417E"];
  const POS = [[96, 40], [232, 40], [368, 40], [96, 112], [232, 112], [368, 112]];
  return (
    <div>
      <div style={{ ...DGM_WRAP, display: "flex", justifyContent: "center" }}>
        <svg viewBox="0 0 460 226" style={{ width: "100%", maxWidth: 480 }} role="img" aria-label={en ? "operating model elements" : "オペレーティングモデルの6要素"}>
          <rect x="82" y="26" width="374" height="132" rx="9" fill="none" stroke={C.line} strokeWidth="1.1" />
          <text x="90" y="20" fill={C.dim} fontSize="9" fontWeight="800">{en ? "operating model — change one and the rest move" : "オペレーティングモデル — どれか1つを変えると他も動く"}</text>
          <g><circle cx="42" cy="92" r="26" fill={C.surface} stroke={C.gold} strokeWidth="1.4" />
            <text x="42" y="89" textAnchor="middle" fill={C.gold} fontSize="8" fontWeight="800">{en ? "value" : "価値"}</text>
            <text x="42" y="100" textAnchor="middle" fill={C.dim} fontSize="7">{en ? "promise" : "提供価値"}</text></g>
          {XF_OM.map((x, i) => {
            const [px, py] = POS[i], on = sel === i;
            return (
              <g key={x.id} className="gh-node" onClick={() => setSel(i)} role="button" tabIndex={0}
                onKeyDown={(ev) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); setSel(i); } }}>
                <rect x={px - 52} y={py - 22} width="104" height="44" rx="7" fill={on ? COLS[i] : C.surface} fillOpacity={on ? 0.25 : 1} stroke={COLS[i]} strokeWidth={on ? 2.2 : 1.2} />
                <text x={px} y={py + 3} textAnchor="middle" fill={COLS[i]} fontSize="10" fontWeight="800">{x.t[en ? 1 : 0]}</text>
              </g>
            );
          })}
          <text x="269" y="178" textAnchor="middle" fill={C.dim} fontSize="8.5">{en ? "a design that changes only technology is not a transformation" : "テクノロジーだけを変えた設計は、変革ではなく置き換えにすぎない"}</text>
        </svg>
      </div>
      <div style={DGM_HINT}>{en ? "Click an element for what it covers and the question that tests it" : "各要素をクリックすると、扱う範囲と確認の問いが出ます"}</div>
      <div style={{ ...DGM_DETAIL, borderLeftColor: COLS[sel] }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: COLS[sel], marginBottom: 4 }}>{m.t[en ? 1 : 0]}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 5 }}>{m.d[en ? 1 : 0]}</div>
        <div style={{ fontSize: 12, color: C.teal, lineHeight: 1.6 }}>❓ {m.q[en ? 1 : 0]}</div>
      </div>
    </div>
  );
}
