  const nR = ranges.length > 1 ? ranges.length : 1;
  const bounds = (ri) => [ranges[ri].lo, ranges[ri].hi];
  const rangeKey = (ri) => `r:${ranges[ri].t}:${ranges[ri].j}`;
  useEffect(() => { setRange(nR > 1 ? 0 : -1); }, [filter]);
  const pool = useMemo(() => {
    let idx = base;
    if (nR > 1 && range >= 0 && range < nR) { const [lo, hi] = bounds(range); idx = base.slice(lo, hi); }
    if (order === "random" || filter === "WEAK") { const r = idx.slice(); for (let i = r.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [r[i], r[j]] = [r[j], r[i]]; } idx = r; }
    return idx;
  }, [base, range, order, nR]);
