          const special = k === "WEAK" || k === "REVIEW" || k === "PRESET";
          const cnt = k === "PRESET" ? preset.ids.length : k === "ALL" ? bank.length : k === "REVIEW" ? Object.keys(wrong).length : k === "WEAK" ? null : bank.filter(x => x.d === k).length;
          const dm = domains.find(d => d.id === k) || {};
