          const rg = nR > 1 && range >= 0 ? (() => { const [lo, hi] = bounds(range); return en ? ` / Q${lo + 1}–${hi}` : ` ／ ${lo + 1}〜${hi}問目`; })() : "";
          return (en ? "Selected: " : "現在の選択：") + th + rg + (en ? ` (${n} Q)` : `（${n}問）`);
