function BprRemoveSheet({ en }) {
  const KEY = "techhub_bpr_remove_v1";
  const [m, setM] = useState(() => bprLoad(KEY, {}));
  const set = (i, k) => { const n = { ...m }; if (n[i] === k) delete n[i]; else n[i] = k; setM(n); bprSave(KEY, n); };
  const cnt = (k) => Object.values(m).filter((v) => v === k).length;
  const done = Object.keys(m).length;
  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 8 }}>
        {en ? "Pick the process you are about to hire for, and mark each of the ten types it contains as remove, standardise or streamline. The sorting is yours — the video gives the ten types and the rule: don't post the job until the sort is done. Your marks stay in this browser."
            : "求人を出そうとしている業務を1つ思い浮かべ、10類型それぞれを「消す・標準化・効率化」に仕分けます。仕分けの判断はあなた自身のもの。動画が示すのは10類型と「仕分けが終わるまで求人を出さない」という順序です。入力はこのブラウザに保存されます。"}
      </div>
      <div style={{ display: "grid", gap: 6 }}>
        {BPR_REMOVE.map((r, i) => (
          <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", background: C.surface2, borderRadius: 8, padding: "7px 10px", borderLeft: `3px solid ${m[i] ? BPR_SORT.find((s) => s.k === m[i]).col : C.line}` }}>
            <span style={{ fontSize: 10.5, color: C.dim, width: 18 }}>{i + 1}</span>
            <span style={{ fontSize: 12.5, fontWeight: 700, flex: "1 1 140px" }}>{r[en ? 1 : 0]}</span>
            <span style={{ display: "flex", gap: 5 }}>
              {BPR_SORT.map((s) => (
                <button key={s.k} className="gh-btn" onClick={() => set(i, s.k)} aria-pressed={m[i] === s.k}
                  style={{ padding: "4px 10px", fontSize: 11.5, borderColor: m[i] === s.k ? s.col : C.line, color: m[i] === s.k ? s.col : C.muted, fontWeight: m[i] === s.k ? 800 : 400 }}>{s.t[en ? 1 : 0]}</button>
              ))}
            </span>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "center", marginTop: 10, fontSize: 12 }}>
        {BPR_SORT.map((s) => <span key={s.k} style={{ color: s.col, fontWeight: 800 }}>{s.t[en ? 1 : 0]} {cnt(s.k)}</span>)}
        <span style={{ color: C.dim }}>{en ? `sorted ${done}/10` : `仕分け済み ${done}/10`}</span>
        {done ? <button className="gh-btn" onClick={() => { setM({}); bprSave(KEY, {}); }} style={{ padding: "3px 10px", fontSize: 11 }}>{en ? "Clear" : "クリア"}</button> : null}
      </div>
      <div style={{ background: C.surface2, borderLeft: `3px solid ${done === 10 ? C.teal : C.gold}`, borderRadius: 8, padding: "9px 12px", fontSize: 12, color: C.text, fontWeight: 700, lineHeight: 1.65, marginTop: 10 }}>
        {done === 10
          ? (en ? "Sort complete. Remove what you marked first, standardise next, and only then decide whether the remaining volume still needs a hire — systems come last." : "仕分け完了。消すものから手を付け、次に標準化し、残った業務量で本当に採用が必要かを判断する。システム化は最後。")
          : (en ? "Not finished yet — per the video, hold the job ad until every type has been sorted." : "まだ途中。動画の順序では、すべての類型を仕分けるまで求人は出さない。")}
      </div>
      <div style={{ marginTop: 8 }}><BprRefs refs={[1]} en={en} /></div>
    </div>
  );
}

function BprSystemize({ en }) {
  const [q, setQ] = useState("hl");
  const [cost, setCost] = useState(3000);
  const [hrs, setHrs] = useState(30);
  const [wage, setWage] = useState(4000);
  const [mk, setMk] = useState(2);
  const [sv, setSv] = useState(10);
  const qq = BPR_QUAD.find((x) => x.k === q);
  const yearly = hrs * wage;
  const years = yearly > 0 ? (cost * 10000) / yearly : Infinity;
  const months = sv > 0 ? (mk * 3600) / sv : Infinity;
  const fmt = (v) => (isFinite(v) ? (v >= 100 ? Math.round(v).toLocaleString() : v.toFixed(1)) : "—");
  const num = (setter) => (e) => { const v = Number(e.target.value); setter(isFinite(v) && v >= 0 ? v : 0); };
  const inp = { width: 92, padding: "5px 8px", fontSize: 12.5 };
  const cell = (x) => {
    const on = q === x.k;
    return (
      <button key={x.k} className="gh-btn" onClick={() => setQ(x.k)} aria-pressed={on}
        style={{ minHeight: 74, padding: "8px 9px", textAlign: "left", borderColor: on ? x.col : C.line, background: on ? C.surface : C.surface2 }}>
        <div style={{ fontSize: 12, fontWeight: 800, color: x.col, lineHeight: 1.45 }}>{x.t[en ? 1 : 0]}</div>
        <div style={{ fontSize: 10, color: C.dim, marginTop: 3 }}>{(x.vol ? (en ? "high volume" : "件数 多") : (en ? "low volume" : "件数 少")) + " × " + (x.chg ? (en ? "changes often" : "変化・例外 多") : (en ? "stable" : "変化・例外 少"))}</div>
      </button>
    );
  };
  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 8 }}>
        {en ? "'Getting off Excel' is not the goal in itself. Place the process on two axes — how many cases, and how often it changes or throws exceptions — and only one corner earns a system."
            : "脱Excelそのものは正解ではない。件数と、変化・例外の多さの2軸に置くと、システム化してよいのは1象限だけになる。"}
      </div>
      <div style={{ fontSize: 10.5, color: C.dim, marginBottom: 5 }}>{en ? "Vertical: change / exceptions (more toward the top) · Horizontal: volume of cases (more toward the right)" : "縦：変化・例外の多さ（上ほど多い）／横：件数（右ほど多い）"}</div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6, maxWidth: 560 }}>
        {cell(BPR_QUAD[2])}{cell(BPR_QUAD[1])}
        {cell(BPR_QUAD[3])}{cell(BPR_QUAD[0])}
      </div>
      <div style={{ ...DGM_DETAIL, borderLeftColor: qq.col }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: qq.col, marginBottom: 4 }}>{qq.t[en ? 1 : 0]}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>{qq.d[en ? 1 : 0]}</div>
      </div>
      <div style={{ fontSize: 11, color: C.wineInk, fontWeight: 800, margin: "12px 0 6px" }}>{en ? "FOUR SYSTEM TRAPS" : "システム化の罠 4つ"}</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
        {BPR_TRAPS.map((x, i) => <span key={i} style={{ fontSize: 11.5, color: C.text, background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 999, padding: "3px 11px" }}>{x[en ? 1 : 0]}</span>)}
      </div>
      <div style={{ fontSize: 11.5, color: C.dim, lineHeight: 1.65, marginTop: 6 }}>
        {en ? "Speaker's rough figures: a system costs several million yen at minimum and tens of millions for a full build, plus monthly maintenance. One case kept a double ledger — tidied in Excel on the floor, then re-keyed into the system."
            : "話者の目安：システムは最低でも数百万円、本格開発で数千万円に加えて毎月の保守費。現場がExcelで整理してからシステムへ再入力する二重帳簿の事例もある。"}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,260px),1fr))", gap: 10, marginTop: 12 }}>
        <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
          <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 6 }}>{en ? "Payback in money" : "お金で見る回収年数"}</div>
          <div style={{ display: "grid", gap: 6, fontSize: 12 }}>
            <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Investment (¥10k)" : "投資額（万円）"}<input className="gh-input" type="number" min="0" value={cost} onChange={num(setCost)} style={inp} /></label>
            <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Hours saved / year" : "年間の削減時間"}<input className="gh-input" type="number" min="0" value={hrs} onChange={num(setHrs)} style={inp} /></label>
            <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Hourly cost (¥)" : "時給換算（円）"}<input className="gh-input" type="number" min="0" value={wage} onChange={num(setWage)} style={inp} /></label>
          </div>
          <div style={{ fontSize: 12, color: C.muted, marginTop: 8 }}>{en ? "Yearly value " : "年間効果 "}<b style={{ color: C.text }}>{(yearly / 10000).toLocaleString(undefined, { maximumFractionDigits: 1 })}{en ? " ×¥10k" : "万円"}</b></div>
          <div style={{ fontSize: 20, fontWeight: 800, color: years > 5 ? "#E27069" : C.teal, marginTop: 2 }}>{fmt(years)}<span style={{ fontSize: 12, marginLeft: 4 }}>{en ? "years to pay back" : "年で回収"}</span></div>
          <div style={{ fontSize: 10.5, color: C.dim, marginTop: 4, lineHeight: 1.55 }}>{en ? "Defaults are the example in video #53 (the speaker rounded it to about 250 years). Maintenance is not included." : "初期値は動画#53の例（話者は約250年と説明）。保守費は含めていない。"}</div>
          <button className="gh-btn" onClick={() => { setCost(3000); setHrs(30); setWage(4000); }} style={{ marginTop: 6, padding: "3px 10px", fontSize: 11 }}>{en ? "Reset to #53" : "#53の例に戻す"}</button>
        </div>
        <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
          <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 6 }}>{en ? "Payback in time" : "時間で見る回収期間"}</div>
          <div style={{ display: "grid", gap: 6, fontSize: 12 }}>
            <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Hours to build" : "作るのにかかる時間"}<input className="gh-input" type="number" min="0" value={mk} onChange={num(setMk)} style={inp} /></label>
            <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Seconds saved / month" : "毎月削減できる秒数"}<input className="gh-input" type="number" min="0" value={sv} onChange={num(setSv)} style={inp} /></label>
          </div>
          <div style={{ fontSize: 20, fontWeight: 800, color: months > 12 ? "#E27069" : C.teal, marginTop: 10 }}>{fmt(months)}<span style={{ fontSize: 12, marginLeft: 4 }}>{en ? "months to pay back" : "か月で回収"}</span></div>
          <div style={{ fontSize: 10.5, color: C.dim, marginTop: 4, lineHeight: 1.55 }}>{en ? "Defaults: a two-hour automation of a task that takes ten seconds a month — 720 months (video #23)." : "初期値：月10秒の作業を2時間かけて自動化すると720か月（動画#23）。"}</div>
          <button className="gh-btn" onClick={() => { setMk(2); setSv(10); }} style={{ marginTop: 6, padding: "3px 10px", fontSize: 11 }}>{en ? "Reset to #23" : "#23の例に戻す"}</button>
        </div>
      </div>
      <div style={{ marginTop: 8 }}><BprRefs refs={[48, 53, 23, 10]} en={en} /></div>
    </div>
  );
}

