          <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12, color: C.muted, lineHeight: 1.7 }}>{BPR_DECAY_CAUSE.map((x, i) => <li key={i}>{x[en ? 1 : 0]}</li>)}</ul>
