function BprKpi({ en }) {
  const [mode, setMode] = useState("new");
  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 8 }}>
        {en ? "Switch between the old and the new scorecard. 'Hours saved' on its own never reaches the P&L: a salary cannot be halved when 20 hours become 10."
            : "旧来のKPIと付け替え後を切り替えて比べます。削減時間だけでは損益に届かない。20時間が10時間に減っても給与は半減できない。"}
      </div>
      <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
        <button className="gh-btn" onClick={() => setMode("old")} aria-pressed={mode === "old"} style={{ padding: "4px 12px", fontSize: 11.5, borderColor: mode === "old" ? C.wine : C.line, color: mode === "old" ? C.wine : C.muted }}>{en ? "Before: hours saved" : "旧：削減時間"}</button>
        <button className="gh-btn" onClick={() => setMode("new")} aria-pressed={mode === "new"} style={{ padding: "4px 12px", fontSize: 11.5, borderColor: mode === "new" ? C.teal : C.line, color: mode === "new" ? C.teal : C.muted }}>{en ? "After: four columns added" : "新：4列を追加"}</button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,180px),1fr))", gap: 8 }}>
        <div style={{ background: C.surface2, borderRadius: 8, padding: "9px 11px", borderTop: `3px solid ${C.muted}` }}>
          <div style={{ fontSize: 12, fontWeight: 800, color: C.text }}>{en ? "Hours saved" : "削減時間"}</div>
          <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.6, marginTop: 3 }}>
            {mode === "old"
              ? (en ? "The only number reported. In the speaker's own firm, hundreds of hours were cut and the floor stayed just as busy." : "これだけを報告する。話者の自社では数百時間を削減しても現場の忙しさは変わらなかった。")
              : (en ? "Still reported — but no longer the only column." : "引き続き報告する。ただし唯一の列ではなくなる。")}
          </div>
        </div>
        {mode === "new" ? BPR_KPI_NEW.map((k, i) => (
          <div key={i} style={{ background: C.surface2, borderRadius: 8, padding: "9px 11px", borderTop: `3px solid ${C.teal}` }}>
            <div style={{ fontSize: 12, fontWeight: 800, color: C.teal }}>{k.t[en ? 1 : 0]}</div>
            <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.6, marginTop: 3 }}>{k.d[en ? 1 : 0]}</div>
          </div>
        )) : (
          <div style={{ background: C.surface2, borderRadius: 8, padding: "9px 11px", border: `1px dashed ${C.wine}`, fontSize: 11.5, color: C.wineInk, lineHeight: 1.6 }}>
            {en ? "Missing: where the time goes, who can take over, how fast decisions are made, whether the tool is used." : "欠けているもの：時間の行き先、担当を替われるか、判断の速さ、ツールが使われているか。"}
          </div>
        )}
      </div>
      <div style={{ fontSize: 12, color: C.text, lineHeight: 1.65, marginTop: 8 }}>
        <span style={{ color: C.teal, fontWeight: 800 }}>{en ? "Make it routine  " : "運用に落とす  "}</span>
        {en ? "Add the columns to the project KPI sheet, report them at the monthly meeting, and make post-launch verification a completion condition of every improvement project."
            : "改善プロジェクトのKPI表に列を加えて月次会議で報告させ、導入後の効果検証を案件の完了条件にする。"}
      </div>
      <div style={{ marginTop: 6 }}><BprRefs refs={[9, 29, 53, 2]} en={en} /></div>
    </div>
  );
}

function BprGates({ en }) {
  const KEY = "techhub_bpr_gates_v1";
  const [g, setG] = useState(() => bprLoad(KEY, {}));
  const tog = (k) => { const n = { ...g, [k]: !g[k] }; setG(n); bprSave(KEY, n); };
  const [recs, setRecs] = useState(20000);
  const [mins, setMins] = useState(10);
  const aOk = BPR_AGENT.every((_, i) => g["a" + i]);
  const oOk = BPR_OUTSRC.every((_, i) => g["o" + i]);
  const oN = BPR_OUTSRC.filter((_, i) => g["o" + i]).length;
  const full = (recs * mins) / 60;
  const top = full * 0.2;
  const num = (setter) => (e) => { const v = Number(e.target.value); setter(isFinite(v) && v >= 0 ? v : 0); };
  const inp = { width: 92, padding: "5px 8px", fontSize: 12.5 };
  const verdict = (ok, okT, ngT) => (
    <div style={{ marginTop: 8, fontSize: 12, fontWeight: 800, lineHeight: 1.6, color: ok ? C.teal : C.gold, background: C.surface, borderRadius: 8, padding: "7px 10px" }}>{ok ? okT : ngT}</div>
  );
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,300px),1fr))", gap: 10 }}>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.fore, marginBottom: 6 }}>{en ? "Is this process right for an AI agent?" : "AIエージェントに任せてよい業務か"}</div>
        <div style={{ display: "grid", gap: 5 }}>{BPR_AGENT.map((x, i) => <BprCheck key={i} on={!!g["a" + i]} onClick={() => tog("a" + i)} label={x[en ? 1 : 0]} col={C.fore} />)}</div>
        {verdict(aOk,
          en ? "All three met. Try the cheapest tier first (existing Copilot or Gemini), name who checks what, and have people check every case for the first two weeks." : "3条件を満たす。追加費用0の既存ツールから試し、人が確認する範囲と責任者を決め、最初の2週間は全件チェックする。",
          en ? "Not yet — pick another process from the inventory. Only 20–30% of agents are still running six months later (speaker's impression)." : "まだ条件を満たさない。棚卸しから別の業務を選ぶ。半年後も回っているのは2〜3割（話者体感）。")}
        <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.65, marginTop: 6 }}>
          {en ? "Second step, once all three are met: can the steps be fixed in advance? If yes, a workflow coded step by step, with an LLM making the judgement at each step, is enough. Use an agent that chooses its own steps only when you can show they cannot be fixed (the rule in the Architect Academy's reference architectures)."
            : "3条件を満たしたら2段目：手順を事前に固定できるか。固定できるなら、手順をコードで組み、各段の判断にLLMを使うワークフローで足りる。自分で手順を選ぶエージェントにするのは、固定できないと示せるときだけ（AIアーキテクト道場の参照アーキテクチャと同じ基準）。"}
        </div>
        <div style={{ marginTop: 6 }}><BprRefs refs={[10]} en={en} /></div>
      </div>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold, marginBottom: 6 }}>{en ? "Five conditions to clear before outsourcing" : "外注の前に社内で潰す5条件"}</div>
        <div style={{ display: "grid", gap: 5 }}>{BPR_OUTSRC.map((x, i) => <BprCheck key={i} on={!!g["o" + i]} onClick={() => tog("o" + i)} label={x[en ? 1 : 0]} col={C.gold} />)}</div>
        {verdict(oOk,
          en ? "All five cleared — move to choosing how much to hand out. Then agree a sample deliverable, the weekly meeting and how monthly hours are spent, in writing, outside the contract." : "5条件クリア。どこまで外に出すかの判断へ。発注時は契約とは別に、成果物サンプル・週次定例・月間工数の使途を書面で合意する。",
          en ? `${oN}/5 cleared. Per the video, hold the order while any condition is open.` : `${oN}/5。未完の条件が残るうちは発注を止める（動画の提案）。`)}
        <div style={{ fontSize: 11, color: C.dim, lineHeight: 1.6, marginTop: 6 }}>
          {en ? "Fixed-deliverable contracts are responsible for the output; time-and-materials contracts only for the hours worked — consulting is usually the latter." : "請負は成果物に責任を負い、準委任は稼働（人月）に責任を負う。コンサルは成果物を事前に定義できず準委任が基本。"}
        </div>
        <div style={{ marginTop: 6 }}><BprRefs refs={[3, 32]} en={en} /></div>
      </div>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px" }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: C.teal, marginBottom: 6 }}>{en ? "Estimate the master-data effort" : "マスター整備の工数を見積もる"}</div>
        <div style={{ display: "grid", gap: 6, fontSize: 12 }}>
          <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Records" : "マスター件数"}<input className="gh-input" type="number" min="0" value={recs} onChange={num(setRecs)} style={inp} /></label>
          <label style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>{en ? "Minutes per record" : "1件あたりの分数"}<input className="gh-input" type="number" min="0" value={mins} onChange={num(setMins)} style={inp} /></label>
        </div>
        <div style={{ fontSize: 12, color: C.muted, marginTop: 8, lineHeight: 1.7 }}>
          {en ? "All records " : "全件 "}<b style={{ color: C.text }}>{Math.round(full).toLocaleString()}{en ? " h" : "時間"}</b>
          {en ? ` — at one hour a day (240 h/yr), ${(full / 240).toFixed(1)} years` : `（1日1時間＝年240時間なら ${(full / 240).toFixed(1)} 年）`}
        </div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>
          {en ? "Top 20% by frequency " : "頻度上位2割に絞ると "}<b style={{ color: C.teal }}>{Math.round(top).toLocaleString()}{en ? " h" : "時間"}</b>
          {en ? ` — ${(top / 240).toFixed(1)} years` : `（${(top / 240).toFixed(1)} 年）`}
        </div>
        <div style={{ fontSize: 10.5, color: C.dim, marginTop: 6, lineHeight: 1.55 }}>
          {en ? "Inputs are your own. For reference, one project with tens of thousands of records took about 5,000 hours (video #52). Don't hand this to the floor without adjusting their targets." : "入力値はあなたの想定。参考：数万件規模で約5,000時間かかったプロジェクトがある（動画#52）。現場のノルマを調整せずに丸投げしない。"}
        </div>
        <div style={{ marginTop: 6 }}><BprRefs refs={[52]} en={en} /></div>
      </div>
    </div>
  );
}

function BprCross({ en }) {
  const [open, setOpen] = useState(null);
  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 8 }}>
        {en ? "The eight shifts the digest author drew across all 53 videos (Japanese only, as in the source). Open one for the evidence, the implication and the videos behind it."
            : "ダイジェスト作成者が53本を横断して抽出した8つの論点。開くとエビデンス・示唆・根拠動画が出ます。"}
      </div>
      <div style={{ display: "grid", gap: 6 }}>
        {BPR_CROSS.map((x, i) => {
          const on = open === i;
          const m = x.t.match(/^【(.+?)】(.*)$/);
          return (
            <div key={i} style={{ background: C.surface2, borderRadius: 8, border: `1px solid ${on ? C.gold : C.line}` }}>
              <button onClick={() => setOpen(on ? null : i)} aria-expanded={on}
                style={{ all: "unset", cursor: "pointer", display: "flex", gap: 10, alignItems: "baseline", padding: "9px 12px", width: "calc(100% - 24px)" }}>
                <span style={{ fontSize: 10.5, color: C.gold, fontWeight: 800, flexShrink: 0 }}>{m ? m[1] : ""}</span>
                <span style={{ fontSize: 12.5, color: C.text, fontWeight: 700, lineHeight: 1.55, flex: 1 }}>{m ? m[2] : x.t}</span>
                <span style={{ fontSize: 11, color: C.dim }}>{on ? "▲" : "▼"}</span>
              </button>
              {on ? (
                <div style={{ padding: "0 12px 10px", fontSize: 12, lineHeight: 1.75 }}>
                  <div style={{ color: C.muted, marginBottom: 6 }}><span style={{ color: C.text, fontWeight: 700 }}>{en ? "Evidence  " : "エビデンス  "}</span>{x.e}</div>
                  <div style={{ color: C.muted, marginBottom: 6 }}><span style={{ color: C.wineInk, fontWeight: 700 }}>{en ? "Implication  " : "示唆  "}</span>{x.a}</div>
                  <BprRefs refs={x.refs} en={en} />
                </div>
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}

