// ============ ITセキュリティ基盤（広義） — AI固有でないセキュリティ・ガバナンスの基本概念 ============
// 出典: デジタル庁・IPA・総務省・NIST・Microsoft Learn・Google Cloud の公開資料（各概念の sources に取得確認済みURL）。
// AI固有の論点（AI利用規程・リスク階層・LLM脅威など）は「セキュリティ・ガバナンス道場」、こちらはその土台になる広義のIT。
const ITSEC_LAYERS = [
  { id: "endpoint", t: ["エンドポイント", "Endpoint"], d: ["PC・スマホ・サーバーそのものを守る", "Protect the devices themselves"], col: "#5FD3C2" },
  { id: "identity", t: ["ID・アクセス", "Identity & access"], d: ["誰が何にアクセスしてよいかを決める", "Decide who may reach what"], col: "#8FA2FF" },
  { id: "network", t: ["ネットワーク境界", "Network perimeter"], d: ["社内外の通信の出入口で守る", "Guard the doors in and out"], col: "#D8A94E" },
  { id: "sase", t: ["クラウドアクセス・SASE", "Cloud access & SASE"], d: ["場所を問わずクラウド経由で守る", "Protect from the cloud, wherever users are"], col: "#E28C4E" },
  { id: "cloud", t: ["クラウド基盤", "Cloud platform"], d: ["IaaS/PaaS の設定と稼働を守る", "Secure cloud configuration and workloads"], col: "#72BA88" },
  { id: "data", t: ["データ保護", "Data protection"], d: ["情報そのものの持ち出し・改ざん・消失を防ぐ", "Stop leaks, tampering and loss of the data itself"], col: "#C27BD6" },
  { id: "ops", t: ["監視・運用", "Detection & operations"], d: ["検知し、調べ、対応する", "Detect, investigate, respond"], col: "#B84A5E" },
  { id: "framework", t: ["ガバナンス・フレームワーク", "Governance frameworks"], d: ["全体を管理する考え方と認証・基準", "Models, standards and certifications"], col: "#9A90B4" },
];
const ITSEC_SPLIT = [
  { t: ["AI固有のセキュリティ・ガバナンス", "AI-specific security & governance"], col: C.gold,
    where: ["道場・リサーチ › セキュリティ・ガバナンス道場（AI利用規程・リスク階層化・SoA と第三者審査・LLM脅威と統制・インシデント対応・業種横断）／実務論点マップの「AIセキュリティ」", "Dojo & Research › Security & Governance Dojo; the AI-security corpus in the Practice Issue Map"],
    eg: ["プロンプトインジェクション、学習データ・出力の権利、モデルのリスク区分（EU AI Act 等）、AI利用ガイドライン", "Prompt injection, training-data and output rights, model risk tiers (EU AI Act), AI use policies"] },
  { t: ["広義のITセキュリティ・ガバナンス（このタブ）", "General IT security & governance (this tab)"], col: C.teal,
    where: ["道場・リサーチ › ITセキュリティ基盤", "Dojo & Research › IT Security Foundations"],
    eg: ["EDR・SWG・CASB・ZTNA・SASE・固定IP・SIEM・DLP・ISMS など、AIの有無に関係なく企業ITを守る仕組み", "EDR, SWG, CASB, ZTNA, SASE, static IPs, SIEM, DLP, ISMS — controls that protect enterprise IT with or without AI"] },
];

function ItSecCard({ c, en, open, onToggle, onJump }) {
  const L = ITSEC_LAYERS.find((l) => l.id === c.layer) || ITSEC_LAYERS[0];
  const row = (label, text, col) => text ? (
    <div style={{ fontSize: 12, lineHeight: 1.75, color: C.muted, marginTop: 6 }}><span style={{ color: col || C.text, fontWeight: 700 }}>{label}　</span>{text}</div>
  ) : null;
  return (
    <div id={"itsec-" + c.id} style={{ background: C.surface2, borderRadius: 10, borderLeft: `3px solid ${L.col}`, padding: "10px 13px", border: open ? `1px solid ${L.col}` : `1px solid ${C.line}` }}>
      <button onClick={onToggle} aria-expanded={open} style={{ all: "unset", cursor: "pointer", display: "block", width: "100%" }}>
        <div style={{ display: "flex", gap: 8, alignItems: "baseline", flexWrap: "wrap" }}>
          <span style={{ fontSize: 14, fontWeight: 800, color: C.text }}>{itL(c, "name", en)}</span>
          {c.full ? <span style={{ fontSize: 11, color: C.dim }}>{itL(c, "full", en)}</span> : null}
          <span style={{ marginLeft: "auto", fontSize: 11, color: C.dim }}>{open ? "▲" : "▼"}</span>
        </div>
        <div style={{ fontSize: 12.5, color: C.text, lineHeight: 1.7, marginTop: 4 }}>{itL(c, "def", en)}</div>
      </button>
      {open ? (
        <div>
          {row(en ? "How it works" : "仕組み", itL(c, "how", en), L.col)}
          {row(en ? "vs. similar" : "似た概念との違い", itL(c, "diff", en), C.gold)}
          {row(en ? "With AI" : "AI導入との接点", itL(c, "ai", en), C.teal)}
          {c.related && c.related.length ? (
            <div style={{ display: "flex", gap: 5, flexWrap: "wrap", alignItems: "center", marginTop: 8 }}>
              <span style={{ fontSize: 10.5, color: C.dim }}>{en ? "Related" : "関連"}</span>
              {c.related.map((r) => {
                const t = ITSEC.find((x) => x.id === r);
                return t ? <button key={r} className="gh-btn" onClick={() => onJump(r)} style={{ padding: "1px 9px", fontSize: 11 }}>{itL(t, "name", en)}</button> : null;
              })}
            </div>
          ) : null}
          <div style={{ marginTop: 8, display: "grid", gap: 3 }}>
            {(c.sources || []).map((s, i) => (
              <a key={i} href={s.url} target="_blank" rel="noopener noreferrer" style={{ fontSize: 11, color: C.teal, textDecoration: "none", wordBreak: "break-all" }}>↗ {s.t}（{s.pub}）</a>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

function ItSecGlossary({ en, initLayer = "ALL", initOpen = null }) {
  const [layer, setLayer] = useState(initLayer);
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(initOpen ? { [initOpen]: true } : {});
  useEffect(() => { if (initOpen) { const el = document.getElementById("itsec-" + initOpen); if (el) el.scrollIntoView({ block: "center" }); } }, []);
  const list = ITSEC.filter((c) => (layer === "ALL" || c.layer === layer) &&
    (!q.trim() || [c.name, c.full, c.def, c.how, c.diff, c.ai, c.nameEn, c.fullEn, c.defEn, c.howEn, c.diffEn, c.aiEn].filter(Boolean).join(" ").toLowerCase().includes(q.trim().toLowerCase())));
  const jump = (id) => {
    const c = ITSEC.find((x) => x.id === id); if (!c) return;
    setLayer("ALL"); setQ(""); setOpen((o) => ({ ...o, [id]: true }));
    setTimeout(() => { const el = document.getElementById("itsec-" + id); if (el) el.scrollIntoView({ behavior: "smooth", block: "center" }); }, 60);
  };
  return (
    <div>
      <div style={{ fontSize: 11, color: C.dim, marginBottom: 6 }}>{en ? "LAYERS — tap to filter (outside in: devices → people → network → cloud → data → operations → governance)" : "層 — 押すと絞り込み（外側の端末から、人・ネットワーク・クラウド・データ・運用・統治の順）"}</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(46%,170px),1fr))", gap: 6, marginBottom: 10 }}>
        <button className="gh-btn" onClick={() => setLayer("ALL")} aria-pressed={layer === "ALL"} style={{ textAlign: "left", borderColor: layer === "ALL" ? C.text : C.line }}>
          <div style={{ fontSize: 12.5, fontWeight: 800 }}>{en ? "All layers" : "すべて"}</div>
          <div style={{ fontSize: 10.5, color: C.dim }}>{ITSEC.length}{en ? " concepts" : "概念"}</div>
        </button>
        {ITSEC_LAYERS.map((l) => {
          const n = ITSEC.filter((c) => c.layer === l.id).length;
          if (!n) return null;
          return (
            <button key={l.id} className="gh-btn" onClick={() => setLayer(l.id)} aria-pressed={layer === l.id}
              style={{ textAlign: "left", borderLeft: `3px solid ${l.col}`, borderColor: layer === l.id ? l.col : C.line, background: layer === l.id ? C.surface : C.surface2 }}>
              <div style={{ fontSize: 12.5, fontWeight: 800, color: layer === l.id ? l.col : C.text }}>{l.t[en ? 1 : 0]} <span style={{ fontSize: 10.5, color: C.dim, fontWeight: 400 }}>{n}</span></div>
              <div style={{ fontSize: 10.5, color: C.dim, lineHeight: 1.5 }}>{l.d[en ? 1 : 0]}</div>
            </button>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", marginBottom: 10 }}>
        <input className="gh-input" value={q} onChange={(e) => setQ(e.target.value)} aria-label={en ? "search (e.g. EDR, 固定IP, CASB)" : "検索（例：EDR、固定IP、CASB）"} placeholder={en ? "search (e.g. EDR, 固定IP, CASB)" : "検索（例：EDR、固定IP、CASB）"} style={{ flex: "1 1 220px" }} />
        <span style={{ fontSize: 11, color: C.muted }}>{list.length}{en ? " shown" : "件"}</span>
        <button className="gh-btn" onClick={() => setOpen(Object.fromEntries(list.map((c) => [c.id, true])))} style={{ padding: "4px 10px", fontSize: 11 }}>{en ? "Expand all" : "すべて開く"}</button>
        <button className="gh-btn" onClick={() => setOpen({})} style={{ padding: "4px 10px", fontSize: 11 }}>{en ? "Collapse" : "閉じる"}</button>
      </div>
      <div style={{ display: "grid", gap: 7 }}>
        {list.map((c) => <ItSecCard key={c.id} c={c} en={en} open={!!open[c.id]} onToggle={() => setOpen((o) => ({ ...o, [c.id]: !o[c.id] }))} onJump={jump} />)}
      </div>
      <div style={{ fontSize: 11, color: C.dim, lineHeight: 1.7, marginTop: 14 }}>
        {en ? "Definitions are paraphrased from the linked public sources; product pages are cited only as examples. Concept names are kept as used in practice. English text is a translation of the Japanese entries."
            : "定義・仕組みはリンク先の公開資料の記載を言い換えたもので、製品ページは例として引用している。"}
      </div>
    </div>
  );
}
// 判定演習の問題（ITSEC の各概念だけを根拠に作成。d は層 IT1〜IT8）
const ITSEC_BANK = [
  {d: "IT1", q: "ランサムウェアが端末に入り込むこと自体を防ぎたい。端末上の振る舞い監視とクラウドの機械学習で脅威を検出・遮断する仕組みは？", qEn: "You want to stop ransomware from getting onto endpoints in the first place. Which mechanism detects and blocks threats using on-device behavior monitoring and cloud machine learning?", o: ["EDR（侵入を前提に、侵入後の検知と封じ込めを担う）", "EPP（端末で脅威を検出・遮断し、侵入を防ぐ）", "MDM（端末を登録・設定し、紛失時に遠隔で消去する）", "MDR（専門アナリストが検知と対応の運用を代行する）"], oEn: ["EDR (assumes a breach and handles post-intrusion detection and containment)", "EPP (detects and blocks threats on the endpoint to prevent intrusion)", "MDM (enrolls and configures devices and remotely wipes them when lost)", "MDR (specialist analysts run detection and response on your behalf)"], a: 1, e: "EPPは端末上の振る舞いとクラウドの機械学習で、侵入そのものを防ぐ。EDRは侵入後の検知と封じ込め、MDMは端末管理、MDRは運用代行で役割が違う。", eEn: "EPP prevents intrusion itself using on-device behavior and cloud ML. EDR handles post-intrusion detection, MDM manages devices, and MDR is an operations service."},
  {d: "IT1", q: "EPPとEDRの役割分担として正しいのは？", qEn: "Which correctly describes the division of roles between EPP and EDR?", o: ["EPPは侵入後の検知と封じ込め、EDRは侵入の防止を主に担う", "EPPは端末だけを見るが、EDRはID・メール・アプリの信号まで相関させる", "EPPは製品、EDRは専門アナリストが運用を代行するサービスである", "EPPは侵入の防止、EDRは侵入後の検知と対処を主に担う"], oEn: ["EPP mainly detects and contains after intrusion; EDR mainly prevents intrusion", "EPP looks only at endpoints, while EDR correlates signals from identity, email and apps", "EPP is a product, while EDR is a service in which specialist analysts operate on your behalf", "EPP mainly prevents intrusion; EDR mainly detects and responds after intrusion"], a: 3, e: "EPPは侵入そのものを防ぐ側、EDRは侵入後の検知と対処を担う側。複数領域の相関はXDR、運用代行はMDRの特徴で、EDRではない。", eEn: "EPP is on the prevention side; EDR handles detection and response after intrusion. Cross-domain correlation is XDR and operations outsourcing is MDR, not EDR."},
  {d: "IT1", q: "生成AIのローカルエージェントが動く端末の防御について、EPPの考え方として正しいのは？", qEn: "For endpoints running local generative-AI agents, which view of EPP is correct?", o: ["エージェントの動作ループを監視して攻撃をブロックする機能があり、AIを動かす端末の防御もEPPの対象になる", "端末上で動くAIエージェントはEPPの対象外で、守る対象はクラウド側のAIサービスとその接続先に限られ、端末側の防御は利用者の注意に任せる", "AIエージェントへの攻撃は、MDMの紛失時消去機能で止めるのが基本である", "管理者権限をPAMで絞れば、AIを動かす端末の振る舞い監視は不要になる"], oEn: ["It can block attacks by monitoring the agent's action loop, so endpoints that run AI are also in EPP's scope", "AI agents running on endpoints are out of EPP's scope; only cloud-side AI services and their connection targets need protection, leaving endpoint defense to user care", "Attacks on AI agents are basically stopped by the remote-wipe feature of MDM", "If admin rights are restricted with PAM, behavior monitoring on AI endpoints is no longer needed"], a: 0, e: "次世代保護には、ローカルAIエージェントへの攻撃を動作ループの監視でブロックする機能がある。AIを動かす端末もEPPの対象で、他の仕組みで代替できない。", eEn: "Next-generation protection can block attacks on local AI agents by monitoring their action loop. AI endpoints are in scope, and other mechanisms cannot replace this."},
  {d: "IT1", q: "端末の挙動に特化して継続的にデータを集め、侵入されることを前提に侵入後の検知と封じ込めを担う仕組みは？", qEn: "Which mechanism focuses on endpoint behavior, continuously collects data, and, assuming a breach, handles post-intrusion detection and containment?", o: ["EPP", "XDR", "MDM／UEM", "EDR"], oEn: ["EPP", "XDR", "MDM/UEM", "EDR"], a: 3, e: "EDRは端末の挙動データを集め、侵入後の検知と封じ込めを担う。EPPは侵入の防止、XDRはID・メール等へ領域を広げた統合防御、MDM／UEMは端末管理。", eEn: "EDR collects endpoint behavior data for post-intrusion detection and containment. EPP prevents, XDR extends across identity and email, and MDM/UEM manages devices."},
  {d: "IT1", q: "Microsoft Defender for Endpointの例で、EDRが同じ攻撃手法や同一攻撃者の警告を扱う方法として正しいのは？", qEn: "In the Microsoft Defender for Endpoint example, how does EDR handle alerts from the same attack technique or the same attacker?", o: ["警告ごとに別案件として扱い、過去30日分のデータだけを調べて、端末の隔離は行わない", "警告を受けたらまずMDMで端末を初期化し、その後の調査は行わない", "ファイルの実行を許可リストで限定し、侵入前の防止に専念する", "一つのインシデントにまとめ、6か月分のデータを遡って調べ、端末の隔離などで対処する"], oEn: ["It treats each alert as a separate case, checks only the past 30 days of data, and does not isolate devices", "On an alert it first resets the device through MDM and performs no further investigation", "It limits file execution with an allow list and focuses on prevention before intrusion", "It groups them into one incident, looks back through six months of data, and responds by, for example, isolating the device"], a: 3, e: "例ではEDRが関連する警告を一つのインシデントに統合し、6か月分を遡って調べ、端末の隔離で対処する。事後の調査と封じ込めがEDRの役割である。", eEn: "In the example, EDR merges related alerts into one incident, investigates six months back, and responds by isolating devices. Post-intrusion investigation and containment is EDR's role."},
  {d: "IT1", q: "生成AIの導入プロジェクトで、対象端末のEDRについて確認項目に入れるべきことは？", qEn: "In a generative-AI rollout project, what should be on the checklist regarding EDR on the target endpoints?", o: ["EDRは侵入前の防止専用の仕組みなので、AI導入では対象端末へのEPPの展開状況だけを確認すればよい", "不審な操作が実際に起きてから、対象端末へのEDR展開を検討すればよい", "対象端末にEDRが展開されているか。展開済みなら、AIツール経由の不審な操作を事後に追跡できる", "AIツール経由の操作は端末の挙動に現れないため、EDRの展開確認は不要である"], oEn: ["EDR is a mechanism only for prevention before intrusion, so confirming EPP deployment on the target endpoints is enough for AI adoption", "Deployment of EDR on the target endpoints can be considered after suspicious operations actually occur", "Whether EDR is deployed on the target endpoints; if so, suspicious operations via AI tools can be traced afterward", "Operations through AI tools do not appear in endpoint behavior, so confirming EDR deployment is unnecessary"], a: 2, e: "EDRは生成AIを使う端末の挙動を事後に追跡でき、不審な操作の調査材料になる。AI導入では対象端末へのEDR展開状況を確認項目に入れる。", eEn: "EDR can trace the behavior of endpoints that use generative AI after the fact, giving investigation material. Include EDR deployment status on target endpoints in the AI rollout checks."},
  {d: "IT1", q: "EDRとXDRの違いとして正しいのは？", qEn: "Which correctly describes the difference between EDR and XDR?", o: ["EDRは端末・ID・メールの信号を相関させて一つのインシデントにまとめ、XDRは端末の挙動だけに特化する", "EDRはツールだが、XDRは専門アナリストが運用を代行するサービスである", "EDRは端末の挙動に特化し、XDRはそこにID・メール・クラウドアプリの信号を足して相関させる", "XDRは組織全体のログを集めてアラートを出す仕組みで、EDRはその一機能である"], oEn: ["EDR correlates signals from endpoints, identity and email into one incident; XDR focuses only on endpoint behavior", "EDR is a tool, but XDR is a service in which specialist analysts operate on your behalf", "EDR focuses on endpoint behavior; XDR adds signals from identity, email and cloud apps and correlates them", "XDR collects logs across the whole organization and raises alerts, and EDR is one of its functions"], a: 2, e: "EDRは端末の挙動に特化し、XDRはID・メール・クラウドアプリの信号まで相関させる。運用代行はMDR、組織全体のログ収集はSIEMの特徴である。", eEn: "EDR specializes in endpoint behavior; XDR also correlates identity, email and cloud app signals. Operations outsourcing is MDR and organization-wide log collection is SIEM."},
  {d: "IT1", q: "SIEMとXDRの違いとして正しいのは？", qEn: "Which correctly describes the difference between SIEM and XDR?", o: ["SIEMは検知と対処まで一体で行い、XDRは組織全体のログを集めて分析しアラートを出すところまでを担う", "SIEMは組織全体のログを集めて分析しアラートを出し、XDRは各製品の検知と対処まで一体で行う", "SIEMは端末の挙動に特化し、XDRは組織全体のログを集めて分析する", "どちらも専門アナリストが検知と対応を代行するサービスの名称で、契約範囲だけが異なる"], oEn: ["SIEM integrates detection and response, while XDR covers only collecting, analyzing organization-wide logs and raising alerts", "SIEM collects and analyzes organization-wide logs and raises alerts, while XDR integrates detection and response across its products", "SIEM focuses on endpoint behavior, while XDR collects and analyzes logs across the organization", "Both are names of services where specialist analysts take over detection and response, differing only in contract scope"], a: 1, e: "SIEMは組織全体のログを集めて分析しアラートを出す。XDRは各製品の検知から対処までを一体で行う。どちらもサービス名ではなく、役割も逆ではない。", eEn: "SIEM gathers and analyzes organization-wide logs and raises alerts; XDR handles detection through response across its products. Neither is a service name, and the roles are not reversed."},
  {d: "IT1", q: "生成AIサービスに絡む不審なサインインと、同じ時間帯の端末の挙動を、製品をまたいで一画面で追って調べたい。まず当てるべき仕組みは？", qEn: "You want to trace a suspicious sign-in to a generative-AI service together with endpoint behavior in the same period, across products on a single screen. Which mechanism should you apply first?", o: ["XDR", "EPP", "MDM／UEM", "パッチ管理"], oEn: ["XDR", "EPP", "MDM/UEM", "Patch management"], a: 0, e: "XDRは端末・ID・クラウドアプリの信号を結び付け、侵入経路と影響を受けた資産を一画面で追える。EPPやMDMは単一領域、パッチ管理は更新の運用である。", eEn: "XDR ties together endpoint, identity and cloud-app signals and shows the entry path and affected assets in one view. EPP and MDM are single-domain; patching is an update operation."},
  {d: "IT1", q: "自社のSOCに人員が足りない。24時間体制でインシデントのキューを管理し、調査を代行してくれる選択肢は？", qEn: "Your own SOC is understaffed. Which option manages the incident queue around the clock and performs investigations for you?", o: ["EDR", "XDR", "EPP", "MDR"], oEn: ["EDR", "XDR", "EPP", "MDR"], a: 3, e: "MDRは専門アナリストが24時間でキューを管理し、調査を代行する運用サービス。EDR、XDR、EPPは検知・防御のツールで、人の運用は含まない。", eEn: "MDR is an operations service where analysts manage the queue 24/7 and investigate for you. EDR, XDR and EPP are tools and do not include human operations."},
  {d: "IT1", q: "MDRの説明として正しいのは？", qEn: "Which statement about MDR is correct?", o: ["EDRやXDRの上位互換にあたるツール製品で、導入すれば自社のSOCを置き換えて人員を減らせる", "侵害が起きた後のインシデント対応作業そのものまで、標準で含んでいる", "端末へのマルウェアの侵入を防ぐ、予防型の製品である", "EDRやXDRを使って人が運用するサービスで、顧客のSOCを置き換えるのではなく補う"], oEn: ["A tool product superior to EDR or XDR; once adopted, it replaces your own SOC and lets you cut staff", "It includes the incident response work itself after a breach as standard", "A preventive product that stops malware from entering endpoints", "A service in which people operate EDR or XDR; it complements the customer's SOC rather than replacing it"], a: 3, e: "MDRはEDR・XDRを使い人が運用するサービスで、SOCを補う位置づけ。侵害後のインシデント対応作業は含まず、別のサービスが用意されている。", eEn: "MDR is a service in which people run EDR/XDR, positioned to complement the SOC. Post-breach incident response work is not included and is offered as a separate service."},
  {d: "IT1", q: "生成AIの導入で監視対象が増えるため、MDRを契約する。契約前に確認すべきことは？", qEn: "Generative-AI adoption increases what must be monitored, so you plan to sign up for MDR. What should you confirm before contracting?", o: ["対象となる製品・ログの範囲と、自社との役割分担", "MDRは全ての他社製品のログを自動で対象にするため、対象範囲の確認は不要である", "専門アナリストが全てを引き受けるため、自社側の役割分担は決めなくてよい", "侵害後のインシデント対応作業も含まれるため、別の手配は確認しなくてよい"], oEn: ["The range of covered products and logs, and the division of roles with your own team", "MDR automatically covers all third-party product logs, so there is no need to check the scope", "Specialist analysts take on everything, so your side does not need to define a division of roles", "Post-breach incident response work is included, so no separate arrangement needs to be checked"], a: 0, e: "MDRは対象の製品・ログの範囲が決まっており、自社との役割分担も要る。侵害後の対応作業は含まれず別サービスのため、手配の確認が必要である。", eEn: "MDR has a defined scope of products and logs and needs a division of roles with you. Post-breach response is not included and is a separate service, so arrangements must be checked."},
  {d: "IT1", q: "私物端末（BYOD）で業務アプリを使わせる。退職時に、組織のデータだけを選択的に消去したい。向いているのは？", qEn: "Employees use business apps on personal devices (BYOD). At departure you want to wipe only the organization's data selectively. What fits?", o: ["MAM（業務アプリとその中のデータだけを管理する）", "MDM（端末全体を管理し、退職時は端末ごと初期化する）", "EDR（端末の挙動を監視して封じ込める）", "パッチ管理（更新プログラムを計画的に配布する）"], oEn: ["MAM (manages only business apps and the data inside them)", "MDM (manages the whole device and wipes it entirely at departure)", "EDR (monitors endpoint behavior and contains threats)", "Patch management (distributes updates in a planned way)"], a: 0, e: "MAMは業務アプリとその中のデータだけを管理し、私物端末向けに退職時の選択的消去ができる。MDMは端末全体の管理で、私物端末には広すぎる。", eEn: "MAM manages only business apps and their data and allows selective wipe at departure on personal devices. MDM manages the whole device, which is too broad for BYOD."},
  {d: "IT1", q: "MDMとMAMの違いとして正しいのは？", qEn: "Which correctly describes the difference between MDM and MAM?", o: ["MDMは業務アプリとその中のデータだけを管理し、MAMは端末全体を管理する", "MDMはモバイル端末だけが対象で、MAMはPCやサーバを含む全端末が対象である", "MDMは端末全体を管理し、MAMは業務アプリとその中のデータだけを管理する", "MDMは脆弱性の優先順位付けを行い、MAMは更新プログラムの配布を行う"], oEn: ["MDM manages only business apps and their data, while MAM manages the whole device", "MDM covers only mobile devices, while MAM covers all devices including PCs and servers", "MDM manages the whole device, while MAM manages only business apps and the data inside them", "MDM prioritizes vulnerabilities, while MAM distributes update programs"], a: 2, e: "MDMは端末全体、MAMは業務アプリとそのデータだけを管理する。MAMは私物端末向けで、脆弱性の優先順位付けや更新配布は別の運用である。", eEn: "MDM manages the whole device and MAM only business apps and their data. MAM suits personal devices; vulnerability prioritization and update distribution are separate operations."},
  {d: "IT1", q: "管理下の端末だけに業務データや生成AIサービスの利用を許したい。MDM／UEMとどの仕組みを連携させるか？", qEn: "You want to allow business data and generative-AI services only from managed devices. Which mechanism do you link with MDM/UEM?", o: ["端末の準拠状態をSCIMで生成AIサービスに渡し、準拠した端末の利用者のアカウントを自動で作成する", "PAMのジャストインタイムで、端末ごとに利用権限を一時的に付与する", "端末の準拠状態を条件付きアクセスに渡し、準拠しない端末からのアクセスを止める", "MFAの第2要素にSMSを使い、登録した端末からの利用だけを許可する"], oEn: ["Pass device compliance status to a generative-AI service via SCIM and automatically create accounts for users of compliant devices", "Use PAM just-in-time access to grant temporary usage rights per device", "Pass device compliance status to Conditional Access and block access from non-compliant devices", "Use SMS as the MFA second factor and allow use only from registered devices"], a: 2, e: "Intuneなどが端末の準拠状態を条件付きアクセスへ渡すと、準拠しない端末を止められる。SCIMはアカウント作成、PAMは特権の時間制限であり別の目的である。", eEn: "When Intune and similar tools pass compliance status to Conditional Access, non-compliant devices can be blocked. SCIM creates accounts and PAM time-limits privileges, which are different purposes."},
  {d: "IT1", q: "パッチ管理と脆弱性管理の違いとして正しいのは？", qEn: "Which correctly describes the difference between patch management and vulnerability management?", o: ["パッチ管理はどれを直すべきかを見つけて優先順位を付ける活動で、脆弱性管理は更新プログラムを当てる作業だけを指す", "パッチ管理は端末だけが対象で、脆弱性管理はサーバだけが対象である", "パッチ管理は更新を当てる作業、脆弱性管理はどれを直すべきかを見つけて優先順位を付ける作業を含む", "脆弱性管理は侵入後の検知と封じ込めを担い、パッチ管理は端末の紛失時の消去を担う"], oEn: ["Patch management is the activity of finding and prioritizing what to fix; vulnerability management means only applying update programs", "Patch management covers only endpoints, and vulnerability management covers only servers", "Patch management is applying updates; vulnerability management includes finding what to fix and prioritizing it", "Vulnerability management handles post-intrusion detection and containment, and patch management handles wiping lost devices"], a: 2, e: "パッチ管理は更新を当てる作業で、脆弱性管理は洗い出し・評価・優先順位付けまで含む広い活動。両者とも端末とサーバが対象で、検知や消去は別の仕組みである。", eEn: "Patch management is applying updates; vulnerability management is the broader activity including discovery, evaluation and prioritization. Both cover endpoints and servers; detection and wiping are other mechanisms."},
  {d: "IT1", q: "更新プログラムをすぐに当てられない端末がある。脆弱性管理の考え方として正しい対処は？", qEn: "Some endpoints cannot have updates applied right away. Which response fits the vulnerability management approach?", o: ["更新できる日まで、その端末は台帳から外して管理対象にしない", "EPPを入れてあれば、脆弱性の修正や緩和策は検討しなくてよい", "構成変更や脆弱なアプリのブロックなど、別の緩和策を取る", "端末をMDMで即時に初期化し、更新の問題を回避する"], oEn: ["Remove the endpoint from the inventory until it can be updated, so it is not managed", "If EPP is installed, there is no need to consider fixes or mitigations for the vulnerability", "Take other mitigations, such as configuration changes or blocking the vulnerable app", "Immediately reset the device via MDM to avoid the update problem"], a: 2, e: "更新を当てられないときは、構成変更や脆弱なアプリのブロックなど別の緩和策を取る。台帳から外すと管理の穴になり、EPPやMDMでは脆弱性は解消されない。", eEn: "When updates cannot be applied, take other mitigations such as configuration changes or blocking vulnerable apps. Dropping it from inventory leaves a gap, and EPP or MDM does not remove the vulnerability."},
  {d: "IT1", q: "生成AI関連のクライアントソフトやブラウザ拡張の扱いとして正しいのは？", qEn: "How should client software and browser extensions related to generative AI be handled?", o: ["ブラウザ拡張は端末にインストールするソフトに当たらないので、継続的な棚卸しの対象外とする", "AIサービス側が自動で更新するため、端末側の台帳への登録は不要である", "問題が報告されたものだけを台帳に登録し、それ以外は管理しない", "棚卸しの対象に入れ、台帳から漏らさない。それが更新漏れを防ぐ前提になる"], oEn: ["Browser extensions do not count as software installed on endpoints, so they are excluded from the continuous inventory", "The AI service updates automatically, so registering them in the endpoint register is unnecessary", "Register only items for which problems were reported and do not manage the rest", "Include them in the inventory so none is missed from the register; that is the prerequisite for avoiding missed updates"], a: 3, e: "AI導入で増える端末上のソフトやブラウザ拡張も継続的に棚卸しし、台帳から漏らさないことが更新漏れを防ぐ前提になる。拡張も棚卸しの対象である。", eEn: "Software and browser extensions added by AI adoption must also be inventoried continuously. Keeping them in the register is the prerequisite for avoiding missed updates."},
  {d: "IT1", q: "アンチウイルスが悪性と判定したものを止めるのではなく、許可したコードだけを動かす方針で端末を固めたい。当てるべき仕組みは？", qEn: "You want to lock down endpoints so that only approved code runs, rather than blocking what antivirus judges malicious. Which mechanism fits?", o: ["EPP（振る舞いを監視して悪性と判定したものを止める）", "EDR（侵入後の挙動を集めて封じ込める）", "アプリケーション制御（許可リスト）", "デバイス制御（周辺機器の種類で利用を絞る）"], oEn: ["EPP (monitors behavior and blocks what it judges malicious)", "EDR (collects post-intrusion behavior and contains it)", "Application control (allowlisting)", "Device control (restricts use by peripheral type)"], a: 2, e: "アプリケーション制御は、実行してよいコードをポリシーで定め、許可されていないものを動かさない。EPPは悪性判定型、EDRは侵入後の対処、デバイス制御は周辺機器の制御。", eEn: "Application control defines which code may run and blocks everything else. EPP is verdict-based, EDR handles post-intrusion response, and device control governs peripherals."},
  {d: "IT1", q: "アプリケーション制御とアンチウイルスの関係について、出典の考え方として正しいものは？", qEn: "Which statement matches the source's view of the relationship between application control and antivirus?", o: ["アンチウイルスの代わりにはならず、併用すべきである", "許可リストで実行を絞れば、アンチウイルスは不要になる", "アンチウイルスを入れた端末では、許可リストは重ねて使えない", "許可リストは侵入後の検知を担うため、EDRと置き換えられる"], oEn: ["It does not replace antivirus and should be used alongside it", "Allowlisting makes antivirus unnecessary", "On a device with antivirus, an allowlist cannot be layered on top", "Allowlisting handles post-intrusion detection, so it can replace EDR"], a: 0, e: "出典は、アプリケーション制御はアンチウイルスの代わりにならず併用すべきとしている。許可リストは実行を絞る対策で、侵入後の検知を担うEDRの代替でもない。", eEn: "The source says application control is not a substitute for antivirus and should be combined with it. It limits execution and does not replace EDR's post-intrusion detection."},
  {d: "IT1", q: "Windowsのアプリケーション制御（App Control for Business、AppLocker）が制限できる対象として正しいものは？", qEn: "Which describes what Windows application control (App Control for Business, AppLocker) can restrict?", o: ["実行ファイルだけが対象で、スクリプトやMSIやバッチファイルは対象外となり、カーネルのコードは対象となる", "ユーザー領域で動くコードだけが対象で、PowerShellの対話セッションやカーネルのコードは対象外となる", "USBメモリやプリンターなどの周辺機器を、端末に接続してよいかどうかが対象となる", "アプリのほか、スクリプト、MSI、バッチ、PowerShellの対話セッション、カーネルのコードにも及ぶ"], oEn: ["Only executables are covered; scripts and MSI are out of scope", "Only user-space code is covered; kernel code is out of scope", "It covers whether peripherals such as USB drives and printers may connect", "Beyond apps, it extends to scripts, MSI, batch files, interactive PowerShell sessions and kernel code"], a: 3, e: "対象はアプリだけでなく、スクリプト、MSI、バッチファイル、PowerShellの対話セッションにも及び、カーネルで動くコードも制限できる。周辺機器はデバイス制御の領域である。", eEn: "Coverage includes scripts, MSI, batch files and interactive PowerShell, and kernel-mode code can be restricted too. Peripherals belong to device control."},
  {d: "IT1", q: "端末に未承認の生成AIクライアントや開発用ツールを持ち込ませないために、アプリケーション制御でとれる方針は？", qEn: "How can application control help keep unapproved generative AI clients and development tools off endpoints?", o: ["持ち込まれたAIクライアントが実行された後に、その挙動を継続して追跡して、原因を調べられるようにする", "許可した実行ファイルだけを動かし、AIクライアントや開発用ツールを許可リストに含めるかを方針で決める", "端末のディスク全体を暗号化し、未承認のツールが第三者に読まれないようにしておく", "生成AIサービスに送る文字列を検査して、機密情報を含む入力を止める"], oEn: ["Trace the tool's behavior after it runs to investigate the cause", "Run only approved executables, and decide in the rollout policy whether AI clients and dev tools go on the allowlist", "Encrypt the entire disk so unapproved tools cannot be read", "Inspect strings sent to the generative AI service and block inputs with confidential data"], a: 1, e: "許可した実行ファイルだけが動く状態は、未承認ツールの持ち込みを抑える手段になる。事後追跡はEDR、ディスク暗号化は紛失対策、入力検査はDLPの役割である。", eEn: "Letting only approved executables run curbs unapproved tools. After-the-fact tracing is EDR, disk encryption is loss protection, and input inspection is DLP."},
  {d: "IT1", q: "USBメモリやBluetooth機器を、機器のIDやセットアップクラスで許可・拒否して、データの持ち出しとマルウェアの侵入口を絞りたい。当てるべき対策は？", qEn: "You want to allow or deny USB drives and Bluetooth devices by device ID or setup class, narrowing exfiltration and malware entry points. Which measure fits?", o: ["ディスク暗号化", "デバイス制御", "アプリケーション制御", "デバイスコンプライアンス"], oEn: ["Disk encryption", "Device control", "Application control", "Device compliance"], a: 1, e: "デバイス制御は周辺機器をポリシーで制御する対策。ディスク暗号化は紛失時の読取り防止、アプリケーション制御は実行コードの制限、コンプライアンスは端末状態の評価である。", eEn: "Device control governs peripherals by policy. Disk encryption protects against reading on loss, app control limits executable code, and compliance evaluates device state."},
  {d: "IT1", q: "機密度に基づいてUSBメモリへのコピーを防ぎたい。デバイス制御とDLPの違いを踏まえた判断として正しいものは？", qEn: "You want to block copying to USB drives based on sensitivity. Which judgment correctly reflects the difference between device control and DLP?", o: ["機密度で止めるのはデバイス制御で、DLPは各機器のIDやクラスだけを見て止める仕組みである", "両者は同じ仕組みの別名なので、どちらを入れても機密度での制御ができる", "デバイス制御は、BitLockerで暗号化された媒体を文書の機密度とみなして判定する", "中身の機密度で止めるのはEndpoint DLPで、デバイス制御は機器の種類や属性で止める"], oEn: ["Device control stops by sensitivity, while DLP stops only by device ID", "They are two names for the same mechanism, so either can enforce sensitivity-based control", "Device control treats BitLocker-encrypted media as document sensitivity when judging", "Endpoint DLP stops by content sensitivity, while device control stops by device type or attributes"], a: 3, e: "DLPは文書の機密度など中身で持ち出しを止め、デバイス制御は機器の種類や属性で止める。出典も、機密度に基づくUSBへのコピー防止はEndpoint DLPとしている。", eEn: "DLP blocks by content such as sensitivity; device control blocks by device type or attributes. The source assigns sensitivity-based USB copy prevention to Endpoint DLP."},
  {d: "IT1", q: "Defender for Endpointの例で、周辺機器の制御として指定できる内容に当てはまるものは？", qEn: "In the Defender for Endpoint example, which describes what can be specified for peripheral control?", o: ["機器の種類、読み書き実行、ユーザーグループ、ネットワークの場所、ファイル種別まで指定できる", "機器のIDとセットアップクラスによる許可・拒否のみで、読み取りと書き込みの区別まではできない仕組みである", "暗号化の有無は区別できず、媒体の種類ごとに一律で許可か拒否かのどちらかしか選べない仕組みである", "ユーザーグループは指定できず、端末単位でしか設定を分けられないうえ、ネットワークの場所も区別しない"], oEn: ["Device type, read/write/execute, user group, network location and file type can all be specified", "Only allow/deny by device ID and setup class, with no read/write distinction", "Encryption status cannot be distinguished; each media type is uniformly allowed or denied", "User groups cannot be specified; settings can differ only per device"], a: 0, e: "Defender for Endpointの例では、機器の種類、読み書き実行、ユーザーグループ、ネットワークの場所、ファイル種別まで細かく指定でき、暗号化媒体のみ許可もできる。", eEn: "The example allows fine-grained control by device type, read/write/execute, user group, network location and file type, including allowing only encrypted media."},
  {d: "IT1", q: "生成AIの入力制御を整えたうえで、AIに渡す前の元データがUSBや印刷で持ち出される経路にも備えたい。適切な考え方は？", qEn: "With generative AI input controls in place, you also want to cover paths where source data leaves via USB or printing before it reaches AI. What is the right approach?", o: ["ディスク暗号化を有効にすれば、USB経由の持ち出しは防げる", "入力制御を強化すれば、USBや印刷による持ち出しも同時に塞がる", "入力制御とは別に、端末の物理的な出口をデバイス制御で管理する層を設ける", "VDIを導入すれば、コピーや印刷は自動的に禁止されるので追加の設計は要らない"], oEn: ["Strengthening input controls also closes USB and printing exfiltration", "Enabling disk encryption prevents exfiltration via USB", "Add a separate layer that manages the endpoint's physical exits through device control", "Introducing VDI automatically prohibits copying and printing"], a: 2, e: "デバイス制御は、生成AIの入力制御とは別に、USBや印刷など端末の物理的な出口を管理する層。暗号化は紛失対策、VDIは導入だけでは持ち出し対策にならない。", eEn: "Device control is a layer separate from AI input controls that manages physical exits like USB and print. Encryption addresses loss, and VDI alone does not stop exfiltration."},
  {d: "IT1", q: "ノートPCの紛失、盗難、不適切な廃棄があっても、端末内のデータが読まれないようにしたい。まず当てるべき仕組みは？", qEn: "Even if a laptop is lost, stolen or improperly disposed of, you want its data to stay unreadable. Which mechanism should you apply first?", o: ["デバイスコンプライアンス（OSの版などの要件を満たす端末か評価する）", "Measured Boot（起動の記録をTPMに残して健全性を評価する）", "アプリケーション制御（許可したコードだけを実行させる）", "ディスク暗号化（Windowsの標準機能はBitLocker）"], oEn: ["Device compliance (evaluates whether a device meets requirements such as OS version)", "Measured Boot (records boot state in the TPM to assess health)", "Application control (runs only allowed code)", "Disk encryption (BitLocker is the standard Windows feature)"], a: 3, e: "ディスク暗号化は端末のボリューム全体を暗号化し、紛失・盗難・廃棄でデータが読まれることを防ぐ。他の選択肢は、状態評価、起動の完全性、実行制限の仕組みである。", eEn: "Disk encryption encrypts the whole volume so loss, theft or disposal does not expose data. The others are state evaluation, boot integrity and execution restriction."},
  {d: "IT1", q: "BitLockerをTPMと組み合わせて使う利点として正しいものは？", qEn: "What is a correct benefit of using BitLocker together with a TPM?", o: ["回復キーが不要になり、鍵の保管先を管理する手間もなくなるという利点がある", "暗号化の対象がファイル単位に絞られ、ボリューム全体は暗号化されない点にある", "停止中の改ざんの有無も確認でき、起動時にPINや起動キーを求めて多要素にもできる", "TPMが暗号化の実処理を担い、BitLockerは起動の記録を保存する分担になる点にある"], oEn: ["Recovery keys become unnecessary, removing the effort of managing key storage", "Encryption narrows to file level and the whole volume is not encrypted", "It can also confirm no tampering occurred while off, and PIN or startup key can add multi-factor", "The TPM does the actual encryption while BitLocker stores the boot record"], a: 2, e: "TPMと組み合わせると、停止中の改ざん有無も確認でき、PINや起動キーで多要素にもできる。回復キーは別途保管が必要で、暗号化はボリューム全体に及ぶ。", eEn: "With a TPM, tampering while powered off can be checked and PIN or startup key adds multi-factor. Recovery keys still need storage, and the whole volume is encrypted."},
  {d: "IT1", q: "デバイス暗号化でBitLockerが自動的に有効になる環境で、管理上とくに押さえるべきことは？", qEn: "In an environment where device encryption automatically enables BitLocker, what should administration pay particular attention to?", o: ["回復キーは端末のTPMの中だけに置き、組織側では保管しないようにする", "回復キーをMicrosoft Entra IDやAD DSなどに保管し、保管先も管理対象にする", "暗号化が自動で有効になるので、鍵に関して管理する対象はないと整理する", "回復キーは暗号化した端末のデスクトップに置き、利用者本人が自己管理する運用にして、組織側では把握しない"], oEn: ["Keep recovery keys only inside the device's TPM and do not store them on the organization side", "Store recovery keys in places such as Microsoft Entra ID or AD DS, and manage that storage too", "Encryption is automatic, so there is nothing to manage regarding keys", "Place recovery keys on the encrypted device's desktop for users to self-manage"], a: 1, e: "デバイス暗号化ではBitLockerが自動で有効になり、回復キーをMicrosoft Entra IDやAD DSなどに保管する。回復キーの保管先も管理対象になる。", eEn: "Device encryption enables BitLocker automatically and stores the recovery key in places like Entra ID or AD DS. That storage becomes part of what must be managed."},
  {d: "IT1", q: "ディスク暗号化とDLPの違いとして正しいものは？", qEn: "Which statement about the difference between disk encryption and DLP is correct?", o: ["ディスク暗号化は端末のボリュームを守る個別の対策で、中身で持ち出しを判定しない", "ディスク暗号化は文書の機密度を見て、USBへの持ち出しを許可するか決める仕組みである", "ディスク暗号化は鍵の生成と保管を担う枠組みで、KMSやHSMはその一機能にあたる", "DLPは端末のボリューム全体を暗号化して、紛失時に読み取られるのを防ぐ仕組みである"], oEn: ["Disk encryption is an individual measure protecting the endpoint volume and does not judge exfiltration by content", "Disk encryption looks at document sensitivity to decide whether USB export is allowed", "Disk encryption is the framework for key generation and storage, with KMS and HSM as one of its functions", "DLP encrypts the whole endpoint volume to prevent reading after loss"], a: 0, e: "ディスク暗号化は端末のボリュームを守る個別の対策。鍵の生成と保管は暗号化と鍵管理（KMS・HSM）の枠組みが扱い、中身で持ち出しを判定するのはDLPである。", eEn: "Disk encryption protects an endpoint's volume. Key generation and storage belong to encryption and key management (KMS, HSM), and content-based judgment is DLP."},
  {d: "IT1", q: "OSが起動する前に動くブートキットやルートキットを防ぐため、起動過程の各部品が改ざんされていないことを検証したい。当てるべき仕組みは？", qEn: "To stop bootkits and rootkits that run before the OS starts, you want to verify that each boot component is untampered. Which mechanism fits?", o: ["Secure Bootなどによる起動時の完全性検証", "EPPによる、端末上のファイルやプロセスの振る舞い監視と遮断", "アプリケーション制御による、許可したコードだけの実行", "ディスク暗号化による、端末のボリューム全体の暗号化"], oEn: ["Boot integrity verification with Secure Boot and similar features", "EPP monitoring of file and process behavior on the endpoint", "Application control that runs only allowed code", "Disk encryption of the volume"], a: 0, e: "起動時の完全性検証は、OS上のセキュリティ機能が働く前の段階を守る。EPPやアプリケーション制御はOS起動後に働き、ディスク暗号化は改ざん検証が主目的ではない。", eEn: "Boot integrity verification protects the stage before OS-level security works. EPP and app control act after boot, and disk encryption is not mainly about tamper verification."},
  {d: "IT1", q: "Windowsで、起動の記録をTPMに保存し、信頼できるサーバーへ送ることで端末の健全性を評価できるようにするのはどれか？", qEn: "In Windows, which feature stores a record of the boot in the TPM and lets a trusted server assess device health by sending it?", o: ["Secure Boot（信頼できるブートローダーだけを読み込む）", "Measured Boot", "Trusted Boot（カーネルなど起動部品の署名を検証する）", "ELAM（ドライバーを検査する）"], oEn: ["Secure Boot (loads only trusted bootloaders)", "Measured Boot", "Trusted Boot (verifies signatures of boot components such as the kernel)", "ELAM (inspects drivers)"], a: 1, e: "Measured Boot は起動の記録をTPMに保存して信頼できるサーバーに送る。Secure Boot はブートローダー、Trusted Boot は起動部品の署名、ELAM はドライバーを扱う。", eEn: "Measured Boot saves the boot record in the TPM and sends it to a trusted server. Secure Boot covers the bootloader, Trusted Boot component signatures, and ELAM drivers."},
  {d: "IT1", q: "端末コンプライアンスが設定や状態のルールを評価するのに対し、Measured Bootが加える利点は？", qEn: "While device compliance evaluates settings and state rules, what does Measured Boot add?", o: ["端末が申告する正常状態を信頼できるため、サーバー側での検証を省ける", "起動のたびにPINを求めることで、利用者本人の確認を強化できる", "起動の記録が残るため、感染した端末が自分で正常と申告しても見抜ける", "ドライバーだけを検査するので、カーネルの改ざんは検出の対象外となる"], oEn: ["The device's self-reported healthy state can be trusted, so server-side verification can be skipped", "Requiring a PIN at every boot strengthens verification of the user", "Because the boot record is kept, it can see through an infected device that claims to be healthy", "It inspects only drivers, so kernel tampering is outside detection"], a: 2, e: "Measured Boot は起動の記録をTPMに残して外部で評価できるため、感染した端末が自分で正常と申告しても見抜ける。申告を信頼する仕組みではない。", eEn: "Measured Boot keeps the boot record in the TPM for external evaluation, so an infected device cannot pass by self-reporting. It does not rely on self-declaration."},
  {d: "IT1", q: "AIや機密データを扱う端末が改ざんされていないことを前提にしたい。起動時の完全性検証をどう使うのが適切か？", qEn: "You want to assume that endpoints handling AI and confidential data are untampered. How should boot integrity verification be used?", o: ["OS上のセキュリティ機能が動いていれば起動前の改ざんも見つかるので、検証は省く", "導入時に一度だけ確認し、以降の起動では検証結果を使わない", "検証に失敗した端末も、AIを扱わない業務に限ってネットワークへ入れる", "信頼できる起動を確認した端末だけを社内ネットワークに入れる設計に結び付ける"], oEn: ["Security features on the OS would catch pre-boot tampering, so skip verification", "Check once at rollout and do not use verification results on later boots", "Even devices failing verification may join the network for non-AI work", "Tie it to a design that admits only devices with a verified trusted boot to the internal network"], a: 3, e: "起動時の完全性検証は、OS上の機能が働く前の改ざんを守る前提になる。信頼できる起動を確認した端末だけを社内ネットワークに入れる設計に結び付けられる。", eEn: "Boot verification is the premise that guards against tampering before OS-level features run. It can be tied to admitting only verified-boot devices to the internal network."},
  {d: "IT1", q: "OSの最小バージョンを満たし、ジェイルブレイクやルート化がない端末だけに業務資源を使わせたい。端末の状態を評価して判定する仕組みは？", qEn: "You want only devices that meet a minimum OS version and are not jailbroken or rooted to access business resources. Which mechanism evaluates and judges device state?", o: ["ディスク暗号化", "VDI（画面だけを端末へ届ける方式）", "デバイスコンプライアンス", "アプリケーション制御"], oEn: ["Disk encryption", "VDI", "Device compliance", "Application control"], a: 2, e: "デバイスコンプライアンスは、端末が組織の設定要件を満たすかを準拠・非準拠で判定する。判定結果をアクセス制御に使えば、要件を満たす端末だけに業務資源を使わせられる。", eEn: "Device compliance judges compliant or non-compliant against the organization's requirements. Feeding the result to access control admits only qualifying devices."},
  {d: "IT1", q: "条件付きアクセスとデバイスコンプライアンスの関係として正しいものは？", qEn: "Which statement about the relationship between conditional access and device compliance is correct?", o: ["デバイスコンプライアンスが許可の可否を決め、条件付きアクセスは端末の状態を評価する側", "どちらも端末状態の評価を担う仕組みで、役割に違いはなく、名称が違うだけである", "デバイスコンプライアンスは、業務アプリ内のデータだけを管理する仕組みである", "条件付きアクセスは許可を決める制御で、コンプライアンスはその判断に使う端末状態の評価"], oEn: ["Device compliance decides whether to allow, while conditional access evaluates device state", "Both evaluate device state, with no difference in roles", "Device compliance is the mechanism that manages only the data inside business apps", "Conditional access decides whether to allow; compliance is the device-state evaluation behind that decision"], a: 3, e: "条件付きアクセスはアクセスを許可するかを決め、デバイスコンプライアンスはその判断材料となる端末状態の評価。業務アプリ内のデータ管理はMAMの領域である。", eEn: "Conditional access decides access; device compliance supplies the device-state evaluation behind that decision. Managing data inside business apps is MAM's domain."},
  {d: "IT1", q: "Intuneの例で、準拠判定の流れと非準拠時の措置として正しいものは？", qEn: "In the Intune example, which describes the compliance judgment flow and the actions for non-compliance?", o: ["OS版や脅威レベルなどのルールを配り、非準拠なら通知やリモートロックをとり、結果はEntra IDへ報告される", "アプリの署名だけを評価し、非準拠の端末は即時に仮想デスクトップへ移して、結果は端末内に残されるため、アクセスの判断には使われない", "周辺機器のIDを評価し、非準拠になると端末内のデータがすべて自動で暗号化される仕組みになる", "ルールは配らず利用者の自己申告で判定し、結果は端末内だけに残って、アクセス制御には使われない"], oEn: ["Rules such as OS version and threat level are deployed; non-compliance triggers notification or remote lock, and results are reported to Entra ID", "Only app signatures are evaluated, and non-compliant devices are immediately moved to a virtual desktop", "Peripheral IDs are evaluated, and non-compliance encrypts all data on the device", "No rules are deployed; users self-declare, and results stay only on the device"], a: 0, e: "Intuneの例では、OS版、ジェイルブレイクやルート化の有無、脅威レベルなどのルールを配る。非準拠なら通知、リモートロック、リタイアをとり、結果はEntra IDに報告される。", eEn: "Intune deploys rules such as OS version, jailbreak/root status and threat level. Non-compliance leads to notification, remote lock or retire, and results go to Entra ID."},
  {d: "IT1", q: "個人端末から生成AIサービスを使われるのを止めたい。判断材料として使える設計は？", qEn: "You want to stop generative AI services from being used on personal devices. Which design provides a basis for that decision?", o: ["個人端末の利用者に、利用規程への同意を一度だけ求めるようにする", "生成AIの業務利用を許す端末を、準拠済みと判定された端末に限定する", "個人端末のディスクを暗号化して、AIサービスのデータを守るようにする", "端末を問わず、サインインできる全員にAIサービスの利用を許す設計にする"], oEn: ["Ask personal-device users to agree to the usage policy once", "Limit the devices allowed to use generative AI for work to those judged compliant", "Encrypt personal devices' disks to protect AI service data", "Allow everyone who can sign in to use AI services regardless of device"], a: 1, e: "デバイスコンプライアンスの判定を使えば、生成AIの業務利用を許す端末を準拠済みの端末に限定できる。個人端末からの利用を止めたいときの判断材料になる。", eEn: "Compliance judgments let you restrict work use of generative AI to compliant devices, which gives a basis for stopping use from personal devices."},
  {d: "IT1", q: "処理とデータをデータセンターやクラウド側のサーバーに置き、利用者の端末には画面だけを届けて、手元の機器を問わず同じ環境を使わせたい。当てる仕組みは？", qEn: "You want to run processing and data on servers in a datacenter or cloud, send only the screen to users, and give everyone the same environment regardless of device. Which mechanism fits?", o: ["MDM／UEM（端末側の設定を管理する）", "VDI（仮想デスクトップ）", "デバイス制御（周辺機器の利用を制御する）", "ディスク暗号化（端末のボリュームを暗号化する）"], oEn: ["MDM/UEM (manages settings on the device side)", "VDI (virtual desktop)", "Device control (controls use of peripherals)", "Disk encryption (encrypts the device's volume)"], a: 1, e: "VDIは、実際の処理とデータを端末の外に置き、画面だけを届ける方式。MDMは端末側、デバイス制御は周辺機器、ディスク暗号化は端末ボリュームを対象にする。", eEn: "VDI keeps processing and data off the device and delivers only the screen. MDM targets the device side, device control peripherals, and disk encryption the volume."},
  {d: "IT1", q: "MDM／UEMとVDIの管理対象の違いとして正しいものは？", qEn: "Which statement about the difference in what MDM/UEM and VDI manage is correct?", o: ["MDMは端末側の設定を管理し、VDIは配信する側のOSとアプリを管理する", "MDMは配信する側のOSとアプリを管理し、VDIは端末側の設定を管理する", "どちらも端末側の設定を管理し、VDIは画面配信用の基盤を運用する必要がない", "VDIは私物端末の業務アプリ内のデータだけを、退職時に選択的に消去する仕組みである"], oEn: ["MDM manages settings on the device side, while VDI manages the OS and apps on the delivering side", "MDM manages the OS and apps on the delivering side, while VDI manages device-side settings", "Both manage device-side settings, and VDI needs no operation of a screen-delivery platform", "VDI selectively wipes only the data inside business apps on personal devices"], a: 0, e: "MDMは端末側の設定を、VDIは配信する側のOSとアプリを管理する。VDIは端末を問わず同じ環境を使わせやすいが、画面配信用の基盤の運用が要る。", eEn: "MDM manages the device side and VDI the delivering side's OS and apps. VDI offers a uniform environment across devices but requires operating the delivery platform."},
  {d: "IT1", q: "Azure Virtual Desktopの例で、接続と配信の仕組みとして正しいものは？", qEn: "In the Azure Virtual Desktop example, which describes the connection and delivery mechanism correctly?", o: ["配信できるのは完全なデスクトップだけで、個別のアプリは配信の対象にならない", "専用クライアントでの接続のみ可能で、HTML5のWebクライアントは使えない形となる", "接続のために、仮想マシン側で受信ポートを開けておく必要がある仕組みである", "完全なデスクトップか個別アプリを配信し、接続は逆方向で張るため受信ポートの開放は不要"], oEn: ["Only full desktops can be delivered; individual apps cannot", "Only a dedicated client can connect; the HTML5 web client cannot be used", "Inbound ports must be opened on the virtual machine for connections", "It delivers full desktops or individual apps, and the reverse connection means no inbound port needs opening"], a: 3, e: "完全なデスクトップか個別アプリ（RemoteApp）を配信し、専用クライアントやHTML5のWebクライアントで接続できる。接続は逆方向で張るため、受信ポートの開放は不要である。", eEn: "It delivers full desktops or RemoteApp apps and accepts dedicated or HTML5 web clients. Connections are made in reverse, so no inbound port needs opening."},
  {d: "IT1", q: "AIツールを使う作業環境を隔離して配布する目的でVDIを検討している。持ち出し対策としての位置づけは？", qEn: "You are considering VDI to deliver an isolated work environment for AI tools. How should it be positioned as an exfiltration countermeasure?", o: ["導入すれば、コピーや印刷は自動で禁止されるので追加の設計は不要である", "画面だけを届ける方式なので、持ち出しの経路はそもそも存在しなくなり、別の対策は要らない", "導入だけでは持ち出し対策にならないため、コピーや印刷の制御は別途設計する", "端末にデータが残らないため、基盤の運用負担も生じない"], oEn: ["Adoption automatically prohibits copying and printing, so no extra design is needed", "Since only the screen is delivered, no exfiltration path exists", "Adoption alone is not an exfiltration measure, so copy and print controls must be designed separately", "Since no data stays on the device, there is also no platform operation burden"], a: 2, e: "VDIはAIツールを使う作業環境を隔離して配布する選択肢になる。ただし導入自体が持ち出し対策になるわけではなく、コピーや印刷の制御は別途設計する。", eEn: "VDI can deliver AI tool environments in isolation, but adopting it does not itself prevent exfiltration; copy and print controls are designed separately."},
  {d: "IT1", q: "管理されていない端末、ルーターなどの機器、プリンターなどのIoTまで、ネットワーク上の資産を漏れなく把握して台帳にまとめたい。当てる活動は？", qEn: "You want to identify every asset on the network, including unmanaged endpoints, devices such as routers, and IoT such as printers, and record them in a ledger. Which activity applies?", o: ["セキュリティベースラインの適用", "MDM／UEMへの端末の登録と設定の配布", "EDRによる侵入後の挙動データの継続的な収集", "IT資産の棚卸し・可視化（デバイス検出）"], oEn: ["Applying security baselines", "Enrolling devices in MDM/UEM and distributing settings", "Collecting post-intrusion behavior data with EDR", "IT asset inventory and discovery (device discovery)"], a: 3, e: "IT資産の棚卸しは、未管理の機器も含めて把握し台帳にまとめる活動。管理されていない機器は守る対象に入らず、脆弱性の抜け穴になる。", eEn: "Asset inventory identifies even unmanaged devices and records them. Unmanaged devices fall outside protection and become vulnerability gaps."},
  {d: "IT1", q: "MDM／UEMとIT資産の棚卸しの違いとして正しいものは？", qEn: "Which statement about the difference between MDM/UEM and IT asset inventory is correct?", o: ["MDM／UEMは登録済みの端末を管理し、棚卸しは未登録の機器の発見を含む", "MDM／UEMは未登録の機器の発見を担い、棚卸しは登録済みの端末だけを扱う", "どちらも登録済みの端末を対象にし、未管理の機器は対象に含めない", "棚卸しは主にクラウドサービスの無断利用を見つけるための活動である"], oEn: ["MDM/UEM manages enrolled devices, while inventory includes discovering unenrolled devices", "MDM/UEM discovers unenrolled devices, while inventory handles only enrolled ones", "Both target enrolled devices and exclude unmanaged ones", "Inventory is mainly the activity of finding unauthorized use of cloud services"], a: 0, e: "MDM／UEMは登録済みの端末を管理し、棚卸しは未登録の機器の発見を含む。クラウドサービスの無断利用が中心のシャドーITとは、機器が中心という点で異なる。", eEn: "MDM/UEM manages enrolled devices; inventory includes discovering unenrolled ones. Unlike shadow IT, which centers on unauthorized cloud use, inventory centers on devices."},
  {d: "IT1", q: "Defender for Endpointのデバイス検出の例で、未管理の機器を見つける方法として正しいものは？", qEn: "In the Defender for Endpoint device discovery example, which describes how unmanaged devices are found?", o: ["未管理の機器が自分で登録を申請するのを待ち、承認されたものだけを、一覧に加える", "管理者が手入力した台帳だけを元にし、通信の観察や探索は行わない", "導入済みの端末が通信を受動的に観察し、必要に応じて能動的に探索して一覧に加える", "PCとサーバーだけが対象で、ルーターやIoTは検出と評価の対象外となる"], oEn: ["Wait for unmanaged devices to request registration, adding only approved ones to the list", "Rely only on a ledger entered by administrators, with no traffic observation or probing", "Onboarded devices passively observe traffic and actively probe as needed to add devices to the list", "Only PCs and servers are covered; routers and IoT are excluded from discovery and assessment"], a: 2, e: "導入済みの端末が通信を受動的に観察し、必要に応じて能動的に探索して未管理の機器を一覧に加える。SNMPの認証付きスキャンでネットワーク機器の脆弱性も評価できる。", eEn: "Onboarded devices passively watch traffic and actively probe as needed to list unmanaged devices. Authenticated SNMP scans can assess network device vulnerabilities."},
  {d: "IT1", q: "生成AIの利用や開発が行われている端末、サーバー、機器のリスクを評価したい。その前提として必要なことは？", qEn: "You want to assess the risk of endpoints, servers and devices where generative AI is used or developed. What is required as a prerequisite?", o: ["AIサービスの契約書を確認すれば、端末側の資産把握は省略できる", "台帳で把握していること。把握できない資産はリスク評価の対象からも漏れる", "管理者が申告した資産だけを評価し、未登録の機器は評価の対象外とする", "資産の把握はAIの利用が始まった後に行い、リスク評価は後回しにしてもよいと整理する"], oEn: ["Reviewing the AI service contract lets you skip identifying endpoint-side assets", "Having them identified in the ledger; assets you cannot see also drop out of the AI adoption risk assessment", "Assess only assets reported by administrators and exclude unregistered devices", "Identify assets after AI use begins and postpone the assessment"], a: 1, e: "IT資産の棚卸しは、AIの利用や開発が行われている端末・サーバー・機器を洗い出す土台になる。把握できない資産は、リスク評価の対象からも漏れる。", eEn: "Asset inventory is the foundation for finding where AI is used or developed. Assets you cannot identify also fall outside the risk assessment."},
  {d: "IT1", q: "OSやアプリの推奨設定の組をあらかじめ決め、全端末に同じ状態で適用して維持し、設定の不備と端末ごとのばらつきを減らしたい。当てる取り組みは？", qEn: "You want to define a recommended settings set for OS and apps up front, apply it identically to all endpoints and maintain it, reducing misconfigurations and variation. Which approach fits?", o: ["セキュリティベースライン（構成のハードニング）", "パッチ管理（更新プログラムの配布・適用）", "IT資産の棚卸し（未登録の機器の発見）", "アプリケーション制御（許可したコードだけの実行）"], oEn: ["Security baseline (configuration hardening)", "Patch management (distributing and applying updates)", "IT asset inventory (discovering unregistered devices)", "Application control (running only allowed code)"], a: 0, e: "セキュリティベースラインは、推奨設定の組を全端末に同じ状態で適用して維持する取り組み。パッチ管理は更新、棚卸しは機器の発見、アプリ制御は実行の制限を扱う。", eEn: "A baseline applies and maintains a recommended settings set on all endpoints. Patch management handles updates, inventory device discovery, and app control execution limits."},
  {d: "IT1", q: "パッチ管理とセキュリティベースラインの違いとして正しいものは？", qEn: "Which statement about the difference between patch management and security baselines is correct?", o: ["パッチ管理は設定を揃える作業で、ベースラインは更新プログラムを当てる作業である", "どちらも更新プログラムの適用を指す言葉で、違いは使われる製品の名称だけである", "パッチ管理は更新プログラムを当てる作業で、ベースラインは設定を揃える作業である", "ベースラインは未登録の機器を見つけて、台帳に加える作業である"], oEn: ["Patch management is aligning settings, while a baseline is applying updates", "Both mean applying updates, differing only in the product names used", "Patch management is applying updates, while a baseline is aligning settings", "A baseline is the work of finding unregistered devices and adding them to the ledger"], a: 2, e: "パッチ管理は更新プログラムを当てる作業、ベースラインは推奨設定をそろえる作業である。未登録の機器を見つけて台帳に加えるのはIT資産の棚卸しである。", eEn: "Patch management applies updates; a baseline aligns recommended settings. Finding unregistered devices for the ledger is asset inventory."},
  {d: "IT1", q: "Intuneのセキュリティベースラインの扱いとして正しいものは？", qEn: "Which describes the correct handling of Intune security baselines?", o: ["CISやNISTに厳密に準拠しているので、調整せずにそのまま配れば足りると考えてよく、追加の確認も不要になる", "CISやNISTに厳密には準拠せず出発点として調整して使い、版の更新と他ポリシーとの競合を確認する", "一度配れば版が更新されても自動で追従するため、運用上の確認は要らないと考えてよい", "他のポリシーと競合した場合は、後から配ったものが常に優先されるので確認は不要である"], oEn: ["They strictly follow CIS and NIST, so deploying them unchanged is enough", "Not strictly CIS or NIST-compliant; adjust as a starting point, and check version updates and conflicts with other policies", "Once deployed they follow version updates automatically, so no operational check is needed", "When they conflict with other policies, the one deployed later always wins"], a: 1, e: "出典は、IntuneのベースラインはCISやNISTに厳密には準拠せず、出発点として調整して使うとする。版が更新される点と、他のポリシーとの競合の確認が運用上の要点になる。", eEn: "The source says Intune baselines do not strictly follow CIS or NIST and serve as a starting point to adjust. Version updates and policy conflicts are the operational points."},
  {d: "IT1", q: "出典のベースライン一覧に、端末上で動くAIエージェント向けのもの（プレビュー）がある。AIの実行環境の設定はどう扱うべきか？", qEn: "The source's baseline list includes one for AI agents running on endpoints (preview). How should the settings of AI execution environments be handled?", o: ["クラウド側の設定なので、端末のベースラインの対象には含めない", "プレビュー段階のため、基準を決めずに利用者の判断に任せる", "OSのベースラインを適用済みなら、AI向けの基準は別途不要とする", "他の端末と同様に、基準を決めて管理する"], oEn: ["Exclude it from endpoint baselines because it is a cloud-side setting", "Because it is in preview, leave it to users' discretion without setting a standard", "If the OS baseline is applied, no separate standard for AI is needed", "Set a standard and manage it just like other endpoints"], a: 3, e: "出典のベースライン一覧には、端末上で動くAIエージェント向けのものも載っている。AIの実行環境の設定も、他の端末と同様に基準を決めて管理する。", eEn: "The source's baseline list includes one for AI agents on endpoints. AI execution environment settings should be governed by a defined standard like other endpoints."},
  {d: "IT2", q: "認証と認可の違いとして正しいのは？", qEn: "Which correctly describes the difference between authentication and authorization?", o: ["認証は何をしてよいかの判断、認可は本人確認で、別の処理である", "認証と認可は同じ処理の別名で、IAMはそのどちらか一方だけを担う", "認証はIdPだけが、認可はSSOだけが担い、他の構成要素は関与しない", "認証は本人確認、認可は何をしてよいかの判断で、別の処理である"], oEn: ["Authentication decides what may be done and authorization is identity verification; they are separate processes", "Authentication and authorization are two names for the same process, and IAM handles only one of them", "Only the IdP performs authentication and only SSO performs authorization; no other component is involved", "Authentication is identity verification and authorization decides what may be done; they are separate processes"], a: 3, e: "認証は本人確認、認可は何をしてよいかの判断で、別の処理。IAMは両方を含む枠組みで、IdPやSSOだけがそれぞれを担うわけではない。", eEn: "Authentication verifies identity and authorization decides what is permitted; they are separate. IAM covers both, and neither is the exclusive job of the IdP or SSO."},
  {d: "IT2", q: "IAMと、IdP・SSO・MFA・PAMの関係として正しいのは？", qEn: "Which correctly describes the relationship between IAM and IdP, SSO, MFA and PAM?", o: ["IAMは認証と認可を含む枠組みで、IdP・SSO・MFAはその構成要素、PAMは特権に特化した領域", "PAMがIAM全体を包む上位の枠組みで、IdP・SSO・MFAはPAMの機能として下位に置かれ、IAMはその一部にすぎない", "SSOがIAMの上位枠組みで、IAMはSSOを実現するための一機能にすぎない", "IAMは人のIDだけを扱い、マシンやソフトウェアのIDはPAMが扱う"], oEn: ["IAM is the framework including authentication and authorization; IdP, SSO and MFA are components and PAM specializes in privileges", "PAM is the umbrella framework over all of IAM, and IdP, SSO and MFA sit below it as PAM functions, with IAM merely a part of it", "SSO is the higher-level framework over IAM, and IAM is merely a function that realizes SSO", "IAM handles only human IDs, and PAM handles machine and software IDs"], a: 0, e: "IAMは認証と認可を含む枠組みで、IdP・SSO・MFAは構成要素、PAMは影響の大きい特権に特化した領域。IDは人以外にも発行されIAMが扱う。", eEn: "IAM is the framework including authentication and authorization; IdP, SSO and MFA are components, and PAM focuses on high-impact privileges. IDs are issued to non-humans too and IAM covers them."},
  {d: "IT2", q: "生成AIのエージェントに社内システムへアクセスさせたい。IAMの設計としてどう考えるべきか？", qEn: "You want a generative-AI agent to access internal systems. How should this be considered in IAM design?", o: ["IDは人にだけ発行するものなので、AIは利用した担当者のIDを共有して動かし、AI独自のIDは設けない", "AIにどのIDで何をさせるかをIAMの設計対象に含め、エージェントに独立したIDを与えて統制する", "AIエージェントはIAMの対象外で、EPPによる端末の監視で管理する", "AIの動作は認証済みのアプリの一部とみなし、認可の判断は設けない"], oEn: ["IDs are issued only to people, so the AI runs by sharing the ID of the employee who uses it, with no ID of its own", "Include which ID the AI uses and what it may do in the IAM design, and give the agent its own governed ID", "AI agents are outside IAM and are managed by endpoint monitoring with EPP", "Treat AI behavior as part of an authenticated app and set no authorization decisions"], a: 1, e: "IDはワークロードやAIエージェントにも発行される。Entra Agent IDのように独立IDを与えて認証・認可・統制する設計が現れており、IAMの設計対象に含める。", eEn: "IDs are also issued to workloads and AI agents. As with Entra Agent ID, give agents independent IDs with authentication, authorization and governance, and include them in IAM design."},
  {d: "IT2", q: "アプリが利用者の認証を任せ、共通のIDでサインインさせる。さらにポリシー設定や不審な動きの検知を中央で担う仕組みは？", qEn: "Apps delegate user authentication to it and users sign in with a common ID; it also centrally handles policy setting and detection of suspicious activity. What is it?", o: ["IdP", "IDライフサイクル管理（SCIMによるアカウントの作成と無効化）", "PAM", "MDM／UEM"], oEn: ["IdP", "Identity lifecycle management (creating and disabling accounts via SCIM)", "PAM", "MDM/UEM"], a: 0, e: "IdPがIDの管理と認証を中央で担い、アプリは認証を任せる。SCIMのライフサイクル管理はアカウントの作成と無効化、PAMは特権、MDMは端末の管理が役割である。", eEn: "The IdP centrally handles ID management and authentication while apps delegate to it. SCIM lifecycle management creates and disables accounts, PAM handles privileges and MDM manages devices."},
  {d: "IT2", q: "IdPとIDaaSの違いとして正しいのは？", qEn: "Which correctly describes the difference between IdP and IDaaS?", o: ["IdPはクラウドで提供される形態、IDaaSは自社で構築して運用するオンプレミス型を指す", "IDaaSは認証を担う役割、IdPはそれをクラウドで使う提供形態を指す", "IdPはIAMの上位の枠組みで、IAMはIdPの認証結果を受け取って使う側である", "IdPは認証を担う役割、IDaaSはそれをクラウドサービスとして使う提供形態を指す"], oEn: ["The IdP is a cloud-delivered form; IDaaS is a self-built, self-operated on-premises type", "IDaaS is the authentication role; the IdP is the delivery form of using it in the cloud", "The IdP is a framework above IAM, and IAM is the side that receives and uses the IdP's result", "The IdP is the authentication role; IDaaS is the delivery form of using it as a cloud service"], a: 3, e: "IdPは認証を担う役割、IDaaSはそれをクラウドサービスとして使う提供形態。IAMがIdPを含む上位の枠組みで、認証結果を受け取るのはアプリ側である。", eEn: "The IdP is the authentication role and IDaaS is its cloud-service form. IAM is the higher framework that includes the IdP, and the apps are the ones that receive authentication results."},
  {d: "IT2", q: "Azureの設計指針が、生成AIサービスの認証について勧める考え方は？", qEn: "What approach does Azure's design guidance recommend for authenticating generative-AI services?", o: ["サービスごとに個別のアカウントを発行し、利用部門が各自でパスワードの設定と更新を管理する運用にして、IdPでの集約は行わない", "生成AIサービスごとに独自のID基盤を構築し、IdPは社内アプリ専用とする", "独自のID基盤を作らず信頼できるIdPを使い、認証をIdPに集約してサービスごとの個別アカウントを増やさない", "IdPは使わず、各サービスの標準のパスワード認証だけに任せる"], oEn: ["Issue individual accounts per service and have each department manage setting and updating its own passwords without central policy", "Build a dedicated identity platform for each generative-AI service and reserve the IdP for internal apps", "Use a trusted IdP instead of building your own identity platform, centralizing authentication and not multiplying per-service accounts", "Do not use an IdP and rely solely on each service's standard password authentication"], a: 2, e: "Azureの設計指針は独自のID基盤を作らず信頼できるIdPを使うよう勧める。生成AIの認証もIdPに集約し、個別アカウントを増やさない。", eEn: "Azure guidance recommends using a trusted IdP rather than building your own identity platform. Centralize generative-AI authentication in the IdP and avoid extra per-service accounts."},
  {d: "IT2", q: "再認証の回数を減らして管理を一元化することが目的のとき、中心に据える仕組みは？", qEn: "When the goal is to reduce re-authentication and centralize management, which mechanism should be central?", o: ["MFA", "SSO", "PAM", "最小権限の原則"], oEn: ["MFA", "SSO", "PAM", "Principle of least privilege"], a: 1, e: "SSOは一度のサインインで複数アプリを使え、管理を一元化する。MFAは認証の強度、PAMは特権の統制、最小権限は権限の大きさを絞る別の目的の仕組みである。", eEn: "SSO lets one sign-in cover multiple apps and centralizes management. MFA raises authentication strength, PAM governs privileges and least privilege narrows permission size."},
  {d: "IT2", q: "SAML 2.0とOIDCの使い分けとして正しいのは？", qEn: "Which correctly describes when to use SAML 2.0 versus OIDC?", o: ["SAMLは新しいWebアプリ・モバイル・APIに、OIDCは従来型のWebアプリに向く", "SAMLは従来型のWebアプリに、OIDCは新しいWebアプリ・モバイル・APIに向く", "SAMLはJSONのトークンを使い、OIDCはXML形式でやり取りする", "SAMLとOIDCはどちらもIdPを必要とせず、アプリ同士で認証を完結させる"], oEn: ["SAML suits newer web apps, mobile and APIs, while OIDC suits traditional web apps", "SAML suits traditional web apps, while OIDC suits newer web apps, mobile and APIs", "SAML uses JSON tokens, while OIDC exchanges information in XML format", "Neither SAML nor OIDC needs an IdP; apps complete authentication among themselves"], a: 1, e: "SAML 2.0はXML形式で従来型のWebアプリ向き、OIDCはOAuth 2.0上のJSONトークンで新しいWebアプリ・モバイル・APIに向く。どちらもIdPが認証する。", eEn: "SAML 2.0 uses XML and suits traditional web apps; OIDC uses JSON tokens on OAuth 2.0 and suits newer web apps, mobile and APIs. Both rely on the IdP to authenticate."},
  {d: "IT2", q: "生成AIサービスをSSO配下に置くことの効果として正しいのは？", qEn: "What is a correct effect of placing generative-AI services under SSO?", o: ["生成AIサービス側の認証強度が上がるため、MFAは不要になる", "サービスごとに個別アカウントを作る運用に切り替わり、管理が分散する", "利用ポリシーの適用やアクセス停止を、IdP側で一括して行える", "個人向けプランでもSSOに対応していれば、企業利用の要件を満たす"], oEn: ["Authentication strength at the AI service rises, so MFA becomes unnecessary", "Operations switch to per-service individual accounts, spreading management out", "Usage policies and access suspension can be applied in one place on the IdP side", "If SSO is supported even on personal plans, enterprise requirements are met"], a: 2, e: "SSO配下に置けば、利用ポリシーの適用やアクセス停止をIdPで一括できる。SSOは認証の回数を減らす仕組みでMFAの代わりにならず、企業向けサービスで選ぶ。", eEn: "Under SSO, policies and access suspension are applied centrally at the IdP. SSO reduces sign-in counts and does not replace MFA; choose enterprise-grade services that support it."},
  {d: "IT2", q: "パスワードが他のサイトで漏えいした場合でも、攻撃者に不正サインインされにくくしたい。まず導入する仕組みは？", qEn: "You want to make unauthorized sign-in harder even if a password leaks from another site. What should you introduce first?", o: ["SSO", "MFA", "IDライフサイクル管理", "最小権限の原則"], oEn: ["SSO", "MFA", "Identity lifecycle management", "Principle of least privilege"], a: 1, e: "MFAはパスワードに加え、持っているものや生体など別の種類の確認を求める。第2要素は攻撃者が入手しにくいので、漏えいしたパスワードだけでは入れない。", eEn: "MFA requires another kind of verification, such as something you have or a biometric, besides the password. The second factor is hard for attackers to obtain, so a leaked password alone fails."},
  {d: "IT2", q: "MFAとして成立する組み合わせはどれか？", qEn: "Which combination qualifies as MFA?", o: ["異なる二つのパスワードを順に入力する（どちらも「知っていること」に当たる）", "パスワードと、認証アプリやFIDO2パスキーなど「持っているもの」の確認", "一度のサインインで、割り当てられた複数のアプリを続けて使えるようにする", "社内ネットワークからのアクセスかどうかだけで、サインインの可否を決める"], oEn: ["Entering two different passwords in turn (both count as \"something you know\")", "A password plus verification of \"something you have\", such as an authenticator app or a FIDO2 passkey", "Letting one sign-in cover continued use of multiple assigned apps", "Deciding whether to allow sign-in solely by whether access comes from the corporate network"], a: 1, e: "MFAは「知っていること」「持っているもの」「本人の特徴」のうち2種類以上を組み合わせる。パスワード二つは同じ種類で、SSOや場所の判定はMFAではない。", eEn: "MFA combines two or more of something you know, something you have and something you are. Two passwords are the same type, and SSO or location checks are not MFA."},
  {d: "IT2", q: "生成AIサービスの管理者や、社内データと連携する利用者に、まず必須にすべき対策は？", qEn: "What should be made mandatory first for administrators of a generative-AI service and for users connected to internal data?", o: ["MFA", "全利用者のパスワードを毎月変更させること", "利用者の端末をMDMで定期的に初期化すること", "生成AIサービスをSSOの配下から外すこと"], oEn: ["MFA", "Forcing all users to change passwords monthly", "Periodically resetting users' devices through MDM", "Removing the generative-AI service from SSO"], a: 0, e: "デジタル庁は本人確認のリスクが高い場合の施策として全利用者のMFA必須化を挙げる。生成AIの管理者や社内データ連携の利用者には、まずMFAを必須にする。", eEn: "Japan's Digital Agency lists mandatory MFA for all users as a measure when identity risk is high. Make MFA mandatory first for AI admins and users connected to internal data."},
  {d: "IT2", q: "社内ネットワークでは通常のサインイン、社外や私物端末からは追加の本人確認を求めたい。必要な仕組みは？", qEn: "You want normal sign-in on the corporate network but extra verification from outside or from personal devices. Which mechanism is needed?", o: ["SSO", "条件付きアクセス", "IDライフサイクル管理", "最小権限の原則"], oEn: ["SSO", "Conditional Access", "Identity lifecycle management", "Principle of least privilege"], a: 1, e: "条件付きアクセスは、場所・端末・リスクなどの信号でMFAを求めるかどうかを決める。SSOは再認証を減らす仕組みで、状況に応じた制御はできない。", eEn: "Conditional Access decides whether to require MFA based on signals such as location, device and risk. SSO reduces re-authentication and cannot vary controls by situation."},
  {d: "IT2", q: "条件付きアクセスと、ロールによる認可の違いとして正しいのは？", qEn: "Which correctly describes the difference between Conditional Access and role-based authorization?", o: ["ロールによる認可は誰が何をできるかを決め、条件付きアクセスは端末や場所などの状況で入口を絞る", "条件付きアクセスは誰が何をできるかを決め、ロールによる認可は端末や場所などの状況を見て入口を絞る", "条件付きアクセスはMFAの別名で、ロールによる認可とは評価の順序だけが異なる", "条件付きアクセスは第一要素の認証より前に評価され、認可は認証後に評価される"], oEn: ["Role-based authorization decides who can do what, while Conditional Access narrows the entry by situation such as device or location", "Conditional Access decides who can do what, while role-based authorization narrows entry by looking at situations such as device or location", "Conditional Access is another name for MFA and differs from role-based authorization only in evaluation order", "Conditional Access is evaluated before first-factor authentication, and authorization is evaluated after authentication"], a: 0, e: "ロール認可は誰が何をできるかを決め、条件付きアクセスは端末や場所などの状況で入口を絞る。条件付きアクセスは第一要素の認証後に評価される。", eEn: "Role-based authorization decides who can do what; Conditional Access narrows entry by device or location. Conditional Access is evaluated after the first-factor authentication."},
  {d: "IT2", q: "Microsoft Entra条件付きアクセスとAIエージェントの関係として正しいのは？", qEn: "Which correctly describes the relationship between Microsoft Entra Conditional Access and AI agents?", o: ["人のサインインにしか使えず、AIエージェントやワークロードのIDは条件付きアクセスの対象にできない", "第一要素の認証より前に、AIエージェントのIDを自動で遮断する", "AIエージェントにはMFAだけが適用され、場所や端末の条件は組めない", "AIエージェントのIDも対象にでき（2026年11月時点で、Entra Agent ID は一般提供、エージェント用ユーザーアカウントの指定はプレビュー）、ゼロトラストの原則をAIワークロードへ広げる"], oEn: ["It works only for human sign-ins and cannot target the identities of AI agents or workloads", "It automatically blocks AI agent identities before first-factor authentication", "Only MFA applies to AI agents, and location or device conditions cannot be set", "It can also target AI agent identities (preview), extending Zero Trust principles to AI workloads"], a: 3, e: "条件付きアクセスはAIエージェントのIDも対象にでき（2026年11月時点で、Entra Agent ID は一般提供、エージェント用ユーザーアカウントの指定はプレビュー）、ゼロトラストの原則をAIワークロードへ広げる。評価は第一要素の認証後である。", eEn: "Conditional Access can target AI agent identities (preview), extending Zero Trust to AI workloads. Evaluation takes place after first-factor authentication."},
  {d: "IT2", q: "AI基盤の管理者権限を、常時付与せず必要な間だけ有効化したい。承認と期限も付けたい。当てるべき仕組みは？", qEn: "You want AI platform admin rights activated only while needed, not always granted, with approval and expiry. Which mechanism applies?", o: ["IDライフサイクル管理（入社・異動・退職に合わせた作成と無効化）", "SSO", "PAM", "MDM／UEM"], oEn: ["Identity lifecycle management (creating and disabling accounts on joining, transfer and leaving)", "SSO", "PAM", "MDM/UEM"], a: 2, e: "PAMはジャストインタイムや期限付き割り当て、承認、MFAで特権を統制する。ライフサイクル管理は入退社に合わせた作成・無効化で、時間制限の目的とは違う。", eEn: "PAM governs privileges with just-in-time access, time-bound assignments, approval and MFA. Lifecycle management creates and disables accounts around joiners and leavers, not time-limiting privileges."},
  {d: "IT2", q: "PAMによる統制として、適切でないものはどれか？", qEn: "Which of the following is NOT appropriate as PAM-based control?", o: ["必要な間だけ権限を有効にするジャストインタイム（JIT）で運用する", "権限の有効化時にMFAと理由の入力を求める", "一度付与した管理者権限を、退職まで常時有効のままにしておく", "アクセスレビューと監査履歴で、特権の使われ方を確認する"], oEn: ["Operating with just-in-time (JIT) so rights are active only while needed", "Requiring MFA and a stated reason when a right is activated", "Leaving an admin right active at all times, once granted, until the employee leaves", "Checking how privileges are used through access reviews and audit history"], a: 2, e: "PAMは特権の常時付与を避け、JIT、期限、承認、MFA、理由入力、アクセスレビュー、監査履歴で統制する。退職まで常時有効にする運用は趣旨に反する。", eEn: "PAM avoids standing privilege and controls it via JIT, expiry, approval, MFA, reasons, access reviews and audit history. Keeping rights always active until departure defeats this."},
  {d: "IT2", q: "通常のIAMとPAMの違いとして正しいのは？", qEn: "Which correctly describes the difference between regular IAM and PAM?", o: ["IAMは全利用者のアクセスを扱い、PAMは影響の大きい管理者権限に絞り、時間や承認で制限する", "IAMは影響の大きい管理者権限に絞り、PAMは全利用者のアクセスを扱う", "PAMは管理者権限を常時付与したまま、承認も時間の制限も設けず、操作の監査ログだけを残す方式である", "PAMの対象は人の特権アカウントに限られ、サービスのアカウントは含まない"], oEn: ["IAM handles access for all users, while PAM focuses on high-impact admin rights and limits them by time and approval", "IAM focuses on high-impact admin rights, while PAM handles access for all users", "PAM keeps admin rights granted at all times with no approval or time limit, and merely records audit logs of operations", "PAM covers only human privileged accounts and does not include service accounts"], a: 0, e: "IAMは全利用者、PAMは影響の大きい管理者権限に絞り、常時付与を避けて時間や承認で制限する。アプリやサービスのアカウントもPAMの対象である。", eEn: "IAM covers all users; PAM narrows to high-impact admin rights and limits them by time and approval, avoiding standing access. Application and service accounts are in PAM's scope too."},
  {d: "IT2", q: "異動や退職で割り当て対象から外れた利用者のアカウントを、アプリ側でも自動で無効化したい。当てるべき仕組みは？", qEn: "You want accounts of users removed from assignment by transfer or departure to be automatically disabled in the app as well. Which mechanism applies?", o: ["SSO（一度のサインインで複数アプリを使え、退職者のアカウントも消す）", "MFA（パスワードに加えて別の要素を求める）", "条件付きアクセス（状況に応じて許可や拒否を決める）", "SCIMを使ったIDライフサイクル管理（プロビジョニング）"], oEn: ["SSO (one sign-in covers multiple apps and also deletes departed users' accounts)", "MFA (requires another factor in addition to the password)", "Conditional Access (decides allow or deny depending on the situation)", "Identity lifecycle management using SCIM (provisioning)"], a: 3, e: "SCIMによるプロビジョニングは、アカウントの作成・更新・無効化・削除をアプリ側へ反映する。SSOやMFA、条件付きアクセスはサインインの制御で、アカウント自体は変えない。", eEn: "SCIM provisioning reflects creation, update, disabling and deletion of accounts in the app. SSO, MFA and Conditional Access control sign-in and do not change the accounts themselves."},
  {d: "IT2", q: "SSOとSCIMによるプロビジョニングの違いとして正しいのは？", qEn: "Which correctly describes the difference between SSO and SCIM provisioning?", o: ["SSOはアカウントそのものの作成と無効化を、SCIMはどのIDでサインインするかを扱う", "SSOとSCIMはどちらも認証結果をアプリに伝える標準でSAMLとOIDCの別名である", "SCIMは認証の強度を上げる標準プロトコルで、SSOは認証の回数を減らす仕組みである", "SSOはどのIDでサインインするかを、SCIMはアカウントそのものの作成と無効化を扱う"], oEn: ["SSO deals with creating and disabling accounts; SCIM deals with which ID is used to sign in", "SSO and SCIM are both standards that convey authentication results to apps, and are other names for SAML and OIDC", "SCIM is a standard protocol that raises authentication strength, and SSO reduces the number of authentications", "SSO deals with which ID is used to sign in; SCIM deals with creating and disabling the accounts themselves"], a: 3, e: "SSOは「どのIDでサインインするか」、SCIMは「アカウントそのものの作成と無効化」を扱う。SCIMはプロビジョニングの標準プロトコルで、認証強度はMFAの役割である。", eEn: "SSO covers which ID is used to sign in, while SCIM covers creating and disabling accounts. SCIM is a provisioning protocol, and authentication strength is MFA's role."},
  {d: "IT2", q: "新しい業務ロールの権限を設計する。最小権限の原則に沿った進め方は？", qEn: "You are designing permissions for a new business role. Which approach follows the principle of least privilege?", o: ["まず管理者相当の広い権限を与えて運用を始め不要と分かった権限を問題が起きた後に1つずつ外していく", "読み取りだけで足りるかを問い、最小の権限から始めて必要に応じて追加し、適用範囲も職務の範囲に絞る", "個人やリソースごとに許可を個別に設定し、きめ細かく管理する", "適用範囲は組織全体にしておき、ロール内の細かい制限で絞る"], oEn: ["Start operations by granting administrator-level broad permissions and remove those found unnecessary one by one after a problem occurs", "Ask whether read access is enough, start with minimal permissions and add as needed, and limit the scope to the job's range", "Set permissions individually per person or resource for fine-grained management", "Keep the scope at the whole organization and narrow it with detailed restrictions inside the role"], a: 1, e: "最小権限は、読み取りで足りるかを問い、最小の権限から追加し、スコープも職務の範囲に絞る。個別設定は避け、組み込みロールとグループで管理する。", eEn: "Least privilege means asking if read-only suffices, adding from the minimum, and scoping to the duties. Avoid per-person or per-resource grants and use built-in roles and groups."},
  {d: "IT2", q: "JIT（ジャストインタイム）と最小権限の原則の関係として正しいのは？", qEn: "Which correctly describes the relationship between JIT (just-in-time) and the principle of least privilege?", o: ["JITは権限を持つ時間を絞り、最小権限は権限の大きさを絞る。併用するとIDの侵害時の影響範囲を小さくできる", "JITは権限の大きさを絞り、最小権限は権限を持つ時間を絞る。併用するとIDの侵害時の影響範囲を小さくできる", "JITと最小権限は権限を絞る点で同じ効果を持つため、併用しても影響範囲は変わらず、どちらか一方を導入すれば足りる", "最小権限は承認とMFAで有効化する方式で、JITは読み取り専用の権限を指す"], oEn: ["JIT limits how long a privilege is held; least privilege limits how large it is. Together they shrink the blast radius when an ID is compromised", "JIT limits how large a privilege is; least privilege limits how long it is held. Together they shrink the blast radius when an ID is compromised", "JIT and least privilege have the same effect of narrowing privileges, so combining them changes nothing and adopting either one is enough", "Least privilege is a method of activating via approval and MFA, and JIT means read-only permissions"], a: 0, e: "JITは権限を持つ時間、最小権限は権限の大きさを絞る。両者を組み合わせるとIDが侵害された際の影響範囲を小さくできる。どちらかで代替はできない。", eEn: "JIT limits the time a privilege is held, and least privilege limits its size. Combined, they reduce the impact if an ID is compromised, and neither substitutes for the other."},
  {d: "IT2", q: "AIを使った攻撃でフィッシングが巧妙になり、生成AIサービスの管理者が偽サイトで認証コードを入力させられる被害を懸念している。偽サイトに渡せない認証へ移すとき、当てるべきものは？", qEn: "Phishing has grown more sophisticated with AI-powered attack tools, and we worry that administrators of a generative AI service will be tricked into typing authentication codes into fake sites. What should we move to so that credentials cannot be handed to a fake site?", o: ["SMSで届くコードをパスワードに足す方式", "SSOを導入して再認証の回数を減らす", "パスキー（FIDO2）", "IDaaSで各アプリのIDを統合管理する"], oEn: ["Adding a code sent by SMS on top of the password", "Introducing SSO to reduce the number of re-authentications", "Passkeys (FIDO2)", "Using IDaaS to manage each app's IDs in one place"], a: 2, e: "パスキーは認証情報が登録したサイトに紐づくため偽サイトに渡せない。SMSコードは盗まれ得る。SSOは再認証を減らし、IDaaSはID統合の仕組みで、偽サイト対策ではない。", eEn: "A passkey is bound to the registered site, so it cannot be given to a fake site. SMS codes can be stolen. SSO reduces re-authentication and IDaaS unifies IDs; neither addresses fake sites."},
  {d: "IT2", q: "パスキーと、SMSコードをパスワードに足す一般的なMFAの違いとして正しいのは？", qEn: "Which statement correctly describes the difference between passkeys and common MFA that adds an SMS code to a password?", o: ["SMSコードはフィッシングで盗まれ得るが、パスキーは認証情報が接続先に紐づくため偽サイトに渡せない", "SMSコードは接続先に紐づくため偽サイトには使えず、パスキーは盗まれたコードで突破される", "SMSコードは公開鍵暗号で署名を返し、パスキーは乱数を端末に表示して入力させる", "SMSコードもパスキーも秘密鍵を使うが、パスキーだけは端末の外へ書き出して家族や同僚と自由に共有できる"], oEn: ["An SMS code can be stolen by phishing, but a passkey is bound to the destination and cannot be handed to a fake site", "An SMS code is bound to the destination and so cannot be used on a fake site, whereas a passkey can be broken with a stolen code", "An SMS code returns a signature using public-key cryptography, whereas a passkey shows a random number on the device to be typed in", "Both SMS codes and passkeys use a private key, but only a passkey can be exported from the device and shared with family or colleagues"], a: 0, e: "SMSコードはフィッシングで盗まれ得る。パスキーは公開鍵暗号を使い、認証情報が接続先に紐づくため偽サイトに渡せない。選択肢の逆の説明や署名の取り違えは誤り。", eEn: "SMS codes can be phished. A passkey uses public-key cryptography and is bound to the destination, so it cannot be handed to a fake site. The reversed claims and the signature mix-up are wrong."},
  {d: "IT2", q: "パスキーでのサインインの流れとして正しいのは？", qEn: "Which describes the sign-in flow with a passkey correctly?", o: ["端末が、公開鍵で署名して返し、サーバーが保管している秘密鍵で検証して、認証を完了させる流れ", "サーバーがパスワードのハッシュを端末へ送り、端末側で照合して結果を返す", "利用者が生体情報をサーバーへ送り、サーバーが登録済みの情報と照合する", "サーバーが乱数（チャレンジ）を送り、端末の秘密鍵で署名して返し、サーバーが公開鍵で検証する"], oEn: ["The device signs with the public key, and the server verifies with a private key it stores", "The server sends a password hash to the device, which compares it locally and returns the result", "The user sends biometric data to the server, which compares it with the registered data", "The server sends a random challenge, the device signs it with its private key, and the server verifies it with the public key"], a: 3, e: "サーバーが送る乱数に対し、生体認証やPINで解錠した端末の秘密鍵が署名を返し、サーバーが公開鍵で検証する。秘密鍵は端末側に残り、生体情報もサーバーへ送らない。", eEn: "The server sends a challenge; the device, unlocked by biometrics or PIN, signs it with its private key, and the server verifies it with the public key. The private key stays on the device and no biometrics are sent."},
  {d: "IT2", q: "パスキーの端末固定型とクラウド同期型について、正しいのは？", qEn: "Which statement about device-bound and cloud-synced passkeys is correct?", o: ["クラウドで同期する型は、構成証明に対応し、端末固定型は対応しない", "クラウドで同期する型は、構成証明（アテステーション）に対応しない", "どちらの型も秘密鍵をサーバーに預け、構成証明はサーバーが代行する", "クラウドで同期する型は、公開鍵暗号を使わずパスワードを同期する"], oEn: ["The cloud-synced type supports attestation, whereas the device-bound type does not", "The cloud-synced type does not support attestation", "Both types store the private key on the server, and the server performs attestation on their behalf", "The cloud-synced type does not use public-key cryptography but syncs passwords"], a: 1, e: "パスキーには端末に固定する型とクラウドで同期する型があり、同期型は構成証明に対応しない。どちらも公開鍵暗号を使い、秘密鍵をサーバーへ預けることはない。", eEn: "Passkeys come as a device-bound type and a cloud-synced type, and the synced type does not support attestation. Both use public-key cryptography and never store the private key on the server."},
  {d: "IT2", q: "管理者アカウントが侵害された疑いがある。サインインや権限変更などの行動を分析して不審な動きを検知し、アカウントの無効化やセッションの失効まで行う取り組みは？", qEn: "An administrator account may have been compromised. Which approach analyzes behavior such as sign-ins and permission changes to detect suspicious activity and then disables the account or revokes sessions?", o: ["PAM", "ITDR", "アクセスレビュー", "条件付きアクセス"], oEn: ["PAM", "ITDR", "Access review", "Conditional access"], a: 1, e: "ITDRは行動の分析でIDを狙う攻撃を検知し、アカウント無効化やセッション失効まで扱う。PAMとアクセスレビューは権限を絞る側で、条件付きアクセスは入口の可否を決める。", eEn: "ITDR detects identity attacks through behavior analysis and handles account disabling and session revocation. PAM and access review limit privileges; conditional access decides entry."},
  {d: "IT2", q: "IAM・PAMとITDRの役割の違いとして正しいのは？", qEn: "Which statement correctly describes how the roles of IAM and PAM differ from ITDR?", o: ["IAMとPAMは不審な行動を分析して検知する側、ITDRは権限を与えて利用を制限する側", "ITDRは人のIDだけを守り、非人間IDはIAMとPAMだけが守る", "ITDRは端末のマルウェアを検知する仕組みで、IDの行動は対象にしない", "IAMとPAMは権限を与えて制限する側、ITDRは不審な行動を検知して対処する側"], oEn: ["IAM and PAM analyze and detect suspicious behavior, whereas ITDR grants privileges and restricts their use", "ITDR protects only human IDs, and non-human IDs are protected only by IAM and PAM", "ITDR detects malware on devices and does not cover identity behavior", "IAM and PAM grant and restrict privileges, whereas ITDR detects and responds to suspicious behavior"], a: 3, e: "IAMとPAMは権限を与え制限する側で、ITDRは不審な行動を検知してID単位の封じ込めまで行う側である。ITDRは非人間IDも対象にし、見るのはIDの行動である。", eEn: "IAM and PAM grant and restrict; ITDR detects suspicious behavior and contains at the ID level. ITDR also covers non-human IDs, and what it watches is identity behavior."},
  {d: "IT2", q: "ITDRで、侵害されたIDの封じ込めとして挙げられている対処の組み合わせは？", qEn: "Which combination of actions is listed under ITDR for containing a compromised identity?", o: ["侵害されたアカウントの無効化、セッションの失効、認証情報のリセット", "端末のネットワーク隔離、プロセスの強制終了、不審ファイルの隔離と再イメージ化", "WAFでの通信遮断、CDNのキャッシュ破棄、DNSの切り替え", "全社員のパスワード削除、ID基盤の停止、SSO設定の初期化"], oEn: ["Disabling the compromised account, revoking sessions, and resetting credentials", "Isolating the device from the network, killing processes, and quarantining suspicious files and reimaging", "Blocking traffic at a WAF, purging the CDN cache, and switching DNS", "Deleting all employees' passwords, stopping the ID platform, and resetting SSO settings"], a: 0, e: "ITDRの対処は、侵害されたアカウントの無効化、セッションの失効、認証情報のリセットなどID単位のものである。端末の隔離は別の仕組みの役割で、他の案は範囲を取り違えている。", eEn: "ITDR responses are ID-level: disabling the compromised account, revoking sessions, and resetting credentials. Device isolation belongs to another mechanism; the other options misjudge the scope."},
  {d: "IT2", q: "社内のAIが使うサービスアカウントやAIエージェントのIDの異常な動きも検知したい。ITDRの保護対象として正しいのは？", qEn: "We also want to detect abnormal behavior of service accounts and AI agent IDs used by internal AI. Which statement about the protection scope of ITDR is correct?", o: ["人のIDだけが対象で、AIが使うサービスアカウントなどの、非人間IDは検知の範囲外になる扱い", "AIエージェントのIDだけが対象で、人のIDは対象に含まれない", "人のIDに加え、サービスアカウント、サービスプリンシパル、AIエージェントのIDも対象になる", "特権ロールを持つIDだけが対象で、一般の利用者とAIは範囲外になる"], oEn: ["Only human IDs are covered, and non-human IDs used by AI fall outside detection", "Only AI agent IDs are covered, and human IDs are not included", "In addition to human IDs, service accounts, service principals, and AI agent IDs are covered", "Only IDs with privileged roles are covered, and ordinary users and AI are out of scope"], a: 2, e: "出典は、人のIDに加えサービスアカウント、サービスプリンシパル、AIエージェントのIDも保護対象としている。AIが使う非人間IDの異常な動きの検知にも使える。", eEn: "The source covers service accounts, service principals, and AI agent IDs in addition to human IDs, so ITDR can also detect abnormal behavior of non-human IDs used by AI."},
  {d: "IT2", q: "委託先の担当者に、委託先が自組織で持つIDのまま、AI関連の環境へサインインさせたい。組織間で認証の信頼関係を結ぶ仕組みは？", qEn: "We want contractor staff to sign in to our AI-related environment with the IDs they already have at their own organization. Which mechanism establishes an authentication trust relationship between organizations?", o: ["条件付きアクセス", "委託先への管理者権限のJIT付与", "パスキーの配布", "IDフェデレーション"], oEn: ["Conditional access", "Granting administrator privileges to the contractor just in time", "Distributing passkeys", "Identity federation"], a: 3, e: "IDフェデレーションは組織間で信頼を結び、利用者が自組織のアカウントのまま別組織のアプリへサインインできるようにする。他の案は入口の絞り込みや権限の期間、認証方式の話である。", eEn: "Identity federation sets up trust between organizations so users can sign in with their own organization's accounts. The others concern entry restrictions, privilege duration, or authentication methods."},
  {d: "IT2", q: "SSOとIDフェデレーションの違いとして正しいのは？", qEn: "Which statement correctly describes the difference between SSO and identity federation?", o: ["SSOは組織間の信頼関係そのものを指し、フェデレーションは一度の認証で複数のアプリを使えるようにする体験", "SSOは一度の認証で複数アプリを使う体験を指し、フェデレーションはそれを組織をまたいで成立させる信頼関係", "SSOは認証の強度を上げる仕組みで、フェデレーションは認証の回数を減らす仕組み", "SSOはサインインを担い、フェデレーションはアカウントの作成と無効化を担う"], oEn: ["SSO is the trust relationship between organizations itself, and federation is the experience of being able to use multiple apps with one authentication", "SSO is the experience of using multiple apps with one authentication, and federation is the trust relationship that makes it work across organizations", "SSO raises authentication strength, whereas federation reduces the number of authentications", "SSO handles sign-in, whereas federation handles account creation and disabling"], a: 1, e: "SSOは再認証を減らす体験で、フェデレーションはそれを組織をまたいで成立させる信頼関係である。認証強度はMFA、アカウントの作成と無効化はプロビジョニングの役割である。", eEn: "SSO is the reduced-re-authentication experience; federation is the trust that makes it work across organizations. Authentication strength is MFA's role; account creation and disabling is provisioning's."},
  {d: "IT2", q: "SAMLやWS-Fedで相手のIdPとフェデレーションを設定するときの説明として正しいのは？", qEn: "Which statement is correct when setting up federation with a partner's IdP using SAML or WS-Fed?", o: ["自社側だけで設定すればよく、相手のIdP側の設定は要らない", "署名証明書は使わず、双方の管理者がパスワードを共有して信頼関係を確立する", "双方で設定が要り、発行元URI、認証エンドポイント、署名証明書を登録する", "相手のIdPのIDとパスワードを、自社のIdPに複製して保管する"], oEn: ["Only our side needs configuration, and nothing is needed on the partner IdP side", "No signing certificate is used, and both sides' administrators establish trust by sharing a password", "Both sides must be configured, registering the issuer URI, the authentication endpoint, and the signing certificate", "The partner IdP's IDs and passwords are copied and stored in our own IdP"], a: 2, e: "フェデレーションは双方の設定が要り、発行元URIと認証エンドポイント、署名証明書を登録する。パスワードの共有や複製はせず、利用者は自分のIdPで認証して結果を受けて戻る。", eEn: "Federation needs configuration on both sides: the issuer URI, authentication endpoint, and signing certificate. Passwords are neither shared nor copied; users authenticate at their own IdP and return."},
  {d: "IT2", q: "取引先がフェデレーションでAI関連の環境に入る場合に、自社側で必要な管理は？", qEn: "When a business partner enters our AI-related environment through federation, what must our side manage?", o: ["ゲストの権限と有効期間を、自社側で管理する", "相手のIdPが管理するため、自社側の管理は不要になる", "権限は相手のIdPが決め、自社は有効期間だけを管理する", "ゲスト用のB2Bアカウントを廃止し、共有アカウントに切り替える"], oEn: ["Manage the guest's permissions and validity period on our side", "The partner's IdP manages them, so no management is needed on our side", "The partner's IdP decides permissions, and we manage only the validity period", "Abolish guest B2B accounts and switch to a shared account"], a: 0, e: "相手のIDを使わせる場合も、自社側でゲストの権限と有効期間を管理する必要がある。出典はゲスト用のB2Bアカウントがフェデレーションでも不要にならないとする。", eEn: "Even when the partner's ID is used, our side must manage the guest's permissions and validity period. The source says guest B2B accounts do not become unnecessary with federation."},
  {d: "IT2", q: "特定のタグを持つBlobだけを読めるようにしたい。ロール割り当ての数も減らしたい。どの方式を当てるべきか？", qEn: "We want users to read only Blobs that carry a specific tag, and also to reduce the number of role assignments. Which approach should we apply?", o: ["RBACのロール割り当てに、タグを条件とするABACの条件を加える", "対象のBlobごとに個別のロール割り当てを作成し、タグの数だけ割り当てを増やす", "条件付きアクセスで社外からの接続を拒否する", "PAMのJITで読み取り権限を時間限定にする"], oEn: ["Add an ABAC condition on the tag to the RBAC role assignment", "Create an individual role assignment for each target Blob, increasing assignments by the number of tags", "Deny connections from outside the company with conditional access", "Limit read privileges in time with PAM's JIT"], a: 0, e: "Azure ABACはロール割り当てに条件を加え、特定のタグを持つBlobだけを読めるようにでき、割り当ての数も減らせる。条件付きアクセスやJITは入口や時間の制御で、リソースの属性では絞らない。", eEn: "Azure ABAC adds a condition to a role assignment so only Blobs with a given tag can be read, and it reduces assignments. Conditional access and JIT control entry or time, not resource attributes."},
  {d: "IT2", q: "RBACとABACの違いとして正しいのは？", qEn: "Which statement correctly describes the difference between RBAC and ABAC?", o: ["RBACは、属性で細かく絞り、ABACは役割に権限をまとめて業務に沿って単純に実装する", "RBACは認証の方式で、ABACは認可の方式である", "RBACは役割に権限をまとめて業務に沿って単純に実装でき、ABACは属性で細かく絞れる", "RBACとABACは排他的な方式で、併用はできない"], oEn: ["RBAC narrows access finely by attributes, whereas ABAC grants grouped privileges by role", "RBAC is an authentication method, whereas ABAC is an authorization method", "RBAC groups privileges by role and is simple to implement along business lines, whereas ABAC narrows access finely by attributes", "RBAC and ABAC are mutually exclusive and cannot be used together"], a: 2, e: "RBACは役割で権限をまとめ、業務に沿って単純に実装できる。ABACは属性で細かく絞れる。どちらも認可の設計モデルで、出典は併用すると高度な認可になるとする。", eEn: "RBAC groups privileges by role and is simple to implement; ABAC narrows by attributes. Both are authorization models, and the source says using them together enables advanced authorization."},
  {d: "IT2", q: "Azure RBACでロール割り当てを構成する3つの要素は？", qEn: "Which three elements make up a role assignment in Azure RBAC?", o: ["プリンシパル、属性、条件", "プリンシパル、ロール定義、スコープ", "ロール、ポリシー、端末", "ユーザー名、所属グループ、リソースのタグ"], oEn: ["Principal, attribute, and condition", "Principal, role definition, and scope", "Role, policy, and device", "User name, group membership, and resource tag"], a: 1, e: "Azure RBACのロール割り当ては、プリンシパル、ロール定義、スコープの3つからなり、効果は割り当ての合計になる。属性と条件はABACを加えたときの要素である。", eEn: "An Azure RBAC role assignment consists of a principal, a role definition, and a scope, and the effect is the sum of assignments. Attributes and conditions belong to ABAC."},
  {d: "IT2", q: "AIが参照する社内データについて、AIが人の権限を超えて資料を引かないようにしたい。設計として適切なのは？", qEn: "We want AI that references internal data not to pull documents beyond a person's authority. Which design is appropriate?", o: ["AIのサービスアカウントに管理者ロールを与え、絞り込みはAIの回答側に任せる", "全社員共通のロールを1つ作り、AIにもそのロールで最大の参照範囲を与える", "属性は使わず、端末の準拠状態だけで参照の可否を決める", "ロールに加え、機密区分やプロジェクトなどの属性で可否を決めるABACも使う"], oEn: ["Give the AI service account an administrator role and leave narrowing to the AI's answers", "Create one role common to all employees and give the AI the widest reference range with it", "Use no attributes and decide access only by device compliance state", "Also use ABAC, which decides access by attributes such as confidentiality class and project, in addition to roles"], a: 3, e: "AIが参照するデータは、ロールだけでなく機密区分やプロジェクトなどの属性でも絞る設計にし、AIが人の権限を超えて資料を引かない前提にする。管理者ロールの付与は権限が過大になる。", eEn: "Narrow AI-referenced data by attributes such as confidentiality class and project as well as roles, so AI never exceeds a person's authority. Granting an administrator role gives excessive privileges."},
  {d: "IT2", q: "GitHub Actionsからクラウドへ、長期のシークレットを持たせずに認証させたい。Entraで当てるべきものは？", qEn: "We want GitHub Actions to authenticate to the cloud without holding long-lived secrets. What should we apply in Entra?", o: ["サービスプリンシパルにパスワードを発行し、リポジトリの設定ファイルに保存する", "ワークロードIDフェデレーション", "MFAを必須にして、実行のたびに担当者へ認証コードを入力させる", "SCIMでパイプライン用のユーザーアカウントを作成する"], oEn: ["Issue a password for a service principal and store it in the repository's config file", "Workload identity federation", "Require MFA and have a person enter an authentication code on every run", "Create a user account for the pipeline with SCIM"], a: 1, e: "ワークロードIDフェデレーションはGitHub Actionsなどでシークレットなしの認証を可能にする。設定ファイルへのパスワード保存はシークレットを持たせる誤った前提である。", eEn: "Workload identity federation enables secret-free authentication for GitHub Actions and similar. Storing a password in a config file is the wrong premise of holding a secret."},
  {d: "IT2", q: "人のIDとワークロードID（非人間ID）の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between human IDs and workload (non-human) IDs?", o: ["ワークロードは資源ごとに複数の資格情報を持ち、作成と失効の把握が難しい", "ワークロードは1つのIDで複数の資源に入るため、失効の把握が人より簡単になる", "人のIDは資源ごとに複数の資格情報を持ち、ワークロードは1つで足りる", "ワークロードIDには、条件付きアクセスやアクセスレビューは適用できない"], oEn: ["A workload has multiple credentials per resource, making creation and revocation hard to track", "A workload enters multiple resources with a single ID, so revocation is easier to track than for people", "A human ID has multiple credentials per resource, whereas a workload needs only one", "Conditional access and access reviews cannot be applied to workload IDs"], a: 0, e: "人は1つのIDで複数の資源に入るが、ワークロードは資源ごとに複数の資格情報を持ち、作成と失効の把握が難しい。攻撃者が狙う傾向も指摘され、条件付きアクセス等は適用できる。", eEn: "A person uses one ID across resources, but a workload holds multiple credentials per resource, which is hard to track. Attackers target them, and conditional access and reviews can be applied."},
  {d: "IT2", q: "Entraのマネージドアイデンティティ（マネージドID）の利点として正しいのは？", qEn: "What is a correct benefit of managed identities in Entra?", o: ["管理者が行うパスワードの定期変更を、自動化ツールが代行する", "端末の準拠状態を判定して、アクセスの可否を決める", "資格情報を暗号化して、専用の保管庫に預ける", "ワークロードの資格情報の管理を不要にする"], oEn: ["An automation tool performs the periodic password changes that administrators used to do", "It evaluates device compliance and decides whether access is allowed", "It encrypts credentials and stores them in a dedicated vault", "It removes the need to manage the workload's credentials"], a: 3, e: "マネージドIDは、アプリなどのワークロードが使う資格情報の管理を不要にする。端末の準拠判定は条件付きアクセスの役割で、保管庫への預け入れはシークレット管理の役割である。", eEn: "Managed identities remove the need to manage credentials used by workloads. Device compliance evaluation is conditional access's role, and vault storage is secrets management's."},
  {d: "IT2", q: "AIエージェントのIDについて、出典が示している専用IDの特徴は？", qEn: "What characteristics of the dedicated ID for AI agents does the source describe?", o: ["人のIDと共有し、AIは担当者のIDで認証する", "有効期限を持たない代わりに、保証人を置かない", "人間の保証人、ライフサイクル管理、一括の方針適用を持つ", "作成時に権限を固定し、ライフサイクルの管理や保証人の指名は不要とする"], oEn: ["It is shared with a person's ID, and the AI authenticates as the staff member", "It has no expiry date, and in exchange no sponsor is assigned", "It has a human sponsor, lifecycle management, and bulk policy application", "Permissions are fixed at creation, and lifecycle management and naming a sponsor are unnecessary"], a: 2, e: "出典はAIエージェントを別種の機械IDとし、人間の保証人、ライフサイクル管理、一括の方針適用を持つ専用IDを用意している。AIがAPIを呼ぶIDの棚卸しの中心になる。", eEn: "The source treats an AI agent as a separate kind of machine ID with a human sponsor, lifecycle management, and bulk policy application, and it is central to inventorying IDs that AI uses for API calls."},
  {d: "IT2", q: "パスワード、証明書、APIキーをアプリの設定ファイルに書いて運用している。漏えいの機会を減らすために、まず当てる仕組みは？", qEn: "Passwords, certificates, and API keys are written in app config files. What should be applied first to reduce opportunities for leakage?", o: ["アクセスレビュー（付与済みの権限が今も必要かを定期的に見直す活動）", "IDライフサイクル管理（入退社に合わせた付与と剥奪）", "シークレット管理（専用の保管庫での一元保管とアクセス制御）", "条件付きアクセス（状況に応じた入口の制御）"], oEn: ["Access review (the activity of periodically checking whether granted permissions are still needed)", "ID lifecycle management (granting and revoking with joiners and leavers)", "Secrets management (central storage in a dedicated vault with access control)", "Conditional access (entry control according to circumstances)"], a: 2, e: "シークレット管理は、機密情報をコードや設定ファイルに書かず、専用の保管庫で一元的に保管してアクセスを制御し、漏えいの機会を減らす。他の案は権限や入口の管理で、機密の置き場所を変えない。", eEn: "Secrets management keeps sensitive data out of code and config files, stores it centrally in a vault, and controls access. The others manage permissions or entry and do not change where secrets live."},
  {d: "IT2", q: "暗号化と鍵管理（KMS・HSM）とシークレット管理の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between encryption and key management (KMS/HSM) and secrets management?", o: ["暗号化と鍵管理はアプリが使う認証情報全般を預かり、シークレット管理はデータ暗号化の鍵を守る", "シークレット管理は保存データの暗号化だけを担い、パスワードやAPIキーは対象外である", "両者は同じ目的で、Key Vaultでは一方しか使えない", "暗号化と鍵管理はデータ暗号化の鍵を守り、シークレット管理はアプリが使う認証情報全般を預かる"], oEn: ["Encryption and key management hold credentials in general used by apps, whereas secrets management protects keys for data encryption", "Secrets management only encrypts stored data and excludes passwords and API keys", "The two have the same purpose, and Key Vault can be used for only one of them", "Encryption and key management protect keys for data encryption, whereas secrets management holds credentials in general used by apps"], a: 3, e: "暗号化と鍵管理はデータ暗号化の鍵を守り、シークレット管理はアプリが使う認証情報全般を預かる。Key Vaultは両方に使えるが、目的が異なる。", eEn: "Encryption and key management protect data-encryption keys, while secrets management holds the credentials apps use. Key Vault can serve both, but the purposes differ."},
  {d: "IT2", q: "Azure Key Vaultの例で、漏えい時の影響を小さくし、利用を追跡できる運用として正しいのは？", qEn: "In the Azure Key Vault example, which operation limits the impact of a leak and keeps usage traceable?", o: ["アプリ単位で保管庫を分けてアクセスを絞り、利用記録をログに残して監視する", "全アプリのシークレットを1つの保管庫にまとめ、全アプリに同じアクセスを許す", "保存時の暗号化は行わず、利用記録も容量節約のため取らない", "アクセスの絞り込みをアプリのコードに任せ、保管庫は記録を持たない"], oEn: ["Separate vaults per app to narrow access, and log usage records for monitoring", "Put all apps' secrets in one vault and allow the same access to every app", "Skip encryption at rest, and do not keep usage records to save capacity", "Leave access narrowing to the app code, and keep no records in the vault"], a: 0, e: "保管庫はアプリ単位で分けてアクセスを絞れ、保存時にHSMの鍵で暗号化され、利用記録をログに残して監視できる。1つにまとめて同じアクセスを許すと影響範囲が広がる。", eEn: "Vaults can be split per app to narrow access, are encrypted at rest with an HSM key, and usage can be logged and monitored. Pooling everything with identical access widens the blast radius."},
  {d: "IT2", q: "AIアプリが使う外部APIキーやモデルの接続情報の扱いとして、出典に沿った設計は？", qEn: "Which design follows the source for handling external API keys and model connection information used by an AI app?", o: ["キーを管理者個人のIDに紐づけ、管理者と同じ権限で使わせる", "保管庫から取得させ、キーを非人間IDに紐づけて最小限の権限に限る", "キーをコードに埋め込み、権限は広く取って、キーの更新も省いて運用の手間を減らす", "キーを共有メールで配布し、開発者全員が同じキーを使う"], oEn: ["Tie the key to an administrator's personal ID and let it be used with the same privileges", "Have the app fetch them from a vault, tie the key to a non-human ID, and limit it to minimum privileges", "Embed the key in code, grant broad privileges, and skip key updates to reduce operational effort", "Distribute the key by shared email so all developers use the same key"], a: 1, e: "AIアプリはキーやモデルの接続情報をコードに埋め込まず、保管庫から取る。キーは非人間IDに紐づけ、最小限の権限に限る。個人IDへの紐づけや共有は権限過大や追跡不能を招く。", eEn: "The AI app fetches keys and connection details from a vault instead of embedding them, ties the key to a non-human ID, and limits privileges. Personal IDs or sharing lead to excess privilege and poor traceability."},
  {d: "IT2", q: "特権ロールの人数や、外部ゲストの残存を責任者が定期的に確認し、不要な権限を外したい。当てるべき仕組みは？", qEn: "We want owners to periodically check the number of privileged-role holders and remaining external guests and remove unneeded access. Which mechanism applies?", o: ["条件付きアクセスで、社外からのサインインにMFAを求める", "SCIMのプロビジョニングで、退職者のアカウントを自動で削除する", "JITで、特権ロールを必要な間だけ有効化する", "アクセスレビュー"], oEn: ["Conditional access requiring MFA for sign-ins from outside the company", "SCIM provisioning to automatically delete leavers' accounts", "JIT to activate privileged roles only while needed", "Access review"], a: 3, e: "アクセスレビューは、与えたアクセス権が今も必要かを責任者などが定期的に確認し、不要なものを外す。特権ロールの人数や外部ゲストの残存の確認に向く。他の案は入口や自動付与、時間の制御である。", eEn: "Access review has owners periodically confirm whether access is still needed and remove the rest; it suits checking privileged-role counts and lingering guests. The others control entry, automated provisioning, or time."},
  {d: "IT2", q: "IDライフサイクル管理とアクセスレビューの違いとして正しいのは？", qEn: "Which statement correctly describes the difference between ID lifecycle management and access review?", o: ["ライフサイクル管理は入社・異動・退職に合わせて自動で付与と剥奪を行い、アクセスレビューは自動で拾えない権限を人が再確認する", "ライフサイクル管理は自動化で拾えない権限を人が再確認し、アクセスレビューは入社・異動・退職に合わせて自動で付与と剥奪を行うもの", "アクセスレビューは入社時のアカウント作成を担い、ライフサイクル管理は監査の指摘に対応する", "どちらも人が確認する作業で、自動化の範囲に違いはない"], oEn: ["Lifecycle management automatically grants and revokes with joins, moves, and exits, whereas access review has people re-confirm privileges that automation cannot catch", "Lifecycle management has people re-confirm privileges that automation cannot catch, whereas access review automatically grants and revokes with joins, moves, and exits", "Access review creates accounts at joining, and lifecycle management responds to audit findings", "Both are manual confirmation tasks, and there is no difference in automation scope"], a: 0, e: "ライフサイクル管理は入社・異動・退職に合わせた付与と剥奪を自動で行い、アクセスレビューは自動化で拾えない権限を人が再確認する。PAMの時間制限とも補い合う。", eEn: "Lifecycle management automates granting and revoking with joins, moves, and exits; access review has people re-check what automation misses. It also complements PAM's time limits."},
  {d: "IT2", q: "Entraの例で、アクセスレビューの運用として正しいのは？", qEn: "In the Entra example, which describes the operation of access reviews correctly?", o: ["対象は、ロールだけで、実施は年1回に固定され、担当者に拒否の選択肢はなく、承認した結果だけを監査用に記録する", "グループ、アプリの割り当て、ロールなどを対象に、週次から年次の繰り返しでレビューし、担当者が承認か拒否を選ぶ", "対象は端末の準拠状態で、結果は自動でMFAの要求に変換される", "レビューは1回限りで、担当者は常にIT管理者1人に固定される"], oEn: ["Only roles are targeted, it is fixed at once a year, and reviewers cannot deny", "Targets include groups, app assignments, and roles, reviews repeat from weekly to yearly, and the reviewer approves or denies", "The target is device compliance, and the result is automatically converted into an MFA requirement", "The review is one-time only, and the reviewer is always fixed to one IT administrator"], a: 1, e: "Entraでは、グループのメンバー、アプリの割り当て、ロール、アクセスパッケージを対象に、週次から年次の繰り返しでレビューを作り、担当者が承認か拒否を選ぶ。", eEn: "In Entra, reviews target group members, app assignments, roles, and access packages, repeat from weekly to yearly, and the reviewer chooses to approve or deny."},
  {d: "IT2", q: "AI基盤の管理者ロールや、AIに権限を持たせたサービスプリンシパルの扱いとして、出典に沿うのは？", qEn: "How should AI platform administrator roles and service principals granted authority to AI be handled, according to the source?", o: ["人ではないのでレビュー対象外とし、作成時の権限を維持する", "AI基盤の管理者ロールだけをレビューの対象とし、AIに権限を持たせたサービスプリンシパルは対象外とする", "人のIDと同様にレビューの対象に含め、特権ロールのサービスプリンシパルもレビューする", "AIの利用ログの保存期間を確認する作業に置き換える"], oEn: ["Exclude them from review because they are not people, and keep the permissions given at creation", "Review only AI platform administrator roles and exclude service principals granted authority to AI", "Include them in reviews like human IDs, including service principals assigned to privileged roles", "Replace the review with checking the retention period of AI usage logs"], a: 2, e: "AI基盤の管理者ロールや、AIに権限を持たせたサービスプリンシパルもレビューの対象に含める。出典は、特権ロールに割り当てたサービスプリンシパルのレビューも可能と述べている。", eEn: "AI platform administrator roles and service principals given authority to AI are included in reviews. The source says service principals assigned to privileged roles can also be reviewed."},
  {d: "IT3", q: "社内から外部の生成AIサービスへ出る通信を、通信先のFQDNやURLの単位で許可・拒否したい。土台として当てるべき仕組みはどれか。", qEn: "You want to allow or deny traffic from inside the company to external generative AI services by destination FQDN or URL. Which mechanism should serve as the foundation?", o: ["WAF（Webアプリへのリクエストの中身を検査して、SQLインジェクションなどを防ぐ）", "ファイアウォール／NGFW（FQDNやURL単位でルール化して通す・遮断する）", "NAT（内部のプライベートIPを公開IPに書き換えて、外部へ接続させる）", "DDoS対策（大量の要求による過負荷攻撃を検知して、自動で緩和する）"], oEn: ["WAF (inspects the content of requests to a web app to stop things like SQL injection)", "Firewall / NGFW (writes rules by FQDN or URL to allow or block traffic)", "NAT (rewrites internal private IPs to a public IP so they can connect externally)", "DDoS protection (detects overload attacks from mass requests and mitigates them automatically)"], a: 1, e: "通信先のFQDNやURL単位で許可・拒否する土台はFW／NGFW。WAFはリクエストの中身、NATはアドレスの書き換え、DDoS対策は過負荷の緩和で、通信先の許可判断とは役割が違う。", eEn: "The base for allowing or denying by destination FQDN or URL is the firewall/NGFW. WAF inspects request content, NAT rewrites addresses, and DDoS protection mitigates overload; none decides which destinations are allowed."},
  {d: "IT3", q: "ファイアウォールとWAFの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between a firewall and a WAF?", o: ["ファイアウォールはWebアプリケーションの通信をアプリケーションレベルで、WAFは一般的なネットワークレベルの通信を監視する", "どちらもネットワークレベルで監視するが、WAFは社内向けの通信だけが対象になる", "ファイアウォールは過負荷攻撃の緩和を担い、WAFは通信の許可・遮断だけを担う", "ファイアウォールはネットワークレベルで、WAFはWebアプリケーションの通信をアプリケーションレベルで監視する"], oEn: ["A firewall monitors web application traffic at the application level, while a WAF monitors general network-level traffic", "Both monitor at the network level, but a WAF covers only internal-facing traffic", "A firewall mitigates overload attacks, while a WAF only allows or blocks traffic", "A firewall monitors at the network level, while a WAF monitors web application traffic at the application level"], a: 3, e: "一般的なファイアウォールはネットワークレベル、WAFはWebアプリの通信をアプリケーションレベルで監視する。過負荷攻撃の緩和はDDoS対策の役割で、どちらでもない。", eEn: "A general firewall works at the network level; a WAF watches web app traffic at the application level. Mitigating overload attacks is the job of DDoS protection, not either of these."},
  {d: "IT3", q: "FWで通信先のFQDNやURLを制御する土台はできた。そのうえで、利用者単位の制御やデータの持ち出し対策を補う仕組みはどれか。", qEn: "A firewall now controls traffic by destination FQDN or URL. Which mechanisms add per-user control and data exfiltration countermeasures on top?", o: ["NAT（出口IPの集約）とDDoS対策（過負荷攻撃の緩和）", "SWG（Webアクセス全般の統制）やCASB（SaaS利用の可視化とデータ制御）", "IDS（不正の検知と通知）とネットワークセグメンテーション（区画分け）", "WAF（Webアプリの保護）とDNSフィルタリング（悪性ドメインの名前解決を遮断）"], oEn: ["NAT (consolidating egress IPs) and DDoS protection (mitigating overload attacks)", "SWG (control of web access overall) and CASB (SaaS usage visibility and data control)", "IDS (detecting and notifying) and network segmentation (dividing into zones)", "WAF (protecting web apps) and DNS filtering (blocking name resolution of malicious domains)"], a: 1, e: "FWが担う通信先の制御に対し、利用者単位の制御やデータ持ち出し対策はSWGやCASBが担う。NAT・DDoS対策・IDS・セグメンテーション・WAF・DNSフィルタは、その役割ではない。", eEn: "On top of the destination control the firewall provides, per-user control and data exfiltration countermeasures are handled by SWG and CASB. NAT, DDoS protection, IDS, segmentation, WAF and DNS filtering do not play that role."},
  {d: "IT3", q: "IDSとIPSの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between IDS and IPS?", o: ["IDSは不正なパケットを自動で遮断し、IPSは不正を検知して管理者にメールやアラームなどで知らせるだけである", "IDSは不正を検知して管理者に知らせるまで、IPSは検知に加えて不正なパケットの自動遮断まで行う", "IDSは外部からの通信だけ、IPSは内部同士の通信だけを検査する", "IDSはルールだけで許可・拒否を決め、IPSはパターンで攻撃を見分ける"], oEn: ["IDS automatically blocks malicious packets, while IPS only detects intrusions and notifies the administrator by email, alarm or the like", "IDS detects intrusions and notifies the administrator, while IPS also automatically blocks the malicious packets", "IDS inspects only inbound external traffic, while IPS inspects only internal-to-internal traffic", "IDS decides allow/deny by rules alone, while IPS recognizes attacks by patterns"], a: 1, e: "IDSは検知して知らせるまで、IPSは遮断まで行う点が違う。どちらも通信のパターンから攻撃を見分け、許可・拒否のルールで判断するファイアウォールとは別の役割を持つ。", eEn: "IDS stops at detecting and notifying; IPS goes on to block. Both recognize attacks from traffic patterns, a role separate from the firewall's allow/deny rules."},
  {d: "IT3", q: "生成AIやRAGの基盤をクラウドに置く。基盤の入口や内部通信の不審な挙動を見張る層として使え、誤検知で正当な通信を止めない運用も導入時に決めておくべき仕組みはどれか。", qEn: "You are placing a generative AI / RAG platform in the cloud. Which mechanism can watch for suspicious behavior at the platform entrance and in internal traffic, and requires deciding at rollout how to avoid blocking legitimate traffic on false positives?", o: ["IDS／IPS（通信のパターンから攻撃を見分け、設定により遮断もする）", "NAT（内部機器の送信元IPを出口のIPに集約して外部へ出し、攻撃のパターンも見分ける）", "DNSフィルタリング（悪意のあるドメインの名前解決を止める）", "固定IP（接続元のIPアドレスを変わらない値にする）"], oEn: ["IDS / IPS (recognizes attacks from traffic patterns and, by setting, also blocks)", "NAT (consolidates internal source IPs into an egress IP to go outside and also recognizes attack patterns)", "DNS filtering (stops name resolution for malicious domains)", "Static IP (fixes the source IP address to an unchanging value)"], a: 0, e: "入口や内部通信の不審な挙動を見張るのはIDS／IPS。IPSは遮断までするため、誤検知で正当な通信を止めない運用を決めておく。NATなどは通信の挙動を見張る仕組みではない。", eEn: "IDS/IPS watches for suspicious behavior at the entrance and in internal traffic. Because IPS can block, operations to avoid stopping legitimate traffic on false positives must be set. NAT and the others do not watch traffic behavior."},
  {d: "IT3", q: "社内外に公開する生成AIのチャットUIがある。入口でSQLインジェクションなどWebの典型的な攻撃を防ぐ層として、最も適切なのはどれか。", qEn: "You publish a generative AI chat UI inside and outside the company. What is the most appropriate layer at the entrance to stop typical web attacks such as SQL injection?", o: ["L3/L4を守るDDoS対策だけを置いて、Webアプリ層（L7）の防御は任せる", "接続元IPを固定して許可リストで絞るだけで、リクエストの中身は見ない", "送信元を書き換えるSNATを置いて、外部からの攻撃を見えにくくする", "WAFを置き、リクエストの中身をルールと照らして許可・遮断する"], oEn: ["Place only DDoS protection for L3/L4 and rely on it for the web app layer (L7)", "Just fix the source IP and narrow access by an allow list, without looking at request content", "Place SNAT to rewrite the source so external attacks are harder to see", "Place a WAF that checks request content against rules to allow or block it"], a: 3, e: "Webの典型的な攻撃はリクエストの中身を見るWAFで防ぐ。DDoS対策はL3/L4を守るためL7には別にWAFが要る。IP制限やSNATはリクエストの中身を検査しない。", eEn: "Typical web attacks are stopped by a WAF that inspects request content. DDoS protection covers L3/L4, so L7 needs a WAF added. IP restriction and SNAT do not inspect request content."},
  {d: "IT3", q: "WAFを入口に置いた生成AIのチャットUIがある。WAFだけでは足りず、別に検討が必要な対策はどれか。", qEn: "A generative AI chat UI has a WAF at its entrance. Which measure is not covered by the WAF and needs separate consideration?", o: ["プロンプトなど、AI固有の入力そのものに対する対策", "SQLインジェクションなどの典型的な攻撃への対策", "既知の脆弱性を各アプリで直さず一括で対処する対策", "リクエストの中身をルールと照らして許可・遮断する対策"], oEn: ["Measures against AI-specific input itself, such as prompts", "Measures against typical web attacks such as SQL injection", "Measures that handle known vulnerabilities collectively rather than fixing each app", "Measures that check request content against rules to allow or block it"], a: 0, e: "WAFはSQLインジェクションなど典型的な攻撃を防ぎ、既知の脆弱性にも一括で対処できる。ただしプロンプトなどAI固有の入力への対策は、別に検討する必要がある。", eEn: "A WAF stops typical attacks like SQL injection and can handle known vulnerabilities in one place. Measures for AI-specific input such as prompts, however, need to be considered separately."},
  {d: "IT3", q: "テレワーク端末からオフィスのネットワークへVPN接続させ、クラウド利用もオフィス経由にする構成で、導入時に別途の対策が要るのはどれか。", qEn: "In a setup where teleworking devices connect to the office network by VPN and cloud usage also goes through the office, which issue needs a separate countermeasure?", o: ["クラウド利用がオフィスの機器を経由しないため、同等の水準を保てなくなる点", "端末にデータを保存できるため、紛失や持ち出しを防ぐ対策が別に必要になる点", "VPNが外向き専用で、外部から始まる接続を受け付けない点", "接続先に見える送信元IPが端末ごとに変わり、許可リストを使えない点"], oEn: ["Cloud usage bypasses office devices, so an equal level can no longer be kept", "Separate measures are needed against loss or carrying out of data, since data can be stored on the device", "VPN is outbound-only and does not accept connections started from outside", "The source IP seen by the destination changes per device, so allow lists are unusable"], a: 1, e: "VPNならクラウド利用もオフィスのセキュリティ機器を経由し、同等の水準を保てる。ただし端末にデータを保存できるので、紛失や持ち出しへの対策が別に必要になる。", eEn: "With VPN, cloud usage also passes through the office security devices, keeping an equal level. But since data can be saved on the device, countermeasures against loss or carrying out of data are needed separately."},
  {d: "IT3", q: "社内に置いた生成AIへ、VPNでリモートから届かせている。VPNは広い範囲に届きやすい点を踏まえ、併せて検討すべき対策はどれか。", qEn: "A generative AI hosted internally is reached remotely over VPN. Given that VPN tends to reach a wide range, which measure should be considered alongside?", o: ["VPNの接続範囲を広げ、AI基盤を社内LANと同じ区画に置く", "出口IPを毎回変えて、攻撃者に特定されにくくする", "VPNをやめて、全端末の通信をDNSフィルタリングだけで制御する", "AI基盤を別の区画に分け、ZTNAでアプリ単位に絞り込む"], oEn: ["Widen the VPN reach and put the AI platform in the same zone as the internal LAN", "Change the egress IP every time so attackers find it harder to identify", "Drop VPN and control all device traffic with DNS filtering alone", "Place the AI platform in a separate zone and narrow access per app with ZTNA"], a: 3, e: "VPNは広い範囲に届きやすいので、AI基盤を別の区画に分け、ZTNAでIDと状況に基づきアプリ単位に絞る。範囲を広げたりDNSフィルタだけにしたりしても、この課題は解消しない。", eEn: "VPN tends to reach widely, so the AI platform is placed in a separate zone and ZTNA narrows access per app by identity and context. Widening reach or relying on DNS filtering alone does not resolve this."},
  {d: "IT3", q: "Microsoftは従来のVPNをどう位置づけ、どう進めるよう示しているか。", qEn: "How does Microsoft position the traditional VPN, and what approach does it show?", o: ["アプリ単位の許可を行うものと位置づけ、ZTNAへ一括で置き換えるよう勧める", "広いアクセスを与える点は変わらないとして、VPNを残したまま段階的にSWGへ置き換える進め方を示している", "証明書などだけで広いアクセスを与えるものと位置づけ、アプリ単位のZTNAへ段階的に置き換える", "IDと状況を見て接続を絞るものと位置づけ、SD-WANへ段階的に置き換える"], oEn: ["It sees VPN as per-app permission and recommends replacing it with ZTNA all at once", "It says VPN keeps broad access and shows replacing it step by step with SWG while leaving VPN in place", "It sees VPN as granting broad access on certificates alone, and replaces it step by step with per-app ZTNA", "It sees VPN as narrowing by identity and context and replaces it step by step with SD-WAN"], a: 2, e: "Microsoftは従来のVPNを、証明書などだけで広いアクセスを与えるものとみなす。IDと状況を見てアプリ単位で許可するZTNAへ、段階的に置き換える進め方を示している。", eEn: "Microsoft regards the traditional VPN as giving broad access on certificates alone, and shows a step-by-step replacement with ZTNA, which permits per app based on identity and context."},
  {d: "IT3", q: "生成AIサービスへの通信を1か所に集め、許可したサービスだけに通し、利用の記録も残せる出口を作りたい。当てはまる仕組みはどれか。", qEn: "You want a single egress that gathers traffic to generative AI services, lets through only approved services, and keeps a usage record. Which mechanism fits?", o: ["NAT（送信元アドレスを書き換えるだけで、通信先の許可判断はしない）", "IPS（検知した不正なパケットを自動で遮断する）", "WAF（公開しているWebアプリへのリクエストを検査する）", "フォワードプロキシ（内部の端末に代わって代理で外部と通信する）"], oEn: ["NAT (only rewrites the source address and makes no judgement on allowed destinations)", "IPS (automatically blocks malicious packets it detects)", "WAF (inspects requests to a published web app)", "Forward proxy (communicates externally on behalf of internal devices)"], a: 3, e: "通信をプロキシに集めれば、許可したサービスだけに通し、利用の記録を残す出口を作れる。NATは書き換えのみ、IPSは不正パケットの遮断、WAFは公開Webアプリの保護が役割。", eEn: "Funneling traffic through a proxy lets only approved services through and leaves usage records. NAT only rewrites, IPS blocks malicious packets, and WAF protects published web apps."},
  {d: "IT3", q: "フォワードプロキシとSWGの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between a forward proxy and an SWG?", o: ["プロキシは外部から内部への通信を代理し、SWGは内部同士の通信だけを評価する", "プロキシはクラウド型の仕組みで、SWGは設置型の機器だけを指す", "プロキシはアクセス先のURLやIPアドレスの安全性を評価して安全でなければ遮断する仕組みで、SWGは内部から外部への通信を代理するだけで、評価や遮断は行わない", "プロキシは内部から外部への通信を代理する仕組みで、SWGはこれをクラウド型にして、アクセス先のURLやIPアドレスの安全性を評価し、安全でなければ遮断する"], oEn: ["A proxy relays external-to-internal traffic, and an SWG evaluates only internal-to-internal traffic", "A proxy is a cloud-based mechanism, and an SWG refers only to on-premises appliances", "A proxy evaluates the safety of the destination URL or IP address and blocks it if unsafe, while an SWG only relays internal-to-external traffic and neither evaluates nor blocks", "A proxy relays internal-to-external traffic; an SWG makes this cloud-based, evaluates the safety of the destination URL or IP address, and blocks it if unsafe"], a: 3, e: "プロキシは内部から外部への通信の代理。SWGはそれをクラウド型にし、URLやIPアドレスの安全性を評価して、安全でなければ遮断する点が違う。", eEn: "A proxy relays internal-to-external traffic. An SWG makes that cloud-based and adds evaluating the URL or IP address for safety, blocking it when unsafe."},
  {d: "IT3", q: "未承認の生成AIサービスのドメインを、通信が始まる入口の名前解決の段階で止めたい。使える手段はどれか。", qEn: "You want to stop the domains of unapproved generative AI services at the name resolution stage, the entrance of communication. Which means can be used?", o: ["IDS（不正を検知して管理者に知らせる）", "固定IP（出口のIPアドレスを変わらない値にして、受け側の許可リストに載せる）", "DNSフィルタリング（名前解決の段階でドメインを止める）", "WAF（公開Webアプリへのリクエストの中身を検査して、典型的な攻撃を防ぐ）"], oEn: ["IDS (detects intrusions and notifies the administrator)", "Static IP (fixes the egress IP to an unchanging value for the receiver's allow list)", "DNS filtering (stops domains at the name resolution stage)", "WAF (inspects the content of requests to a published web app to stop typical attacks)"], a: 2, e: "名前解決の段階でドメインをブロックするのがDNSフィルタリング。未承認の生成AIサービスのドメインを止める手段になる。IDSは通知まで、固定IPとWAFは別の目的の仕組み。", eEn: "Blocking domains at name resolution is DNS filtering, which can stop unapproved generative AI service domains. IDS only notifies, and static IP and WAF serve other purposes."},
  {d: "IT3", q: "DNSフィルタリングで未承認の生成AIサービスを止めている。許可したサービスの中での利用内容まで見たいとき、補う仕組みはどれか。", qEn: "DNS filtering is stopping unapproved generative AI services. To also look at what is done inside approved services, which mechanism supplements it?", o: ["CASBのように、利用内容や持ち出しを見られる別の仕組み", "DNSフィルタリングのルールに、許可ドメインをさらに追加する", "NATの出口IPを増やして、利用内容が通信先に見えるようにする", "ネットワークセグメンテーションでサブネットを細かく分ける"], oEn: ["A different mechanism, like CASB, that can see usage content and exfiltration", "Add more allowed domains to the DNS filtering rules", "Add more NAT egress IPs so the usage content is visible to the destination", "Divide subnets more finely with network segmentation"], a: 0, e: "DNSフィルタリングはサービス（ドメイン）単位の遮断が中心で、許可したサービス内の利用内容は見えない。それはCASBなど別の仕組みで見る。ルール追加やNAT、分割では見えない。", eEn: "DNS filtering mainly blocks per service (domain) and cannot see usage inside an allowed service; that is viewed with something like CASB. Adding rules, NAT or segmentation does not reveal it."},
  {d: "IT3", q: "SWGの構成要素にあるWebフィルタリングとDNSフィルタリングの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between Web filtering and DNS filtering, both components of an SWG?", o: ["Webフィルタリングは悪意のあるWebページを、DNSフィルタリングは悪意のあるドメインをブロックし、DNSは判断の単位がドメインである", "Webフィルタリングは名前解決の段階でドメイン単位に止める仕組みで、DNSフィルタリングはWebページの中身を見て悪意のあるものを止める仕組みである", "どちらも判断の単位はドメインで、違いは通信を記録するかどうかだけである", "DNSフィルタリングはSWGの構成要素に含まれず、CASBの機能として提供される"], oEn: ["Web filtering blocks malicious web pages, DNS filtering blocks malicious domains, and DNS filtering decides per domain", "Web filtering stops traffic per domain at name resolution, while DNS filtering looks at the content of web pages and stops malicious ones", "Both decide per domain, and the only difference is whether traffic is logged", "DNS filtering is not part of an SWG and is provided as a CASB function"], a: 0, e: "SWGの構成要素ではWebフィルタリング（悪意のあるWebページ）とDNSフィルタリング（悪意のあるドメイン）が別項目として並ぶ。DNSは判断の単位がドメインである。", eEn: "In SWG components, Web filtering (malicious web pages) and DNS filtering (malicious domains) are listed as separate items. DNS decides per domain."},
  {d: "IT3", q: "社内システムが外部の生成AIのAPIを呼ぶ。提供元が送信元IPの許可リストを求めている。前提として整えるべきことはどれか。", qEn: "An internal system calls an external generative AI API, and the provider requires an allow list of source IPs. What should be arranged as a prerequisite?", o: ["利用者ごとの端末IPを、毎日変えて割り当てる", "社内システムの出口IPを、変わらない固定のIPアドレスにする", "提供元のIPアドレスを、動的IPに切り替えてもらう", "提供元のドメインを、DNSフィルタリングで許可するルールに加える"], oEn: ["Assign each user's device IP and change it daily", "Make the egress IP of the internal system an unchanging, fixed IP address", "Have the provider switch its IP address to a dynamic IP", "Add the provider's domain to the allow rules in DNS filtering"], a: 1, e: "相手が送信元IPの許可リストを求めるなら、出口IPの固定が前提になる。動的IPは変わりうるので許可リストに載せられず、DNSフィルタの許可は送信元IPとは別の話。", eEn: "If the other side requires a source IP allow list, fixing the egress IP is the prerequisite. Dynamic IPs can change and cannot be listed, and allowing a domain in DNS filtering is a separate matter from the source IP."},
  {d: "IT3", q: "クラウド型プロキシやVPN経由で接続させると、IPアドレス制限は運用しにくくなる。その理由と補い方として正しいものはどれか。", qEn: "Connecting through a cloud proxy or VPN makes IP address restriction harder to operate. Which describes the reason and how to compensate?", o: ["接続先に見えるIPが利用者の端末IPのままなので、許可リストが不要になる", "接続先に見えるIPが各サービスの出口に変わり最新の一覧を保つのが困難なため、端末準拠の条件やソースIP復元で補う", "出口が1つに固定されるので最新の一覧を簡単に保てるが、全通信が1か所に集中して通信量が増え、遅くなる点が大きな難所になる", "IPアドレス制限は使えなくなるので、DNSフィルタリングに全面的に切り替える"], oEn: ["The destination still sees the user's device IP, so an allow list becomes unnecessary", "The IP seen by the destination becomes each service's egress, making an up-to-date list hard to keep, so compensate with device compliance conditions or source IP restoration", "The egress is fixed to one so an up-to-date list is easy to keep, but all traffic concentrates in one place, grows and slows down, which becomes a major difficulty", "IP restriction becomes unusable, so switch entirely to DNS filtering"], a: 1, e: "プロキシやVPN経由だと接続先に見えるIPが各サービスの出口に変わり、最新の一覧を保つのは困難とMicrosoftは述べる。端末準拠の条件やソースIP復元で補う。", eEn: "Microsoft says that via a proxy or VPN the IP the destination sees becomes each service's egress, so keeping an up-to-date list is difficult. Device compliance conditions or source IP restoration compensate."},
  {d: "IT3", q: "IPアドレス制限を導入するが、IPだけに頼らない設計にしたい。Conditional Accessの考え方に沿うのはどれか。", qEn: "You will introduce IP address restriction but want a design that does not rely on IP alone. Which follows the Conditional Access approach?", o: ["許可リストにあるIPからの接続は、認証や端末の状態を確認せずに通す", "接続元IPを、端末の状態など他の条件と並ぶ判断材料の一つにする", "IPアドレスは判断に使わず、端末の状態だけで判断する", "社内のIPからの接続は、管理者権限でも追加確認なしに通す"], oEn: ["Let connections from allow-listed IPs through without checking authentication or device state", "Make the source IP one decision factor alongside others such as device state", "Do not use IP addresses in decisions and decide on device state alone", "Let connections from internal IPs through without extra checks, even for admin rights"], a: 1, e: "Conditional Accessではネットワークの場所は他の条件と並ぶ判断材料の一つ。IPだけに頼らず、認証や端末の状態と組み合わせるのが生成AI連携でも基本になる。", eEn: "In Conditional Access, network location is one decision factor among others. Combining it with authentication and device state rather than relying on IP alone is the basic approach, including for generative AI integration."},
  {d: "IT3", q: "NATの説明として適切でないものはどれか。", qEn: "Which of the following is NOT an appropriate description of NAT?", o: ["SNATでは、複数の内部機器が同じ公開IPアドレスで外部へ接続できる", "SNATは送信元のIPとポートを公開IPとポートの組に書き換え、ポート番号で接続を区別する", "通信の可否をルールで判断して、不要な通信を遮断する役割を持つ", "通信先には個々の機器でなく、出口のIPアドレスだけが見える"], oEn: ["With SNAT, multiple internal devices can connect externally using the same public IP address", "SNAT rewrites the source IP and port to a public IP and port pair and distinguishes connections by port number", "It decides whether traffic is permitted by rules and blocks unneeded traffic", "The destination sees only the egress IP address, not individual devices"], a: 2, e: "NATはアドレスを書き換える仕組みで、通信の可否を判断するのはファイアウォールの役割。可否判断をNATの役割とする記述が適切でない。", eEn: "NAT rewrites addresses; judging whether traffic is permitted is the firewall's role. A description that assigns allow/deny judgement to NAT is inappropriate."},
  {d: "IT3", q: "Azure NAT Gatewayを使う環境で、内部機器から外部への新しい接続だけが失敗し始めた。この仕組みの説明に沿った原因はどれか。", qEn: "In an environment using Azure NAT Gateway, only new connections from internal devices to outside began to fail. Which cause fits how this mechanism works?", o: ["外部から始まる接続を受け付ける設定になり応答のパケットが通らなくなった", "L3からL7までを検査するルールが多すぎて、FQDNの照合に失敗した", "閾値の自動調整が追いつかず、公開IPを持つリソースの保護が止まった", "ポートが尽き、公開IPとポートの組を新しい接続に割り当てられなくなった"], oEn: ["It was set to accept connections started from outside, so response packets no longer pass", "There are too many rules inspecting L3 to L7, so FQDN matching failed", "Automatic threshold adjustment could not keep up, and protection of resources with public IPs stopped", "Ports ran out, so no public IP and port pair could be assigned to new connections"], a: 3, e: "NAT Gatewayは外向き専用で、ポートが尽きると新しい接続は失敗する。外部から始まる接続を受け付けないのが仕様で、L7検査やDDoSの閾値調整は別の仕組みの話。", eEn: "NAT Gateway is outbound-only and new connections fail when ports run out. It does not accept externally initiated connections by design; L7 inspection and DDoS threshold tuning belong to other mechanisms."},
  {d: "IT3", q: "生成AI基盤、参照データ、業務システムを別の区画に置き、必要な通信だけを許可する。この設計の狙いはどれか。", qEn: "A generative AI platform, reference data and business systems are placed in separate zones, with only necessary traffic permitted. What is the aim of this design?", o: ["外部から公開IPに届く大量の要求を、自動で緩和する", "生成AIへのWebアクセスを入口で検査し、プロンプトインジェクションを防ぐ", "接続元の端末IPを固定して、外部サービスの許可リストに登録できるようにする", "侵害されたときに、AI基盤から業務データへ被害が広がるのを抑える"], oEn: ["To automatically mitigate mass requests reaching a public IP from outside", "To inspect web access to generative AI at the entrance and prevent prompt injection", "To fix the source device IP so it can be registered in an external service's allow list", "To limit damage spreading from the AI platform to business data when a breach occurs"], a: 3, e: "区画ごとに通信を制御するネットワークセグメンテーションは、侵害時にAI基盤から業務データへ被害が広がるのを抑える。過負荷の緩和や入口検査、IP固定は別の目的。", eEn: "Network segmentation controls traffic per zone and limits damage spreading from the AI platform to business data on a breach. Overload mitigation, entrance inspection and IP fixing serve other purposes."},
  {d: "IT3", q: "マクロセグメンテーションとマイクロセグメンテーションの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between macro-segmentation and micro-segmentation?", o: ["マクロはアプリ単位の細かい区画で、マイクロは機能ごとの大きな区画である", "マクロは外部との境界を守り、マイクロは外部への通信を代理する", "マクロは機能やセキュリティ要件による大きな区画で、マイクロはその内側をワークロードやアプリ単位まで細かく分け、横方向の移動を制限する", "区画の大きさはどちらも機能やセキュリティ要件ごとの大きなものと同じで、違いは区画の内外をIPベースで分けるかIDベースで分けるかだけである"], oEn: ["Macro is fine-grained zones per app, while micro is large zones per function", "Macro guards the boundary with the outside, while micro relays communication to the outside", "Macro uses large zones by function or security requirement, while micro divides within them down to workloads or apps and limits lateral movement", "Both use the same large zones by function or security requirement, and differ only in whether the inside and outside of a zone are separated by IP or by ID"], a: 2, e: "マクロは機能やセキュリティ要件による大きな区画、マイクロはその内側を細かく分けて攻撃者の横方向の移動を制限する。大きさの関係を逆にした説明は誤り。", eEn: "Macro is large zones by function or security requirement; micro divides finer inside them to limit an attacker's lateral movement. Explanations that reverse the size relation are wrong."},
  {d: "IT3", q: "公開する生成AIのチャットUIとAPIは、可用性を狙う攻撃の対象になりうる。設計に含めるべき組み合わせはどれか。", qEn: "A published generative AI chat UI and API can be a target of attacks on availability. Which combination should the design include?", o: ["L7を緩和するDDoS対策と、L3/L4を守るWAF", "DDoS対策だけで、L3からL7まですべてを守れる", "固定IPの許可リストだけで、公開エンドポイントへの過負荷攻撃を防ぐ", "L3/L4を緩和するDDoS対策と、L7を守るWAF"], oEn: ["DDoS protection mitigating L7 and a WAF guarding L3/L4", "DDoS protection alone can guard everything from L3 to L7", "A static IP allow list alone prevents overload attacks on public endpoints", "DDoS protection mitigating L3/L4 and a WAF guarding L7"], a: 3, e: "DDoS対策はL3/L4を守り、Webアプリ層（L7）はWAFで補う。公開エンドポイントを持つ場合は、両方を設計に含める。層の割り当てを逆にしたり、片方だけにしたりしても足りない。", eEn: "DDoS protection guards L3/L4 and the web app layer (L7) is covered by a WAF. With public endpoints, both go into the design. Swapping layers or using only one is insufficient."},
  {d: "IT3", q: "DoS攻撃とDDoS攻撃の違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between DoS and DDoS attacks?", o: ["DoSは複数台のコンピュータから、DDoSは1台のコンピュータから行う", "DoSは1台のコンピュータから、DDoSはボット感染した複数台から一斉に行う", "DoSは通信の盗聴が目的で、DDoSは大量の要求によるサービスの使用不能が目的である", "DoSはWebアプリ層（L7）だけ、DDoSはL3/L4だけを狙う"], oEn: ["DoS is from multiple computers, while DDoS is from a single computer", "DoS is from one computer, while DDoS is carried out simultaneously from many bot-infected computers", "DoS aims at eavesdropping, while DDoS aims at making the service unusable through mass requests", "DoS targets only the web app layer (L7), while DDoS targets only L3/L4"], a: 1, e: "DoSは1台のコンピュータ、DDoSはボットに感染させた第三者のコンピュータなど複数台が一斉に行う。どちらも過負荷で使用不能にする攻撃で、狙う層で区別するものではない。", eEn: "DoS comes from one computer; DDoS from many at once, such as bot-infected third-party computers. Both aim to make services unusable by overload and are not distinguished by the layer targeted."},
  {d: "IT3", q: "受信側がメールのFromアドレスのドメインとの一致を確認し、失敗したときの扱いと報告先を送信側が指定できる仕組みはどれか。", qEn: "Which mechanism lets the receiver check that the domain matches the From address, with the sender specifying how failures are handled and where reports go?", o: ["DKIM（電子署名の検証）", "SPF（送信元IPの照合）", "DMARC", "TLS検査（暗号化通信の復号）"], oEn: ["DKIM (signature verification)", "SPF (sender IP matching)", "DMARC", "TLS inspection (decrypting encrypted traffic)"], a: 2, e: "DMARCはFromアドレスのドメインとの一致を確認し、失敗時の扱いと報告先を指定する。SPFは送信元の許可、DKIMは署名による改ざん確認が役割で、TLS検査は通信の復号の仕組みである。", eEn: "DMARC checks alignment with the From domain and specifies the handling of failures and the reporting destination. SPF authorizes senders and DKIM verifies tampering via signatures; TLS inspection decrypts traffic."},
  {d: "IT3", q: "SPFはMAIL FROMのドメインしか見ず、DKIMは署名ドメインがFromと違っても通る。この穴を埋めるために組み合わせる仕組みはどれか。", qEn: "SPF only looks at the MAIL FROM domain, and DKIM passes even if the signing domain differs from From. Which mechanism should be combined to close this gap?", o: ["DMARCによる、Fromアドレスのドメインとの一致確認", "SPFレコードに、取引先の送信元IPアドレスをさらに追加する設定", "DKIMの署名鍵を、より長いものに入れ替える運用", "受信側のDNSフィルタリングで、送信元ドメインを名前解決の段階で止める設定"], oEn: ["Alignment checking against the From domain by DMARC", "Adding more partner sender IP addresses to the SPF record", "Replacing the DKIM signing key with a longer one", "DNS filtering on the receiver that blocks the sender domain at name resolution"], a: 0, e: "SPFとDKIMはFromのドメインと食い違っても通るため、DMARCの一致確認で埋める。IPの追加や鍵の長さはこの食い違いに関係せず、DNSフィルタリングは別の役割である。", eEn: "SPF and DKIM can pass even when the domain differs from From, so DMARC's alignment check fills the gap. Adding IPs or lengthening keys does not address the mismatch, and DNS filtering has a different role."},
  {d: "IT3", q: "AIエージェントやSaaS連携が自社ドメインのメールを自動送信するようにした。受信側の認証に失敗しうるとき、先に整えることはどれか。", qEn: "An AI agent or SaaS integration now sends email automatically under the company domain. Authentication may fail at the receiver; what should be set up first?", o: ["その送信サービスの宛先ドメインを、DNSフィルタリングの許可リストに登録する", "メール本文をTLS検査で復号したうえで、ゲートウェイ側で署名を付け直す", "送信元のNAT出口を使うたびに変え、受信側の照合を避ける運用にする", "その送信サービスをSPFに加えるか、自社ドメインでDKIM署名させる"], oEn: ["Register the sending service's destination domain in the DNS filtering allow list", "Decrypt the body by TLS inspection and re-sign it at the gateway", "Change the NAT egress each time so the receiver's matching is avoided", "Add the sending service to SPF, or have it sign with DKIM under the company domain"], a: 3, e: "自動送信を行うサービスがSPFに含まれず、自社ドメインのDKIM署名もないと認証に失敗しうる。DNSフィルタリングやTLS検査、NAT出口の変更では送信元ドメインの検証を満たせない。", eEn: "If the sending service is not in SPF and does not sign with the company's DKIM, authentication can fail. DNS filtering, TLS inspection or changing NAT egress cannot satisfy sender-domain verification."},
  {d: "IT3", q: "SPFの仕組みの説明として正しいものはどれか。", qEn: "Which statement correctly describes how SPF works?", o: ["電子署名をメールヘッダーに付け、受信側が改ざんの有無を確かめる", "DNSのTXTレコードで、そのドメインのメールを送ってよい送信元を示す", "Fromアドレスのドメインとの一致を確認し、失敗時の扱いと報告先を指定する", "メール本文を暗号化して、宛先の受信者だけが読めるようにする"], oEn: ["It attaches a digital signature to the mail header so the receiver can check for tampering", "It indicates, in a DNS TXT record, which senders may send mail for the domain", "It checks alignment with the From domain and specifies failure handling and reporting", "It encrypts the mail body so that only the recipient can read it"], a: 1, e: "SPFはDNSのTXTレコードで送信を許可する送信元を示す。署名で改ざんを確かめるのはDKIM、Fromとの一致確認と報告先の指定はDMARCで、本文の暗号化は3つの役割ではない。", eEn: "SPF lists permitted senders in a DNS TXT record. Tamper checks via signature are DKIM, alignment and reporting are DMARC, and body encryption is not the role of these three."},
  {d: "IT3", q: "サーバ証明書を示された接続元が、接続先が本物かを確かめる方法として正しいものはどれか。", qEn: "How does a client that is shown a server certificate verify that the destination is genuine?", o: ["サーバの公開IPアドレスが、固定IPの許可リストに載っているかで確かめる", "証明書が、自分の信頼するルート証明書にたどり着けるかで確かめる", "認証局に接続のたびに通信を中継してもらい、その内容を照合して確かめる", "サーバが事前共有鍵を知っているかを、共通のパスワードで確かめる"], oEn: ["By checking whether the server's public IP address is on a static IP allow list", "By checking whether the certificate chains up to a root certificate it trusts", "By having the CA relay each connection and comparing the content", "By checking with a shared password whether the server knows a pre-shared key"], a: 1, e: "クライアントはCAの署名が付いたサーバ証明書が信頼するルートにたどり着くかで真正性を確かめ、その後に暗号化する。IP許可リストや事前共有鍵はこの確認の方法ではない。", eEn: "The client verifies authenticity by whether the CA-signed server certificate chains to a trusted root, then encrypts. IP allow lists and pre-shared keys are not this verification method."},
  {d: "IT3", q: "暗号化と鍵管理（KMS）とTLS／PKIの違いとして正しいものはどれか。", qEn: "Which statement correctly distinguishes encryption and key management (KMS) from TLS/PKI?", o: ["KMSは通信相手が本物かを証明書で確かめて通信を暗号化し、TLS／PKIは保管データの鍵の運用と保管先を主に扱う", "KMSもTLS／PKIも保管データの鍵の運用が対象で、通信の暗号化は扱わない", "TLS／PKIは通信を暗号化するが、通信相手が本物かの確認はKMSだけが担う", "KMSは保管データの鍵の運用を主に扱い、TLS／PKIは通信相手が本物かを証明書で確かめたうえで通信を暗号化する"], oEn: ["KMS verifies the peer with a certificate and encrypts communication, while TLS/PKI mainly handles key operations for stored data", "Both KMS and TLS/PKI target key operations for stored data and do not handle communication encryption", "TLS/PKI encrypts communication, but verifying that the peer is genuine is done only by KMS", "KMS mainly handles key operations for stored data, while TLS/PKI verifies the peer with a certificate and then encrypts the communication"], a: 3, e: "KMSは保管データの鍵の運用、TLS／PKIは証明書で接続先の真正性を確かめてから通信を暗号化する。選択肢の入れ替えや、真正性の確認をKMSに寄せる説明は誤りである。", eEn: "KMS covers key operations for stored data; TLS/PKI verifies the peer with certificates and then encrypts traffic. Swapped roles or assigning authenticity checks to KMS are wrong."},
  {d: "IT3", q: "生成AIのAPIやエージェント間の通信をTLSで保護している。接続先の真正性が証明書の検証に依存するため、運用上の要件になるのはどれか。", qEn: "Generative AI APIs and agent-to-agent traffic are protected by TLS. Since peer authenticity depends on certificate validation, what becomes an operational requirement?", o: ["証明書の発行・更新・失効の管理", "通信ごとに共通鍵を、手作業で配り直す作業", "利用者ごとのプロンプトの内容を、証明書に記録して保管する運用", "送信元IPアドレスを、許可リストに登録し続ける作業"], oEn: ["Managing the issuance, renewal and revocation of certificates", "Manually redistributing a shared key for each communication", "Recording each user's prompt contents in certificates and storing them", "Continuously registering source IP addresses in an allow list"], a: 0, e: "TLSの接続先確認は証明書の検証に依存するため、証明書の発行・更新・失効の管理が運用要件になる。共通鍵の手配や許可リストの維持は、この仕組みの要件ではない。", eEn: "TLS peer verification relies on certificate validation, so managing issuance, renewal and revocation is an operational requirement. Hand-distributing keys or maintaining allow lists is not."},
  {d: "IT3", q: "生成AIサービスへの通信はHTTPSで暗号化されている。FWやプロキシで送信内容を検査したいとき、まず必要になる仕組みはどれか。", qEn: "Traffic to a generative AI service is encrypted with HTTPS. To inspect the content at the firewall or proxy, which mechanism is needed first?", o: ["DNSフィルタリング（名前解決の段階で悪意あるドメインを止める）", "NAT（送信元アドレスを公開IPアドレスに書き換える）", "TLS検査（通信をいったん復号して中身を調べ、再暗号化して送る）", "ネットワークセグメンテーション（区画ごとに通信を分ける）"], oEn: ["DNS filtering (block domains at name resolution)", "NAT (rewrite the source address to a public IP address)", "TLS inspection (decrypt, inspect, and re-encrypt before forwarding)", "Network segmentation (separate traffic by zone)"], a: 2, e: "HTTPSの中身は復号しないと見えないため、TLS検査で終端して復号し、検査後に再暗号化する。DNSフィルタリングやNAT、分割は送信内容を調べる仕組みではない。", eEn: "HTTPS content is invisible without decryption, so TLS inspection terminates, decrypts, inspects and re-encrypts. DNS filtering, NAT and segmentation do not examine content."},
  {d: "IT3", q: "IDS／IPSやWAFとTLS検査の関係として正しいものはどれか。", qEn: "Which statement correctly describes the relationship between IDS/IPS or WAF and TLS inspection?", o: ["IDS／IPSやWAFが通信の中身を見る機能で、TLS検査は暗号化通信を見られるようにする前処理にあたる", "TLS検査は通信の中身を見る機能で、IDS／IPSやWAFは暗号化し直す後処理にあたる", "TLS検査を入れると復号せずに暗号化トンネルの中が見えるため、IDS／IPSやWAFの個別の設定は要らなくなる", "IDS／IPSとWAFは暗号化通信を自力で復号できるので、TLS検査と併用する意味はない"], oEn: ["IDS/IPS and WAF look at traffic content; TLS inspection is the preprocessing that makes encrypted content visible to them", "TLS inspection looks at content, and IDS/IPS and WAF are post-processing that re-encrypts", "With TLS inspection the inside of an encrypted tunnel is visible without decryption, so IDS/IPS settings become unnecessary", "IDS/IPS and WAF can decrypt encrypted traffic on their own, so combining them with TLS inspection is pointless"], a: 0, e: "IDS／IPSやWAFが中身を調べ、TLS検査は暗号化通信を復号してそれを可能にする前処理である。復号しなければ暗号化トンネルの中は見えず、両者は併用して働く。", eEn: "IDS/IPS and WAF inspect content, and TLS inspection is the preprocessing that decrypts so they can. Without decryption the tunnel is opaque, and the two work together."},
  {d: "IT3", q: "TLS検査の対象範囲の設計として、考え方に沿うものはどれか。", qEn: "Which approach to defining the scope of TLS inspection is consistent with the concept?", o: ["例外を作らず、すべてのHTTPS通信を、暗号化の種類を問わず復号の対象にしなければならない", "信頼する宛先ほど中身を詳しく調べるため、復号の対象を優先して広げる", "復号の対象外にできるのはDNSの問い合わせだけで、Webの宛先は外せない", "金融や医療のカテゴリや、Microsoft 365など信頼する宛先は、復号の対象から外せる"], oEn: ["Every HTTPS communication must be decrypted with no exceptions", "Trusted destinations are inspected in more detail, so they are prioritized for decryption", "Only DNS queries can be excluded from decryption; web destinations cannot be excluded", "Categories such as finance and healthcare, and trusted destinations such as Microsoft 365, can be excluded from decryption"], a: 3, e: "金融や医療などのカテゴリは復号の対象外にでき、Microsoft 365など信頼する宛先は外す推奨もある。全件復号が必須という考え方や、Webの宛先は外せないという説明は誤りである。", eEn: "Finance and healthcare categories can be excluded, and excluding trusted destinations like Microsoft 365 is recommended. Mandatory full decryption or non-excludable web destinations are wrong."},
  {d: "IT3", q: "FW（Azure Firewall Premiumの例）がHTTPS通信を復号して検査するときの接続の張り方はどれか。", qEn: "In the Azure Firewall Premium example, how does the firewall set up connections when it decrypts and inspects HTTPS traffic?", o: ["クライアントとWebサーバの間に1本のTLSを張ったまま、パケットを複製して、その中身を調べる", "Webサーバ側とクライアント側の2本のTLSを張り、顧客のCA証明書で即席のサーバ証明書を作る", "Webサーバの秘密鍵を預かり、サーバ証明書をそのままクライアントに示す", "Microsoftが用意した共通のCA証明書で、全顧客に同じ即席サーバ証明書を発行する"], oEn: ["It keeps a single TLS connection between client and web server and copies packets to read the content", "It sets up two TLS connections, to the web server and to the client, and creates an on-the-fly server certificate with a customer-provided CA certificate", "It holds the web server's private key and presents the server certificate to the client as is", "It issues the same on-the-fly server certificate to all customers using a common CA certificate prepared by Microsoft"], a: 1, e: "ファイアウォールはWebサーバ側とクライアント側の2本のTLSを張り、顧客のCA証明書で即席のサーバ証明書を作る。1本のままの複製や秘密鍵の預かり、共通CAの利用は仕組みと異なる。", eEn: "The firewall sets up two TLS connections and builds an on-the-fly server certificate from the customer's CA certificate. A single connection with copying, holding private keys, or a common CA differs from the mechanism."},
  {d: "IT3", q: "VPNと閉域接続の違いとして正しいものはどれか。", qEn: "Which statement correctly distinguishes a VPN from private connectivity?", o: ["VPNは公衆網に暗号化トンネルを張り、閉域接続は経路自体が公衆網に出ない", "VPNは経路自体が公衆網に出ず、閉域接続は公衆網に暗号化トンネルを張って経路を保護する", "どちらも公衆網に暗号化トンネルを張るが、閉域接続は専用線に限られる", "VPNは社内向け、閉域接続はクラウド向けで、経路が公衆網に出るかは同じ"], oEn: ["A VPN builds an encrypted tunnel over a public network, whereas private connectivity keeps the path itself off the public network", "A VPN keeps the path off the public network, whereas private connectivity builds an encrypted tunnel over it", "Both build encrypted tunnels over a public network, but private connectivity is limited to leased lines", "A VPN is for internal use and private connectivity for cloud use, but whether the path leaves the public network is the same"], a: 0, e: "VPNは公衆網上に暗号化トンネルを張るのに対し、閉域接続は経路自体が公衆網に出ない。IP-VPNなど専用線以外の方式もあり、用途で分かれるわけではない。", eEn: "A VPN tunnels over a public network, whereas private connectivity keeps the path off it. Methods like IP-VPN exist besides leased lines, and the split is not by use case."},
  {d: "IT3", q: "PaaSにプライベートエンドポイントを作成した。インターネットからの到達も塞ぎたいとき、必要なことはどれか。", qEn: "A private endpoint was created for a PaaS service. To also block access from the internet, what is needed?", o: ["作成した時点で公開側は自動で止まるので、追加の設定は要らない", "ExpressRouteの接続事業者に、公開側の通信の遮断を依頼する", "DDoS対策をL7まで有効にして、公開側の通信を自動で拒否させる", "公開側のアクセスを止める制御を、別に設定する"], oEn: ["Public-side access stops automatically on creation, so no additional setting is needed", "Ask the ExpressRoute connectivity provider to block public-side traffic", "Enable DDoS protection up to L7 so that public-side traffic is rejected automatically", "Configure a separate control that stops the public-side access"], a: 3, e: "プライベートエンドポイントは公開側のアクセスを自動では止めないため、別の制御が要る。事業者への依頼やDDoS対策では、公開側の到達は止まらない。", eEn: "A private endpoint does not automatically stop public-side access, so a separate control is needed. A provider request or DDoS protection does not block public reachability."},
  {d: "IT3", q: "社内データを扱うAI検索や機械学習のサービスを、インターネットに公開しない設計にしたい。使える仕組みはどれか。", qEn: "You want to design AI search or machine learning services handling internal data so they are not exposed to the internet. Which mechanism can be used?", o: ["NATゲートウェイ（外向きの通信専用で、外部から始まる接続は受け付けず、応答パケットだけを通す）", "プライベートエンドポイント（仮想ネットワークのプライベートIPを持つNICとして自網に取り込む）", "WAF（リクエストの中身をルールと照らして許可・遮断する）", "フォワードプロキシ（内部の端末に代わって代理で外部と通信する）"], oEn: ["NAT gateway (outbound only; passes only response packets)", "Private endpoint (brings the service into your own network as a NIC with a private IP in the virtual network)", "WAF (allows or blocks requests by matching their content against rules)", "Forward proxy (communicates externally on behalf of internal devices)"], a: 1, e: "AI検索や機械学習のサービスはプライベートエンドポイントの対象に挙がり、公開せず自網に取り込める。NATゲートウェイ、WAF、プロキシは公開サービスを自網内へ取り込む仕組みではない。", eEn: "AI search and ML services are listed as private-endpoint targets, so they can be brought into your network unexposed. NAT gateways, WAFs and proxies do not bring services inside your network."},
  {d: "IT3", q: "閉域接続・プライベートエンドポイントの説明として適切でないものはどれか。", qEn: "Which description of private connectivity and private endpoints is NOT appropriate?", o: ["ExpressRouteは、any-to-any（IP-VPN）や専用イーサネットを選んでクラウドと私設接続できる", "IP-VPNは、通信事業者の閉域網を使う閉域接続の一種にあたる", "ExpressRouteは、接続事業者を介さずに、公衆インターネット経由でオンプレミスとクラウドを結ぶ", "プライベートエンドポイントは、仮想ネットワークのプライベートIPを持つNICとして働く"], oEn: ["ExpressRoute lets you choose any-to-any (IP-VPN) or dedicated Ethernet for a private connection to the cloud", "IP-VPN is a type of private connectivity that uses the carrier's closed network", "ExpressRoute connects on-premises and cloud over the public internet without a connectivity provider", "A private endpoint acts as a NIC with a private IP in the virtual network"], a: 2, e: "ExpressRouteは接続事業者を介してオンプレミスとクラウドを私設接続で結ぶため、公衆インターネット経由という説明が誤りである。他の3つは閉域接続の説明として正しい。", eEn: "ExpressRoute links on-premises and cloud via a connectivity provider over a private connection, so the public-internet description is wrong. The other three are correct."},
  {d: "IT3", q: "有線LAN、Wi-Fi、VPNの入口で、接続しようとする端末が登録済みか、ポリシーに適合しているかを確認して接続の可否を決めたい。当てるべき仕組みはどれか。", qEn: "At the entrance of wired LAN, Wi-Fi and VPN, you want to check whether a connecting device is registered and policy-compliant and decide whether to allow it. Which mechanism applies?", o: ["ネットワークセグメンテーションによる区画の分割", "NAC（ネットワークアクセス制御）", "DNSフィルタリングによる悪意あるドメインのブロック", "WAFによるWebアプリケーションへの攻撃の遮断"], oEn: ["Zone separation by network segmentation", "NAC (network access control)", "Blocking malicious domains with DNS filtering", "Blocking attacks on web applications with a WAF"], a: 1, e: "NACは接続しようとする端末を認証し、登録とポリシー適合を確認して接続の可否を制御する。区画の分割、ドメインのブロック、Web攻撃の遮断は端末の接続可否を決める仕組みではない。", eEn: "NAC authenticates connecting devices, checks registration and compliance, and controls access. Segmentation, domain blocking and web-attack blocking do not decide device admission."},
  {d: "IT3", q: "条件付きアクセスとNACの違いとして正しいものはどれか。", qEn: "Which statement correctly distinguishes Conditional Access from NAC?", o: ["条件付きアクセスは社内Wi-FiやVPNなどネットワークに接続する時点で判断し、NACはクラウドアプリへのアクセスを判断する", "どちらもクラウドアプリへのアクセス時に判断し、NACは端末の登録状態を見ない", "条件付きアクセスはクラウドアプリへのアクセスを判断し、NACは社内Wi-FiやVPNなどネットワークに接続する時点で判断する", "両者は役割が重なるため、NACを入れたら条件付きアクセスは併用できない"], oEn: ["Conditional Access decides at connection to a network such as internal Wi-Fi or VPN, while NAC decides access to cloud apps", "Both decide at access to cloud apps, and NAC does not look at device registration status", "Conditional Access decides access to cloud apps, while NAC decides when connecting to a network such as internal Wi-Fi or VPN", "Their roles overlap, so Conditional Access cannot be used together once NAC is introduced"], a: 2, e: "条件付きアクセスはクラウドアプリへのアクセスを、NACはネットワークへ接続する時点を判断し、両者は連携して使われる。役割の入れ替えや併用不可という説明は誤りである。", eEn: "Conditional Access judges cloud app access and NAC judges network connection, and they are used together. Swapped roles or incompatibility is wrong."},
  {d: "IT3", q: "NAC製品がIntuneなどに問い合わせ、端末がポリシーに適合しないと分かった。このときの扱いとして正しいものはどれか。", qEn: "A NAC product queries Intune or a similar service and finds that a device does not comply with policy. How is the device handled?", o: ["登録や修復へ誘導され、適合したあとで接続が許可される", "そのまま接続を許可し、ログだけを残して後から管理者に知らせる", "接続は拒否され、管理者が手動で登録し直すまで再接続を試せない", "送信元IPアドレスを固定したうえで、DNSフィルタリングの対象に加えられる"], oEn: ["It is guided to enrollment or remediation and is allowed to connect after it becomes compliant", "It is allowed to connect as is, and only a log is kept and the administrator notified later", "Its connection is refused, and it cannot retry until an administrator re-registers it manually", "Its source IP address is fixed and it is added to the DNS filtering targets"], a: 0, e: "NAC製品は端末の登録と準拠の状態をIntuneなどに問い合わせ、不適合なら登録や修復へ誘導し、適合後に接続を許可する。接続を許したまま記録だけ残す扱いは検知型の動きで、NACとは異なる。", eEn: "NAC queries Intune for enrollment and compliance, guides non-compliant devices to enrollment or remediation, and allows connection afterward. Allowing and only logging is detection-style behavior, not NAC."},
  {d: "IT3", q: "社内ネットワークやVPNに入れる端末を、管理下の端末に限ることには、生成AI導入の観点でどんな狙いがあるか。", qEn: "From the viewpoint of adopting generative AI, what is the aim of limiting devices allowed into the internal network and VPN to managed ones?", o: ["端末上で動くローカルAIエージェントへの攻撃を、動作ループの監視でブロックできる", "外部の生成AIサービスへ出る通信を、通信先のFQDNやURLの単位で許可・拒否できる", "AIに入力されるプロンプトの内容をネットワーク上で検査し、機密情報を伏せ字にできる", "未管理の端末が社内データを経由してAIに触れる経路を狭められる"], oEn: ["It can block attacks on local AI agents running on the device by monitoring the agent's action loop", "It can allow or deny traffic to external generative AI services by destination FQDN or URL", "It can inspect prompts entered into AI on the network and mask confidential information", "It narrows the path by which unmanaged devices reach AI via internal data"], a: 3, e: "NACで入れる端末を管理下に限ると、未管理端末が社内データ経由でAIに触れる経路を狭められる。ローカルAIの保護はEPP、FQDN単位の制御はFWの役割で、プロンプトの伏せ字化はNACの役割ではない。", eEn: "Limiting admitted devices to managed ones narrows the path for unmanaged devices to reach AI via internal data. Local AI protection is EPP, FQDN control is the firewall, and prompt masking is not NAC's role."},
  {d: "IT3", q: "無線LANの事前共有鍵（PSK）方式と、企業向けの802.1X／EAP方式の違いとして正しいものはどれか。", qEn: "Which statement correctly distinguishes the pre-shared key (PSK) method from the enterprise 802.1X/EAP method for wireless LAN?", o: ["PSKは共通のパスワードで接続し、802.1X／EAPは利用者や端末ごとに認証サーバへ照会する", "PSKは利用者や端末ごとに認証サーバへ照会し、802.1X／EAPは共通のパスワードだけで接続する", "PSKはAESで暗号化できず、802.1X／EAPだけがAESに対応する", "どちらも利用者ごとに認証するが、802.1X／EAPは暗号鍵を固定で運用する"], oEn: ["PSK connects with a shared password, while 802.1X/EAP queries an authentication server per user or device", "PSK queries an authentication server per user or device, while 802.1X/EAP connects with a shared password", "PSK cannot encrypt with AES, and only 802.1X/EAP supports AES", "Both authenticate per user, but 802.1X/EAP operates with fixed encryption keys"], a: 0, e: "PSK方式は共通のパスワードで接続し、802.1X／EAP方式は利用者や端末ごとに認証して鍵を動的に管理する。入れ替えた説明や、AES対応の差、鍵の固定運用は誤りである。", eEn: "PSK uses a shared password, while 802.1X/EAP authenticates per user or device and manages keys dynamically. Swapped roles, AES support differences and fixed keys are wrong."},
  {d: "IT3", q: "企業の無線LANで、利用者や端末ごとに認証して管理下の端末だけを入れたい。PSK方式に比べて新たに必要になる運用はどれか。", qEn: "You want an enterprise wireless LAN to authenticate by user or device and admit only managed devices. What operation becomes newly necessary compared with the PSK method?", o: ["接続する全員が共通で使うパスワードを、定期的に配布する作業", "WEPの暗号鍵を端末ごとに、手入力で設定する作業", "認証サーバや証明書の運用", "接続先のFQDNを固定IPの許可リストに、登録し続ける作業"], oEn: ["Periodically distributing the password shared by everyone connecting", "Manually entering a WEP encryption key on each device", "Operating an authentication server and certificates", "Continuously registering destination FQDNs in a static IP allow list"], a: 2, e: "802.1X／EAPは利用者や端末ごとに認証できる代わりに、認証サーバや証明書の運用が要る。共通パスワードの配布はPSK側の運用で、WEPは使わず、許可リストの登録も無関係である。", eEn: "802.1X/EAP allows per-user or per-device authentication in exchange for operating an authentication server and certificates. Shared-password distribution is PSK-side, WEP is not used, and allow lists are unrelated."},
  {d: "IT3", q: "企業の無線LANの暗号化の方針として正しいものはどれか。", qEn: "Which statement is correct as an encryption policy for an enterprise wireless LAN?", o: ["WEPで通信を暗号化し、認証だけを802.1Xで補う", "AESを推奨し、WEPは使わない", "暗号化は不要で、802.1Xによる接続時の認証だけで通信の盗み見も防げる", "AESとWEPのうち、端末が対応する古い方を優先して使う"], oEn: ["Encrypt traffic with WEP and supplement only authentication with 802.1X", "Recommend AES and do not use WEP", "Encryption is unnecessary; connection-time authentication by 802.1X alone also prevents eavesdropping", "Of AES and WEP, prefer whichever older one the device supports"], a: 1, e: "無線LANではWEPの弱点を補ったWPA系が使われ、暗号化はAESが推奨でWEPは使わない。認証だけで盗み見を防げるわけではなく、認証と暗号化を組み合わせる。", eEn: "Wireless LANs use WPA, which fixes WEP's weaknesses; AES is recommended and WEP is not used. Authentication alone does not prevent eavesdropping; authentication and encryption are combined."},
  {d: "IT3", q: "Azure Firewallで、FQDNやURL単位の制限に加え、MicrosoftがNGFWと位置づけるPremiumが備える機能の組み合わせはどれか。", qEn: "In Azure Firewall, which combination of features does Premium, which Microsoft positions as an NGFW, provide in addition to FQDN and URL-level restrictions?", o: ["DDoSの緩和とNATゲートウェイによる外向き通信の専用化", "WAFによるSQLインジェクションの遮断とDNSの名前解決の記録", "ExpressRouteによる私設接続とプライベートエンドポイントの自動作成", "侵入の検知・防止（IDPS）とTLS検査"], oEn: ["DDoS mitigation and outbound-only traffic through a NAT gateway", "SQL injection blocking by WAF and recording of DNS name resolution", "Private connection via ExpressRoute and automatic creation of private endpoints", "Intrusion detection and prevention (IDPS) and TLS inspection"], a: 3, e: "Azure Firewall PremiumはIDPSとTLS検査を備え、MicrosoftはこれをNGFWと位置づける。DDoS緩和、WAF、ExpressRouteなどは別の製品の機能である。", eEn: "Azure Firewall Premium provides IDPS and TLS inspection, and Microsoft positions it as an NGFW. DDoS mitigation, WAF and ExpressRoute belong to other products."},
  {d: "IT3", q: "Azure DDoS Protectionの動作と保護対象として正しいものはどれか。", qEn: "Which statement correctly describes how Azure DDoS Protection operates and what it protects?", o: ["トラフィックのパターンを24時間監視し、攻撃の兆候を検知すると自動で緩和する。対象は公開IPアドレスを持つリソースである", "攻撃の通報を受けた管理者が手動で緩和する。対象は仮想ネットワーク内のプライベートIPだけである", "リクエストの中身をルールと照らして遮断する。対象はApplication GatewayとFront Doorのリソースだけである", "通信量の閾値を固定値で運用し、L7のSQLインジェクションも遮断する。対象は公開IPリソースである"], oEn: ["It monitors traffic patterns 24 hours a day and mitigates automatically when it detects signs of attack; targets are resources with public IP addresses", "An administrator mitigates manually after receiving an attack report; targets are only private IPs inside the virtual network", "It blocks requests by matching their content against rules; targets are only Application Gateway and Front Door", "It uses fixed traffic thresholds and also blocks L7 SQL injection; targets are public IP resources"], a: 0, e: "Azure DDoS Protectionはトラフィックを常時監視して自動緩和し、公開IPアドレスを持つリソースを守る。手動緩和、リクエスト内容での遮断、L7の防御はこの仕組みの説明ではない。", eEn: "Azure DDoS Protection continuously monitors and mitigates automatically, protecting resources with public IPs. Manual mitigation, content-based blocking and L7 defense do not describe it."},
  {d: "IT3", q: "ハブのAzure Firewallで検査する分割構成で、分割が意図どおりかをフローログの分析で検証する仕組みはどれか。", qEn: "In a segmented design inspected by Azure Firewall in the hub, which mechanism verifies that the segmentation works as intended by analyzing flow logs?", o: ["NSGのルールによる通信の許可", "Traffic Analytics", "Azure DNS resolver policyによるドメインの遮断", "ExpressRouteによるオンプレミスとの私設接続"], oEn: ["Allowing traffic through NSG rules", "Traffic Analytics", "Blocking domains with Azure DNS resolver policy", "Private connection to on-premises through ExpressRoute"], a: 1, e: "分割が意図どおりかは、フローログを分析するTraffic Analyticsで検証する。NSGは必要な通信だけを許可する側、DNS resolver policyとExpressRouteは検証の仕組みではない。", eEn: "Traffic Analytics verifies that segmentation works as intended by analyzing flow logs. NSGs permit needed traffic, while DNS resolver policy and ExpressRoute are not verification mechanisms."},
  {d: "IT3", q: "Microsoftがネットワークのセグメンテーションで原則に挙げる考え方はどれか。", qEn: "Which approach does Microsoft list as a principle for network segmentation?", o: ["IDベースよりも、従来のIPベースのセグメンテーションを優先する", "区画は細かく分けず、機能ごとの大きな区画だけで運用する", "従来のIPベースよりも、IDベースのセグメンテーションを採る", "区画間の通信はすべて許可し、検査はインターネット境界だけで行う"], oEn: ["Prefer traditional IP-based segmentation over identity-based", "Do not split finely and operate only with large functional zones", "Adopt identity-based segmentation rather than the traditional IP-based approach", "Allow all traffic between zones and inspect only at the internet boundary"], a: 2, e: "Microsoftは従来のIPベースより、IDベースのセグメンテーションを採ることを原則に挙げる。IP優先や大きな区画のみ、区画間の全許可は、被害の広がりを抑える設計に反する。", eEn: "Microsoft lists identity-based segmentation over traditional IP-based as a principle. IP-first, only large zones, or allowing all inter-zone traffic runs against limiting spread."},
  {d: "IT4", q: "外部へのWebアクセスをクラウド型で安全に行わせ、アクセス先のURLやIPアドレスから安全性を評価して、安全でなければ遮断したい。当てはまる仕組みはどれか。", qEn: "You want web access to the outside to be done safely in a cloud-based way, evaluating safety from the destination URL or IP address and blocking if unsafe. Which mechanism fits?", o: ["SWG（クラウド型のプロキシとして、Webアクセスを仲介する）", "CASB（SaaSの利用に絞って可視化し、データの持ち出しを制御する）", "SD-WAN（広域ネットワークをソフトウェアで制御する）", "NAT（内部のプライベートIPと公開IPを相互に変換する）"], oEn: ["SWG (a cloud-based proxy that mediates web access)", "CASB (visualizes and controls data exfiltration, focused on SaaS usage)", "SD-WAN (controls wide-area networks by software)", "NAT (translates between internal private IPs and public IPs)"], a: 0, e: "アクセス先のURLやIPアドレスから安全性を評価し、安全でなければ遮断するクラウド型プロキシがSWG。CASBはSaaS利用に絞り、SD-WANは経路制御、NATはアドレス変換が役割。", eEn: "A cloud-based proxy that evaluates destination URL or IP safety and blocks unsafe access is an SWG. CASB focuses on SaaS usage, SD-WAN does path control, and NAT does address translation."},
  {d: "IT4", q: "SWGとCASBの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between SWG and CASB?", o: ["SWGはSaaSの利用に絞って可視化・制御しCASBはWebアクセス全般の安全確認と遮断を担う", "SWGは拠点間の経路最適化を担い、CASBはWebアクセス全般を扱う", "SWGはWebアクセス全般を扱い、CASBはSaaSの利用に絞って可視化し、持ち出しを制御する", "どちらも担当範囲は同じで、違いは提供元の製品名だけである"], oEn: ["SWG focuses on SaaS usage visibility and control, while CASB handles safety checks and blocking of web access in general", "SWG handles route optimization between sites, while CASB handles web access in general", "SWG handles web access in general, while CASB focuses on SaaS usage, visualizing it and controlling exfiltration", "Both have the same scope, and the only difference is the vendor's product name"], a: 2, e: "SWGはWebアクセス全般の安全確認と遮断を扱い、CASBはSaaSの利用に絞って可視化し、アクセスやデータの持ち出しを制御する。担当範囲を入れ替えた説明は誤りである。", eEn: "SWG handles safety checks and blocking of web access in general; CASB narrows to SaaS usage, visualizing it and controlling access and data exfiltration. Swapping the scopes is wrong."},
  {d: "IT4", q: "IPAがSWGの機能として挙げるものに含まれないものはどれか。", qEn: "Which of the following is NOT among the functions IPA lists for an SWG?", o: ["Webフィルタリング、DNSフィルタリング", "拠点間の経路の最適化と選択", "DLP、マルウェア検出", "不正侵入防止、サンドボックス"], oEn: ["Web filtering and DNS filtering", "Optimization and selection of routes between sites", "DLP and malware detection", "Intrusion prevention and sandboxing"], a: 1, e: "SWGはWebフィルタリング、DNSフィルタリング、DLP、マルウェア検出、不正侵入防止、サンドボックスなどをクラウド型で提供する。経路の最適化と選択はSD-WANの役割。", eEn: "An SWG provides Web filtering, DNS filtering, DLP, malware detection, intrusion prevention and sandboxing in the cloud. Route optimization and selection is the role of SD-WAN."},
  {d: "IT4", q: "未承認の生成AIサービスも、SaaSの一種として利用の発見、リスク評価、利用制御の対象にしたい。中心になる仕組みはどれか。", qEn: "You want unapproved generative AI services to be subject to discovery, risk evaluation and usage control as a type of SaaS. Which mechanism is central?", o: ["ZTNA（IDと状況を見てアプリ単位できめ細かく接続を許可する）", "FWaaS（FW機能をクラウドサービスとして提供する）", "CASB（SaaSの利用を可視化し、リスク評価と利用制御を行う）", "SD-WAN（経路の最適化と選択を、拠点側の機器が担う）"], oEn: ["ZTNA (permits connections finely per app based on identity and context)", "FWaaS (provides firewall functions as a cloud service)", "CASB (visualizes SaaS usage and performs risk evaluation and usage control)", "SD-WAN (site-side devices optimize and select routes)"], a: 2, e: "SaaSの利用状況の可視化、リスク評価、アクセス制御を担うのはCASB。未承認の生成AIもSaaSの一種として対象にできる。ZTNAは接続許可、FWaaSは通信検査、SD-WANは経路制御。", eEn: "Visualizing SaaS usage, evaluating risk and controlling access is CASB's role, and unapproved generative AI can be covered as a kind of SaaS. ZTNA permits connections, FWaaS inspects traffic, and SD-WAN controls paths."},
  {d: "IT4", q: "IPAがCASBを整理する4要素に含まれないものはどれか。", qEn: "Which of the following is NOT among the four elements by which IPA organizes CASB?", o: ["通信経路の最適化", "可視化", "データセキュリティ", "脅威防御"], oEn: ["Optimization of communication routes", "Visibility", "Data security", "Threat protection"], a: 0, e: "IPAはCASBを可視化・データセキュリティ・コンプライアンス・脅威防御の4要素で整理する。通信経路の最適化はSD-WANなどネットワーク機能の話で、含まれない。", eEn: "IPA organizes CASB into visibility, data security, compliance and threat protection. Route optimization belongs to network functions such as SD-WAN and is not included."},
  {d: "IT4", q: "固定IP、SWG、CASB、ZTNA、SASEの説明として正しいものはどれか。", qEn: "Which of the following correctly describes static IP, SWG, CASB, ZTNA and SASE?", o: ["固定IPは、SWGと同様にアクセス先のURLやIPアドレスの安全性を評価し、危険と判断した通信を遮断してログに残す仕組みである", "ZTNAは、VPNと同様に接続後に広いネットワークへ届くことを特徴とする仕組みである", "SASEは、SWGやCASBなどのセキュリティ機能と、SD-WANなどのネットワーク機能をクラウドで束ねる枠組みである", "CASBは、Webアクセス全般の安全確認を担い、SaaSの可視化は担わない仕組みである"], oEn: ["A static IP is a mechanism that, like SWG, evaluates the safety of the destination URL or IP address, blocks traffic judged dangerous and logs it", "ZTNA is a mechanism that, like VPN, is characterized by reaching a wide network after connecting", "SASE is a framework bundling security functions such as SWG and CASB with network functions such as SD-WAN in the cloud", "CASB handles safety checks for web access in general and does not handle SaaS visibility"], a: 2, e: "SASEはCASBやSWGなどのセキュリティ機能とSD-WANなどのネットワーク機能をクラウドで束ねる枠組み。固定IPは接続元IPを固定するだけで、ZTNAはアプリ単位、CASBはSaaSの可視化を担う。", eEn: "SASE bundles security functions such as CASB and SWG with network functions such as SD-WAN in the cloud. A static IP merely fixes the source IP, ZTNA works per app, and CASB handles SaaS visibility."},
  {d: "IT4", q: "VPN接続後に広い範囲のネットワークへ届いてしまう点が問題になっている。IDと端末の状態やリスクを見て、アプリ単位できめ細かく接続を許可する方式はどれか。", qEn: "A problem is that after a VPN connection a wide network range is reachable. Which approach permits connections finely per app by looking at identity, device state and risk?", o: ["SWG（Webアクセス全般の安全性を評価して遮断する）", "FWaaS（クラウドに置いたFW機能で通信を検査する）", "固定IP（接続元のIPを固定して許可リストで絞る）", "ZTNA（IDと状況に基づく、アプリ単位の接続許可）"], oEn: ["SWG (evaluates the safety of web access in general and blocks)", "FWaaS (inspects traffic with a cloud-placed firewall function)", "Static IP (fixes the source IP and narrows with an allow list)", "ZTNA (per-app connection permission based on identity and context)"], a: 3, e: "IDと状況（端末の状態やリスク）を見てアプリ単位で接続を許可し、常に確認するのがZTNA。SWGはWebアクセス、FWaaSは通信検査、固定IPは接続元の固定で、アプリ単位の許可ではない。", eEn: "ZTNA permits per app by identity and context (device state, risk) and always verifies. SWG covers web access, FWaaS inspects traffic, and static IP fixes the source; none is per-app permission."},
  {d: "IT4", q: "VPNからZTNAへ移行する進め方として、Microsoftが示すものはどれか。", qEn: "Which migration approach from VPN to ZTNA does Microsoft show?", o: ["すべてのアプリを一括でアプリ単位の接続に切り替え、VPNは移行初日に廃止して以後は使わない", "重要でないアプリだけを先にアプリ単位へ切り替え、重要なアプリは広いアクセスのまま残して後回しにする", "VPNと同等のQuick Accessから始め、重要なアプリからアプリ単位の接続へ移す", "SD-WANの拠点機器を全拠点へ先に配り終えてから、その後にZTNAの設定を始める"], oEn: ["Switch all apps to per-app connections at once and retire VPN on day one, never using it again", "Switch only unimportant apps to per-app first and leave important apps with broad access, postponing them", "Start with Quick Access, equivalent to VPN, and move to per-app connections beginning with important apps", "Finish distributing SD-WAN site devices to all sites first, then begin ZTNA configuration"], a: 2, e: "Microsoftは、VPNと同等の広いアクセスを与えるQuick Accessから始め、重要なアプリからアプリ単位の接続へ移す段階的な移行を示している。一括切り替えや順序の逆転ではない。", eEn: "Microsoft shows a staged migration: start with Quick Access, which gives VPN-like broad access, then move important apps first to per-app connections. It is neither all-at-once nor in reversed order."},
  {d: "IT4", q: "AI基盤の管理画面へのリモートアクセスについて、VPNより適した絞り方はどれか。", qEn: "For remote access to the management console of an AI platform, which way of narrowing access is more suitable than VPN?", o: ["アプリ単位かつIDに基づいて接続を許可するZTNAで絞る", "VPNで社内ネットワーク全体へ届くようにして、管理画面も同じ範囲に置く", "接続元の出口IPを固定して、そのIPからの接続はすべて通す", "管理画面のドメインをDNSフィルタリングで許可して、それ以外は確認しない"], oEn: ["Narrow it with ZTNA, which permits connections per app based on identity", "Let VPN reach the whole internal network and place the console in the same range", "Fix the source egress IP and let through every connection from that IP", "Allow the console's domain in DNS filtering and perform no other checks"], a: 0, e: "社内データに接続する生成AIアプリや管理画面へのリモートアクセスは、ZTNAでアプリ単位かつIDに基づいて絞れる。VPNの広い到達範囲やIPだけ、ドメイン許可だけの運用は絞り込みにならない。", eEn: "Remote access to generative AI apps or consoles connected to internal data can be narrowed per app and by identity with ZTNA. VPN's wide reach, IP-only, or domain-allow-only operation does not narrow access."},
  {d: "IT4", q: "リモートやモバイルなど拠点外からの通信、契約したクラウドサービスと外部の通信、私物端末（BYOD）の通信まで、同じセキュリティ設定で保護したい。当てはまるのはどれか。", qEn: "You want to protect, under the same security settings, off-site communications such as remote and mobile, communications between contracted cloud services and the outside, and BYOD devices. Which fits?", o: ["FWaaS", "拠点ごとの物理FW機器", "WAF", "IDS"], oEn: ["FWaaS", "A physical firewall appliance at each site", "WAF", "IDS"], a: 0, e: "拠点外の通信、クラウドサービスと外部の通信、BYODの通信まで同じ設定で保護できるのはクラウド提供のFWaaS。拠点ごとの機器、WAF、IDSではこの範囲を一括で扱えない。", eEn: "Cloud-delivered FWaaS can protect off-site traffic, cloud-to-outside traffic and BYOD under the same settings. Per-site appliances, WAF and IDS cannot handle this range in one place."},
  {d: "IT4", q: "物理的なファイアウォール機器とFWaaSの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between a physical firewall appliance and FWaaS?", o: ["FWaaSは設定と制御が同じ機器で行われ、物理機器はクラウドから提供される", "FWaaSは機能をクラウドに置くため、設置場所に縛られない", "FWaaSはネットワークルールを設定できず、検査だけを行う", "FWaaSは拠点内の通信だけが対象で、リモートやモバイルの通信は対象外である"], oEn: ["FWaaS has configuration and control done on the same device, while physical appliances are provided from the cloud", "FWaaS places the function in the cloud, so it is not tied to an installation location", "FWaaS cannot set network rules and only performs inspection", "FWaaS covers only on-site communication, not remote or mobile traffic"], a: 1, e: "物理機器はネットワークルールの設定と制御が同じ機器で行われる。FWaaSはその機能をクラウドに置くため設置場所に縛られず、リモートやモバイルの通信も同じ設定で扱える。", eEn: "A physical appliance does rule configuration and control on the same device. FWaaS places that function in the cloud, so it is not tied to a location and handles remote and mobile traffic under the same settings."},
  {d: "IT4", q: "SASEとSD-WANの関係として正しいものはどれか。", qEn: "Which statement correctly describes the relationship between SASE and SD-WAN?", o: ["SD-WANはSASEのうち、セキュリティ機能の側を指す", "SD-WANはセキュリティ機能とネットワーク機能をクラウドから提供する上位の枠組みで、SASEはSD-WANに含まれるCASB機能の一部だけを指す", "SASEはセキュリティ機能とSD-WANなどのネットワーク機能をクラウドから提供する枠組みで、SD-WANはそのネットワーク側に位置づく", "SASEはSD-WANだけを指す別名で、SWGやCASBは含まれない"], oEn: ["SD-WAN refers to the security-function side of SASE", "SD-WAN is a higher-level framework delivering security and network functions from the cloud, and SASE refers only to part of the CASB function within SD-WAN", "SASE delivers security functions and network functions such as SD-WAN from the cloud, and SD-WAN sits on its network side", "SASE is another name for SD-WAN alone and does not include SWG or CASB"], a: 2, e: "SASEはCASBやSWGなどのセキュリティ機能と、SD-WANなどのネットワーク機能をクラウドから提供する枠組み。SD-WANはそのネットワーク側で、セキュリティ側を指すのはSSE。", eEn: "SASE is a framework providing security functions such as CASB and SWG and network functions such as SD-WAN from the cloud. SD-WAN is on the network side; the security side is called SSE."},
  {d: "IT4", q: "拠点、データセンター、クラウドに分散した生成AI基盤や業務システムへの経路を、一元的に制御する土台になるものはどれか。", qEn: "What can serve as a foundation for centrally controlling routes to generative AI platforms and business systems distributed across sites, data centers and the cloud?", o: ["CASB（SaaSの利用状況を可視化し、アクセスやデータの持ち出しを制御する仕組みである）", "DNSフィルタリング（名前解決の段階で、悪意のあるドメインをブロックする）", "WAF（公開Webアプリへのリクエストを検査して、典型的な攻撃を防ぐ）", "SD-WAN（拠点側機器が経路を最適化し、IPsecなどでクラウドのハブに接続する）"], oEn: ["CASB (a mechanism that visualizes SaaS usage and controls access and data exfiltration)", "DNS filtering (blocks malicious domains at the name resolution stage)", "WAF (inspects requests to a published web app to stop typical attacks)", "SD-WAN (site devices optimize routes and connect to the cloud hub via IPsec and the like)"], a: 3, e: "広域ネットワークをソフトウェアで制御するSD-WANは、分散した生成AI基盤や業務システムへの経路を一元的に制御する土台になる。拠点側機器が経路の最適化と選択を担う。", eEn: "SD-WAN, which controls wide-area networks by software, can be the base for centrally controlling routes to distributed generative AI platforms and business systems, with site devices optimizing and selecting routes."},
  {d: "IT4", q: "SSEとSASEの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between SSE and SASE?", o: ["SSEはSD-WANなどのネットワーク機能の側を指し、SASEはセキュリティ機能だけをクラウドで束ねた枠組みである", "SSEはセキュリティ機能の側を指し、SASEはSD-WANなどのネットワーク機能も合わせた枠組みである", "SSEはSASEを含む上位概念で、SWGやCASBはSASEにだけ含まれる", "両者は同じ意味で、違いはGartnerとIPAのどちらが呼んだかだけである"], oEn: ["SSE refers to the network-function side such as SD-WAN, while SASE is a framework bundling security functions only in the cloud", "SSE refers to the security-function side, while SASE is a framework that also includes network functions such as SD-WAN", "SSE is a higher-level concept containing SASE, and SWG and CASB are included only in SASE", "They mean the same thing, differing only in whether Gartner or IPA used the term"], a: 1, e: "SSEはセキュリティ機能の側を指し、SASEはSD-WANなどのネットワーク機能も合わせた枠組み。MicrosoftはSSEの機能をSASEの枠組みに組み込む形で説明する。", eEn: "SSE refers to the security-function side; SASE also includes network functions such as SD-WAN. Microsoft explains SSE functions as being built into the SASE framework."},
  {d: "IT4", q: "MicrosoftがSSEを構成する例として挙げる製品のうち、社内リソースへの接続を担う（ZTNAにあたる）ものはどれか。", qEn: "Among the products Microsoft gives as an example of composing SSE, which handles connections to internal resources (the ZTNA part)?", o: ["Entra Private Access", "Entra Internet Access", "Defender for Cloud Apps", "Azure Virtual WAN"], oEn: ["Entra Private Access", "Entra Internet Access", "Defender for Cloud Apps", "Azure Virtual WAN"], a: 0, e: "MicrosoftのSSE例で社内リソースへの接続を担うZTNAはEntra Private Access。IDベースのSWGはEntra Internet Access、CASBはDefender for Cloud Apps。", eEn: "In Microsoft's SSE example, the ZTNA handling connections to internal resources is Entra Private Access; the ID-based SWG is Entra Internet Access and the CASB is Defender for Cloud Apps."},
  {d: "IT4", q: "AI利用の統制をネットワークの入口に集めたい。製品例のGlobal Secure Accessがインターネット向けに機能として挙げる組み合わせはどれか。", qEn: "You want to centralize AI usage control at the network entrance. Which combination does the example product Global Secure Access list as functions for the internet?", o: ["経路の最適化と選択、各拠点をクラウドのハブへ接続するIPsecによる接続の確立を行う", "公開IPを持つリソースへの過負荷攻撃の自動緩和、冗長な設計", "生成AIアプリの利用検出（シャドーAI）、プロンプトインジェクション対策、DLP", "出口IPの固定と、送信元IPの許可リストの管理"], oEn: ["Route optimization and selection, and carrying out the establishment of IPsec connections linking each site to the cloud hub", "Automatic mitigation of overload attacks on resources with public IPs, and redundant design", "Detection of generative AI app usage (shadow AI), prompt injection protection, and DLP", "Fixing egress IPs and managing source IP allow lists"], a: 2, e: "Global Secure Accessはインターネット向けに、生成AIアプリの利用検出（シャドーAI）、プロンプトインジェクション対策、DLPを挙げる。AI利用の統制を入口に集める発想につながる。", eEn: "Global Secure Access lists for the internet detection of generative AI app usage (shadow AI), prompt injection protection and DLP. This leads to the idea of centralizing AI usage control at the entrance."},
  {d: "IT4", q: "セキュリティとネットワークの技術を単一のクラウドプラットフォームに集約し、利用者が場所を問わず使えるようにする、Gartner社が定義したフレームワークはどれか。", qEn: "Which framework, defined by Gartner, consolidates security and network technologies into a single cloud platform so users can use systems from any location?", o: ["SASE（Secure Access Service Edge）", "ZTNA（IDと状況を見て、アプリ単位で接続を許可する方式）", "CASB（SaaSの利用状況の可視化とデータの持ち出しを制御する）", "FWaaS（ファイアウォール機能をクラウドサービスとして提供する）"], oEn: ["SASE (Secure Access Service Edge)", "ZTNA (permits connections per app based on identity and context)", "CASB (visualizes SaaS usage and controls data exfiltration)", "FWaaS (provides firewall functions as a cloud service)"], a: 0, e: "セキュリティとネットワークの技術を単一のクラウドプラットフォームに集約するフレームワークがSASE。ZTNAは接続許可、CASBはSaaS制御、FWaaSはFW機能の提供で、一部を担うにすぎない。", eEn: "The framework that consolidates security and network technologies on a single cloud platform is SASE. ZTNA, CASB and FWaaS are each only parts: connection permission, SaaS control and firewall delivery."},
  {d: "IT4", q: "ゼロトラストとSASEの関係として正しいものはどれか。", qEn: "Which statement correctly describes the relationship between zero trust and SASE?", o: ["ゼロトラストは「暗黙に信頼しない」考え方で、SASEは機能をクラウドで束ねる枠組みである", "ゼロトラストは機能をクラウドで束ねる枠組みを指し、SASEは「暗黙に信頼しない」考え方を指す", "両者は排他的な関係にあり、SASEを導入するとゼロトラストの考え方は不要になる", "ゼロトラストはSASEのうち、セキュリティ機能の側を指す名称である"], oEn: ["Zero trust is the idea of 'never implicitly trust', and SASE is a framework bundling functions in the cloud", "Zero trust is a framework bundling functions in the cloud, and SASE is the idea of 'never implicitly trust'", "They are mutually exclusive, and adopting SASE makes the zero trust idea unnecessary", "Zero trust is the name for the security-function side of SASE"], a: 0, e: "ゼロトラストは考え方、SASEは機能をクラウドで束ねる枠組みで、Microsoftは両者を組み合わせて説明する。セキュリティ機能の側を指すのはSSEで、ゼロトラストではない。", eEn: "Zero trust is an idea and SASE is a framework bundling functions in the cloud; Microsoft explains them together. The security-function side is SSE, not zero trust."},
  {d: "IT4", q: "SASEを導入済みなのに、一部の端末から生成AIへの通信が検知できていない。まず確認すべきことはどれか。", qEn: "SASE is deployed, yet traffic to generative AI from some devices is not detected. What should be checked first?", o: ["生成AIの提供元が、送信元IPの許可リストを用意しているか", "NATの出口IPで使えるポートが、足りているか", "WAFがL7の攻撃を遮断する設定になっているか", "その通信がSASEを経由する構成になっているか"], oEn: ["Whether the generative AI provider has prepared a source IP allow list", "Whether the ports available on the NAT egress IP are sufficient", "Whether the WAF is set to block L7 attacks", "Whether that traffic is configured to go through SASE"], a: 3, e: "生成AIへの通信を統制するには、その通信がSASEを経由する構成にする必要がある。IPAの検証でも、SASEを通らない通信は検知できないという気づきが示された。", eEn: "To control traffic to generative AI, that traffic must be configured to go through SASE. IPA's verification also showed that traffic bypassing SASE cannot be detected."},
  {d: "IT4", q: "シャドーAIとシャドーITの違いとして正しいものはどれか。", qEn: "Which statement correctly describes the difference between shadow AI and shadow IT?", o: ["シャドーAIはITサービス全般の無許可利用を指し、主なリスクはデータの散逸。シャドーITは生成AIアプリやツールに限った無許可利用で、主なリスクはAIへのデータ漏えいやコンプライアンス違反", "どちらも生成AIに限った話で、違いは利用者が社内か社外かだけである", "シャドーAIは生成AIアプリやツールに限った無許可利用で、主なリスクはAIへのデータ漏えいやコンプライアンス違反。シャドーITはITサービス全般で、データの散逸が主なリスク", "シャドーAIは許可済みの生成AIの過剰利用で、シャドーITは許可済みサービスの障害である"], oEn: ["Shadow AI is unauthorized use of IT services in general, mainly risking data sprawl; shadow IT is unauthorized use limited to generative AI apps and tools, mainly risking data leakage to AI and compliance violations", "Both are limited to generative AI, differing only in whether the user is internal or external", "Shadow AI is unauthorized use limited to generative AI apps and tools, mainly risking data leakage to AI and compliance violations; shadow IT covers IT services in general, mainly risking data sprawl", "Shadow AI is overuse of approved generative AI, while shadow IT is failure of approved services"], a: 2, e: "シャドーAIは生成AIに限った無許可利用でAIへのデータ漏えいやコンプライアンス違反が主なリスク。シャドーITはITサービス全般で、データの散逸が主なリスクとなる。", eEn: "Shadow AI is unauthorized use limited to generative AI, mainly risking data leakage to AI and compliance violations. Shadow IT covers IT services generally, mainly risking data sprawl."},
  {d: "IT4", q: "利用中のアプリを洗い出し、リスクを評価し、承認・非承認に分けて管理している。非承認のアプリを止める手段として、Defender for Cloud Appsの例で挙げられているのはどれか。", qEn: "Apps in use are identified, risk-evaluated, and managed as approved or unapproved. In the Defender for Cloud Apps example, which means is given for stopping unapproved apps?", o: ["ファイアウォール、プロキシ、SWGなどの出口の仕組みでブロックする", "NATの出口IPを増やして、非承認アプリの通信を分散させる", "IDSで検知して、管理者に知らせるだけにとどめる", "SD-WANの経路を切り替えて、非承認アプリへの通信経路を使わせないようにする"], oEn: ["Block with egress mechanisms such as a firewall, a proxy or an SWG", "Increase NAT egress IPs to spread unapproved app traffic", "Detect with IDS and only notify the administrator", "Switch SD-WAN routes so that the communication path to unapproved apps is not used"], a: 0, e: "Defender for Cloud Appsの例では、非承認のアプリはファイアウォール、プロキシ、SWGでブロックする。NATの出口IP、IDSの通知、SD-WANの経路切り替えは、止める手段として挙げられていない。", eEn: "In the Defender for Cloud Apps example, unapproved apps are blocked with a firewall, proxy or SWG. NAT egress IPs, IDS notifications and SD-WAN route switching are not given as means to stop them."},
  {d: "IT4", q: "ChatGPTやClaudeなどへの通信をネットワーク通信の分析から見つけ、利用者や通信量、リスクスコアを可視化できた。その後の進め方として適切なのはどれか。", qEn: "Traffic to ChatGPT, Claude and others was found from network traffic analysis, and users, volumes and risk scores were visualized. What is an appropriate way to proceed?", o: ["検出された生成AIはすべて直ちに全面禁止し、代替手段は何も用意しない", "禁止だけで終わらせず、承認済みの代替手段を用意することと一体で進める", "リスクスコアが高い利用者だけを対象にして、通信量は評価に使わない", "利用が確認できた生成AIを、審査せずに承認済みとして扱う"], oEn: ["Immediately and fully prohibit all detected generative AI and prepare no alternatives whatsoever", "Do not stop at prohibition; proceed together with preparing approved alternatives", "Target only users with high risk scores and not use traffic volume in evaluation", "Treat the confirmed generative AI as approved without review"], a: 1, e: "シャドーAIの検出は、利用者や通信量、リスクスコアを可視化できる。進め方は禁止だけで終わらせず、承認済みの代替手段の用意と一体にする。審査なしの承認や一律の禁止は適切でない。", eEn: "Shadow AI detection can visualize users, volumes and risk scores. The approach should not end at prohibition but go together with preparing approved alternatives. Approving without review or blanket bans is inappropriate."},
  {d: "IT4", q: "メールで届いた未知のサイトのリンクを、悪意あるコードを利用者の端末で動かさずに閲覧させたい。まず当てるべき仕組みはどれか。", qEn: "Users must open a link to an unknown site from an email without running any malicious code on their own devices. Which mechanism should be applied first?", o: ["SWG（アクセス先を評価して通信を許可し、描画は端末のブラウザで行う）", "CASB（SaaSの利用を可視化し、データの持ち出しを制御する）", "RBI（閲覧処理を隔離環境で実行し、描画結果だけを端末に送る）", "SD-WAN（拠点側の機器が経路を最適化して選択する）"], oEn: ["SWG (evaluates the destination and permits the traffic, while rendering happens in the device's browser)", "CASB (visualizes SaaS use and controls data exfiltration)", "RBI (runs browsing in an isolated environment and sends only the rendered result to the device)", "SD-WAN (branch-side equipment optimizes and selects the route)"], a: 2, e: "RBIは描画とJavaScriptの実行を隔離環境で行い、端末には画面の映像だけを届ける。SWGは通信の許可と遮断を決める仕組みで描画は端末側のまま。CASBはSaaS利用の制御、SD-WANは経路の制御で目的が異なる。", eEn: "RBI performs rendering and JavaScript execution in an isolated environment and delivers only a screen image to the device. SWG decides to allow or block traffic, but rendering stays on the device. CASB controls SaaS use and SD-WAN controls routes, so neither fits."},
  {d: "IT4", q: "SWGとRBIの違いとして正しいものはどれか。", qEn: "Which statement about the difference between SWG and RBI is correct?", o: ["SWGは通信を検査して許可と遮断を決め、RBIは悪意あるコードを端末で動かさない", "RBIは通信を検査して許可と遮断を決め、SWGは閲覧処理を隔離環境で実行する", "SWGは手元のブラウザに制御を入れ、RBIは通信をプロキシに通さずに端末へ届ける", "SWGは描画結果だけを端末に送り、RBIはSaaSの利用を可視化して持ち出しを制御する"], oEn: ["SWG inspects traffic to decide allow or block, while RBI keeps malicious code from running on the device", "RBI inspects traffic to decide allow or block, while SWG runs browsing in an isolated environment", "SWG builds controls into the local browser, while RBI delivers traffic to the device without passing it through a proxy", "SWG sends only the rendered result to the device, while RBI visualizes SaaS use and controls exfiltration"], a: 0, e: "SWGは通信を検査して許可と遮断を判断し、RBIは実行場所を隔離環境に移して悪意あるコードを端末で動かさない。他の選択肢は役割の入れ替えや、CASB・セキュアブラウザの特徴の取り違えである。", eEn: "SWG inspects traffic and decides allow or block, while RBI moves execution to an isolated environment so malicious code never runs on the device. The others swap the roles or confuse them with CASB and secure browser traits."},
  {d: "IT4", q: "RBIで、利用者の端末に届くものと隔離側へ転送されるものの組み合わせとして正しいものはどれか。", qEn: "In RBI, which combination of what reaches the user's device and what is forwarded to the isolated side is correct?", o: ["端末にはHTMLとJavaScriptが届いて描画され、入力だけが隔離側へ転送される", "端末にはJavaScriptの実行結果が届き、クリックは端末側のブラウザが処理する", "端末には画面の映像だけが届き、キー入力やクリックは端末側で処理される", "端末には画面の映像だけが届き、キー入力やクリックは隔離側へ転送される"], oEn: ["HTML and JavaScript reach the device and are rendered there, and only inputs are forwarded to the isolated side", "The results of JavaScript execution reach the device, and clicks are handled by the device's browser", "Only a screen video reaches the device, and keystrokes and clicks are handled on the device", "Only a screen video reaches the device, and keystrokes and clicks are forwarded to the isolated side"], a: 3, e: "ページの描画とJavaScriptの実行は隔離環境のブラウザが担い、端末には映像（ピクセルストリーム）だけが届く。キー入力やクリックは隔離側へ転送される。誤りは、コードや入力の処理場所が逆の組み合わせである。", eEn: "The isolated browser handles rendering and JavaScript execution, and only a pixel stream reaches the device, while keystrokes and clicks are forwarded to the isolated side. The wrong options reverse where code or input is handled."},
  {d: "IT4", q: "AIが示した未知の外部サイトの閲覧にRBIを使う。それだけでは足りない点として正しいものはどれか。", qEn: "RBI is used to browse unknown external sites suggested by AI. Which point shows what RBI alone does not cover?", o: ["描画が端末側で行われるため、悪意あるJavaScriptが端末で動く", "映像を通じた情報の出入りは残るため、DLPなどとの併用が要る", "生成AIアプリの利用検出ができないため、CASBへの置き換えが要る", "実行場所はクラウド型に限られるため、オンプレミスでは使えない"], oEn: ["Rendering takes place on the device, so malicious JavaScript still runs there", "Information can still move in and out through the video, so it must be combined with DLP and similar controls", "It cannot detect generative AI app use, so it must be replaced with CASB", "Its execution location is limited to the cloud type, so it cannot be used on premises"], a: 1, e: "RBIは悪意あるコードを端末で動かさないが、映像経由の情報の出入りは残るためDLPなどと併用する。描画は隔離側で行われ、実行場所はクラウド型・オンプレミス型・ローカル型から選べる。", eEn: "RBI keeps malicious code off the device, but information can still pass through the video, so it is paired with DLP. Rendering happens on the isolated side, and the execution location can be cloud, on-premises or local."},
  {d: "IT4", q: "利用中のSaaSの設定ミスや不備を継続的に見つけ、改善の手順まで示したい。当てるべき仕組みはどれか。", qEn: "The organization wants to continuously find misconfigurations and weaknesses in the SaaS it uses and be shown how to fix them. Which mechanism should be applied?", o: ["SSPM（SaaSの設定を継続的に評価し、改善の手順を示す）", "CASB（SaaSの利用を可視化し、データの持ち出しを制御する）", "CSPM（クラウド基盤の設定を評価する）", "SWG（Webアクセス全般の安全性を確認し、遮断する）"], oEn: ["SSPM (continuously evaluates SaaS settings and shows how to improve them)", "CASB (visualizes SaaS use and controls data exfiltration)", "CSPM (evaluates the configuration of the cloud infrastructure)", "SWG (checks the safety of web access in general and blocks it)"], a: 0, e: "SSPMはSaaSアプリの設定を継続的に評価し、不備を見つけて改善手順を示す。CASBは利用や操作の制御、CSPMはクラウド基盤の設定、SWGはWebアクセスの遮断が役割で、SaaSの設定評価ではない。", eEn: "SSPM continuously evaluates SaaS app settings, finds weaknesses and shows how to fix them. CASB controls use and operations, CSPM covers cloud infrastructure settings, and SWG blocks web access, none of which evaluate SaaS settings."},
  {d: "IT4", q: "CASBとSSPMの違いとして正しいものはどれか。", qEn: "Which statement about the difference between CASB and SSPM is correct?", o: ["CASBは各SaaSの設定そのものの安全性を評価し、SSPMはSaaSの利用や操作を監視・制御する", "CASBはSaaSの利用や操作を監視・制御し、SSPMは各SaaSの設定そのものの安全性を評価する", "CASBはクラウド基盤の設定を評価し、SSPMはWebアクセス全般を遮断する", "CASBはSaaSの設定を評価対象とし、SSPMは通信をリバースプロキシで経由させる"], oEn: ["CASB evaluates the settings of each SaaS themselves, while SSPM monitors and controls SaaS use and operations", "CASB monitors and controls SaaS use and operations, while SSPM evaluates the safety of each SaaS's settings themselves", "CASB evaluates cloud infrastructure settings, while SSPM blocks web access in general", "CASB evaluates SaaS settings, while SSPM routes traffic through a reverse proxy"], a: 1, e: "CASBは利用や操作の可視化と制御、SSPMは設定そのものの評価を担う。SSPMはクラウド基盤の設定を見るCSPMの考え方をSaaSに当てたもので、通信の経由やWebアクセスの遮断は担わない。", eEn: "CASB visualizes and controls use and operations, while SSPM evaluates the settings themselves. SSPM applies the CSPM idea of checking cloud infrastructure settings to SaaS, and it does not route traffic or block web access."},
  {d: "IT4", q: "SaaSをコネクタで接続したSSPMで、設定の評価結果はどのように示されるか。Defender for Cloud Appsの例で答えよ。", qEn: "In SSPM with SaaS connected through connectors, how are the settings evaluation results presented? Answer using the Defender for Cloud Apps example.", o: ["90以上の指標によるアプリごとのリスク評価として示され、自動で遮断される", "非承認と判定されたアプリの一覧として示され、境界の機器で遮断される", "通信ログの検知件数として示され、DLPのポリシー違反の数で確認できる", "推奨事項として示され、Secure Scoreで確認できる"], oEn: ["They are shown as per-app risk ratings from more than 90 indicators and are blocked automatically", "They are shown as a list of apps judged unsanctioned and are blocked by perimeter devices", "They are shown as detection counts in communication logs and checked by the number of DLP policy violations", "They are shown as recommendations and can be checked in Secure Score"], a: 3, e: "SaaSをコネクタで接続すると、設定の評価結果が推奨事項として示され、Secure Scoreで確認できる。90以上の指標でのリスク評価は利用中SaaSの特定に関わるCASB側の機能で、自動遮断の説明も誤りである。", eEn: "Once SaaS is connected through connectors, evaluation results appear as recommendations that can be checked in Secure Score. Risk rating with more than 90 indicators belongs to identifying SaaS in use on the CASB side, and automatic blocking is not what is described."},
  {d: "IT4", q: "AI基盤のAPIを公開する。有効なトークンを持つ呼び出し元だけを通し、流量も制限してバックエンドを守る入口として適切なものはどれか。", qEn: "An AI platform's API is to be exposed. Which entry point passes only callers with a valid token and also limits traffic to protect the backend?", o: ["WAFだけを置き、攻撃パターンの検査で呼び出し元の認証・認可を代替する", "購読キーを認証手段として頼り、キーを持つ呼び出し元をすべて通す", "APIゲートウェイでJWTを検証し、レート制限やクォータを適用する", "SWGを経由させ、Webフィルタリングで呼び出し元を判別する"], oEn: ["Place only a WAF and let attack-pattern inspection replace caller authentication and authorization", "Rely on subscription keys for authentication and let every caller holding a key through", "Use an API gateway to validate JWTs and apply rate limits and quotas", "Route calls through an SWG and identify callers by web filtering"], a: 2, e: "APIゲートウェイでJWTを検証して有効なトークンの呼び出し元だけを通し、レート制限やクォータでバックエンドを守る。WAFは攻撃パターンの検査が役割で、購読キーは認証手段として頼らない。", eEn: "An API gateway validates JWTs to admit only callers with valid tokens and protects the backend with rate limits and quotas. A WAF inspects attack patterns, and subscription keys should not be relied on for authentication."},
  {d: "IT4", q: "WAFとAPIゲートウェイの違いと配置として正しいものはどれか。", qEn: "Which statement about the difference between a WAF and an API gateway, and how they are placed, is correct?", o: ["WAFは認証・認可と利用量の制御が中心で、APIゲートウェイは攻撃パターンを検査し、ゲートウェイの後段にWAFを置く構成が推奨される", "WAFが呼び出し元の認証・認可を担うので、APIゲートウェイは不要であり、どちらか一方を置けば足りる", "WAFは攻撃パターンを検査し、APIゲートウェイは認証・認可と利用量の制御が中心で、ゲートウェイの前段にWAFを置く構成が推奨される", "APIゲートウェイは攻撃パターンの検査が中心で、レート制限は行えず、WAFの前段に置く構成が推奨される"], oEn: ["A WAF centers on authentication, authorization and usage control, while an API gateway inspects attack patterns, and placing the WAF behind the gateway is recommended", "A WAF handles caller authentication and authorization, so an API gateway is unnecessary and either one is enough", "A WAF inspects attack patterns, while an API gateway centers on caller authentication, authorization and usage control, and placing the WAF in front of the gateway is recommended", "An API gateway centers on attack-pattern inspection and cannot rate limit, and placing it in front of the WAF is recommended"], a: 2, e: "WAFはWebアプリへの攻撃パターンを検査し、APIゲートウェイは呼び出し元の認証・認可と利用量の制御が中心。ゲートウェイの前段にWAFを置く構成が推奨され、両者は代替関係ではない。", eEn: "A WAF inspects attack patterns aimed at web apps, while an API gateway centers on caller authentication, authorization and usage control. Putting the WAF in front of the gateway is recommended, and the two are not substitutes."},
  {d: "IT4", q: "AI向けゲートウェイ（Azure API Managementの例）でできることとして正しいものはどれか。", qEn: "Which statement about what an AI gateway (the Azure API Management example) can do is correct?", o: ["マネージドIDで認証してAPIキーを不要にし、トークン使用量の上限設定や、プロンプトと応答のログ取得ができる", "APIキーを全呼び出し元に配布して認証する形になり、トークン使用量の上限設定もプロンプトと応答のログ取得もできない", "プロンプトの機微情報を自動で取り除く一方で、プロンプトと応答のログは取得できない", "生成AIへの通信をSASE経由に切り替え、拠点間の経路を最適化する"], oEn: ["It authenticates with a managed identity so API keys are unnecessary, and can set token usage limits and log prompts and responses", "It authenticates by distributing API keys to all callers, and token usage limits cannot be set", "It automatically strips sensitive information from prompts, but prompts and responses cannot be logged", "It switches traffic to generative AI over to SASE and optimizes routes between sites"], a: 0, e: "AI向けゲートウェイは、マネージドIDで認証してAPIキーを不要にし、トークン使用量の上限設定やプロンプトと応答のログ取得ができる。経路の最適化はSD-WANの役割で、ゲートウェイの機能ではない。", eEn: "An AI gateway authenticates with a managed identity so API keys are not needed, and can set token usage limits and log prompts and responses. Route optimization is the role of SD-WAN, not the gateway."},
  {d: "IT4", q: "SaaS利用の遅延と社内回線の負荷を減らすため、拠点やテレワーク端末の通信を本社に集めず、利用者に近い出口から直接出したい。当てはまる構成はどれか。", qEn: "To reduce SaaS latency and the load on the corporate line, the organization wants branch and remote-work traffic to exit directly near the user instead of being gathered at headquarters. Which design fits?", o: ["VPNによる本社集約（通信をいったん本社へ戻して、検査を一か所に集約する）", "ローカルブレイクアウト（最寄りの入口から直接インターネットへ送る）", "RBI（閲覧処理を隔離環境で実行して映像だけを送る）", "テナント制限（外部アカウントのサインインを既定で拒否する）"], oEn: ["Consolidation at headquarters over VPN (returns traffic to headquarters and centralizes inspection)", "Local breakout (sends traffic directly to the internet from the nearest entry point)", "RBI (runs browsing in an isolated environment and sends only the video)", "Tenant restrictions (denies sign-in with external accounts by default)"], a: 1, e: "ローカルブレイクアウトは、通信を中央拠点に集めず利用者に近い出口から直接インターネットへ送り、SaaS利用の遅延と社内回線の負荷を減らす。VPNでの本社集約は逆に遅延が増える。", eEn: "Local breakout sends traffic directly to the internet from an exit near the user instead of a central site, reducing SaaS latency and corporate line load. Backhauling over VPN to headquarters does the opposite and adds latency."},
  {d: "IT4", q: "VPNで本社へ戻す構成と比べた、ローカルブレイクアウトの特徴として正しいものはどれか。", qEn: "Compared with returning traffic to headquarters over VPN, which statement describes local breakout correctly?", o: ["検査を本社に集約できる代わりに遅延が増えるので、SWGやCASBなどで補う設計にもなる", "遅延を抑えつつ、本社のプロキシで全通信を検査できるので、ほかの対策を足す必要はない", "検査の位置は変わらないが、DNSの名前解決は本社で行う必要があり、遅延の改善は小さい", "遅延を抑えられる代わりに検査の位置が分散するので、SWGやCASBなどで補う設計になる"], oEn: ["Inspection can be centralized at headquarters but latency increases, so the design is complemented with SWG, CASB and similar", "Latency is reduced while headquarters' proxy still inspects all traffic, so no other measures need to be added", "The inspection location does not change, but DNS resolution must be done at headquarters, so the latency gain is small", "Latency is reduced but inspection becomes distributed, so the design is complemented with SWG, CASB and similar"], a: 3, e: "ローカルブレイクアウトは遅延を抑える代わりに検査の位置が分散し、SWGやCASBなどで補う設計になる。検査を集約できるが遅延が増えるのはVPNで本社へ戻す構成の特徴である。DNSの名前解決も近くで行う。", eEn: "Local breakout lowers latency but distributes inspection, so SWG, CASB and similar controls complement it. Centralized inspection with higher latency is the trait of the VPN-to-headquarters design, and DNS resolution is also done nearby."},
  {d: "IT4", q: "ローカルブレイクアウトを採る環境で、生成AIサービスへの通信のDLPをどう設計すべきか。", qEn: "In an environment using local breakout, how should DLP for traffic to generative AI services be designed?", o: ["出口の設計と併せて、どこで検査とDLPを効かせるかを決める", "本社経由の検査がなくなるため、生成AIへの通信にDLPは不要になると判断する", "本社経由と同じ検査が自動で効くため、設計は変えない", "検査は端末側の対策だけで補い、クラウド側では行わない"], oEn: ["Decide where to apply inspection and DLP together with the design of the exit", "Judge DLP unnecessary because inspection via headquarters disappears", "Leave the design unchanged because the same inspection as via headquarters applies automatically", "Compensate with device-side measures only and do not perform it on the cloud side"], a: 0, e: "生成AIへの通信も、本社経由かローカル出口かで遅延と検査位置が変わる。中央の検査を通らない分は端末側とクラウド側の対策で補うため、出口の設計と併せて検査とDLPを効かせる場所を決める。", eEn: "For generative AI traffic too, latency and inspection location change depending on headquarters routing or a local exit. What bypasses central inspection is covered by device-side and cloud-side measures, so the DLP location is decided with the exit design."},
  {d: "IT4", q: "利用者がSaaSをブラウザで使っている最中に、ダウンロードをその場で遮断したい。CASBの接続方式として適しているものはどれか。", qEn: "The organization wants to block a download on the spot while a user is using SaaS in a browser. Which CASB connection method fits?", o: ["API連携型（SaaS提供元のAPIに接続し、ブラウザ操作中の通信をその場で確実に遮断する）", "ローカルブレイクアウト（最寄りの出口から直接インターネットへ送る）", "リバースプロキシ型（条件付きアクセスと連携して通信を経由させ、セッション中に制御する）", "SSPM（SaaSの設定を評価して推奨事項を示す）"], oEn: ["API connector type (connects to the SaaS provider's API and blocks traffic during the session)", "Local breakout (sends traffic directly to the internet from the nearest exit)", "Reverse proxy type (routes traffic through it in coordination with Conditional Access and controls the session)", "SSPM (evaluates SaaS settings and shows recommendations)"], a: 2, e: "セッション中の即時制御はリバースプロキシ型の役割で、条件付きアクセスと連携して通信を経由させ、ダウンロード遮断などを行う。API連携型は接続したSaaSの状態や操作の把握が中心で、通信そのものは止めない。", eEn: "Immediate control during a session is the reverse proxy type's role: it routes traffic in coordination with Conditional Access and blocks downloads. The API type mainly grasps the state and operations of the connected SaaS and does not stop the traffic itself."},
  {d: "IT4", q: "API連携型のCASBでSaaSの全ファイルを走査したところ、完了までに時間がかかった。その理由として正しいものはどれか。", qEn: "Scanning all files of a SaaS with an API connector type CASB took a long time to complete. Which reason is correct?", o: ["通信をリバースプロキシ経由にするため、利用者のセッションごとに遅延が生じ、走査も遅くなる", "ネイティブのクライアントが対象外になるため、走査が途中で止まる", "条件付きアクセスの評価が毎回エッジで実行され、完了を待つことになる", "SaaS提供元のAPI制限のため、全ファイルの走査に数時間から数日かかることがある"], oEn: ["Because traffic goes through a reverse proxy, delay occurs in every session", "Because native clients are out of scope, the scan stops partway", "Because Conditional Access evaluation runs at the edge each time, the scan has to wait for completion", "Because of the SaaS provider's API limits, scanning all files can take hours to days"], a: 3, e: "API連携型はSaaS提供元のAPIで可視性と制御を得るが、API制限のため全ファイルの走査に数時間から数日かかることがある。通信の経由やネイティブクライアントの扱いはプロキシ型に関する話である。", eEn: "The API connector type gains visibility and control through the SaaS provider's API, but API limits can make a full file scan take hours to days. Traffic routing and native clients concern the proxy type."},
  {d: "IT4", q: "リバースプロキシ型のCASBの制約として正しいものはどれか。", qEn: "Which statement about a limitation of a reverse proxy type CASB is correct?", o: ["API制限のため、全ファイルの走査に数時間から数日かかる", "ブラウザ操作が対象のため、ネイティブのクライアントは対象外になりうる", "接続したSaaSの状態は把握できるが、セッション中の即時制御はできない", "ブラウザ以外のクライアントは常に制御できるが、ブラウザ操作は対象外である"], oEn: ["Because of API limits, scanning all files takes hours to days", "It targets browser operations, so native clients may be out of scope", "It can grasp the state of the connected SaaS but cannot control a session immediately", "It can always control non-browser clients, but browser operations are out of scope"], a: 1, e: "プロキシ型はセッション中の即時制御が強みだが、ブラウザ操作が対象で、ネイティブのクライアントは対象外になりうる。API制限による走査時間や即時制御の不可はAPI型の特徴である。", eEn: "The proxy type excels at immediate control during sessions, but it targets browser operations, so native clients may be out of scope. Scan time due to API limits and the lack of immediate control are traits of the API type."},
  {d: "IT4", q: "SaaS型の生成AIについて、設定や共有の状況の確認とアップロードの遮断を、CASBの接続方式でどう分担するか。正しいものはどれか。", qEn: "For SaaS-type generative AI, how are checking settings and sharing status and blocking uploads divided between CASB connection methods? Which is correct?", o: ["設定や共有の確認はリバースプロキシだけで行い、アップロードの遮断はAPIでの接続だけで行い、対応可否は製品ごとに必ず確認する", "どちらもAPI連携型だけで実現できるので、製品ごとの対応可否の確認は不要であり、すぐに導入できる", "設定や共有の確認はAPIでの接続で、アップロードの遮断はブラウザ利用でのセッション制御で検討し、対応可否は製品ごとに確認する", "どちらもブラウザでのセッション制御だけで実現でき、APIでの接続は生成AIには使えないと判断する"], oEn: ["Checking settings and sharing is done through a reverse proxy, and blocking uploads through API connection, with support confirmed per product", "Both can be achieved with the API connector type alone, so checking per-product support is unnecessary and it can be introduced right away", "Checking settings and sharing is considered through API connection, and blocking uploads through session control for browser use, with support confirmed per product", "Both can be achieved with browser session control alone, and API connection is judged unusable for generative AI"], a: 2, e: "APIで接続できれば設定や共有の状況を確認でき、ブラウザ利用ならアップロード遮断などのセッション制御を検討できる。対応可否は製品ごとに確認する必要があり、方式の役割を入れ替えた選択肢は誤りである。", eEn: "If it can connect over the API, settings and sharing status can be checked, and for browser use session control such as upload blocking can be considered. Support must be confirmed per product, and options swapping the methods' roles are wrong."},
  {d: "IT4", q: "BYODや委託先の端末で、別のプロキシを通さずに、ブラウザの内側でコピーと貼り付けやアップロードを制御したい。当てはまる方式はどれか。", qEn: "On BYOD and contractor devices, the organization wants to control copy and paste and uploads inside the browser without passing through a separate proxy. Which approach fits?", o: ["セキュアブラウザ（業務用ブラウザにセキュリティ制御を組み込む）", "RBI（閲覧処理を隔離環境で実行して映像だけを送る）", "リバースプロキシ型CASB（通信を経由させてセッション中に制御する）", "FWaaS（通信をクラウドのエッジに集めて同一のポリシーで検査する）"], oEn: ["Secure browser (builds security controls into the business browser)", "RBI (runs browsing in an isolated environment and sends only the video)", "Reverse proxy CASB (routes traffic through it and controls the session)", "FWaaS (gathers traffic at the cloud edge and inspects it under a single policy)"], a: 0, e: "セキュアブラウザは業務用ブラウザ自体に制御を組み込み、通信を別のプロキシに通さずブラウザの内側で操作を管理する。RBIは実行場所の隔離、リバースプロキシ型CASBとFWaaSは通信を経由させる方式である。", eEn: "A secure browser builds controls into the business browser and manages operations inside the browser without passing traffic through another proxy. RBI isolates the execution location, while reverse proxy CASB and FWaaS route traffic through them."},
  {d: "IT4", q: "RBIとセキュアブラウザの違いとして正しいものはどれか。", qEn: "Which statement about the difference between RBI and a secure browser is correct?", o: ["RBIは手元のブラウザに制御を入れ、セキュアブラウザは閲覧の実行場所を隔離環境へ移す", "どちらも画面の映像だけを端末に送り、違いは隔離環境がクラウドかローカルかだけである", "RBIはブラウザ内でコピーや印刷を管理し、セキュアブラウザは通常プロキシで全Web通信を分離基盤に通す", "RBIは閲覧の実行場所を隔離環境へ移し、セキュアブラウザは手元のブラウザに制御を入れる"], oEn: ["RBI puts controls into the local browser, while a secure browser moves the browsing execution location to an isolated environment", "Both send only a screen video to the device, and the only difference is whether the isolated environment is cloud or local", "RBI manages copying and printing inside the browser, while a secure browser normally passes all web traffic through an isolation platform via a proxy", "RBI moves the browsing execution location to an isolated environment, while a secure browser puts controls into the local browser"], a: 3, e: "RBIは閲覧の実行場所を隔離環境へ移し、セキュアブラウザは手元のブラウザ自体に制御を入れる。他の選択肢は両者の特徴を入れ替えたもの、または両方を映像送信方式と取り違えたものである。", eEn: "RBI moves the execution location of browsing to an isolated environment, while a secure browser puts controls into the local browser itself. The other options swap their traits or mistake both for video-streaming approaches."},
  {d: "IT4", q: "Microsoftが、リバースプロキシと比べたセキュアブラウザの利点として説明しているものはどれか。", qEn: "What does Microsoft describe as an advantage of a secure browser compared with a reverse proxy?", o: ["ネイティブのクライアントの操作も含め、すべてのSaaSを走査できる", "遅延やアプリ互換の問題を避けられる", "API制限の影響を受けずに、全ファイルを即時に走査できる", "閲覧処理がクラウドの隔離環境で動くので、端末にコードが届かない"], oEn: ["It can scan every SaaS, including operations from native clients", "It can avoid latency and application compatibility problems", "It scans all files immediately, unaffected by API limits", "Browsing runs in a cloud isolation environment, so no code reaches the device"], a: 1, e: "Microsoftは、リバースプロキシに比べて遅延やアプリ互換の問題を避けられると説明する。閲覧処理を隔離環境で動かすのはRBIの特徴で、セキュアブラウザは手元のブラウザに制御を入れる。", eEn: "Microsoft explains that, compared with a reverse proxy, a secure browser avoids latency and application compatibility problems. Running browsing in an isolated environment is an RBI trait, whereas a secure browser puts controls into the local browser."},
  {d: "IT4", q: "従業員が自社のネットワークから、個人や外部組織のアカウントでSaaSにサインインしてしまう。許可する取引先のテナントだけを例外に、それ以外を既定で拒否したい。当てはまる仕組みはどれか。", qEn: "Employees sign in to SaaS from the company network with personal or external-organization accounts. The organization wants to deny everything by default and allow only partner tenants as exceptions. Which mechanism fits?", o: ["固定IP（SaaS側で接続元のIPアドレスを絞り、サインインするアカウントの種類は問わない）", "SSPM（SaaSの設定を継続的に評価して推奨事項を示す）", "テナント制限（クロステナントアクセス設定で外部アカウントを既定でブロックする）", "ローカルブレイクアウト（最寄りの出口から直接インターネットへ送る）"], oEn: ["Fixed IP (narrows the source IP address on the SaaS side)", "SSPM (continuously evaluates SaaS settings and shows recommendations)", "Tenant restrictions (block external accounts by default through cross-tenant access settings)", "Local breakout (sends traffic directly to the internet from the nearest exit)"], a: 2, e: "テナント制限は、許可する外部テナントだけを指定してそれ以外を既定で拒否する。Entra IDの例では、クロステナントアクセス設定で外部アカウントと外部アプリを既定でブロックし、取引先などを例外にする。", eEn: "Tenant restrictions specify only the external tenants to allow and deny the rest by default. In the Entra ID example, cross-tenant access settings block external accounts and apps by default, with partners as exceptions."},
  {d: "IT4", q: "固定IPによる制限とテナント制限の違いとして正しいものはどれか。", qEn: "Which statement about the difference between fixed-IP restriction and tenant restrictions is correct?", o: ["固定IPは自組織の端末から外部のアカウントのサインインを既定で拒否し、テナント制限はSaaS側で接続元のIPアドレスだけを一律に絞る", "固定IPはSaaS側で接続元を絞り、テナント制限は自組織の端末やネットワークから、どのテナントのアカウントでサインインできるかを絞る", "どちらもSaaS側で接続元のIPアドレスを絞る点は同じで、テナント制限は個人アカウントだけが対象になる", "固定IPはサインインできるテナントを絞り、テナント制限は端末のWebアクセス全般を遮断する"], oEn: ["Fixed IP denies external-account sign-in from the organization's devices by default, while tenant restrictions narrow the source IP address on the SaaS side", "Fixed IP narrows the source on the SaaS side, while tenant restrictions narrow which tenants' accounts can sign in from the organization's own devices and network", "Both narrow the source IP address on the SaaS side, and tenant restrictions cover only personal accounts", "Fixed IP narrows which tenants can be signed in to, while tenant restrictions block web access in general from devices"], a: 1, e: "固定IPはSaaS側で接続元を絞る方式で、テナント制限は自組織の端末やネットワークからどのテナントのアカウントでサインインできるかを絞る。後者は外部のアカウント側に着目しており、役割を入れ替えた選択肢は誤りである。", eEn: "Fixed IP narrows the source on the SaaS side, while tenant restrictions narrow which tenants' accounts can sign in from the organization's own devices and network. Options that swap these roles are wrong."},
  {d: "IT4", q: "テナント制限で制御できる範囲について、正しいものはどれか。", qEn: "Which statement about the scope that tenant restrictions can control is correct?", o: ["IDの種類にかかわらず、すべてのSaaSのアカウントを制御できる", "自組織のアカウントによるサインインを、既定で拒否する", "許可する外部テナントを指定せず、外部アカウントを例外なく拒否する", "制御できるのは対応するIDの範囲に限られる"], oEn: ["It can control the accounts of every SaaS, regardless of identity type", "It denies sign-in by the organization's own accounts by default", "It denies external accounts without exception, without specifying allowed external tenants", "Control is limited to the scope of the supported identities"], a: 3, e: "テナント制限で制御できるのは対応するIDの範囲に限られる。拒否の対象は外部や個人のアカウントで、自組織のアカウントではない。また許可する外部テナントだけを例外に指定できる。", eEn: "What tenant restrictions can control is limited to the supported identities. The denial targets external or personal accounts, not the organization's own, and only the allowed external tenants are specified as exceptions."},
  {d: "IT4", q: "ZTNAでアプリに接続中の利用者に、リスクが検知された。Microsoftの例で、このときに行われる対応はどれか。", qEn: "A risk is detected for a user connected to an app through ZTNA. In Microsoft's example, what action is taken?", o: ["継続的アクセス評価で再評価や切断を行う", "接続時に一度だけ評価し、以後は再評価しない", "Quick Accessに切り替えて、VPNと同等の広いアクセスを与える", "拠点側のSD-WAN機器が経路を切り替えて、同じアプリへ接続させる"], oEn: ["Re-evaluates or disconnects through continuous access evaluation", "Evaluates only once at connection and never re-evaluates afterward", "Switches to Quick Access and grants broad access equivalent to VPN", "Branch-side SD-WAN equipment switches the route and connects to the same app"], a: 0, e: "Microsoftの例では、端末の状態やリスクの信号で判断し、リスクを検知すると継続的アクセス評価で再評価や切断を行う。一度きりの評価や広いアクセスの付与は、常に確認するZTNAの考え方に反する。", eEn: "In Microsoft's example, decisions use device state and risk signals, and when risk is detected continuous access evaluation re-evaluates or disconnects. One-time evaluation or granting broad access contradicts ZTNA's always-verify idea."},
  {d: "IT4", q: "Microsoft Entra Internet Accessは、Webアクセスの制御にどのような判断材料を使うか。", qEn: "What does Microsoft Entra Internet Access use as the basis for controlling web access?", o: ["アクセス先のIPアドレスだけを見て、IDやConditional Accessとは無関係に、全利用者へ一律の制御を適用する", "ユーザー・端末・場所・リスクの文脈をConditional Accessと連携させ、IDに基づいて制御する", "拠点側の機器が選んだ経路の品質を見て、IPsecで接続先を切り替えて制御する", "SaaSのAPIコネクタで取得した設定の評価結果をもとに、設定ごとに制御する"], oEn: ["It looks only at the destination IP address and applies uniform control to all users regardless of identity", "It links the context of user, device, location and risk with Conditional Access and controls access based on identity", "It looks at the quality of routes chosen by branch equipment and switches destinations over IPsec", "It controls per setting based on evaluation results of settings obtained through SaaS API connectors"], a: 1, e: "製品例のEntra Internet Accessは、ユーザー・端末・場所・リスクの文脈をConditional Accessと連携させ、IDに基づいてWebアクセスを制御する。経路の品質はSD-WAN、設定評価はSSPMの領域。", eEn: "Microsoft Entra Internet Access links user, device, location and risk context with Conditional Access and controls web access based on identity. Route quality belongs to SD-WAN and settings evaluation to SSPM."},
  {d: "IT4", q: "Microsoft Defender for Cloud Appsは、利用中のSaaSをどのように特定し、評価するか。", qEn: "How does Microsoft Defender for Cloud Apps identify and evaluate the SaaS in use?", o: ["SaaS提供元のAPIから各SaaSの設定を取得し、推奨事項を並べたSecure Scoreでリスクを評価し、改善手順を示す", "端末のブラウザ処理を隔離環境で実行し、画面の映像を解析して利用中のSaaSを特定して、リスクを評価する", "固定IPで接続元を絞った通信だけを集め、IPアドレスの一覧から利用中のSaaSを特定して、リスクを評価する", "ネットワーク通信とアプリのカタログから利用中のSaaSを特定し、90以上の指標でリスクを評価して、ポリシーで継続的に監視する"], oEn: ["It obtains each SaaS's settings from the SaaS provider's API, rates risk with a Secure Score listing recommendations, and shows improvement steps", "It runs the device's browser processing in an isolated environment, analyzes the screen video to identify the SaaS in use, and rates the risk", "It collects only traffic from fixed-IP-restricted sources, identifies the SaaS in use from a list of IP addresses, and rates the risk", "It identifies the SaaS in use from network traffic and the app catalog, rates risk with more than 90 indicators, and monitors continuously through policies"], a: 3, e: "Defender for Cloud Appsはネットワーク通信とアプリのカタログから利用中のSaaSを特定し、90以上の指標でリスクを評価してポリシーで継続的に監視する。設定評価はSSPM、画面解析はRBIとは無関係である。", eEn: "Defender for Cloud Apps identifies SaaS in use from network traffic and the app catalog, rates risk with over 90 indicators and monitors continuously by policy. Settings evaluation is SSPM, and screen analysis has nothing to do with RBI."},
  {d: "IT4", q: "MicrosoftがSSEの機能として挙げるFWaaSが、クラウドのエッジで適用する処理はどれか。", qEn: "Which processing does FWaaS, which Microsoft lists as an SSE function, apply at the cloud edge?", o: ["TLS検査、URLフィルタリング、DLP、脅威インテリジェンスなど", "拠点側の機器による通信経路の最適化と、IPsecによるクラウドのハブへの接続", "SaaSの設定評価によるSecure Scoreの算出", "閲覧処理の隔離環境での実行と映像の転送"], oEn: ["TLS inspection, URL filtering, DLP, threat intelligence and similar", "Route optimization and selection by branch-side equipment", "Calculation of Secure Score by evaluating SaaS settings", "Running browsing in an isolated environment and forwarding video"], a: 0, e: "FWaaSは通信をクラウドのエッジに集めて同一のポリシーで検査し、TLS検査、URLフィルタリング、DLP、脅威インテリジェンスなどを適用する。経路の最適化はSD-WAN、設定評価はSSPM、隔離実行はRBIの役割である。", eEn: "FWaaS gathers traffic at the cloud edge and inspects it under one policy, applying TLS inspection, URL filtering, DLP, threat intelligence and similar. Route optimization is SD-WAN, settings evaluation is SSPM, and isolated execution is RBI."},
  {d: "IT4", q: "MicrosoftのAzure Virtual WANについて正しい説明はどれか。", qEn: "Which description of Microsoft's Azure Virtual WAN is correct?", o: ["拠点側の機器として経路の最適化と選択を担う、SD-WAN CPEそのものとして提供される機能である", "SWGやCASBを束ねたSSEであり、ネットワーク機能は持たず、セキュリティだけを担う", "それ自体がクラウド型のSD-WANであり、拠点側のSD-WANやSASEとの相互接続も想定している", "SASEの代わりに使う方式で、拠点側のSD-WANとは相互接続できず、単独で使う"], oEn: ["It is provided as the SD-WAN CPE itself, branch-side equipment that handles route optimization and selection", "It is an SSE bundling SWG and CASB, has no network functions, and handles only security", "It is itself a cloud-based SD-WAN and is also designed to interconnect with branch-side SD-WAN and SASE", "It is used instead of SASE, cannot interconnect with branch-side SD-WAN, and is used standalone"], a: 2, e: "Azure Virtual WANは自らがクラウド型のSD-WANで、拠点側のSD-WANやSASEとの相互接続も想定している。経路の最適化を担う拠点側機器はSD-WAN CPE、セキュリティ機能の束はSSEである。", eEn: "Azure Virtual WAN is itself a cloud-based SD-WAN and is designed to interconnect with branch-side SD-WAN and SASE. The branch-side equipment handling route optimization is the SD-WAN CPE, and the bundle of security functions is SSE."},
  {d: "IT5", q: "IaaS で仮想マシンを使うとき、形態にかかわらず必ず利用者の責任に残るものの組み合わせはどれか。", qEn: "When you run virtual machines on IaaS, which combination always remains the customer's responsibility regardless of the service model?", o: ["物理ホストとデータセンター", "物理ネットワークと OS", "データと ID", "アプリケーションと物理ホスト"], oEn: ["Physical hosts and the data center", "The physical network and the OS", "Data and identity", "Applications and physical hosts"], a: 2, e: "データと ID は IaaS・PaaS・SaaS のどれでも利用者に残る。物理ホストやデータセンターは IaaS から事業者の責任で、OS は形態により共有になる。", eEn: "Data and identity stay with the customer in IaaS, PaaS and SaaS. Physical hosts and data centers are the provider's from IaaS onward, and the OS is shared depending on the model."},
  {d: "IT5", q: "Google が紹介する「共有運命（shared fate）」の説明として正しいのはどれか。", qEn: "Which statement correctly describes the \"shared fate\" idea that Google introduces?", o: ["責任の線引きにとどまらず、事業者がガイダンスやツールを手厚く提供する考え方", "事業者が全責任を負い、利用者の責任をなくす考え方", "責任の分担を IaaS・PaaS・SaaS のどれでも同じ割合に固定する考え方", "データと ID の責任を利用者から事業者へ移す考え方"], oEn: ["An approach in which the provider goes beyond drawing the line of responsibility and offers extensive guidance and tools", "An approach in which the provider takes all responsibility and the customer has none", "An approach that fixes the split at the same ratio for IaaS, PaaS and SaaS", "An approach that moves responsibility for data and identity from the customer to the provider"], a: 0, e: "共有運命は線引きにとどまらず、事業者が手厚くガイダンスとツールを出す方向。責任をなくす、固定する、データと ID を移すといった説明は誤り。", eEn: "Shared fate goes beyond the dividing line, with the provider giving strong guidance and tools. Removing, fixing or moving the customer's responsibility is not what it means."},
  {d: "IT5", q: "Microsoft が生成AIの責任共有を三層（AI プラットフォーム、AI アプリケーション、AI の利用）で整理するとき、「AI の利用」層で利用者側の務めとされるのはどれか。", qEn: "In Microsoft's three-layer view of AI shared responsibility (AI platform, AI application, AI usage), what is the customer's duty at the AI usage layer?", o: ["物理ホストの保守と更新", "データセンターの入退室管理", "物理ネットワークの制御", "利用規定の更新と教育"], oEn: ["Maintaining and updating physical hosts", "Managing entry to and exit from the data center", "Controlling the physical network", "Updating usage policies and providing training"], a: 3, e: "利用層では、利用規定の更新と教育が利用者の務め。物理ホスト、物理ネットワーク、データセンターは IaaS から事業者の責任である。", eEn: "At the usage layer, updating usage policies and training are the customer's job. Physical hosts, the physical network and data centers are the provider's from IaaS onward."},
  {d: "IT5", q: "クラウド資源の構成を継続的に点検し、ポリシーに反する設定ミスを推奨事項として示したい。まず当てるべき仕組みはどれか。", qEn: "You want to continuously check cloud resource configuration and surface policy-violating misconfigurations as recommendations. Which mechanism should you apply first?", o: ["CWPP（稼働中のワークロード群の保護）", "CSPM（クラウドセキュリティ態勢管理）", "DLP（データ損失防止）", "KMS（鍵管理サービス）"], oEn: ["CWPP (protection of running workloads)", "CSPM (Cloud Security Posture Management)", "DLP (Data Loss Prevention)", "KMS (Key Management Service)"], a: 1, e: "CSPM は構成を点検し、違反する設定を推奨事項に変換して態勢を保つ。CWPP は稼働中の脅威対策、DLP は情報流出防止、KMS は鍵管理が役割。", eEn: "CSPM checks configuration and turns violations into recommendations. CWPP handles threats to running workloads, DLP prevents data leaks, and KMS manages keys."},
  {d: "IT5", q: "CSPM と CWPP の違いとして正しいのはどれか。", qEn: "Which statement about the difference between CSPM and CWPP is correct?", o: ["CSPM は稼働中の各ワークロードの脅威検知と防御を担い、CWPP は構成と態勢の点検が中心", "どちらも設定ミスの点検だけを担い、守る対象のクラウド資源が異なる", "CSPM は構成と態勢の点検が中心で、CWPP は稼働中のワークロードの脅威検知と防御を担う", "CSPM は開発段階、CWPP は運用段階だけを担当する"], oEn: ["CSPM detects and defends against threats to running workloads, while CWPP focuses on checking configuration and posture", "Both only check misconfigurations and differ in which cloud resources they cover", "CSPM focuses on checking configuration and posture, while CWPP detects and defends against threats to running workloads", "CSPM covers only development and CWPP covers only operations"], a: 2, e: "CSPM は構成の正しさの点検、CWPP は稼働中のワークロードの脅威検知と防御が担当。両者を束ねたものが CNAPP である。", eEn: "CSPM checks that configuration is correct; CWPP detects and defends against threats to running workloads. CNAPP bundles the two."},
  {d: "IT5", q: "社内に点在する生成AIワークロードを洗い出し、その態勢を評価したい。Defender for Cloud の機能として当てはまるのはどれか。", qEn: "You want to find generative AI workloads scattered across the company and assess their posture. Which Defender for Cloud capability fits?", o: ["AI SPM", "AI Services プラン", "サーバ向けのファイル整合性監視", "ストレージ向けのマルウェアスキャン"], oEn: ["AI SPM", "The AI Services plan", "File integrity monitoring for servers", "Malware scanning for storage"], a: 0, e: "AI SPM は生成AIワークロードを検出して AI BOM を示し、態勢を評価する。AI Services プランは脅威の特定、他の二つはワークロード保護の機能である。", eEn: "AI SPM detects generative AI workloads, shows the AI BOM and assesses posture. The AI Services plan identifies threats, and the other two are workload protection features."},
  {d: "IT5", q: "CWPP がワークロード別に提供する保護のうち、コンテナ向けに挙げられているものはどれか。", qEn: "Among the protections CWPP offers per workload type, which is listed for containers?", o: ["脆弱性評価とファイル整合性監視", "ストレージ向けのマルウェアスキャン", "攻撃パス分析による危険な経路の確認", "環境強化と実行時保護"], oEn: ["Vulnerability assessment and file integrity monitoring", "Malware scanning for storage", "Attack path analysis to confirm dangerous routes", "Environment hardening and runtime protection"], a: 3, e: "コンテナ向けは環境強化と実行時保護。脆弱性評価とファイル整合性監視はサーバ向け、マルウェアスキャンはストレージ向け、攻撃パス分析は CSPM 側である。", eEn: "For containers it is environment hardening and runtime protection. Vulnerability assessment and file integrity monitoring are for servers, malware scanning is for storage, and attack path analysis belongs to CSPM."},
  {d: "IT5", q: "CWPP が脅威を検知したときに出すアラートが知らせる内容はどれか。", qEn: "What does an alert raised by CWPP on detecting a threat tell you?", o: ["違反している設定の一覧とセキュアスコアの変化", "脅威の性質と重大度", "事業者と利用者の責任分担の線引き", "暗号化に使われている鍵の保護水準"], oEn: ["The list of violating settings and the change in secure score", "The nature and severity of the threat", "How responsibility is split between provider and customer", "The protection level of the keys used for encryption"], a: 1, e: "CWPP のアラートは検知した脅威の性質と重大度を知らせる。設定違反とセキュアスコアは CSPM、責任分担は責任共有モデル、鍵の水準は鍵管理の話である。", eEn: "CWPP alerts report the nature and severity of a detected threat. Setting violations and secure score belong to CSPM, responsibility split to the shared responsibility model, and key levels to key management."},
  {d: "IT5", q: "生成AIアプリケーションに向けられた脅威をリアルタイムに特定し、対応を助けたい。Defender for Cloud のどれを使うか。", qEn: "You want to identify threats aimed at a generative AI application in real time and get help responding. Which Defender for Cloud item do you use?", o: ["AI SPM", "セキュアスコアの改善状況の確認", "AI Services プラン", "攻撃パス分析"], oEn: ["AI SPM", "Checking the secure score improvement status", "The AI Services plan", "Attack path analysis"], a: 2, e: "AI Services プランは生成AIアプリへの脅威をリアルタイムに特定し対応を助ける。AI SPM は態勢評価、セキュアスコアと攻撃パス分析は CSPM 側の機能。", eEn: "The AI Services plan identifies threats to generative AI apps in real time and helps respond. AI SPM assesses posture; secure score and attack path analysis are CSPM features."},
  {d: "IT5", q: "CSPM と CWPP を別々の製品で導入した結果、製品が増えて管理が煩雑になった。CNAPP の観点での方向性はどれか。", qEn: "After adopting CSPM and CWPP as separate products, the number of tools grew and management became cumbersome. What direction does the CNAPP view suggest?", o: ["CSPM だけを残し、ワークロードの脅威検知を外す", "製品ごとに別の担当チームを置いて個別に運用する", "CWPP を廃止してコード段階の検査に一本化する", "両者を統合し、ポイント製品の数を減らす"], oEn: ["Keep only CSPM and drop workload threat detection", "Assign a separate team to each product and operate them individually", "Retire CWPP and consolidate on code-stage scanning", "Integrate the two and reduce the number of point products"], a: 3, e: "CNAPP は CSPM や CWPP などの機能を統合し、ポイント製品の数を減らす方向にある。片方を外す、別運用のまま、検査に一本化する対応は趣旨に合わない。", eEn: "CNAPP integrates features such as CSPM and CWPP to cut the number of point products. Dropping one, keeping separate operations or collapsing into code scanning misses the point."},
  {d: "IT5", q: "Defender for Cloud が CNAPP の中核に置く三つの要素はどれか。", qEn: "Which three elements does Defender for Cloud place at the core of CNAPP?", o: ["CSPM、DLP、CWPP", "CSPM、DevSecOps、CWPP", "EDR、DevSecOps、CWPP", "CSPM、DevSecOps、KMS（鍵管理）"], oEn: ["CSPM, DLP and CWPP", "CSPM, DevSecOps and CWPP", "EDR, DevSecOps and CWPP", "CSPM, DevSecOps and KMS (key management)"], a: 1, e: "Defender for Cloud は CSPM、DevSecOps、CWPP の三つを中核に置く。DLP、EDR、KMS はそれぞれデータ保護、端末、鍵管理の別の仕組みである。", eEn: "Defender for Cloud centers on CSPM, DevSecOps and CWPP. DLP, EDR and KMS are separate mechanisms for data protection, endpoints and key management."},
  {d: "IT5", q: "コード段階で見つかった誤設定や露出した秘密情報について、修復の優先順位を付けたい。CNAPP の考え方に沿うのはどれか。", qEn: "You want to prioritize fixes for misconfigurations and exposed secrets found at the code stage. Which approach matches CNAPP thinking?", o: ["クラウド上の状況と結び付けて優先順位を付ける", "コード段階の検出件数が多いものから順に直し、件数の少ないものは後回しにする", "運用開始後の検知結果が出るまで修復を保留する", "検出した秘密情報をすべて同じ重要度で扱う"], oEn: ["Prioritize by linking each finding to the situation in the cloud", "Fix in order of the most detections at the code stage, deferring those with fewer detections", "Hold off on fixes until detections appear after go-live", "Treat every detected secret at the same severity"], a: 0, e: "CNAPP はコード段階の誤設定や秘密情報を、クラウドの状況と結び付けて修復の優先順位を付ける。件数順、保留、一律扱いではライフサイクル全体を守れない。", eEn: "CNAPP links code-stage misconfigurations and exposed secrets to cloud context to rank fixes. Ordering by count, deferring or treating all alike does not protect the whole lifecycle."},
  {d: "IT5", q: "Azure・AWS・GCP に散らばるIDの権限を一つの画面で追跡し、休眠アカウントや過剰権限を洗い出したい。まず当てるべき仕組みはどれか。", qEn: "You want to track permissions of identities scattered across Azure, AWS and GCP in one view and find dormant accounts and excessive permissions. Which mechanism should you apply first?", o: ["CWPP（稼働中のワークロードを脅威から守る仕組み）", "CIEM（クラウドインフラのエンタイトルメント管理）", "プライベートリンク（プライベートエンドポイント）", "API ゲートウェイによるレート制限"], oEn: ["CWPP (the mechanism that protects running workloads from threats)", "CIEM (Cloud Infrastructure Entitlement Management)", "Private Link (private endpoint)", "Rate limiting at an API gateway"], a: 1, e: "CIEM は複数クラウドのIDの権限を洗い出し、休眠や過剰を見つけて最小権限に近づける。CWPP は稼働中ワークロードの脅威を守る別の役割。", eEn: "CIEM inventories identity permissions across clouds, finds dormant or excessive ones and moves toward least privilege. CWPP protects running workloads, a different role."},
  {d: "IT5", q: "IAM と CIEM の違いとして正しいのはどれか。", qEn: "Which statement about the difference between IAM and CIEM is correct?", o: ["CIEM が権限の付与と管理を担い、IAM は付与済みの権限が過剰でないかを複数クラウド横断で検査する", "IAM は人のIDだけを扱い、CIEM は非人間IDだけを扱うため、両者の対象は重ならない", "IAM は複数クラウドの権限を一つの画面で追跡し、CIEM は単一クラウド内の認証だけを扱う", "IAM は権限を付与・管理する仕組みで、CIEM は付与済みの権限の過剰を複数クラウド横断で検査する"], oEn: ["CIEM grants and manages permissions, while IAM inspects across multiple clouds whether granted permissions are excessive", "IAM handles only human identities and CIEM handles only non-human identities, so their scopes never overlap", "IAM tracks permissions across multiple clouds in one view, while CIEM handles only authentication within a single cloud", "IAM is the mechanism that grants and manages permissions; CIEM inspects, across multiple clouds, granted permissions for excess"], a: 3, e: "IAM が付与・管理の仕組みで、CIEM は付与済み権限の過剰を検査する側。役割を逆にした選択肢や、対象を人／非人間に分けた説明は誤り。", eEn: "IAM grants and manages; CIEM checks granted permissions for excess. Swapping the roles, or splitting scope into human versus non-human, is wrong."},
  {d: "IT5", q: "AIエージェントや推論基盤が使うサービスアカウントやマネージドIDの権限を棚卸ししたい。CIEM の対象範囲の説明として正しいのはどれか。", qEn: "You want to review permissions of service accounts and managed identities used by AI agents and inference platforms. Which description of CIEM's scope is correct?", o: ["ユーザーだけでなく、サービスプリンシパルやマネージドIDなどの非人間IDにも及ぶ", "人のユーザーアカウントに限られるため、サービスアカウントなどの非人間IDは別の仕組みで扱う", "特権ユーザーのパスワードを保管し、貸し出しを管理する範囲に限られる", "稼働中の仮想マシンに入るマルウェアを検知する範囲に限られる"], oEn: ["It covers not only users but also non-human identities such as service principals and managed identities", "It is limited to human user accounts, so non-human identities such as service accounts are handled by another mechanism", "It is limited to vaulting and checking out privileged users' passwords", "It is limited to detecting malware entering running virtual machines"], a: 0, e: "CIEM の対象はユーザーに限らず、サービスプリンシパルやマネージドID、サービスアカウントなど非人間IDも含み、AI基盤のID棚卸しにも使える。", eEn: "CIEM's scope is not limited to users; it includes service principals, managed identities and service accounts, so it fits AI platform ID reviews."},
  {d: "IT5", q: "CIEM と CSPM の関係として正しいのはどれか。", qEn: "Which statement about the relationship between CIEM and CSPM is correct?", o: ["CSPM が CIEM の一機能であり、CIEM を導入しない限り CSPM の推奨事項は一切使えなくなる", "CIEM は CWPP の下位機能で、仮想マシン上のIDだけを対象にする", "CIEM は CSPM の一機能として提供される例があり、過剰権限のIDからの横展開も攻撃経路として示せる", "両者は排他的で、同じクラウド環境では併用できない"], oEn: ["CSPM is a feature of CIEM, and no CSPM recommendation can be used unless CIEM is deployed", "CIEM is a sub-function of CWPP and covers only identities on virtual machines", "CIEM is sometimes provided as a CSPM feature and can show lateral movement from over-privileged identities as an attack path", "They are mutually exclusive and cannot be used together in the same cloud environment"], a: 2, e: "Defender for Cloud のように CIEM を CSPM の一機能として提供する例があり、過剰権限のIDからの横展開を攻撃経路として示す。", eEn: "As in Defender for Cloud, CIEM may be offered inside CSPM, and it shows lateral movement from over-privileged identities as an attack path."},
  {d: "IT5", q: "ストレージや SQL Database への通信を公開インターネットに出さず、自社の仮想ネットワーク内のプライベートなアドレスで接続したい。まず当てるべき仕組みはどれか。", qEn: "You want to reach storage and SQL Database over private addresses inside your own virtual network without going over the public internet. Which mechanism should you apply first?", o: ["VPN（拠点のネットワーク間を結ぶ暗号化トンネル）", "API ゲートウェイのレート制限", "プライベートリンク（プライベートエンドポイント）", "コンテナのゲート付きデプロイ"], oEn: ["VPN (encrypted tunnel connecting the networks of sites)", "Rate limiting at an API gateway", "Private Link (private endpoint)", "Gated deployment for containers"], a: 2, e: "プライベートエンドポイントは仮想ネットワーク内に接続口を置き、Microsoft のバックボーン上で通信する。VPN はネットワーク間のトンネルで役割が違う。", eEn: "A private endpoint puts the connection point inside the virtual network and carries traffic on Microsoft's backbone. A VPN is a network-to-network tunnel, a different role."},
  {d: "IT5", q: "VPN とプライベートリンクの違いとして正しいのはどれか。", qEn: "Which statement about the difference between a VPN and Private Link is correct?", o: ["VPN はネットワーク間に暗号化トンネルを張り、プライベートリンクは特定サービスへの接続口を自社ネットワーク内に置く", "プライベートリンクはネットワーク間に暗号化トンネルを張り、VPN は特定のクラウドサービスへの接続口を自社ネットワーク内に置く", "VPN はクラウドサービス専用で、プライベートリンクはオンプレミス同士の接続専用である", "両者は同じ仕組みの別名であり、機能に違いはない"], oEn: ["A VPN builds an encrypted tunnel between networks, while Private Link places an entry point to a specific service inside your network", "Private Link builds an encrypted tunnel between networks, while a VPN places an entry point to a specific cloud service inside your network", "A VPN is only for cloud services and Private Link is only for connecting on-premises sites to each other", "They are two names for the same mechanism and have no functional difference"], a: 0, e: "VPN はネットワーク間の暗号化トンネル、プライベートリンクは特定サービスへの接続口を自社ネットワーク内に置く仕組み。役割を入れ替えた選択肢は誤り。", eEn: "A VPN is a network-to-network encrypted tunnel; Private Link places an entry to a specific service in your network. Swapped roles are wrong."},
  {d: "IT5", q: "プライベートエンドポイントが対応する範囲として正しいのはどれか。", qEn: "Which statement about the scope a private endpoint maps to is correct?", o: ["同じサービスに属する全リソースに対応し、接続先は自動で切り替わる", "サービス全体ではなく特定のリソースに対応し、他のリソースへの接続は遮断される", "仮想ネットワーク内のすべての PaaS サービスに共通の一つの接続口として働く", "接続先は限定せず、公開インターネット向けの通信も同じ口から通す"], oEn: ["It maps to every resource of the same service, and the target switches automatically", "It maps to a specific resource rather than the whole service, and connections to other resources are blocked", "It works as one shared entry for all PaaS services in the virtual network", "It does not limit targets and also passes public internet traffic through the same entry"], a: 1, e: "エンドポイントは特定のリソースに対応し、他のリソースへの接続は遮断される。そのためデータ流出のリスクを下げられる。", eEn: "An endpoint maps to one specific resource and blocks connections to others, which lowers the risk of data exfiltration."},
  {d: "IT5", q: "オンプレミスの社内拠点から、プライベートエンドポイント経由でクラウド上のサービスを使いたい。経路として示されているのはどれか。", qEn: "An on-premises office wants to use a cloud service through a private endpoint. Which path is described?", o: ["公開インターネット経由に限られる", "WAF や SASE を経由する場合に限って使える", "SASE を導入した場合に限って使える", "VPN や ExpressRoute 経由で使える"], oEn: ["It is limited to the public internet", "It can be used only via a WAF or SASE", "It can be used only when SASE is deployed", "It can be used via VPN or ExpressRoute"], a: 3, e: "オンプレミスからは VPN や ExpressRoute 経由でプライベートエンドポイントを使える。公開インターネット限定という前提は誤り。", eEn: "From on-premises, a private endpoint can be used via VPN or ExpressRoute. The premise of public-internet-only is wrong."},
  {d: "IT5", q: "ARM や Terraform のテンプレートの設定ミスが本番環境に出るのを、配備の前に防ぎたい。まず当てるべき仕組みはどれか。", qEn: "You want to stop misconfigurations in ARM or Terraform templates before they reach production. Which mechanism should you apply first?", o: ["IaCセキュリティ（テンプレートの静的検査）", "CSPM（稼働中資源の構成点検）", "CWPP（稼働中のワークロードを脅威から保護）", "CIEM（付与済み権限の検査）"], oEn: ["IaC security (static scanning of templates)", "CSPM (configuration checks of running resources)", "CWPP (protecting running workloads from threats)", "CIEM (inspection of granted permissions)"], a: 0, e: "IaCセキュリティは配備前のテンプレートを検査し、誤設定が本番へ入るのを防ぐ。CSPM や CWPP は稼働中の資源が対象で、時点が異なる。", eEn: "IaC security scans templates before deployment so misconfigurations never reach production. CSPM and CWPP target running resources, a different point in time."},
  {d: "IT5", q: "CSPM と IaCセキュリティの違いとして正しいのはどれか。", qEn: "Which statement about the difference between CSPM and IaC security is correct?", o: ["CSPM は配備前のテンプレートを点検し、IaCセキュリティは稼働中のクラウド資源の設定を点検する", "CSPM は稼働中のクラウド資源の設定を点検し、IaCセキュリティは配備前のテンプレートを点検する", "CSPM はコンテナだけを対象にし、IaCセキュリティは仮想マシンだけを対象にする", "CSPM は脅威を検知して封じ込め、IaCセキュリティは誤設定を検知するだけで違いがない"], oEn: ["CSPM checks templates before deployment, while IaC security checks settings of running cloud resources", "CSPM checks settings of running cloud resources, while IaC security checks templates before deployment", "CSPM covers only containers and IaC security covers only virtual machines", "CSPM detects and contains threats while IaC security only detects misconfigurations, with no real difference"], a: 1, e: "CSPM は稼働中の資源、IaCセキュリティは配備前のテンプレートが対象。両者は点検の時点が違い、補い合う関係にある。", eEn: "CSPM targets running resources and IaC security targets pre-deployment templates. They check at different times and complement each other."},
  {d: "IT5", q: "Microsoft Security DevOps が IaC テンプレートの検査に使うツールの組み合わせはどれか。", qEn: "Which combination of tools does Microsoft Security DevOps use to scan IaC templates?", o: ["SPDX、CycloneDX、SWID", "SAST、DAST、シークレットスキャン", "Azure Policy、管理グループ、Key Vault、Entra", "Template Analyzer、Checkov、Terrascan"], oEn: ["SPDX, CycloneDX, SWID", "SAST, DAST, secret scanning", "Azure Policy, management groups, Key Vault, Entra", "Template Analyzer, Checkov, Terrascan"], a: 3, e: "Microsoft Security DevOps は Template Analyzer、Checkov、Terrascan を使う。SPDX などは SBOM の標準形式で、役割が違う。", eEn: "Microsoft Security DevOps uses Template Analyzer, Checkov and Terrascan. SPDX and the like are SBOM formats, a different role."},
  {d: "IT5", q: "AI基盤のネットワーク、権限、ストレージを IaC で構築している。公開設定や権限の誤りを最も早い段階で防げるのはどれか。", qEn: "You build the network, permissions and storage of an AI platform with IaC. Which approach prevents public-exposure and permission errors at the earliest stage?", o: ["本番稼働後に監査ログを集めて確認する", "AI の利用規定を更新して利用者に教育する", "配備前にテンプレートをコードの段階で検査する", "侵害を受けた後にワークロードの脅威検知で気づく"], oEn: ["Collect and review audit logs after production starts", "Update AI usage rules and train users", "Scan the templates at the code stage before deployment", "Notice through workload threat detection after a breach"], a: 2, e: "IaC で構築するなら、公開設定や権限の誤りはコードの段階で検査して直せる。稼働後の確認や侵害後の検知は、それより遅い。", eEn: "When built with IaC, public-exposure and permission errors can be scanned and fixed at the code stage. Post-deployment review or post-breach detection comes later."},
  {d: "IT5", q: "コンテナ・Kubernetes 環境を守るとき、Defender for Containers が扱う三つの面はどれか。", qEn: "Which three aspects does Defender for Containers address when protecting container and Kubernetes environments?", o: ["認証、認可、暗号化", "構成の不備、脆弱性、実行時の脅威", "ビルド、配備、廃棄", "物理、ネットワーク、アプリケーション"], oEn: ["Authentication, authorization, encryption", "Configuration weaknesses, vulnerabilities, runtime threats", "Build, deploy, disposal", "Physical, network, application"], a: 1, e: "コンテナ保護は構成の不備、脆弱性、実行時の脅威という三つの面で行う。他の三点組は、別の分類で、コンテナ固有の整理ではない。", eEn: "Container protection works on configuration weaknesses, vulnerabilities and runtime threats. The other triples are different classifications, not the container-specific one."},
  {d: "IT5", q: "脆弱なイメージの配備を止め、特権コンテナの作成も禁じたい。当てはまる制御はどれか。", qEn: "You want to block deployment of vulnerable images and also forbid creating privileged containers. Which control fits?", o: ["脆弱なイメージを監査・拒否するゲート付きデプロイと、特権コンテナの作成を禁じるポリシー", "ノード上のファイル整合性監視と、サーバ向けの脆弱性評価の定期実行", "配備済みイメージを夜間にまとめて削除するバッチ処理", "クラスタ API への匿名アクセスを許し、問題が起きた後に監査ログで追跡するだけの運用を続ける"], oEn: ["Gated deployment that audits or denies vulnerable images, plus a policy forbidding privileged containers", "File integrity monitoring on nodes and periodic server vulnerability assessment", "A nightly batch that deletes deployed images in bulk", "Allowing anonymous cluster API access and only tracing problems afterwards through audit logs"], a: 0, e: "ゲート付きデプロイで脆弱なイメージの配備を監査・拒否し、特権コンテナの作成禁止もポリシーで実現できる。他は目的に合わない。", eEn: "Gated deployment audits or denies vulnerable images, and a policy can forbid privileged containers. The others do not meet the goal."},
  {d: "IT5", q: "従来のホスト（VM）中心の保護と比べた、コンテナセキュリティの特徴はどれか。", qEn: "Compared with traditional host (VM)-centered protection, what characterizes container security?", o: ["ホストOSのパッチ適用だけで、イメージもクラスタ設定も実行時の挙動もまとめて守ることができる", "実行時の挙動は対象外とし、イメージの脆弱性だけを配備前に確認する", "イメージの脆弱性、クラスタのAPI設定、コンテナ内の実行時の挙動を別々の層として扱う", "クラスタのAPI設定は事業者の責任として扱い、利用者は何も点検しない"], oEn: ["Patching the host OS alone can protect images, cluster settings and runtime behavior together", "It excludes runtime behavior and checks only image vulnerabilities before deployment", "It treats image vulnerabilities, cluster API settings and runtime behavior in containers as separate layers", "It treats cluster API settings as the provider's responsibility so users inspect nothing"], a: 2, e: "コンテナではイメージ、クラスタ設定、実行時の挙動を別々の層として扱う。ホストのパッチだけでは三つの層は覆えない。", eEn: "Containers treat images, cluster settings and runtime behavior as separate layers. Host patching alone cannot cover all three."},
  {d: "IT5", q: "生成AIの推論基盤を Kubernetes 上で動かす。コンテナのセキュリティとして出発点になるのはどれか。", qEn: "You run a generative AI inference platform on Kubernetes. What is the starting point for container security?", o: ["モデルの学習データを自動で増やす仕組みの導入", "利用者向けの利用規定の更新と教育だけ", "すべての通信を許可して異常を後から集計する運用", "イメージの脆弱性検査と、不要な特権の禁止"], oEn: ["Introducing a mechanism that automatically grows the training data", "Only updating usage rules and training users", "Allowing all traffic and tallying anomalies afterwards", "Image vulnerability scanning and banning unnecessary privileges"], a: 3, e: "AI の推論基盤をKubernetes上で動かす場合も、イメージの脆弱性検査と不要な特権の禁止が出発点になる。", eEn: "Even for AI inference on Kubernetes, scanning image vulnerabilities and banning unneeded privileges is the starting point."},
  {d: "IT5", q: "DevSecOps／CI/CDパイプラインの保護が持つ二つの面はどれか。", qEn: "Which two aspects does DevSecOps / CI/CD pipeline security have?", o: ["本番稼働後にまとめて検査することと、稼働中のワークロードを脅威から守ることの二つの面である", "検査を開発から配備までに自動で組み込むことと、ビルド・配備の基盤そのものを攻撃から守ること", "配備前のテンプレートを検査することと、付与済みの権限を横断で検査すること", "部品の一覧を整えることと、公開APIの利用量を制限すること"], oEn: ["Inspecting everything in bulk after production starts, and protecting running workloads from threats", "Embedding checks automatically from development to deployment, and protecting the build and deployment infrastructure itself from attack", "Scanning templates before deployment, and inspecting granted permissions across clouds", "Maintaining a parts inventory, and limiting usage of public APIs"], a: 1, e: "DevSecOps は検査をパイプラインに自動で組み込む（シフトレフト）面と、ビルド・配備基盤そのものを守る面の二つを持つ。", eEn: "DevSecOps has two sides: embedding checks into the pipeline (shift left) and protecting the build and deployment infrastructure itself."},
  {d: "IT5", q: "IaCセキュリティと DevSecOps／CI/CDパイプラインの保護の関係として正しいのはどれか。", qEn: "Which statement about the relationship between IaC security and DevSecOps / CI/CD pipeline security is correct?", o: ["IaCセキュリティはパイプラインの認証情報や承認の仕組みの保護を担い、DevSecOps はテンプレート検査を担う", "両者は同じ検査であり、DevSecOps は稼働後にだけ実行される", "IaCセキュリティは CSPM に完全に含まれ、DevSecOps とは無関係である", "IaC スキャンは、SAST やシークレットスキャン、DAST と並んで、パイプラインに組み込む検査の一つである"], oEn: ["IaC security protects pipeline credentials and approval mechanisms, while DevSecOps handles template scanning", "They are the same check, and DevSecOps runs only after deployment", "IaC security is fully contained in CSPM and unrelated to DevSecOps", "IaC scanning is one of the checks embedded in the pipeline, alongside SAST, secret scanning and DAST"], a: 3, e: "ベンチマークは SAST、シークレットスキャン、IaCスキャン、DAST を CI/CD に組み込むよう示す。IaCスキャンはその一つに当たる。", eEn: "The benchmark has SAST, secret scanning, IaC scanning and DAST embedded in CI/CD. IaC scanning is one of them."},
  {d: "IT5", q: "ビルド・配備の基盤そのものを守る対策として示されているものはどれか。", qEn: "Which measures are described for protecting the build and deployment infrastructure itself?", o: ["パイプラインの変更権限の制限、配備前のイメージ検査、DevOps 監査ログの集約", "最終段階で一度だけ行う、アプリのコードの静的検査", "シークレットはコードに直接書き込み、変更履歴だけで管理して一元管理の仕組みは使わないこと", "パイプラインの承認の仕組みを外し、配備を高速化すること"], oEn: ["Restricting pipeline change rights, inspecting images before deployment, aggregating DevOps audit logs", "A single static scan of application code at the final stage", "Writing secrets directly in code, managing them only through change history, and using no central management", "Removing pipeline approval steps to speed up deployment"], a: 0, e: "パイプラインの変更権限を制限し、配備前にイメージを検査し、DevOps の監査ログを集約して不正な変更を検知する。", eEn: "Restrict pipeline change rights, inspect images before deployment, and aggregate DevOps audit logs to detect unauthorized changes."},
  {d: "IT5", q: "AIアプリも他のアプリと同じ CI/CD パイプラインで配備している。パイプラインの保護が重要な理由はどれか。", qEn: "AI apps are deployed through the same CI/CD pipeline as other apps. Why does pipeline protection matter?", o: ["AIアプリは配備後に自動で再学習されるため、検査が免除されるから", "AI 専用のパイプラインは他のアプリと共有されないから", "パイプラインの乗っ取りが、AIアプリ全体の改ざんにつながるから", "パイプラインの保護が利用規定の更新に置き換わるから"], oEn: ["Because AI apps retrain automatically after deployment and are therefore exempt from checks", "Because AI-dedicated pipelines are never shared with other apps", "Because hijacking the pipeline can lead to tampering with the whole AI app", "Because pipeline protection is replaced by updating usage rules"], a: 2, e: "AIアプリの配備も同じパイプラインを通るため、パイプラインの乗っ取りはAIアプリ全体の改ざんにつながる。", eEn: "AI app deployments pass through the same pipeline, so a hijacked pipeline can lead to tampering with the entire AI app."},
  {d: "IT5", q: "現場が自由に新しいAI環境を作れるようにしつつ、最低限の統制も保ちたい。まず当てるべき仕組みはどれか。", qEn: "You want teams to create new AI environments freely while keeping minimum controls. Which mechanism should you apply first?", o: ["ランディングゾーンとガードレール（許可リージョンの限定や診断ログ送信の必須化）", "RBAC で作成権限を全員から取り上げ、申請制にする運用", "AI 用データストアの接続口を閉じるプライベートエンドポイントを個別に作る運用を続ける", "稼働中のワークロードの脅威を検知する CWPP"], oEn: ["Landing zone and guardrails (allowed regions and mandatory diagnostic log forwarding)", "Taking creation rights away from everyone with RBAC and moving to a request process", "Individually creating private endpoints that close the AI data store's entry", "CWPP that detects threats to running workloads"], a: 0, e: "ガードレールは現場への権限委譲と統制を両立させる。AI用サブスクリプションに許可リージョンやログ送信を適用すれば最低限の統制が保てる。", eEn: "Guardrails combine delegation with control. Applying allowed regions and log forwarding to the AI subscription keeps minimum controls even for new environments."},
  {d: "IT5", q: "RBAC とポリシーの違いとして正しいのはどれか。", qEn: "Which statement about the difference between RBAC and policy is correct?", o: ["RBAC はリソースの状態が規則に合うかを評価し、ポリシーは誰に操作を許すかを決める", "権限を持つ人が操作する場合、ポリシーは非準拠でも作成や更新を拒否しない", "RBAC は誰に操作を許すかを決め、ポリシーはリソースの状態が規則に合うかを評価する", "ポリシーは管理グループには割り当てられず、個別のリソースにだけ割り当てる"], oEn: ["RBAC evaluates whether a resource's state complies with rules, while policy decides who may operate", "When a permitted person operates, policy does not reject non-compliant creation or updates", "RBAC decides who may operate, while policy evaluates whether a resource's state complies with rules", "Policy cannot be assigned to management groups and is assigned only to individual resources"], a: 2, e: "RBAC は誰に操作を許すか、ポリシーは状態が規則に合うかを評価する。権限があっても非準拠なら作成や更新は拒否される。", eEn: "RBAC decides who may act; policy evaluates compliance of state. Even with permission, non-compliant creation or updates are denied."},
  {d: "IT5", q: "ポリシーを新しく適用して、非準拠の変更を拒否できるようにしたい。推奨される進め方はどれか。", qEn: "You want to apply a new policy so that non-compliant changes can be denied. What is the recommended approach?", o: ["最初から拒否で全体に強制し、問題が出たら例外を作る", "記録だけの設定を続け、強制には移さない", "管理グループには適用せず、個別のリソースごとに手作業で適用する", "まず監査から始め、影響を確かめてから強制へ移す"], oEn: ["Enforce deny everywhere from the start and create exceptions when problems arise", "Keep a record-only setting and never move to enforcement", "Skip management groups and apply it by hand to each resource", "Start with audit, check the impact, then move to enforcement"], a: 3, e: "まず監査から始めて影響を確かめ、強制へ移すのが推奨される。ポリシーは管理グループなどの階層に割り当てて配下へ継承させる。", eEn: "Start with audit, confirm the impact, then move to enforcement. Policies are assigned at hierarchy levels such as management groups and inherited downward."},
  {d: "IT5", q: "AI用データストアへの通信を閉域化したい。あわせて、新しいAI環境にも許可リージョンの限定を課したい。それぞれに当たる仕組みの組み合わせはどれか。", qEn: "You want to make traffic to an AI data store private, and also impose allowed-region limits on new AI environments. Which pairing of mechanisms fits?", o: ["閉域化はガードレール、リージョン限定はプライベートリンク", "閉域化はプライベートリンク、リージョン限定はガードレール", "閉域化は CIEM、リージョン限定は CWPP", "閉域化は SBOM、リージョン限定は WAF"], oEn: ["Guardrails for closing traffic, Private Link for region limits", "Private Link for closing traffic, guardrails for region limits", "CIEM for closing traffic, CWPP for region limits", "SBOM for closing traffic, WAF for region limits"], a: 1, e: "通信経路の閉域化はプライベートリンク、新しい環境への許可リージョンの限定はポリシーによるガードレールの役割。", eEn: "Making the path private is Private Link; limiting allowed regions for new environments is the policy-based guardrail role."},
  {d: "IT5", q: "新しい CVE が公表されたとき、自社が使う製品が影響を受けるかを素早く確かめたい。事前に整えておくべきものはどれか。", qEn: "When a new CVE is published, you want to quickly check whether your products are affected. What should you prepare in advance?", o: ["稼働中ワークロードのアラートの重大度一覧", "IaC テンプレートの静的検査の結果だけを保管し、依存の一覧は持たない運用", "直接・推移的な依存の一覧を維持し、CVE と継続的に照合する体制", "責任共有モデルの分担表だけを最新にする運用"], oEn: ["A list of alert severities for running workloads", "Keeping only static-scan results of IaC templates and holding no dependency list", "A maintained list of direct and transitive dependencies, continuously matched against CVEs", "Keeping only the shared responsibility table up to date"], a: 2, e: "直接・推移的な依存の一覧を維持し、新しい CVE と継続的に照合する。これが SBOM を整えたサプライチェーン管理の使い方。", eEn: "Maintain a list of direct and transitive dependencies and match it continuously against new CVEs. That is how an SBOM supports supply chain management."},
  {d: "IT5", q: "SBOM の位置づけとして適切でないものはどれか。", qEn: "Which of the following is NOT an appropriate description of the position of an SBOM?", o: ["ソフトウェアが安全に作られたことを保証する記録である", "ソフトウェアの構築に使う部品と供給関係の正式な記録である", "脆弱性管理を置き換えず、補完するものである", "ベンダーのリスク評価を置き換えず、補完するものである"], oEn: ["A record that guarantees the software was built securely", "A formal record of the components and supply relationships used to build software", "It complements vulnerability management without replacing it", "It complements vendor risk assessment without replacing it"], a: 0, e: "SBOM は部品の一覧であり、安全に作られたことの保証ではない。NIST は脆弱性管理やベンダーのリスク評価を補完するものと位置づける。", eEn: "An SBOM is a parts list, not a guarantee of secure construction. NIST positions it as complementing, not replacing, vulnerability management and vendor risk assessment."},
  {d: "IT5", q: "NIST が SBOM の標準形式に挙げているものはどれか。", qEn: "Which formats does NIST list as standard formats for SBOMs?", o: ["Template Analyzer、Checkov、Terrascan", "ARM、Bicep、Terraform", "SAST、DAST、シークレットスキャン", "SPDX、CycloneDX、SWID"], oEn: ["Template Analyzer, Checkov, Terrascan", "ARM, Bicep, Terraform", "SAST, DAST, secret scanning", "SPDX, CycloneDX, SWID"], a: 3, e: "NIST は SBOM の標準形式として SPDX、CycloneDX、SWID を挙げる。他の選択肢は IaC のツールやテンプレート形式、CI/CD の検査手法。", eEn: "NIST lists SPDX, CycloneDX and SWID as SBOM standard formats. The others are IaC tools and template formats, or CI/CD scan methods."},
  {d: "IT5", q: "SBOM とコンテナの脆弱性評価の違いとして正しいのはどれか。", qEn: "Which statement about the difference between an SBOM and container vulnerability assessment is correct?", o: ["SBOM は実行中コンテナの脅威を検知し、脆弱性評価は部品とその供給関係の記録だけを扱い、脅威検知は行わない", "SBOM は部品と供給関係の記録で安全性を保証せず、脆弱性評価はイメージや実行中コンテナの脆弱性を調べる", "SBOM を作成すれば、コンテナの脆弱性評価は不要になる", "両者は同一の検査で、出力形式が異なるだけである"], oEn: ["An SBOM detects threats in running containers, while vulnerability assessment handles only records of components and supply relationships", "An SBOM records components and supply relationships without guaranteeing safety, while vulnerability assessment examines images and running containers for vulnerabilities", "Once an SBOM is created, container vulnerability assessment becomes unnecessary", "They are the same check and differ only in output format"], a: 1, e: "SBOM は部品と供給関係の記録で、安全性の保証や脆弱性管理の代替にはならない。脆弱性評価はイメージや実行中コンテナを調べる。", eEn: "An SBOM records components and supply relations; it does not guarantee safety or replace vulnerability management. Vulnerability assessment examines images and running containers."},
  {d: "IT5", q: "公開 API に、OAuth 2 トークンの検証、レート制限、スキーマに基づく検証、未定義エンドポイントの拒否を一か所で強制したい。置くべきものはどれか。", qEn: "You want to enforce OAuth 2 token validation, rate limits, schema validation and rejection of undefined endpoints for public APIs in one place. What should you deploy?", o: ["各バックエンドのサービスごとに個別に実装した認証処理とレート制限の仕組み", "仮想ネットワーク内のプライベートエンドポイント", "稼働中ワークロードを守る CWPP", "Azure API Management のような API ゲートウェイ"], oEn: ["Authentication and rate limiting implemented separately in each backend service", "A private endpoint inside the virtual network", "CWPP protecting running workloads", "An API gateway such as Azure API Management"], a: 3, e: "API ゲートウェイでトークン検証、レート制限、スキーマ検証、未定義エンドポイントの拒否を一か所で強制できる。", eEn: "An API gateway can enforce token validation, rate limits, schema validation and rejection of undefined endpoints in one place."},
  {d: "IT5", q: "WAF と APIセキュリティの違いとして正しいのはどれか。", qEn: "Which statement about the difference between a WAF and API security is correct?", o: ["WAF は従来型のWeb攻撃やボットを防ぎ、APIセキュリティはオブジェクト単位の認可や利用量の制限が中心で、両者は補完関係にある", "WAF はオブジェクト単位の認可や利用量の制限を担い、APIセキュリティは従来型のWeb攻撃やボットの防御を担うため、両者は補完関係にある", "APIセキュリティを導入すれば WAF は不要になる", "WAF は認証済みの通信だけを対象にし、APIセキュリティは未認証の通信だけを対象にする"], oEn: ["A WAF blocks conventional web attacks and bots, while API security centers on object-level authorization and usage limits; they complement each other", "A WAF handles object-level authorization and usage limits, while API security defends against conventional web attacks and bots, so they complement each other", "Once API security is deployed, a WAF becomes unnecessary", "A WAF covers only authenticated traffic and API security covers only unauthenticated traffic"], a: 0, e: "WAF は従来型のWeb攻撃やボット、APIセキュリティはオブジェクト単位の認可や利用量の制限が中心。両者は補完関係で、一方で他方は代替できない。", eEn: "A WAF targets conventional web attacks and bots; API security centers on object-level authorization and usage limits. They complement, not replace, each other."},
  {d: "IT5", q: "生成AI向けの API で、利用量とコストを管理するために使える手段はどれか。", qEn: "Which measure can manage usage and cost for a generative AI API?", o: ["休眠アカウントの削除と、管理者権限の限定、利用実績に基づく権限の適正化", "トークン数の上限設定と、消費量メトリクスの出力", "IaC テンプレートの配備前の静的検査", "コンテナイメージの脆弱性評価の定期実行"], oEn: ["Deleting dormant accounts, limiting admin rights, and right-sizing permissions based on usage", "Setting token limits and emitting consumption metrics", "Static scanning of IaC templates before deployment", "Periodic vulnerability assessment of container images"], a: 1, e: "生成AI向けAPIでは、トークン数の上限設定（トークン制限）と消費量メトリクスの出力で利用とコストを管理できる。", eEn: "For generative AI APIs, token limits and consumption metrics let you manage usage and cost."},
  {d: "IT5", q: "API ゲートウェイで強制する制御やその運用として適切でないものはどれか。", qEn: "Which of the following is NOT an appropriate control or practice enforced at an API gateway?", o: ["OAuth 2 トークンを検証して、無効な要求を拒否する処理", "レート制限とクォータを設ける", "バックエンドの認証に、全 API 共通の固定パスワードを使う", "未定義のエンドポイントへの要求を拒否する"], oEn: ["Validating OAuth 2 tokens and rejecting invalid requests", "Setting rate limits and quotas", "Using one fixed password shared by all APIs for backend authentication", "Rejecting requests to undefined endpoints"], a: 2, e: "バックエンドの認証にはマネージドIDを使うのが示されており、共通の固定パスワードは不適切。他の三つはゲートウェイで強制する制御。", eEn: "Managed identities are the recommended way to authenticate to the backend, so a shared fixed password is inappropriate. The other three are gateway controls."},
  {d: "IT5", q: "Microsoft の整理で、物理ホスト、物理ネットワーク、データセンターが事業者の責任になるのは、どの利用形態からか。", qEn: "In Microsoft's framework, from which service model do physical hosts, physical networks and datacenters become the provider's responsibility?", o: ["IaaS から", "PaaS からのみ", "SaaS でのみ", "どの形態でも利用者の責任"], oEn: ["From IaaS onward", "Only from PaaS", "Only in SaaS", "The customer's responsibility in every model"], a: 0, e: "物理ホスト、物理ネットワーク、データセンターは IaaS から事業者の責任になる。SaaS でのみ、という限定は誤り。", eEn: "Physical hosts, networks and datacenters become the provider's responsibility from IaaS onward. Limiting it to SaaS only is wrong."},
  {d: "IT5", q: "責任共有モデルで常に利用者の責任に残る「構成」と「ID」について、構成の点検と権限の点検に当たる仕組みの組み合わせはどれか。", qEn: "Under the shared responsibility model, the customer always keeps responsibility for configuration and identities. Which pairing fits configuration checks and permission checks?", o: ["構成の点検は CWPP、ID の権限の点検は CSPM", "構成の点検は CIEM、ID の権限の点検は CWPP", "構成の点検は CSPM、ID の権限の点検は CIEM", "構成の点検はプライベートリンク、ID の権限の点検は SBOM"], oEn: ["CWPP for configuration checks, CSPM for identity permission checks", "CIEM for configuration checks, CWPP for identity permission checks", "CSPM for configuration checks, CIEM for identity permission checks", "Private Link for configuration checks, SBOM for identity permission checks"], a: 2, e: "構成の継続点検は CSPM、付与済みIDの権限の過剰を検査するのは CIEM の役割。他の組み合わせは役割が入れ替わっている。", eEn: "CSPM continuously checks configuration; CIEM inspects granted identity permissions for excess. The other pairings swap roles."},
  {d: "IT5", q: "CSPM で、ポリシーに反する設定が推奨事項に変換され、対応が進むと上がる指標はどれか。", qEn: "In CSPM, policy-violating settings become recommendations. Which indicator rises as remediation progresses?", o: ["AI BOM", "セキュアスコア", "アラートの重大度", "ファイルの整合性"], oEn: ["AI BOM", "Secure score", "Alert severity", "File integrity"], a: 1, e: "CSPM ではポリシー違反の設定が推奨事項になり、対応が進むとセキュアスコアが上がる。AI BOM は AI SPM が示すもの。", eEn: "In CSPM, violating settings become recommendations and the secure score rises as they are addressed. AI BOM is shown by AI SPM."},
  {d: "IT5", q: "ストレージに置かれたファイルのマルウェアを調べたい。CWPP がストレージ向けに挙げている保護はどれか。", qEn: "You want to check files stored in storage for malware. Which protection does CWPP list for storage?", o: ["ファイル整合性監視", "実行時保護", "環境強化", "マルウェアスキャン"], oEn: ["File integrity monitoring", "Runtime protection", "Environment hardening", "Malware scanning"], a: 3, e: "CWPP はストレージ向けにマルウェアスキャンを提供する。ファイル整合性監視はサーバ向け、実行時保護や環境強化はコンテナ向け。", eEn: "CWPP offers malware scanning for storage. File integrity monitoring is for servers; runtime protection and hardening are for containers."},
  {d: "IT5", q: "Defender for Cloud が CNAPP の中核に置く三つのうち、コード段階の誤設定や露出した秘密情報を扱うのはどれか。", qEn: "Among the three core elements Defender for Cloud places in CNAPP, which handles misconfigurations and exposed secrets at the code stage?", o: ["CSPM（稼働中の構成点検）", "CWPP（稼働中ワークロードの保護）", "DevSecOps（コードの検査）", "CIEM（権限の過剰の検査）"], oEn: ["CSPM (configuration checks of running resources)", "CWPP (protection of running workloads)", "DevSecOps (code-stage checks)", "CIEM (inspection of excess permissions)"], a: 2, e: "コード段階の誤設定や秘密情報は DevSecOps が扱う。CSPM は稼働中の構成、CWPP は稼働中ワークロード。CIEM は三つの中核に含まれない。", eEn: "DevSecOps handles code-stage misconfigurations and secrets. CSPM covers running configuration and CWPP running workloads. CIEM is not one of the three core elements."},
  {d: "IT5", q: "Google の Security Command Center Enterprise が、AI ワークロード向けに挙げているものはどれか。", qEn: "What does Google's Security Command Center Enterprise list for AI workloads?", o: ["予防・検出の制御", "復旧・廃棄の制御", "復旧・廃棄・監査の制御", "設計・開発の制御"], oEn: ["Preventive and detective controls", "Recovery and disposal controls", "Recovery, disposal and audit controls", "Design and development controls"], a: 0, e: "SCC Enterprise（Security Command Center の Enterprise 階層。2027年5月21日に終了予定で、既定では Premium 階層へ移行）は AI ワークロード向けの予防・検出制御を挙げている。CNAPP の領域でも AI への対応が進んでいる。", eEn: "SCC Enterprise (the Security Command Center Enterprise tier, which shuts down on May 21, 2027 and moves to the Premium tier by default) lists preventive and detective controls for AI workloads, showing AI coverage within the CNAPP space."},
  {d: "IT6", q: "クレジットカード番号を含むファイルが社外へ共有されそうなとき、内容を解析して警告やブロックを行い、操作を監査ログに残す仕組みはどれか。", qEn: "When a file containing credit card numbers is about to be shared externally, which mechanism analyzes the content, warns or blocks, and records the action in an audit log?", o: ["イミュータブルバックアップ", "CSPM", "KMS", "DLP"], oEn: ["Immutable backup", "CSPM", "KMS", "DLP"], a: 3, e: "DLP はポリシーに基づき内容を解析し、警告表示や共有のブロックを行い、操作を監査ログに記録する。他の三つは復旧、構成点検、鍵管理の仕組みである。", eEn: "DLP analyzes content under policy, warns or blocks sharing, and logs the action. The other three are for recovery, configuration checking and key management."},
  {d: "IT6", q: "DLP と機密ラベルの関係として正しいのはどれか。", qEn: "Which statement about the relationship between DLP and sensitivity labels is correct?", o: ["DLP が文書へ機密度の印を付けて保護の出発点になり、ラベルがその印や内容を条件に共有や持ち出しを止める", "ラベルは機密度を示して保護の出発点になり、DLP はラベルや内容を条件に共有や持ち出しを制御する", "ラベルがあれば DLP は不要で、どちらか片方だけ使えばよい", "DLP は保存期間を制御し、ラベルはバックアップを保護する"], oEn: ["DLP applies sensitivity marks as the starting point for protection, and labels block sharing and exfiltration based on those marks or content", "Labels mark sensitivity as the starting point for protection, and DLP controls sharing and exfiltration using labels or content as conditions", "With labels in place DLP is unnecessary, so only one of them is needed", "DLP controls retention periods, and labels protect backups"], a: 1, e: "ラベルが機密度の印を付け、DLP がその印や内容を条件に共有・持ち出しを止める。両者は組み合わせて使う。役割の入れ替えや片方のみの運用は誤り。", eEn: "Labels mark sensitivity and DLP stops sharing or exfiltration based on those marks or content. They are used together; swapping roles or using just one is wrong."},
  {d: "IT6", q: "未承認の外部生成AIサービスへの機密情報の送信を抑えたい。Microsoft Purview の DLP について正しいのはどれか。", qEn: "You want to curb sending confidential information to unapproved external generative AI services. Which statement about Microsoft Purview DLP is correct?", o: ["対象は Microsoft 365 Copilot だけで、ブラウザやネットワーク経由での外部サービスへの送信は対象外", "機密ラベルを付けるだけで、送信のブロックはできない", "ブラウザやネットワーク経由での ChatGPT、Gemini、DeepSeek などへの送信も対象にできる", "鍵管理サービスで暗号化した通信に限って送信を検査できる"], oEn: ["It covers only Microsoft 365 Copilot and not sending to external services via the browser or network", "It can only apply sensitivity labels and cannot block sending", "It can also cover sending to ChatGPT, Gemini, DeepSeek and others via the browser or network", "It can inspect sending only for traffic encrypted with a key management service"], a: 2, e: "Purview の DLP は Copilot を監視場所に含めるうえ、ブラウザやネットワーク経由で外部の生成AIへの機密情報の送信も対象にできる。", eEn: "Purview DLP includes Copilot as a monitored location and can also cover sending sensitive data to external generative AI via the browser or network."},
  {d: "IT6", q: "標準の鍵管理サービスと HSM 型の違いとして正しいのはどれか。", qEn: "Which statement about the difference between standard key management and HSM-type is correct?", o: ["標準は専用ハードウェアで鍵を保護し、HSM 型はソフトウェアで保護する", "標準は事業者が管理する鍵だけを扱い、HSM 型は利用者が作成・管理する顧客管理鍵だけを扱う", "標準はデータの暗号化に使い、HSM 型は通信の暗号化にだけ使う", "標準はソフトウェアで鍵を保護し、HSM 型は認証済みのハードウェア内で鍵を保護する"], oEn: ["Standard protects keys in dedicated hardware, while HSM-type protects them in software", "Standard handles only provider-managed keys, while HSM-type handles only customer-managed keys", "Standard encrypts data, while HSM-type is used only to encrypt communications", "Standard protects keys in software, while HSM-type protects keys inside certified hardware"], a: 3, e: "標準の鍵管理はソフトウェアで、HSM 型は認証済みハードウェア内で鍵を保護する。保護の仕組みが逆、鍵の種類で分ける、用途で分ける説明は誤りである。", eEn: "Standard key management protects keys in software; HSM-type protects them in certified hardware. Reversing the mechanism or splitting by key type or use is wrong."},
  {d: "IT6", q: "規制の要件から、鍵の信頼の起点を利用者自身が握る必要がある。どの保護水準を選ぶべきか。", qEn: "A regulation requires the customer itself to hold the root of trust for its keys. Which protection level should you choose?", o: ["単一テナント型の HSM", "事業者が管理する鍵", "ソフトウェアで鍵を保護する標準の鍵管理サービス", "鍵暗号化鍵を追加で重ねる構成"], oEn: ["A single-tenant HSM", "Provider-managed keys", "The standard key management service that protects keys in software", "A configuration that adds a key encryption key on top"], a: 0, e: "単一テナント型の HSM は、利用者が鍵の信頼の起点を握る型である。事業者管理の鍵や標準のソフト保護、鍵暗号化鍵の追加ではその要件を満たさない。", eEn: "A single-tenant HSM lets the customer hold the root of trust for keys. Provider-managed keys, standard software protection or an added key encryption key do not meet that need."},
  {d: "IT6", q: "生成AIに渡す社内データを置く基盤で、保存時の暗号化に顧客管理鍵を使うか迷っている。判断の根拠として適切なのはどれか。", qEn: "You are unsure whether to use customer-managed keys for encryption at rest on the platform holding internal data for generative AI. What is an appropriate basis for the decision?", o: ["事業者管理の鍵は保存時の暗号化に使えない点", "規制や契約の要件", "顧客管理鍵は生成AIに渡すデータには使えない点", "データと ID は利用者の責任なので鍵は必ず自社で持つ点"], oEn: ["That provider-managed keys cannot be used for encryption at rest", "Regulatory and contractual requirements", "That customer-managed keys cannot be used for data passed to generative AI", "That data and identity are the customer's responsibility, so keys must always be held in-house"], a: 1, e: "鍵を自社で持つかは、規制や契約の要件から決める論点。事業者管理の鍵と顧客管理鍵は選べるので、使えない、必ず自社で持つという前提は誤りである。", eEn: "Whether to hold keys in-house is decided by regulatory and contractual requirements. Both provider-managed and customer-managed keys can be chosen, so the stated premises are wrong."},
  {d: "IT6", q: "機密ラベルを付けたファイルを別の保存先へ移した。ラベルの扱いとして正しいのはどれか。", qEn: "A file carrying a sensitivity label was moved to a different storage location. What happens to the label?", o: ["移動先で付け直さない限り、ラベルは外れる", "ラベルは保存先のフォルダ設定として保持され、別のフォルダへ移動すると移動先の設定に置き換わる", "ラベルはファイルのメタデータに保存されるので、保存先が変わっても付いて回る", "ラベルは社内の保存先に限り付いて回る"], oEn: ["The label is dropped unless it is reapplied at the destination", "The label is held as a folder setting and is replaced by the destination's setting upon moving to another folder", "The label is stored in the file's metadata, so it follows the file even when the location changes", "The label follows the file only within internal locations"], a: 2, e: "ラベルはファイルのメタデータに保存され、保存先が変わっても付いて回る。移動で外れる、フォルダ設定で置き換わるといった理解は誤り。", eEn: "Labels are stored in file metadata and follow the file when the location changes. Thinking they drop off or are replaced by folder settings is wrong."},
  {d: "IT6", q: "文書の保存期間を制御したい。機密ラベルとの関係として正しいのはどれか。", qEn: "You want to control how long documents are kept. Which statement about its relationship to sensitivity labels is correct?", o: ["機密ラベルを最上位の区分にすれば、保存期間も自動で決まる", "保持ラベルを付けると機密ラベルは外れる", "保持ラベルは暗号化や透かしを適用するために使う", "保持ラベルを、機密ラベルとは別に付ける"], oEn: ["Setting the sensitivity label to the top tier decides the retention period automatically", "Applying a retention label removes the sensitivity label", "Retention labels are used to apply encryption and watermarks", "Apply a retention label separately from the sensitivity label"], a: 3, e: "保持ラベルは保存期間の制御用で、機密ラベルとは別に付ける。暗号化や透かしは機密ラベルに応じて適用する保護であり、両者は役割が異なる。", eEn: "Retention labels control retention and are applied separately from sensitivity labels. Encryption and watermarks are protections applied by sensitivity labels, so the roles differ."},
  {d: "IT6", q: "暗号化を伴う機密ラベルが付いた文書を、Microsoft 365 Copilot が扱うときの挙動として正しいのはどれか。", qEn: "How does Microsoft 365 Copilot behave with a document carrying a sensitivity label that includes encryption?", o: ["利用者にコピー権限（EXTRACT）がある項目のデータだけを返す", "ラベルに関係なく、文書の内容をすべて返す", "暗号化ラベルが付いた文書は一切参照しない", "利用者に閲覧権限があれば、ラベルや暗号化の有無にかかわらず常にデータを返す"], oEn: ["It returns only data from items for which the user has the copy right (EXTRACT)", "It returns all content regardless of the label", "It never references documents with an encryption label", "It always returns data as long as the user has view permission, whether or not a label or encryption is applied"], a: 0, e: "Copilot は機密ラベルを認識し、暗号化を伴うラベルでは EXTRACT 権限がある項目のデータだけを返す。全返却や一切不参照、閲覧権限だけの判断は誤り。", eEn: "Copilot recognizes sensitivity labels and, for encrypting labels, returns data only from items where the user holds EXTRACT. Returning everything, nothing, or deciding on view permission alone is wrong."},
  {d: "IT6", q: "ランサムウェアにバックアップごと消されても、復旧に使う復旧ポイントを残したい。最も適した対策はどれか。", qEn: "Even if ransomware tries to wipe the backups too, you want recovery points to survive. Which measure fits best?", o: ["通常のバックアップを取得する頻度を上げ、世代数も増やして保管する", "保持期間中は削除も改変もできないイミュータブル設定にする", "バックアップの暗号化鍵を顧客管理鍵に切り替える", "バックアップ先への機密ラベル付与を徹底する"], oEn: ["Take regular backups more often and keep more generations", "Use an immutable setting that prevents deletion and modification during the retention period", "Switch the backup encryption key to a customer-managed key", "Make sure sensitivity labels are applied to the backup destination"], a: 1, e: "イミュータブル設定は保持期間中の削除・改変を防ぎ、復旧ポイントを残す。通常のバックアップは権限があれば削除でき、頻度や鍵、ラベルでは防げない。", eEn: "Immutable settings block deletion and modification during retention, keeping recovery points. Regular backups can be deleted by anyone with permission, and frequency, keys or labels do not prevent it."},
  {d: "IT6", q: "Azure Backup のイミュータブル保管庫を「ロック」した後の状態として正しいのはどれか。", qEn: "Which describes the state of an Azure Backup immutable vault after it is locked?", o: ["期限前の削除は禁止されるが、保持期間の短縮は認められる", "管理者であれば、保持期間中でもいつでもイミュータブル設定を無効化できる", "WORM ストレージとなり、イミュータブル設定を無効化できなくなる", "保持期間が終わるまで、復旧ポイントを復旧に使えなくなる"], oEn: ["Early deletion is prohibited, but shortening the retention period is allowed", "An administrator can disable the immutability setting at any time, even within the retention period", "It becomes WORM storage and the immutability setting can no longer be disabled", "Recovery points cannot be used for recovery until the retention period ends"], a: 2, e: "ロックすると WORM ストレージとなり、無効化もできなくなる。期限前の削除と保持期間の短縮はどちらも禁止される。管理者でも無効化はできない。", eEn: "Locking makes it WORM storage and disabling is no longer possible. Both early deletion and shortening retention are prohibited, and even administrators cannot disable it."},
  {d: "IT6", q: "生成AIの導入で、検索用の文書や索引などの社内データが増えた。バックアップの考え方として適切なのはどれか。", qEn: "Generative AI adoption has increased internal data such as documents and indexes for search. Which backup approach is appropriate?", o: ["モデルを利用するだけなので、バックアップの対象外とする", "索引だけを対象にして、元の文書は対象から外す", "通常のバックアップと同じ扱いにして、保持期間は決めない", "復旧対象と保持期間を決めて、バックアップの範囲に含める"], oEn: ["Exclude them since the model is only being used", "Back up only the indexes and leave out the source documents", "Treat them like regular backups without setting retention periods", "Decide the recovery targets and retention periods and include them in the backup scope"], a: 3, e: "生成AIの導入で増えるデータも、復旧対象と保持期間を決めてバックアップの範囲に含める。対象外にする、索引だけにする、期間を決めないのは不十分。", eEn: "Data that grows with generative AI should also get defined recovery targets and retention periods within backup scope. Excluding it, backing up only indexes or skipping retention is inadequate."},
  {d: "IT6", q: "複数のクラウドに散らばるデータストアについて、機密データの所在、アクセス権、保護状況を自動で探索・把握し、流出につながるリスクの優先順位を付けたい。まず当てる仕組みは？", qEn: "You want to automatically discover where sensitive data sits across data stores in multiple clouds, who can access it and how it is protected, and to prioritize leak risks. Which mechanism should you apply first?", o: ["DSPM：データそのものを起点に、所在と保護の穴を継続的に見つける", "DLP：ポリシーに基づき、共有や持ち出しの操作を検知して遮断する", "IRM：暗号化と利用権限をファイル自体に付け、管理外でも保護を続ける", "eDiscovery：訴訟に備え、対象データを保全して検索・書き出しする"], oEn: ["DSPM: starts from the data itself and continuously finds where it is and where protection has gaps", "DLP: detects and blocks sharing or exfiltration operations based on policy", "IRM: attaches encryption and usage rights to the file itself so protection continues outside managed storage", "eDiscovery: preserves, searches and exports target data in preparation for litigation"], a: 0, e: "DSPM は複数クラウドのデータを自動で探索し、所在・アクセス権・保護状況を把握してリスクに優先順位を付ける。DLP は操作の遮断、IRM は保護の付与、eDiscovery は証拠の保全が役割。", eEn: "DSPM automatically discovers data across clouds and ranks risks by location, access and protection. DLP blocks operations, IRM attaches protection, and eDiscovery preserves evidence."},
  {d: "IT6", q: "媒体のサニタイズについて、NIST SP 800-88 が示すものとして正しいのはどれか。", qEn: "Regarding media sanitization, which statement correctly describes what NIST SP 800-88 provides?", o: ["業種ごとに文書を残す法定の保存年数を定め、期限までの削除を禁じる一覧", "暗号鍵の作成と保管を専用のハードウェア内で行うための、鍵管理装置の認定基準", "情報の機微度に応じて消去・廃棄の技術と統制を決める、サニタイズ計画の指針", "ランサムウェア対策として、バックアップの復旧ポイントを削除不能にする保管庫の設定手順"], oEn: ["A list of statutory retention periods by industry that forbids deletion before the deadline", "Certification criteria for key-management devices that create and store keys inside dedicated hardware", "Guidance for a sanitization plan that decides disposal techniques and controls according to the sensitivity of the information", "Configuration steps for a vault that makes backup recovery points undeletable against ransomware"], a: 2, e: "NIST SP 800-88 は、媒体上のデータへのアクセスを所定の労力では不可能にするサニタイズについて、情報の機微度に応じた消去・廃棄の技術と統制を決める計画の指針を示す。保存年数の一覧、HSM の基準、イミュータブル保管庫の手順ではない。", eEn: "NIST SP 800-88 gives guidance for planning sanitization (making access to data on media infeasible for a given effort), choosing disposal techniques and controls by information sensitivity. It is not a retention list, an HSM standard or an immutable-vault procedure."},
  {d: "IT6", q: "インターネットに露出した仮想マシンから機密データのあるストアへ至る攻撃経路まで把握したい。Defender for Cloud の DSPM 機能の説明として正しいのはどれか。", qEn: "You want to see the attack path from an internet-exposed virtual machine to a store holding sensitive data. Which describes the DSPM capability of Defender for Cloud?", o: ["データを探索せず、端末上の振る舞いを常時監視して、不審なプロセスと通信とを遮断する", "機密データを含むファイルを自動で暗号化し、攻撃経路そのものを閉じる", "データをサンプリングして機密情報の種類を判定し、露出や流れの評価から攻撃経路も示す", "単一クラウドのデータベースだけを探索し、データの流れは評価しない"], oEn: ["It does not discover data; it monitors behavior on endpoints and blocks suspicious processes and traffic", "It automatically encrypts files containing sensitive data and thereby closes the attack path itself", "It samples data to identify the types of sensitive information and also shows attack paths from its assessment of exposure and data flow", "It explores only databases in a single cloud and does not evaluate data flow"], a: 2, e: "Defender for Cloud は複数クラウドのストアを探索し、サンプリングで機密情報の種類を判定する。露出と流れを評価して攻撃経路も示す。端末の遮断や自動暗号化は DSPM の役割ではない。", eEn: "Defender for Cloud explores stores across clouds, samples data to classify sensitive types, and assesses exposure and flow to show attack paths. Endpoint blocking and auto-encryption are not DSPM's role."},
  {d: "IT6", q: "Microsoft 365 Copilot などのAIアプリやエージェントについて、機密データを含むやり取りや過剰な共有を可視化して追跡したい。Purview のどの領域が担うか。", qEn: "You want to visualize and track exchanges containing sensitive data and excessive sharing for AI apps and agents such as Microsoft 365 Copilot. Which Purview area handles this?", o: ["トークナイゼーション（機密値の代替値への置き換え）", "動的データマスキング（問い合わせ結果の表示の制御）", "データ消去・廃棄（使い終えた媒体のサニタイズ）", "DSPM（AIアプリとエージェントの活動の可視化）"], oEn: ["Tokenization (replacing sensitive values with substitute values)", "Dynamic data masking (controlling what query results display)", "Data disposal (sanitizing media that is no longer needed)", "DSPM (visibility into the activity of AI apps and agents)"], a: 3, e: "Purview の DSPM は AI アプリとエージェントの活動を可視化し、機密データを含むやり取りや過剰な共有を追跡する。消去・トークン化・マスキングは追跡の仕組みではない。", eEn: "Purview DSPM visualizes AI app and agent activity and tracks exchanges with sensitive data and excessive sharing. Disposal, tokenization and masking are not tracking mechanisms."},
  {d: "IT6", q: "書式に制約があるレガシーシステムへ、クレジットカード番号を同じ文字種・長さのまま、意味を持たない値に置き換えて渡したい。適した手法はどれか。", qEn: "You need to pass credit card numbers to a legacy system with format constraints, replaced by meaningless values of the same character type and length. Which technique fits?", o: ["動的マスキングで、保存値は変えずに、下4桁以外を問い合わせ結果の表示上で隠す", "書式保持暗号化（FPE）を使ったトークン化で、同じ文字種・長さの代替値にする", "保持ラベルを付け、期間満了時に処分レビューを挟んで削除する", "匿名加工情報に加工し、本人の同意なく第三者へ提供できる状態にする"], oEn: ["Dynamic masking, hiding all but the last four digits in query results without changing stored values", "Tokenization using format-preserving encryption (FPE), producing substitute values of the same character type and length", "A retention label that inserts a disposition review and deletes at the end of the period", "Processing into anonymously processed information so it can be given to third parties without consent"], a: 1, e: "Cloud DLP は書式保持暗号化で入力値を同じ文字種・長さのトークンに置き換え、書式制約のある旧システムとの互換を保つ。マスキングは見せ方の制御で、値全体の置き換えではない。", eEn: "Cloud DLP uses FPE to replace inputs with tokens of the same character type and length, keeping legacy compatibility. Masking controls display; it does not replace the whole value."},
  {d: "IT6", q: "トークン化の方式の違いとして正しいのはどれか。", qEn: "Which statement correctly describes the difference between tokenization methods?", o: ["書式保持暗号化は一方向で元に戻せず、復元の接頭辞も付けられず、鍵で生成した一方向ハッシュは元に戻せる", "書式保持暗号化は復元できることを示す接頭辞を付けられ、鍵で生成した一方向ハッシュは元に戻せない", "どちらの方式も元に戻せず、同じ文字種・長さの代替値にもできない", "一方向ハッシュ方式だけが、同じ文字種・長さの代替値で書式制約に対応できる"], oEn: ["FPE is one-way and cannot be reversed or carry a restoration prefix, whereas a keyed one-way hash can be reversed", "Format-preserving encryption can carry a prefix showing it is reversible, whereas a keyed one-way hash cannot be reversed", "Neither method can be reversed, and neither can produce substitutes of the same character type and length", "Only the one-way hash method can meet format constraints with substitutes of the same type and length"], a: 1, e: "FPE は同じ文字種・長さで書式制約に対応し、復元できることを示す接頭辞も付けられる。鍵で生成した一方向ハッシュに置き換える方式は元に戻せない。", eEn: "FPE meets format constraints with the same type and length and can carry a reversibility prefix. Replacement with a keyed one-way hash cannot be reversed."},
  {d: "IT6", q: "トークナイゼーション、データマスキング、仮名加工情報の位置づけとして正しいのはどれか。", qEn: "Which statement correctly describes how tokenization, data masking and pseudonymously processed information are positioned?", o: ["三者とも個人情報保護法に定められた加工情報の区分である", "三者とも技術手法であり、法的な区分とは無関係である", "前二者は技術手法であり、仮名加工情報は個人情報保護法上の区分である", "仮名加工情報とマスキングが法的な区分で、トークン化だけが技術手法である"], oEn: ["All three are categories of processed information defined in the Personal Information Protection Act", "All three are technical methods unrelated to any legal category", "The first two are technical methods, while pseudonymously processed information is a category under the Personal Information Protection Act", "Pseudonymization and masking are legal categories; only tokenization is a technical method"], a: 2, e: "マスキングが一部を隠し、トークン化が値全体を代替値に置き換える技術手法であるのに対し、仮名加工情報は個人情報保護法上の区分。技術手法と法的区分は別物。", eEn: "Masking hides part of a value and tokenization replaces the whole value; both are technical methods, whereas pseudonymously processed information is a legal category."},
  {d: "IT6", q: "口座番号を含む文章を生成AIに渡す前に、口座番号をトークンに置き換える利点として正しいのはどれか。", qEn: "What is a correct benefit of replacing account numbers with tokens before passing text containing them to a generative AI?", o: ["置き換えた値は常に元へ戻せるので、外部サービス側で復元して照合できる", "置き換えた時点で個人情報に当たらなくなり、本人の同意なく第三者へ提供できる", "機密ラベルが自動で付き、以後のあらゆる共有がブロックされる", "モデルや外部サービスへ生の値を送らずに、処理を進められる"], oEn: ["The replaced values can always be restored, so the external service can reverse them and match records", "Once replaced, the data is no longer personal information and can be given to third parties without consent", "A sensitivity label is attached automatically and all later sharing is blocked", "Processing can proceed without sending the raw values to the model or external service"], a: 3, e: "トークンに置き換えれば、モデルや外部サービスへ生の値を送らずに処理できる。方式によっては復元できず、またトークン化は技術手法で、法的区分を自動で変えるものではない。", eEn: "Tokens let processing proceed without sending raw values externally. Some methods are irreversible, and tokenization is a technique that does not automatically change legal classification."},
  {d: "IT6", q: "データベースの保存値は変えずに、権限のない利用者にはクレジットカード番号を下4桁だけ見せたい。適した手法はどれか。", qEn: "You want unprivileged users to see only the last four digits of credit card numbers without changing the values stored in the database. Which technique fits?", o: ["動的データマスキングで、問い合わせ結果だけを利用者に応じて隠す", "トークナイゼーションで、保存する値そのものを代替値に置き換える", "DSPM で機密の列を探索し、権限のない利用者の参照を自動で止める", "保持ラベルを付け、権限のない利用者の閲覧を禁止する"], oEn: ["Dynamic data masking, hiding only the query results according to the user", "Tokenization, replacing the stored values themselves with substitute values", "DSPM, discovering sensitive columns and automatically stopping references by unprivileged users", "A retention label that prohibits viewing by unprivileged users"], a: 0, e: "動的マスキングは保存値を変えず、問い合わせ結果だけを権限のない利用者向けに隠す。トークン化は保存値自体を置き換え、DSPM は所在を見つけるだけ、保持ラベルは保存期間の制御用。", eEn: "Dynamic masking leaves stored values intact and hides only query results from unprivileged users. Tokenization replaces stored values, DSPM only discovers, and retention labels control retention periods."},
  {d: "IT6", q: "動的データマスキングを設定したカード番号の列を、UNMASK 権限を持つ利用者が問い合わせると、何が返るか。", qEn: "What is returned when a user with UNMASK permission queries a card-number column that has dynamic data masking configured?", o: ["下4桁だけが見える形にした値が返る", "意味を持たない代替値のトークンが返る", "元の値がそのまま返る", "保存値が上書きされた、伏せ字だけの値が返る"], oEn: ["A value showing only the last four digits is returned", "A meaningless substitute token is returned", "The original value is returned as is", "A value consisting only of mask characters, overwriting the stored value, is returned"], a: 2, e: "UNMASK 権限を持つ利用者や管理者には元の値が見える。動的マスキングは保存値を変えず、権限のない利用者への結果だけを隠す。", eEn: "Users with UNMASK permission and administrators see the original values. Dynamic masking does not alter stored values and only hides results from unprivileged users."},
  {d: "IT6", q: "本番データを使った AI の検証や障害調査で、開発者への個人情報の露出を抑えたい。マスキングの使い方として適切なのはどれか。", qEn: "You want to limit exposure of personal data to developers during AI validation or incident investigation that uses production data. Which use of masking is appropriate?", o: ["開発者にトークン化した値の復元手段を渡し、必要なときに元の値へ戻させる", "開発者全員に UNMASK 権限を付け、画面上の扱いに注意を促す", "開発者にはマスキング済みの結果だけを見せ、UNMASK 権限は与えない", "機密ラベルを付けるだけで、開発者の画面でも値が自動的に伏せ字になる"], oEn: ["Give developers a way to restore tokenized values and let them revert to the originals when needed", "Grant UNMASK permission to all developers and urge care with what is on screen", "Show developers only masked results and do not grant UNMASK permission", "Just attaching a sensitivity label automatically turns the values into mask characters on the developer's screen"], a: 2, e: "開発・テスト担当には、マスキング済みの結果だけを見せれば個人情報の露出を抑えられる。UNMASK 権限や復元手段を渡すと露出は防げず、ラベルだけでは値は伏せ字にならない。", eEn: "Showing developers only masked results limits exposure. Granting UNMASK or restoration means defeats this, and a label alone does not mask values."},
  {d: "IT6", q: "本人の同意なく第三者へ提供できるのは、個人情報保護法上のどの加工情報か。", qEn: "Which kind of processed information under the Personal Information Protection Act can be provided to a third party without the data subject's consent?", o: ["仮名加工情報（他の情報と照合しない限り識別できない）", "匿名加工情報（識別できず、元に復元できない）", "マスキング済みの情報（一部の文字を固定文字で隠した値）", "トークン化した情報（値全体を代替値に置き換えた値）"], oEn: ["Pseudonymously processed information (not identifiable unless matched with other information)", "Anonymously processed information (cannot be identified or restored)", "Masked information (values with some characters hidden by fixed characters)", "Tokenized information (values wholly replaced by substitute values)"], a: 1, e: "匿名加工情報は個人情報に該当せず、本人の同意なく第三者へ提供できる。仮名加工情報は第三者提供が原則禁止。マスキングやトークン化は技術手法で、法的な区分ではない。", eEn: "Anonymously processed information is not personal information and can be provided without consent. Pseudonymized information generally cannot be provided; masking and tokenization are not legal categories."},
  {d: "IT6", q: "作成者が元の情報を通常保有する仮名加工情報の扱いとして正しいのはどれか。", qEn: "Which correctly describes the handling of pseudonymously processed information, where the creator normally retains the original information?", o: ["個人情報には当たらないが、第三者への提供は原則禁止で、利用目的の変更も関連性の範囲内に限られる", "個人情報に当たらず、本人の同意なく第三者へ自由に提供でき、利用目的も変更できる", "原則として個人情報に当たり、第三者提供も利用目的の変更も認められない", "原則として個人情報に当たり、第三者提供は原則禁止だが、利用目的は関連性の範囲を超えて変更できる"], oEn: ["It is not personal information, but provision to third parties is prohibited and changes of purpose are limited to the scope of relevance", "It is not personal information, can be freely provided to third parties without consent, and its purpose of use can be changed", "It is in principle personal information, and neither provision to third parties nor a change of purpose is allowed", "It is in principle personal information and may not generally be provided to third parties, but the purpose of use may be changed beyond the scope of relevance"], a: 3, e: "仮名加工情報は、作成者が元の情報を持つため原則個人情報に当たる。第三者提供は原則禁止だが、利用目的は関連性の範囲を超えて変更できる点が特徴。", eEn: "Because the creator holds the original data, pseudonymized information is in principle personal information. Third-party provision is generally prohibited, but the purpose can be changed beyond relevance."},
  {d: "IT6", q: "個人情報を含む顧客データを AI の分析や学習に使う前に、第三者提供や利用目的の扱いを見極めるため、確認すべきことは何か。", qEn: "Before using customer data containing personal information for AI analysis or training, what should be checked to determine handling of third-party provision and purpose of use?", o: ["加工にマスキングとトークン化のどちらを使ったか、その技法の名称", "AI サービスの提供先リージョンが日本国内かどうか、その一点", "データに付いた保持ラベルの期間が、AI の学習期間より長いかどうか", "加工した情報を、仮名加工情報と匿名加工情報のどちらとして扱えるか"], oEn: ["Which of masking or tokenization was used for processing, by technique name", "Whether the AI service's region is in Japan, as the only point", "Whether the retention period on the data's label is longer than the AI training period", "Whether the processed data can be treated as pseudonymously or anonymously processed information"], a: 3, e: "どちらの加工情報として扱えるかで、第三者提供と利用目的の扱いが変わる。技法の名称やリージョン、保持ラベルの期間だけでは、この区分は決まらない。", eEn: "Which type of processed information applies changes the handling of third-party provision and purpose of use. Technique name, region or retention period alone does not decide it."},
  {d: "IT6", q: "個人データを外国にある第三者へ提供する。原則は事前の本人の同意が必要だが、同意なしで提供できる場合はどれか。", qEn: "You will provide personal data to a third party in a foreign country. Prior consent is the rule; in which case can it be provided without consent?", o: ["提供先が、基準に適合する体制を整備している場合", "提供するデータに機密ラベルを付け、暗号化して送る場合", "提供先の国が、日本と取引関係にある国である場合", "提供先のクラウドで、データ所在地のリージョンを選べる場合"], oEn: ["The recipient has established a system that meets the required standards", "The data carries a sensitivity label and is sent encrypted", "The recipient's country has a trade relationship with Japan", "The recipient's cloud lets you choose the region where the data resides"], a: 0, e: "外国の第三者への提供は原則本人の事前同意が必要だが、提供先の国が同等水準の制度を持つと規則で定められた場合や、提供先が基準適合体制を整備している場合は不要。", eEn: "Prior consent is the rule, but it is unnecessary if the recipient's country is designated as having an equivalent system or if the recipient has a standards-compliant system."},
  {d: "IT6", q: "基準適合体制を整備している外国の事業者へ個人データを提供し続ける。提供する側に必要な対応はどれか。", qEn: "You keep providing personal data to a foreign business that has a standards-compliant system. What must the providing side do?", o: ["提供開始時に一度だけ、提供先の体制を確認すれば足りるとする", "年1回程度以上、提供先での基準適合体制の実施状況を確認する", "提供のたびに、本人から個別に書面の同意を取り直す", "提供先の国名を、年1回、官報に掲載して公表する"], oEn: ["Checking the recipient's system once at the start of provision is enough", "Check at least about once a year how the recipient is carrying out its standards-compliant system", "Obtain separate written consent from the individual again each time", "Publish the recipient's country in the official gazette once a year"], a: 1, e: "基準適合体制による提供では、年1回程度以上の実施状況の確認が必要になる。開始時の一度きりの確認では足りない。毎回の同意取り直しや官報掲載は要件ではない。", eEn: "Provision under a standards-compliant system requires confirming implementation about once a year or more. A one-time check is insufficient; re-consent or gazette notices are not required."},
  {d: "IT6", q: "海外のリージョンで動く生成AIサービスに、個人データの処理を委託する。確認として正しいのはどれか。", qEn: "You will entrust processing of personal data to a generative AI service running in an overseas region. Which check is correct?", o: ["委託は提供に当たらないので、個人データの処理でも第28条の対象外として扱ってよい", "国内リージョンを選んでいなければ、一律に第28条違反となる", "委託であっても、外国にある第三者への提供として第28条の対象になるかを確認する", "暗号化していれば、提供先の確認も本人の同意も不要である"], oEn: ["Entrustment is not provision, so it may be treated as outside Article 28", "Unless a domestic region is chosen, it is uniformly a violation of Article 28", "Check whether, even as entrustment, it counts as provision to a third party in a foreign country subject to Article 28", "If it is encrypted, neither confirming the recipient nor obtaining consent is required"], a: 2, e: "海外リージョンの生成AIへの委託も、外国にある第三者への提供として第28条の対象とされている。委託だから対象外、暗号化すれば不要、とは言えない。", eEn: "Entrustment to an overseas generative AI is also treated as provision to a foreign third party under Article 28. Entrustment or encryption does not exempt it."},
  {d: "IT6", q: "データ所在地と越境移転規制の関係として正しいのはどれか。", qEn: "Which statement correctly describes the relationship between data residency and cross-border transfer rules?", o: ["所在地は外国の第三者への提供に課される法的規律、越境規制はリージョンで選ぶ置き場所の選択であり、どちらかを確認すれば足りる", "国内リージョンを選べば越境規制の対象外となるので、所在地の確認だけでよい", "越境規制は外国にデータを置く場合だけにかかり、提供の有無は問われない", "所在地はリージョンで選ぶ置き場所の選択、越境規制は外国の第三者への提供に課される法的規律で、両方を確認する"], oEn: ["Residency is a legal obligation on provision to foreign third parties and transfer rules are a region-based choice of location, so checking either one is enough", "Choosing a domestic region exempts you from transfer rules, so checking residency alone is enough", "Transfer rules apply only when data is stored abroad, regardless of whether it is provided to anyone", "Residency is a choice of location made by region, whereas transfer rules are legal obligations on provision to foreign third parties; check both"], a: 3, e: "データ所在地はどこに置くかの選択で、クラウドではリージョンで選ぶ。越境移転規制は外国の第三者への提供に課される法的規律。両者は別の確認事項なので両方を確認する。", eEn: "Residency is where to place data, chosen by region in the cloud. Transfer rules are legal obligations on provision to foreign third parties. They are separate checks, so confirm both."},
  {d: "IT6", q: "Azure Data Box でデータのアップロードが完了した。端末内のデータの扱いと確認手段として正しいのはどれか。", qEn: "Uploading with Azure Data Box is complete. Which describes the handling of data on the device and how it is verified?", o: ["論理削除されるだけで、消去の証明書は発行されず、確認には事業者への個別の問い合わせが必要になる", "ブロック消去され、NIST SP 800-88 に沿った消去証明書をポータルから取得できる", "暗号鍵だけが破棄され、消去証明書は物理媒体の返送後に郵送される", "保持ポリシーに従って一定期間残り、期間満了後に自動で削除される"], oEn: ["It is merely logically deleted, no proof of erasure is issued, and you must inquire with the provider", "It is block-erased, and an erasure certificate aligned with NIST SP 800-88 can be obtained from the portal", "Only the encryption key is destroyed, and a certificate is mailed after the physical media is returned", "It remains for a set period under a retention policy and is deleted automatically after expiry"], a: 1, e: "Azure Data Box はアップロード完了後に端末内のデータをブロック消去し、NIST SP 800-88 に沿った消去証明書をポータルから取得できる。論理削除や鍵破棄だけの扱いではない。", eEn: "After upload, Azure Data Box block-erases the device data and provides a NIST SP 800-88 erasure certificate via the portal. It is not mere logical deletion or key destruction."},
  {d: "IT6", q: "データ保持とデータ消去・廃棄の関係として正しいのはどれか。", qEn: "Which statement correctly describes the relationship between data retention and data disposal?", o: ["保持が残す期間を決め、消去・廃棄は満了後に対象を確実にアクセス不能にする終端の工程になる", "消去・廃棄が残す期間を決め、保持は満了後に、対象を確実にアクセス不能にする終端の工程になる", "両者は同じ工程の別名で、期間の管理と媒体の処理に使い分けはない", "保持は復旧用の複製だけを対象にし、消去・廃棄は元のコンテンツだけを対象にする"], oEn: ["Retention sets how long data is kept; disposal is the final step that reliably makes it inaccessible after expiry", "Disposal sets how long data is kept; retention is the final step that makes it inaccessible after expiry", "They are two names for the same step, with no difference between managing periods and handling media", "Retention covers only recovery copies, whereas disposal covers only the original content"], a: 0, e: "データ保持が残す期間を決め、消去・廃棄は期間が満了したあと対象を確実にアクセス不能にする終端の工程。二つは期間管理と終端処理という別の役割を持つ。", eEn: "Retention decides how long data stays; disposal is the terminal step that makes it reliably inaccessible after expiry. They are distinct roles."},
  {d: "IT6", q: "AIの検証のために複製したデータと、使い終えた検証環境がある。消去・廃棄の前提として正しいのはどれか。", qEn: "You have data copied for AI validation and a validation environment that is no longer needed. Which is a correct premise for disposal?", o: ["元データを消せば複製も自動で消えるので、所在の把握は不要である", "検証環境を削除するだけで、中のデータは対象外のため消去は不要である", "複製の所在を把握しておく。把握していないと消去できない", "学習が終われば、検証用の複製は管理対象から外れて消去の対象にならない"], oEn: ["Deleting the original also removes copies automatically, so tracking their location is unnecessary", "Simply deleting the environment suffices because the data inside is out of scope for disposal", "Know where the copies are. Without that knowledge they cannot be erased", "Once training ends, validation copies leave management scope and are no longer subject to disposal"], a: 2, e: "AIの学習や検証のために複製したデータや、使い終えた環境内のデータも消去・廃棄の対象。複製の所在を把握していないと消去できない。", eEn: "Data copied for AI training or validation, and data in used environments, are subject to disposal. Copies cannot be erased if their location is unknown."},
  {d: "IT6", q: "クラウド上で処理中（利用中）のデータを暗号化によって守りたい。利用中の暗号化に使われる選択肢はどれか。", qEn: "You want to protect data being processed in the cloud with encryption. Which option is used for encryption of data in use?", o: ["AES-256 によるサーバー側暗号化（保存時の暗号化に使う）", "コンフィデンシャルコンピューティング", "TLS 1.2 以上による通信の保護（転送時の暗号化に使う）", "IPsec で暗号化された VPN 接続（転送時の暗号化に使う）"], oEn: ["Server-side encryption with AES-256 (used for encryption at rest)", "Confidential computing", "Communication protection with TLS 1.2 or later (used for encryption in transit)", "A VPN connection encrypted with IPsec (used for encryption in transit)"], a: 1, e: "処理中のデータを守る利用中の暗号化には、コンフィデンシャルコンピューティングが使われる。AES-256 は保存時、TLS や VPN の IPsec は転送時の暗号化。", eEn: "Confidential computing protects data in use. AES-256 is for data at rest, while TLS and VPN IPsec are for data in transit."},
  {d: "IT6", q: "保存時・転送時の暗号化と、鍵管理（KMS・HSM）の関係として正しいのはどれか。", qEn: "Which statement correctly describes the relationship between encryption at rest/in transit and key management (KMS/HSM)?", o: ["前者はどの状態のデータを守るかの分類、後者は鍵を誰がどこで管理するかで、別の軸なので組み合わせて使う", "前者は鍵を誰がどこで管理するかの分類であり、後者はどの状態のデータを守るかを分ける分類であり、別の軸である", "鍵管理を導入すれば、保存時と転送時の暗号化は不要になり、どちらか一方で足りる", "保存時の暗号化は鍵管理と無関係で、顧客管理鍵の選択肢は転送時にだけ存在する"], oEn: ["The former classifies which state of data is protected, the latter who manages keys and where; they are separate axes used together", "The former classifies who manages keys and where, the latter which state of data is protected; they are separate axes", "With key management in place, encryption at rest and in transit becomes unnecessary and either one suffices", "Encryption at rest is unrelated to key management, and customer-managed keys exist only for data in transit"], a: 0, e: "保存時・転送時はどの状態のデータを守るかという分類で、鍵管理は鍵を誰がどこで管理するかを扱う。別の軸なので組み合わせて使う。", eEn: "At rest/in transit classifies which state of data is protected; key management covers who manages keys and where. They are separate axes combined in practice."},
  {d: "IT6", q: "社内データを RAG 用に置いて生成AIに渡す構成で、暗号化が必要な箇所はどこか。", qEn: "In a setup that places internal data for RAG and passes it to a generative AI, where is encryption needed?", o: ["処理中のデータだけで、通信の経路と保存先は暗号化の対象にならない", "通信の経路だけで、保存先は社内にあるため暗号化は不要", "生成AIへデータを渡す通信の経路と、RAG用データの保存先の両方", "保存先だけで、通信は閉じたネットワーク内なので暗号化は不要"], oEn: ["Only data in use; the communication path and storage are not subject to encryption", "Only the communication path; storage is in-house so encryption is unnecessary", "Both the communication path to the generative AI and the storage location of the RAG data", "Only the storage location; communication is on a closed network so encryption is unnecessary"], a: 2, e: "生成AIにデータを渡す通信の経路と、RAG 用に置くデータの保存先の両方で暗号化が必要。処理中のデータにはコンフィデンシャルコンピューティングという選択肢もある。", eEn: "Encryption is needed both on the path to the generative AI and where RAG data is stored. Confidential computing is an additional option for data in use."},
  {d: "IT6", q: "契約書を法令に従って一定期間残し、期間が過ぎたら削除したい。Microsoft Purview の保持の設定として適切なのはどれか。", qEn: "You want to keep contracts for a set period as required by law and delete them afterward. Which Microsoft Purview retention setting is appropriate?", o: ["保持のみを設定し、期間が満了したあとも削除せずに残し続ける", "削除のみを設定し、保持期間の途中でも削除を防がずに運用する", "eDiscovery のホールドだけを置き、期間満了を待たず事案ごとに解除する", "保持後に削除を設定し、保持期間の満了を待って削除へ進める"], oEn: ["Configure retain-only, keeping the contracts even after the period expires", "Configure delete-only, operating without preventing deletion even during the period", "Place only an eDiscovery hold and release it per case without waiting for the period to expire", "Configure retain-then-delete, proceeding to deletion once the retention period expires"], a: 3, e: "Purview は保持（削除を防ぎ eDiscovery に残す）と削除を組み合わせ、保持のみ、削除のみ、保持後に削除を設定できる。残して期限後に消すなら保持後に削除。", eEn: "Purview combines retain (prevent deletion, keep for eDiscovery) and delete: retain-only, delete-only, or retain-then-delete. Keeping then removing calls for retain-then-delete."},
  {d: "IT6", q: "全社の保持ポリシーとは別に、特定の契約書だけ個別の保存期間で運用したい。適した仕組みはどれか。", qEn: "Besides the company-wide retention policy, you want to manage only certain contracts with an individual retention period. Which mechanism fits?", o: ["サイト単位で適用する保持ポリシー", "メールボックス単位で適用する保持ポリシー", "文書単位で付ける保持ラベル", "文書に付ける機密ラベル"], oEn: ["A retention policy applied per site", "A retention policy applied per mailbox", "A retention label applied per document", "A sensitivity label applied to the document"], a: 2, e: "保持ラベルは文書・メール単位で保存期間を制御する。保持ポリシーはサイトやメールボックス単位。機密ラベルは機密度を示すもので、保存期間の制御用ではない。", eEn: "Retention labels control retention per document or email; retention policies work per site or mailbox. Sensitivity labels indicate sensitivity, not retention."},
  {d: "IT6", q: "イミュータブルバックアップとデータ保持の違いとして正しいのはどれか。", qEn: "Which statement correctly describes the difference between immutable backup and data retention?", o: ["イミュータブルは障害や攻撃からの復旧用の複製を守り、データ保持は法令や規程のために元のコンテンツを残して期限後に削除する", "イミュータブルは法令や規程のために元のコンテンツを残して期限後に削除し、データ保持は障害や攻撃からの復旧に使う複製を守る仕組みである", "どちらも復旧用の複製を守る仕組みで、期限後の削除は両方に共通の機能である", "どちらも元のコンテンツを期限なく残す仕組みで、削除の機能は持たない"], oEn: ["Immutable backup protects recovery copies against failure or attack, while data retention keeps original content for laws and rules and deletes it after the deadline", "Immutable backup keeps original content for laws and rules and deletes it after the deadline, while data retention protects recovery copies", "Both protect recovery copies, and deletion after the deadline is a feature common to both", "Both keep original content indefinitely and have no deletion function"], a: 0, e: "イミュータブルバックアップは障害や攻撃からの復旧用の複製を守る。データ保持は法令や規程のために元のコンテンツを残し、期限後に削除する。守る対象と目的が違う。", eEn: "Immutable backup protects recovery copies against failure and attack; data retention keeps original content for laws and rules and deletes it later. Targets and purposes differ."},
  {d: "IT6", q: "社外に共有したファイルが管理外のストレージに移っても保護を続け、閲覧・印刷・転送の権限を制御したい。適した仕組みはどれか。", qEn: "You want protection to continue even if a shared file moves to unmanaged storage, controlling view, print and forward permissions. Which mechanism fits?", o: ["DLP：ポリシーで持ち出しの操作を検知して遮断する", "IRM：暗号化と利用権限をデータ自体に付ける", "DSPM：データの所在と保護の穴を継続的に見つける", "データマスキング：問い合わせ結果の一部を隠して見せる"], oEn: ["DLP: detects and blocks exfiltration operations by policy", "IRM: attaches encryption and usage rights to the data itself", "DSPM: continuously finds data location and protection gaps", "Data masking: hides part of query results when displaying them"], a: 1, e: "IRM は暗号化と利用権限をデータ自体に付けるので、管理外のストレージに移っても保護が残る。DLP は操作の検知・遮断、DSPM は所在の把握、マスキングは表示の制御。", eEn: "IRM attaches encryption and usage rights to the data, so protection persists in unmanaged storage. DLP detects and blocks operations, DSPM finds data, and masking controls display."},
  {d: "IT6", q: "IRM で機密ファイルを保護した。運用上の注意として正しいのはどれか。", qEn: "You protected a confidential file with IRM. Which operational note is correct?", o: ["管理外のストレージに移ると保護が外れるため、共有先を社内に限定する", "暗号化されるため利用状況の監査はできず、アクセスの取り消しも不可能である", "画面撮影などによる共有は完全には防げないため、他の統制と併用する", "画面撮影も含めて共有を完全に防げるため、他の統制は不要である"], oEn: ["Protection is lost once the file moves to unmanaged storage, so limit sharing to the inside of the company", "Because it is encrypted, usage cannot be audited and access cannot be revoked", "Sharing by means such as screen capture cannot be fully prevented, so combine it with other controls", "It completely prevents sharing, including screen capture, so other controls are unnecessary"], a: 2, e: "IRM は画面撮影などの共有を完全には防げず、他の統制との併用が前提。保護は管理外ストレージでも残り、利用状況の監査や Office ファイルのアクセス取り消しもできる。", eEn: "IRM cannot fully prevent sharing such as screen capture, so it assumes other controls. Protection survives unmanaged storage, and usage auditing and access revocation for Office files are possible."},
  {d: "IT6", q: "メールに「転送不可」を適用した。制限される操作はどれか。", qEn: "A Do Not Forward setting is applied to an email. Which operations are restricted?", o: ["閲覧と編集のみで、転送や印刷は制限されない", "メール本文の保存期間と、期限後の削除のタイミング", "受信者による画面撮影を含む、あらゆる形の共有", "転送、印刷、コピー"], oEn: ["Only viewing and editing; forwarding and printing are not restricted", "The retention period of the email body and when it is deleted after the deadline", "Every form of sharing by the recipient, including screen capture", "Forwarding, printing and copying"], a: 3, e: "「転送不可」は転送、印刷、コピーを制限する。保存期間の制御は保持の役割で、画面撮影などの共有は IRM でも完全には防げない。", eEn: "Do Not Forward restricts forwarding, printing and copying. Retention control belongs to retention, and screen capture cannot be fully prevented even by IRM."},
  {d: "IT6", q: "取引先との訴訟の可能性が出た。調査対象者のメールや Teams の削除を止めて証拠を保全したい。適した措置はどれか。", qEn: "A lawsuit with a business partner is possible. You want to stop deletion of the subject's email and Teams data to preserve evidence. Which measure fits?", o: ["全社の保持ポリシーの期間を、一律に延ばす", "該当ケースの対象場所に、リーガルホールドを置く", "対象者のメールボックスに動的データマスキングを適用する", "対象データを NIST SP 800-88 に沿って消去・廃棄する"], oEn: ["Extend the period of the company-wide retention policy uniformly", "Place a legal hold on the target locations of the relevant case", "Apply dynamic data masking to the subject's mailbox", "Erase and dispose of the target data in line with NIST SP 800-88"], a: 1, e: "リーガルホールドは特定の調査や訴訟のために対象を保全する事案単位の措置。全社の保持ポリシーは一律のルールで、マスキングや消去は保全に反する。", eEn: "A legal hold is a case-specific measure to preserve targets for an investigation or lawsuit. Company-wide retention is a uniform rule, and masking or erasure would defeat preservation."},
  {d: "IT6", q: "Copilot などAIとのやり取りが、将来の証拠開示の対象になりうる。対応として正しいのはどれか。", qEn: "Exchanges with AI such as Copilot may become subject to future discovery. Which response is correct?", o: ["eDiscovery が AI アプリのデータの検索と削除にも対応するので、保存と保全の方針を決めておく", "AI とのやり取りは eDiscovery の対象外なので、メールと Teams の保全だけを行い、AI 側は扱わない", "AI アプリのデータは検索できず、書き出しの時点で初めて保全の対象になる", "保持ポリシーの対象に AI のやり取りは含められないため、方針は不要である"], oEn: ["eDiscovery also supports searching and deleting AI app data, so decide in advance the policy for retention and preservation", "AI exchanges are outside eDiscovery, so only email is preserved", "AI app data cannot be searched and becomes subject to preservation only at export", "AI exchanges cannot be included in retention policies, so no policy is needed"], a: 0, e: "eDiscovery は Copilot やAIアプリのデータの検索と削除に対応する。AIとのやり取りが証拠開示の対象になる場合に備え、保存と保全の方針を決めておく。", eEn: "eDiscovery supports searching and deleting Copilot and AI app data. Decide retention and preservation policy in case such exchanges become discoverable."},
  {d: "IT6", q: "Purview eDiscovery でケースを作り、ホールドを置いた後の手順として正しいのはどれか。", qEn: "After creating a case and placing a hold in Purview eDiscovery, which sequence is correct?", o: ["検索せずに全データを書き出し、その後で対象場所にホールドを置く", "レビューセットで分析した結果を、ケースの外で対象データごと削除する", "検索結果をレビューセットに集め、タグ付けや分析をしてから書き出す", "ホールドを置くと検索ができなくなるため、書き出しは解除後に行う"], oEn: ["Export all data without searching, then place the hold on the target locations", "Delete the analyzed data together with the targets outside the case after review", "Collect search results into a review set, tag and analyze them, then export", "Searching becomes impossible once a hold is placed, so export after releasing it"], a: 2, e: "eDiscovery はケース単位で検索、保留、書き出しを管理する。対象場所のホールドで削除を防ぎ、結果をレビューセットに集めてタグ付けや分析をしてから書き出す。", eEn: "eDiscovery manages search, hold and export per case. Holds prevent deletion; results are gathered into a review set, tagged and analyzed, then exported."},
  {d: "IT6", q: "DLP、DSPM、IRM の役割の違いとして正しいのはどれか。", qEn: "Which statement correctly describes the roles of DLP, DSPM and IRM?", o: ["DLP は保護をデータ自体に付け、DSPM は持ち出しの操作を検知・遮断し、IRM はデータの所在と保護の穴を見つける", "DLP はデータの所在と保護の穴を見つけ、DSPM は保護をデータ自体に付け、IRM は持ち出しの操作を検知・遮断する", "三つとも持ち出しの操作を検知・遮断する仕組みで、対象とする端末が違うだけである", "DLP は持ち出しの操作を検知・遮断し、DSPM はデータの所在と保護の穴を見つけ、IRM は保護をデータ自体に付ける"], oEn: ["DLP attaches protection to the data itself, DSPM detects and blocks exfiltration operations, and IRM finds data location and protection gaps", "DLP finds data location and protection gaps, DSPM attaches protection to the data itself, and IRM detects and blocks exfiltration operations", "All three detect and block exfiltration operations, differing only in the endpoints they target", "DLP detects and blocks exfiltration operations, DSPM finds data location and protection gaps, and IRM attaches protection to the data itself"], a: 3, e: "DLP はポリシーで持ち出しを検知・遮断、DSPM はデータそのものを起点に所在と保護の穴を見つけ、IRM は保護をデータ自体に付ける。三つは役割が異なり、組み合わせて使う。", eEn: "DLP detects and blocks exfiltration by policy, DSPM finds data location and gaps from the data itself, and IRM attaches protection to the data. Their roles differ and are combined."},
  {d: "IT6", q: "Microsoft 365 Copilot の利用で機密情報が扱われる場面を制御したい。Purview の DLP の設定として正しいのはどれか。", qEn: "You want to control situations where sensitive information is handled when using Microsoft 365 Copilot. Which Purview DLP setting is correct?", o: ["Copilot は監視場所に含められないため、ブラウザ経由の利用だけを対象にする", "Copilot を監視場所に含め、ポリシーの条件に合う内容を制御の対象にする", "Copilot の応答を暗号化する鍵を、利用者ごとに作成して管理する", "Copilot の利用履歴を、期間満了時に処分レビューを挟んで削除する"], oEn: ["Copilot cannot be a monitored location, so cover only use through the browser", "Include Copilot as a monitored location and subject content matching the policy conditions to control", "Create and manage, per user, the key that encrypts Copilot responses", "Delete Copilot usage history after a disposition review at the end of the period"], a: 1, e: "Purview の DLP は Microsoft 365 Copilot を監視場所に含められる。鍵の管理や処分レビュー付きの削除は、DLP ではなく鍵管理や保持の役割。", eEn: "Purview DLP can include Microsoft 365 Copilot as a monitored location. Key management and deletion with disposition review belong to key management and retention, not DLP."},
  {d: "IT6", q: "鍵の作成・保管・利用権限を一元管理したい。さらに、鍵そのものを専用ハードウェア内で保護したい。それぞれを担う組み合わせとして正しいのはどれか。", qEn: "You want to centrally manage the creation, storage and usage permissions of keys, and also protect the keys themselves inside dedicated hardware. Which pairing of roles is correct?", o: ["前者は HSM（専用ハードウェアの装置）、後者は KMS（鍵管理）", "前者は DSPM（態勢管理）、後者は KMS（鍵管理）", "前者は DLP（損失防止）、後者は HSM（専用ハードウェアの装置）", "前者は KMS（鍵管理）、後者は HSM（専用ハードウェアの装置）"], oEn: ["The former is HSM (a dedicated hardware device), the latter is KMS (key management)", "The former is DSPM (posture management), the latter is KMS (key management)", "The former is DLP (loss prevention), the latter is HSM (a dedicated hardware device)", "The former is KMS (key management), the latter is HSM (a dedicated hardware device)"], a: 3, e: "鍵の作成・保管・利用権限を一元管理するのが KMS で、鍵を専用ハードウェア内で保護する装置が HSM。クラウドではどちらもサービスとして提供される。", eEn: "KMS centrally manages creation, storage and usage rights of keys, while an HSM is a dedicated device protecting keys. Both are offered as services in the cloud."},
  {d: "IT6", q: "機密ラベルを組織で運用する。区分の作り方とラベルの付与方法として正しいのはどれか。", qEn: "You operate sensitivity labels in your organization. Which statement about creating tiers and applying labels is correct?", o: ["管理者が組織に合う区分を作り、利用者の操作か自動判定でラベルを付ける", "区分は製品が固定で定めており、組織が独自の区分を作ることはできない", "利用者はラベルを付けられず、管理者が一件ずつ手作業で付与する", "自動判定は DLP が担い、ラベルは DLP ポリシーの中にだけ保存される"], oEn: ["Administrators create tiers suited to the organization, and labels are applied by user action or automatic detection", "Tiers are fixed by the product and the organization cannot create its own", "Users cannot apply labels; administrators assign them by hand one by one", "Automatic detection is done by DLP, and labels are stored only inside DLP policies"], a: 0, e: "管理者が組織に合う区分（Public、Confidential など）を作り、利用者の操作か自動判定でラベルを付ける。ラベルはファイルのメタデータに保存され、DLP ポリシー内だけにあるわけではない。", eEn: "Admins create organization-specific tiers and labels are applied by users or automatic detection. Labels live in file metadata, not only in DLP policies."},
  {d: "IT6", q: "イミュータブルのバックアップ保管庫をロックした。運用上の判断として正しいのはどれか。", qEn: "You locked an immutable backup vault. Which operational judgment is correct?", o: ["削除を防げるので、復旧手順を試す訓練は省略できる", "ロック後も権限があれば、期限前に復旧ポイントを削除できる", "ロック後も保持期間を短縮できるため、容量が不足したら短縮する", "復旧訓練は別途必要なので、定期的に復旧手順を試す"], oEn: ["Deletion is prevented, so drills testing the recovery procedure can be skipped", "After locking, anyone with permission can still delete recovery points before expiry", "Retention can still be shortened after locking, so shorten it if capacity runs short", "Recovery drills are needed separately, so periodically test the recovery procedure"], a: 3, e: "イミュータブル設定は期限前の削除や保持期間の短縮を禁止し、ロック後は無効化できないが、復旧訓練は別途必要。削除を防げても復旧手順の確認は省けない。", eEn: "Immutability bars early deletion and shortening of retention and cannot be disabled once locked, but recovery drills are still needed separately."},
  {d: "IT7", q: "端末・クラウド・アプリケーションなど各所のログを集約し、相関ルールで関連イベントを結び付け、重大度に応じた優先度付きアラートを出したい。中核に据える仕組みは？", qEn: "You want to aggregate logs from endpoints, cloud and applications, link related events with correlation rules, and raise alerts prioritized by severity. Which mechanism should be the core?", o: ["SOAR（検知後の対応手順を自動化する仕組み）", "脅威インテリジェンス（脅威情報を意思決定に生かす流れ）", "SIEM（ログとイベントを集約・分析して脅威を検知する基盤）", "ペネトレーションテスト（攻撃者の視点で攻撃の成否と被害の程度を確かめる検査）"], oEn: ["SOAR (a mechanism that automates response steps after detection)", "Threat intelligence (a flow that turns threat information into decisions)", "SIEM (a platform that aggregates and analyzes logs and events to detect threats)", "Penetration test (an exam that checks from the attacker's view whether an attack succeeds and how much damage results)"], a: 2, e: "SIEM は各所のログを正規化・集約し、相関ルールや機械学習で異常を見つけてアラートを出す基盤。SOAR は検知後の対応の自動化で、収集や検知そのものは担わない。", eEn: "SIEM normalizes and aggregates logs from many sources and uses correlation rules or machine learning to find anomalies and raise alerts. SOAR automates response after detection and does not itself collect or detect."},
  {d: "IT7", q: "SIEM と SOC の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between SIEM and SOC?", o: ["SIEM はデータの収集・分析・検知を担う技術基盤で、SOC はそれを道具として使う人とチーム", "SIEM は脅威を監視する専門担当者のチームで、SOC はログを集約する技術基盤", "SIEM は検知後の対応を手順どおりに自動化する仕組みで、SOC はログの収集と検知を担う技術基盤である", "SIEM と SOC は同じものの別名で、どちらも対応手順を自動実行する仕組み"], oEn: ["SIEM is the technical platform for collecting, analyzing and detecting data; the SOC is the people and team that use it as a tool", "SIEM is a team of specialists who monitor threats, and the SOC is the platform that aggregates logs", "SIEM is a mechanism that automates response after detection according to procedures, and the SOC is the platform that handles log collection and detection", "SIEM and SOC are two names for the same thing, both mechanisms that run response steps automatically"], a: 0, e: "SIEM は収集・分析・検知を担う技術基盤で、SOC は SIEM を道具に監視・調査・対応を行う人とチーム。対応の自動化は SOAR の役割で、SIEM や SOC の別名ではない。", eEn: "SIEM is the platform for collection, analysis and detection; the SOC is the team that uses it to monitor, investigate and respond. Automating response is SOAR's role, not an alias of SIEM or SOC."},
  {d: "IT7", q: "生成AIの利用ログを、他システムのログと同じ基盤で相関分析して不審な利用を調べたい。適切な進め方は？", qEn: "You want to correlate generative AI usage logs with other systems' logs on the same platform to investigate suspicious use. What is the appropriate approach?", o: ["生成AIの利用ログは別の専用ツールだけで管理し、SIEM のログとは突き合わせずに調べる", "SOAR のプレイブックに生成AIの利用ログを登録し、相関分析の代わりとする", "脅威インテリジェンスの IoC 一覧に生成AIの利用ログを加え、検知の根拠とする", "生成AIの利用ログも SIEM に取り込み、他システムのログと合わせて相関分析する"], oEn: ["Manage the logs only in a separate dedicated tool and investigate without comparing them with the SIEM's logs", "Register the logs in a SOAR playbook and use that in place of correlation analysis", "Add the logs to a threat intelligence IoC list and use it as the basis for detection", "Ingest the generative AI usage logs into the SIEM and correlate them together with other systems' logs"], a: 3, e: "SIEM は生成AIの利用ログも取り込めば、他システムのログと同じ基盤で相関分析できる。SOAR は検知後の対応を自動化する仕組みで、相関分析の代わりにはならない。", eEn: "If generative AI usage logs are ingested, the SIEM can correlate them with other systems' logs on the same platform. SOAR automates post-detection response and cannot replace correlation analysis."},
  {d: "IT7", q: "端末でマルウェアを検知したとき、隔離、証拠収集、他システムでの同種指標の検索、チケット作成までを自動で行い、担当者の確認につなぎたい。当てる仕組みは？", qEn: "When malware is detected on an endpoint, you want isolation, evidence collection, a search for the same indicators in other systems and ticket creation to run automatically, then hand over to a person. Which mechanism fits?", o: ["SIEM の相関ルール（関連イベントを結び付ける条件）", "ログ管理システム（ログの取得・保管・検索の土台）", "SOAR のプレイブック（定義済みの対応手順）", "SOC の監視体制（専門担当者による分析と判断）"], oEn: ["A SIEM correlation rule (conditions that link related events)", "A log management system (the base for acquiring, storing and searching logs)", "A SOAR playbook (predefined response steps)", "A SOC monitoring setup (analysis and judgment by specialist staff)"], a: 2, e: "SOAR は検知後の定型対応をプレイブックで自動実行し、担当者の確認につなぐ。相関ルールは検知側、ログ管理は保管側、SOC は人による分析で、いずれも自動実行の仕組みではない。", eEn: "SOAR runs routine post-detection steps automatically through playbooks and hands over to a person. Correlation rules are on the detection side, log management on the storage side, and the SOC is human analysis; none is an automatic execution mechanism."},
  {d: "IT7", q: "SIEM と SOAR を併用するときの関係として正しいのは？", qEn: "Which statement correctly describes the relationship when SIEM and SOAR are used together?", o: ["SOAR が脅威を検知し、SIEM がその後の対応を自動化する", "SIEM と SOAR は同じ機能を持つため、どちらか一方だけを導入すればよい", "SIEM が検知した脅威に対して、SOAR が対応を調整・自動化する", "SOAR がログを正規化・集約し、SIEM が隔離などの対応手順を実行する"], oEn: ["SOAR detects threats and the SIEM automates the response afterward", "SIEM and SOAR have the same function, so only one of them needs to be introduced", "SOAR coordinates and automates the response to threats that the SIEM detects", "SOAR normalizes and aggregates logs, and the SIEM executes response steps such as isolation"], a: 2, e: "SIEM が収集・分析・検知を、SOAR が検知後の対応の調整・自動化を担い、SIEM の検知に対応する形で併用される。役割を逆にした組合せや、同一機能とする見方は誤り。", eEn: "SIEM handles collection, analysis and detection, while SOAR coordinates and automates the response after detection, so they are used together. Swapping the roles or treating them as the same function is wrong."},
  {d: "IT7", q: "SOAR のプレイブックの説明として正しいのは？", qEn: "Which is a correct description of a SOAR playbook?", o: ["ログを共通形式に正規化し、関連イベントを結び付けて異常を見つける", "条件に応じて、あらかじめ定義した対応手順を自動または手動で実行する", "攻撃者と同じ視点で想定シナリオの攻撃を試み、成否と被害の程度まで確かめる", "脅威情報を方針策定から評価までのサイクルで回す"], oEn: ["It normalizes logs into a common format and links related events to find anomalies", "It executes predefined response steps, automatically or manually, depending on conditions", "It tries attacks from an assumed scenario from the same viewpoint as an attacker and checks success and even the extent of damage", "It runs threat information through a cycle from policy setting to evaluation"], a: 1, e: "プレイブックは SOAR が条件に応じて実行する、あらかじめ定義した対応手順。正規化と相関は SIEM、攻撃の成否確認はペネトレーションテスト、サイクル運用は脅威インテリジェンスの説明。", eEn: "A playbook is the predefined set of response steps SOAR runs depending on conditions. Normalization and correlation describe SIEM, checking attack success describes a penetration test, and the cycle describes threat intelligence."},
  {d: "IT7", q: "専門担当者が情報システムを監視し、脅威の検知・調査・対応を行うチームや組織を指す用語は？", qEn: "Which term refers to a team or organization in which specialist staff monitor information systems and detect, investigate and respond to threats?", o: ["SOC（セキュリティオペレーションセンター）", "SIEM（セキュリティ情報イベント管理）", "SOAR（セキュリティのオーケストレーション・自動化・対応）", "脅威インテリジェンス（サイバー脅威インテリジェンス）"], oEn: ["SOC (Security Operation Center)", "SIEM (Security Information and Event Management)", "SOAR (Security Orchestration, Automation and Response)", "Threat intelligence (Cyber Threat Intelligence)"], a: 0, e: "SOC は専門担当者が監視・検知・調査・対応を行うチーム。SIEM は SOC が使う技術基盤、SOAR は対応の自動化の仕組み、脅威インテリジェンスは特定のツールではなく意思決定の流れ。", eEn: "A SOC is the team of specialists who monitor, detect, investigate and respond. SIEM is the platform a SOC uses, SOAR automates response, and threat intelligence is a decision flow, not a specific tool."},
  {d: "IT7", q: "生成AIアプリの導入にあたり、SOC の運用で押さえるべき点として適切なのは？", qEn: "When introducing a generative AI app, what is appropriate for SOC operations to address?", o: ["利用ログや制御状況を監視対象に加え、アラートの扱いを手順化し、自社運用か外部委託かも判断する", "生成AIは社内境界の外にあるため、SOC の監視対象から外す", "生成AIのアラートは既存の手順に載せず、利用部門の判断に任せる", "SOC は技術基盤なので、運用は SIEM の設定だけで完結させ、担当者の配置や対応手順の整備は行わない"], oEn: ["Add usage logs and control status to the monitoring targets, define how alerts are handled, and decide whether to run it in-house or outsource", "Generative AI sits outside the internal perimeter, so exclude it from SOC monitoring", "Do not put generative AI alerts into existing procedures; leave them to the user department", "The SOC is a technical platform, so complete operations with SIEM settings alone, without assigning staff or defining response procedures"], a: 0, e: "生成AIアプリの利用ログや制御状況を監視対象に加え、アラートの扱いを運用手順に組み込む。自社で運用するか外部委託かも判断点。監視から外す、手順に載せない、は誤り。", eEn: "Add the app's usage logs and control status to monitoring and build alert handling into operating procedures; in-house versus outsourced operation is also a decision point. Excluding it or leaving it outside procedures is wrong."},
  {d: "IT7", q: "デジタル庁の方針で、不審なアクセスを認めた際の SOC の対処として挙げられているのは？", qEn: "According to the Digital Agency's policy, how should SOCs handle suspicious access once it is recognized?", o: ["組織内の SOC だけで完結させ、外部の SOC にはログも状況も共有せず、結果のみ事後に通知する", "外部の SOC に対処を全面委託し、組織内の SOC は監視から外れる", "組織内外の SOC と共同で対処し、ログ連携やダッシュボードの共有で双方が監視する", "不審なアクセスの記録は SIEM に任せ、SOC は事後の報告のみ受ける"], oEn: ["Finish it within the internal SOC only, sharing neither logs nor status with external SOCs and notifying them of the result only afterward", "Entrust the response entirely to an external SOC and take the internal SOC out of monitoring", "Handle it jointly with SOCs inside and outside the organization, with both sides monitoring through log sharing and shared dashboards", "Leave the records to the SIEM and have the SOC only receive after-the-fact reports"], a: 2, e: "デジタル庁の方針は、組織内外の SOC が共同で対処し、ログ連携やダッシュボード共有で双方が監視する手法を挙げる。内部のみ、全面委託、報告のみの形はこの方針と異なる。", eEn: "The Digital Agency's policy cites joint handling by internal and external SOCs, with both monitoring via log sharing and dashboards. Internal-only, full outsourcing, or report-only approaches differ from it."},
  {d: "IT7", q: "監査ログの運用として正しいのは？", qEn: "Which is correct operation of audit logs?", o: ["各機器の内部時計を使い、ログは取得した機器の中に保管する", "ログは個人情報を含まない前提で、通常の運用資料と同じ扱いにして関係部署へ広く共有する", "NTP で時刻を同期し、機器とは別のログ管理システムに保管して改ざんを防ぐ", "保存期間は機器の標準設定に任せ、想定する攻撃とは切り離して決める"], oEn: ["Use each device's internal clock and keep logs inside the device that acquired them", "Assume logs contain no personal information, treat them like ordinary operating documents and share them widely with related departments", "Synchronize time via NTP and store logs in a log management system separate from the devices to prevent tampering", "Leave the retention period to the device default, decided apart from the attacks anticipated"], a: 2, e: "時刻は NTP で同期し、機器とは別のログ管理システムに保管すれば改ざんを防げる。ログには個人情報が含まれうるため機密情報として扱い、保存期間は扱うデータや想定する攻撃から決める。", eEn: "Synchronizing time with NTP and storing logs apart from the devices prevents tampering. Logs may hold personal information, so treat them as confidential, and set retention from the data handled and the attacks anticipated."},
  {d: "IT7", q: "ログ管理と SIEM の関係として正しいのは？", qEn: "Which statement correctly describes the relationship between log management and SIEM?", o: ["ログ管理は相関分析と検知を担い、SIEM はログの保管だけを担う", "ログ管理は取得・保管・検索の土台で、SIEM はそれを中核に含み相関分析と検知まで担う", "SIEM はログ管理を含まず、ログの取得と保管は SOC が別の基盤で行い、SIEM は検知のみを担う", "ログ管理は検知後の対応の自動化まで担い、SIEM は収集だけを行う"], oEn: ["Log management handles correlation and detection, and SIEM handles only log storage", "Log management is the base for acquiring, storing and searching logs; SIEM includes it at its core and also handles correlation analysis and detection", "SIEM does not include log management; the SOC acquires and stores logs on a separate platform, and SIEM handles detection only", "Log management even automates post-detection response, and SIEM only collects"], a: 1, e: "ログ管理は取得・保管・検索の土台。SIEM はログ管理を中核に含みつつ、その上で相関分析と検知、対応まで担う。役割を逆にした説明は誤り。", eEn: "Log management is the base for acquisition, storage and search. SIEM includes it at its core and adds correlation, detection and response on top. Explanations that reverse the roles are wrong."},
  {d: "IT7", q: "生成AIの利用で、誰がいつどのデータを扱ったかを調査や監査で追えるようにしたい。事前に決めておくべきことは？", qEn: "You want to be able to trace who handled which data and when in generative AI use, for investigations and audits. What should be decided beforehand?", o: ["攻撃シナリオの一覧と、ペネトレーションテストの実施頻度および報告書の様式", "取得するログの対象と保存期間、およびログ内の機密情報の扱い", "経営層に報告する基準と、伝達ルールの連絡先", "プレイブックの実行条件と、自動隔離の対象端末"], oEn: ["The list of attack scenarios, the frequency of penetration tests and the report format", "The log targets to acquire, the retention period, and how confidential information inside the logs is handled", "The criteria for reporting to executives and the contacts in the communication rules", "The execution conditions of playbooks and the endpoints targeted for automatic isolation"], a: 1, e: "誰がいつどのデータを扱ったかを追うには、取得対象と保存期間、ログ内の機密情報の扱いを事前に決める。攻撃シナリオ、経営層への報告基準、自動隔離は別の仕組みの論点。", eEn: "To trace who handled what and when, decide the acquisition targets, retention period and handling of confidential data in logs beforehand. Attack scenarios, executive reporting criteria and auto-isolation belong to other mechanisms."},
  {d: "IT7", q: "脅威インテリジェンスの説明として正しいのは？", qEn: "Which is a correct description of threat intelligence?", o: ["脅威情報を自動で収集して SOC に配信する、特定の製品やサービスの名称", "悪性 IP やハッシュ値などの IoC を一覧にした戦術的な情報だけを指す言葉", "脅威情報を収集・加工・分析して得た知見に基づき、組織が意思決定を行う一連の流れ", "侵入後の端末を隔離して証拠を集める、検知後の対応を自動化する仕組み"], oEn: ["The name of a specific product or service that collects threat information automatically and delivers it to the SOC", "A term for tactical information only, a list of IoCs such as malicious IPs and hash values", "A flow in which an organization makes decisions based on insight gained by collecting, processing and analyzing threat information", "A mechanism that isolates compromised endpoints and collects evidence, automating post-detection response"], a: 2, e: "脅威インテリジェンスは情報を収集・加工・分析し意思決定に生かす流れで、特定のツールやサービスを指さない。IoC は戦術的インテリジェンスの一部にすぎず、隔離の自動化は SOAR。", eEn: "Threat intelligence is the flow of collecting, processing and analyzing information to support decisions, not a specific tool or service. IoCs are only one part of tactical intelligence, and automated isolation is SOAR."},
  {d: "IT7", q: "IPA の整理で、悪性 IP やハッシュ値などの IoC を SOC 向けに使う脅威インテリジェンスは、どの区分に当たるか？", qEn: "In IPA's classification, which category does threat intelligence such as IoCs (malicious IPs, hash values) used for the SOC fall under?", o: ["戦略的インテリジェンス", "戦術的インテリジェンス", "運用インテリジェンス", "どの区分にも当たらず、脅威インテリジェンスとは別の概念"], oEn: ["Strategic intelligence", "Tactical intelligence", "Operational intelligence", "It falls under no category and is a concept separate from threat intelligence"], a: 1, e: "IPA は利用者別に、経営層向けの戦略的、攻撃手法の理解や侵入テストに使う運用、SOC 向けの IoC などの戦術的に分ける。IoC は戦術的の一種で、脅威インテリジェンスの一部。", eEn: "IPA divides by user: strategic for executives, operational for understanding attack methods and penetration testing, and tactical such as IoCs for the SOC. IoCs are a kind of tactical intelligence within threat intelligence."},
  {d: "IT7", q: "生成AIを狙う攻撃や悪用の動向を脅威情報に含める目的として適切なのは？", qEn: "What is an appropriate purpose for including attack and misuse trends targeting generative AI in threat information?", o: ["自組織への影響を見極め、対応の優先順位を判断する材料にするため", "生成AIの利用を一律に禁止する根拠として、例外なく全部署に周知するため", "脆弱性診断の代わりに、生成AIの弱点を網羅的に洗い出すため", "SIEM の代わりに、生成AIのログを集約して保管するため"], oEn: ["To assess the impact on the organization and use it as material for judging response priorities", "To announce to every department, without exception, as grounds for banning generative AI use across the board", "To exhaustively find generative AI weaknesses in place of a vulnerability assessment", "To aggregate and store generative AI logs in place of a SIEM"], a: 0, e: "生成AIを狙う攻撃や悪用の動向は、自組織への影響と対応の優先順位を判断する材料になる。弱点の網羅的な洗い出しは脆弱性診断、ログの集約は SIEM の役割。", eEn: "Trends in attacks and misuse aimed at generative AI serve as material to judge impact on the organization and response priorities. Exhaustive weakness discovery is vulnerability assessment and log aggregation is SIEM."},
  {d: "IT7", q: "脆弱性診断では想定しにくい弱点を、攻撃者の目線で実際に攻撃が成功するかまで確かめたい。実施すべき検査は？", qEn: "You want to check, from an attacker's viewpoint, whether weaknesses that are hard to anticipate in a vulnerability assessment can actually be exploited. Which exam should be run?", o: ["脆弱性診断の再実施（対象を網羅的に検査し、基準に照らして直ちに攻撃に結び付かない弱点まで洗い出す）", "SIEM の相関ルール追加（ログの関連イベントから異常を見つける）", "SOAR のプレイブック整備（検知後の対応手順を自動化する）", "ペネトレーションテスト（攻撃シナリオで目的を達成できるか、被害の程度も確かめる）"], oEn: ["Re-running the vulnerability assessment (inspects the whole target and lists even weaknesses not directly tied to attacks, against standards)", "Adding SIEM correlation rules (finds anomalies from related events in logs)", "Preparing SOAR playbooks (automates response steps after detection)", "Penetration test (checks whether the objective can be achieved in an attack scenario, including the extent of damage)"], a: 3, e: "デジタル庁は、診断で想定しにくい脆弱性を攻撃者の目線のテストで確かめる必要があるとする。ペネトレーションテストは攻撃の成否と被害の程度を確認する。診断は網羅性が軸。", eEn: "The Digital Agency says vulnerabilities hard to foresee in an assessment must be checked by attacker-viewpoint testing. A penetration test confirms whether attacks succeed and the damage; assessments focus on coverage."},
  {d: "IT7", q: "脆弱性診断の説明として正しいのは？", qEn: "Which is a correct description of a vulnerability assessment?", o: ["サーバ、ネットワーク機器、Web アプリ、スマートフォンアプリなどを対象に、基準に照らして直ちに攻撃に結び付かない点も洗い出す", "想定する攻撃シナリオを設定し、実際に目的を達成できるかを確かめて被害の程度まで確認し、直ちに攻撃に結び付かない点は対象外として扱う", "攻撃に直結する脆弱性だけに絞り、リスクベースで少数の項目を検査する", "対象はネットワーク機器に限られ、Web アプリやスマートフォンアプリは含まれない"], oEn: ["It targets servers, network devices, web apps and smartphone apps, and lists even points that do not directly lead to an attack, judged against a standard", "It sets assumed attack scenarios and confirms whether the objective can be achieved, down to the extent of damage, excluding points that do not directly lead to an attack", "It narrows to vulnerabilities directly tied to attacks and inspects a few items on a risk basis", "Its targets are limited to network devices and exclude web apps and smartphone apps"], a: 0, e: "脆弱性診断はサーバ、ネットワーク機器、Web アプリ、スマホアプリなどを網羅的に検査し、直ちに攻撃に結び付かない点も洗い出す。攻撃の成否と被害の確認はペネトレーションテスト。", eEn: "A vulnerability assessment inspects servers, network devices, web and smartphone apps comprehensively, including points not directly tied to attacks. Confirming attack success and damage is the penetration test."},
  {d: "IT7", q: "生成AIを組み込んだシステムに、攻撃者視点の検査を継続的に行うべきだとして、Microsoft のクラウドセキュリティベンチマーク v2（プレビュー）が挙げる管理策は？", qEn: "Which control does Microsoft's cloud security benchmark v2 (preview) list as calling for continuous attacker-viewpoint testing of systems embedding generative AI?", o: ["AI の継続的なレッドチーミング（AI-7）", "年に一度の脆弱性診断だけで足りるとする、診断の定期実施", "SIEM への生成AIログの取り込みを義務付ける管理策", "承認済みモデルの利用を求める管理策（AI-1）"], oEn: ["Continuous red teaming of AI (AI-7)", "Periodic assessments, holding that a once-a-year vulnerability assessment is enough", "A control that makes ingesting generative AI logs into the SIEM mandatory", "A control requiring the use of approved models (AI-1)"], a: 0, e: "同ベンチマークは、定期的なレッドチーム演習に加え、AI の継続的なレッドチーミング（AI-7）を管理策に挙げる。AI-1 は承認済みモデルの利用で、攻撃者視点の検査ではない。", eEn: "The benchmark lists continuous AI red teaming (AI-7) in addition to periodic red team exercises. AI-1 concerns use of approved models and is not attacker-viewpoint testing."},
  {d: "IT7", q: "CSIRT が事前に手順化するインシデントレスポンスの流れとして正しい順序は？", qEn: "What is the correct order of the incident response flow that a CSIRT defines in advance?", o: ["検知、分析、初動処理、復旧、再発防止", "初動処理、検知、分析、再発防止、復旧", "検知、初動処理、復旧、分析、再発防止", "検知、初動処理、分析、復旧、再発防止"], oEn: ["Detection, analysis, initial handling, recovery, recurrence prevention", "Initial handling, detection, analysis, recurrence prevention, recovery", "Detection, initial handling, recovery, analysis, recurrence prevention", "Detection, initial handling, analysis, recovery, recurrence prevention"], a: 3, e: "流れは検知、初動処理（関係部署への連絡、被害拡大の防止、対策機関への情報提供）、分析、復旧、再発防止の順で、これを事前に手順化しておく。", eEn: "The flow is detection, initial handling (notifying departments, preventing spread of damage, informing security bodies), analysis, recovery and recurrence prevention, defined in advance as procedures."},
  {d: "IT7", q: "生成AIによる情報漏えいや誤出力の事案に備える進め方として適切なのは？", qEn: "What is an appropriate way to prepare for incidents of information leakage or erroneous output caused by generative AI?", o: ["生成AIの事案は既存の手順の対象外とし、発生後に対応手順を新たに作る", "生成AIの事案も既存の手順に載せ、判断者と連絡先、経営層へ上げる基準を決める", "経営層への報告は被害範囲が確定してから行う方針とし、伝達ルールは設けず、初動の連絡も控える", "判断者は決めず、初動は最初に気付いた利用部門が単独で判断する"], oEn: ["Treat generative AI incidents as outside existing procedures and create response steps after they occur", "Put generative AI incidents into existing procedures and decide the decision makers, contacts and criteria for escalating to executives", "Report to executives only after the damage scope is settled, with no communication rules, and hold back even the initial notice", "Leave the decision maker undefined and let the user department that first notices decide the initial response alone"], a: 1, e: "生成AIの事案も既存の対応手順に載せ、判断者と連絡先、経営層へ上げる基準を事前に決める。経営層への伝達の遅れが初動を誤らせた例があるため、伝達ルールが要る。", eEn: "Put generative AI incidents into existing response procedures and decide decision makers, contacts and escalation criteria beforehand. Delays in informing executives have misled initial response, so communication rules are needed."},
  {d: "IT7", q: "盗まれた正規の認証情報で、アカウントが普段と違う場所・端末・頻度で使われている兆候を、固定ルールではなく通常の行動からの逸脱で見つけ、調査の優先順位も付けたい。当てる仕組みは？", qEn: "Stolen valid credentials are being used from unusual locations, devices and frequencies. You want to find this as a deviation from normal behavior rather than with fixed rules, and also prioritize investigations. Which mechanism fits?", o: ["SOAR（あらかじめ定義したプレイブックで、検知後の対応を自動化・調整する）", "脆弱性診断（基準に照らして弱点を網羅的に洗い出す）", "UEBA（通常の行動の基準を学び、逸脱にリスクスコアを付ける）", "ASM（インターネットから見える資産を継続的に棚卸しする）"], oEn: ["SOAR (automates post-detection response with predefined playbooks)", "Vulnerability assessment (comprehensively lists weaknesses against a standard)", "UEBA (learns a baseline of normal behavior and assigns risk scores to deviations)", "ASM (continuously inventories assets visible from the internet)"], a: 2, e: "UEBA は通常の行動の基準を学び、場所・デバイス・頻度の逸脱にリスクスコアを付けて調査の優先順位付けに使う。SOAR は対応の自動化、診断と ASM は弱点・資産の把握が役割。", eEn: "UEBA learns a baseline and scores deviations in location, device and frequency to prioritize investigations. SOAR automates response; assessment and ASM identify weaknesses and assets."},
  {d: "IT7", q: "UEBA が「異常」かどうかを判断するとき、現在の活動を比べる対象として正しいのは？", qEn: "When UEBA decides whether activity is anomalous, what does it compare the current activity against?", o: ["本人の過去の行動、所属などから動的に決まるピアグループ、組織全体", "本人の直近1回の操作だけを見て、過去の履歴や他の利用者とは比べない", "管理者があらかじめ書いた、禁止操作の一覧に載るかどうか", "ATT&CK の行列に載る、攻撃技術の既知のパターン"], oEn: ["The user's own history, a dynamically determined peer group (for example by group membership), and the whole organization", "Only the user's most recent single operation, with no reference to past history", "Whether it appears in a list of prohibited operations written in advance by an administrator", "Known patterns of attack techniques listed in the ATT&CK matrix"], a: 0, e: "UEBA は機械学習で行動プロファイルを作り、本人の過去、ピアグループ、組織全体と比べる。直近1回だけの比較や禁止リストへの照合は、基準からの逸脱を見る方法ではない。", eEn: "UEBA builds behavior profiles with machine learning and compares against the user's past, the peer group and the organization. A single-operation check or a prohibition list is not baseline deviation."},
  {d: "IT7", q: "UEBA と SIEM の関係として正しいのは？", qEn: "Which statement about the relationship between UEBA and SIEM is correct?", o: ["UEBA は SIEM の代わりに、ログの収集から保管までを担う基盤である", "UEBA は SIEM が検知した脅威への対応手順を、自動で実行する仕組みである", "UEBA は SIEM を使う人とチームを指し、SOC と同じ意味で使われる", "UEBA は SIEM の上で動く分析機能で、SIEM そのものではない"], oEn: ["UEBA replaces the SIEM as the platform that handles log collection through storage", "UEBA is a mechanism that automatically executes response steps for threats the SIEM detected", "UEBA refers to the people and team who use a SIEM, and means the same as a SOC", "UEBA is an analytics function that runs on top of a SIEM and is not the SIEM itself"], a: 3, e: "UEBA は SIEM の上で動く分析機能で、Microsoft Sentinel のように内蔵する例がある。ログ基盤は SIEM、対応の自動化は SOAR、SIEM を使う人とチームは SOC の役割。", eEn: "UEBA is an analytics function on top of a SIEM, built into Microsoft Sentinel for example. The log platform is SIEM, response automation is SOAR, and the people using SIEM are the SOC."},
  {d: "IT7", q: "生成AIの利用アカウントや連携アプリの、普段と違う動きを検知する考え方に UEBA を応用できる根拠として正しいのは？", qEn: "What is the correct reason UEBA's approach can be applied to detecting unusual behavior of generative AI accounts and connected apps?", o: ["生成AIの出力した文を読み取り、機密情報や個人情報を含むかどうかを内容と文脈の両方から判定する", "ユーザーだけでなくアプリケーションもエンティティとして扱い、通常の行動からの逸脱を異常とみなす", "生成AIのモデルを攻撃者の視点で試験し、弱点を洗い出す", "生成AIの利用を禁止リストで遮断し、通信そのものを止める"], oEn: ["It reads the text output by generative AI and judges by content whether it contains confidential information", "It treats applications as well as users as entities, and regards deviation from normal behavior as anomalous", "It tests the generative AI model from an attacker's viewpoint to find weaknesses", "It blocks generative AI use with a prohibition list and stops the communication itself"], a: 1, e: "UEBA はホストやアプリケーションもエンティティとして扱い、基準からの逸脱を異常とする。内容判定は DLP、攻撃者視点の試験はレッドチーミング、遮断は通信制御の役割である。", eEn: "UEBA treats hosts and applications as entities and flags deviation from baseline. Content judgment is DLP, attacker-view testing is red teaming, and blocking is traffic control."},
  {d: "IT7", q: "生成AI向けに急ごしらえした検証用サイトや API の公開口など、IT部門が把握していない外部公開資産を洗い出したい。当てる仕組みは？", qEn: "You want to uncover externally exposed assets the IT department does not know about, such as hastily built test sites and API endpoints for generative AI. Which mechanism fits?", o: ["脅威インテリジェンス（収集した脅威情報を加工・分析して、組織のセキュリティ上の意思決定に使う）", "ASM／EASM（インターネット側から見える資産を継続的に発見して棚卸しする）", "ログ管理（操作記録を取得・保管して原因究明に使う）", "SOAR（複数のツールを連携させ、対応の定型作業を自動化する）"], oEn: ["Threat intelligence (analyzes threat information for decision-making)", "ASM/EASM (continuously discovers and inventories assets visible from the internet)", "Log management (collects and stores operation records for root-cause investigation)", "SOAR (links multiple tools and automates routine response tasks)"], a: 1, e: "ASM は既知の資産から接続関係をたどり、IT部門が把握していない外部公開資産を発見する。脅威インテリジェンスやログ管理、SOAR は資産の発見を目的とする仕組みではない。", eEn: "ASM follows connections from known assets to find external assets the IT department has not tracked. Threat intelligence, log management and SOAR are not meant for discovering assets."},
  {d: "IT7", q: "ASM／EASM が外部公開資産を見つけるときの進め方として正しいのは？", qEn: "How does ASM/EASM proceed when discovering externally exposed assets?", o: ["社内の資産台帳に載った機器だけを対象に、あらかじめ決めた範囲を四半期ごとに検査し、台帳にない新しい資産は対象に加えない", "攻撃シナリオを設定して侵入し、目的を達成できるかを確かめる", "従業員に疑似メールを送り、報告が担当部門に届くかを確かめる", "既知の正当な資産を起点（シード）にし、観測できる接続関係をたどってドメインや IP アドレスブロックを再帰的に探索する"], oEn: ["It periodically inspects a fixed scope limited to equipment listed in the internal asset register", "It sets an attack scenario, breaks in, and checks whether the objective can be achieved", "It sends simulated emails to employees and checks whether reports reach the responsible department", "It starts from known legitimate assets as seeds and recursively explores domains and IP address blocks by following observable connections"], a: 3, e: "ASM は既知の資産をシードに、ドメイン、IP アドレスブロック、ホストなどを再帰的にたどる。台帳内の定期検査や侵入の試行、疑似メールは別の活動である。", eEn: "ASM uses known assets as seeds and recursively follows domains, IP blocks and hosts. Register-based inspection, intrusion attempts and simulated emails are separate activities."},
  {d: "IT7", q: "脆弱性診断と ASM の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between vulnerability assessment and ASM?", o: ["診断は把握していない資産を発見する活動で、ASM は決めた対象の欠陥を網羅的に調べて洗い出す活動である", "診断は決めた対象を調べ、ASM は既知の資産から関係をたどって、IT部門が把握していない資産を見つける", "診断は攻撃の成否と被害の程度の確認が軸で、ASM は網羅性が軸である", "診断は社外から見える資産だけが対象で、ASM は社内の端末だけが対象である"], oEn: ["Assessment is the activity of discovering unknown assets, and ASM is the activity of comprehensively examining defects in chosen targets", "Assessment examines predefined targets, whereas ASM starts by following relationships from known assets to find assets the IT department does not track", "Assessment centers on whether attacks succeed and the extent of damage, and ASM centers on comprehensiveness", "Assessment covers only externally visible assets, and ASM covers only internal endpoints"], a: 1, e: "診断は対象を決めて調べ、ASM は発見から始める点が違う。前者と後者の入れ替えは誤りで、攻撃の成否と被害の確認はペネトレーションテストの軸にあたる。", eEn: "Assessment examines defined targets while ASM begins with discovery. Swapping them is wrong, and checking attack success and damage is the axis of penetration testing."},
  {d: "IT7", q: "SIEM のアラートには現れていない未検知の脅威を、アナリストが仮説を立ててログを検索し、能動的に探したい。当てる活動は？", qEn: "You want analysts to proactively look for undetected threats that have not appeared in SIEM alerts, by forming hypotheses and searching logs. Which activity fits?", o: ["SOAR のプレイブックによる、検知後の定型対応の自動実行", "脆弱性診断による、システム全体の網羅的な検査", "脅威ハンティング（仮説を立ててデータを検索し検証する）", "標的型メール訓練による、従業員の対処の確認"], oEn: ["Automated post-detection response by SOAR playbooks", "Comprehensive inspection of the whole system by vulnerability assessment", "Threat hunting (forms hypotheses, searches data and verifies them)", "Confirming employee handling through targeted-email training"], a: 2, e: "脅威ハンティングは仮説を立てて検索し、アラートに現れない未検知の脅威を能動的に探す。SOAR は検知後の対応、診断は弱点の洗い出し、訓練は人の対処の確認が役割である。", eEn: "Threat hunting forms hypotheses and searches to proactively find threats absent from alerts. SOAR handles post-detection response, assessment finds weaknesses, and training checks human handling."},
  {d: "IT7", q: "脅威ハンティングと SIEM の検知ルールの違いとして正しいのは？", qEn: "Which statement correctly describes the difference between threat hunting and SIEM detection rules?", o: ["検知ルールは既知のパターンに反応し、ハンティングはアラートが出ていない脅威を探す", "検知ルールは仮説に基づいて手動で検索し、ハンティングは既知のパターンに自動で反応する", "検知ルールは端末内だけを見て、ハンティングはクラウドのログだけを対象にする", "検知ルールは過去の事故の証拠保全を担い、ハンティングは復旧手順の訓練を担う"], oEn: ["Detection rules react to known patterns, and hunting looks for threats that have not raised alerts", "Detection rules search manually from hypotheses, and hunting reacts automatically to known patterns", "Detection rules look only inside endpoints, and hunting covers only cloud logs", "Detection rules preserve evidence of past incidents, and hunting trains recovery procedures"], a: 0, e: "検知ルールは既知のパターンに反応し、ハンティングはアラートのない脅威を仮説で探す。手動と自動の入れ替えは誤りで、対象範囲や証拠保全・復旧訓練で分ける考え方もない。", eEn: "Rules react to known patterns; hunting seeks threats without alerts using hypotheses. Swapping manual and automatic is wrong, and scope, evidence preservation or recovery training are not the dividing lines."},
  {d: "IT7", q: "生成AIや連携アプリの認証、API 呼び出しなどのログが集まっている。脅威ハンティングに活かす方法として適切なのは？", qEn: "Authentication and API call logs for generative AI and connected apps have been collected. What is an appropriate way to use them for threat hunting?", o: ["ログを集めただけで十分とし、アラートが出るまで調査は始めない", "生成AIのログは SIEM に取り込めないため、別の表計算で個別に管理する", "利用者全員に疑似メールを送り、対処できるかを確かめる", "普段と違う利用パターンを仮説にして、ログをクエリで調べる"], oEn: ["Treat collecting the logs as sufficient and start no investigation until an alert appears", "Manage generative AI logs separately in a spreadsheet because they cannot be ingested into a SIEM", "Send simulated emails to all users and check whether they can respond", "Take unusual usage patterns as hypotheses and investigate the logs with queries"], a: 3, e: "ログが集まっていれば、普段と違う利用パターンを仮説にして調べられる。アラート待ちにするとハンティングにならず、生成AIのログも SIEM に取り込める。", eEn: "With logs collected, unusual usage patterns can be hypotheses to investigate. Waiting for alerts is not hunting, and generative AI logs can also be ingested into a SIEM."},
  {d: "IT7", q: "脅威ハンティングで仮説を検証し、不審な挙動の証拠が見つかった。その後の扱いとして適切なのは？", qEn: "A threat hunt verified a hypothesis and found evidence of suspicious behavior. What is the appropriate follow-up?", o: ["証拠をブックマークに残し、新しい検知ルール、脅威インテリジェンス、インシデントとして反映する", "証拠は残さず口頭で共有するにとどめ、既存の検知ルールも脅威インテリジェンスも変更せずそのままにしておく", "検証済みの仮説は成果に数えず、次回も同じ調査をゼロからやり直す", "見つけた内容は、そのまま刑事手続の証拠として提出する"], oEn: ["Keep the evidence in bookmarks and reflect it as new detection rules, threat intelligence and incidents", "Share it verbally without keeping evidence and leave existing detection rules unchanged", "Do not count verified hypotheses as results and redo the same investigation from scratch next time", "Submit the findings as they are as evidence in criminal proceedings"], a: 0, e: "ハンティングでは証拠をブックマークに残し、新しい検知ルール、脅威インテリジェンス、インシデントへ反映する。成果は検証済み仮説の数などで測り、法的証拠化はフォレンジックの領域。", eEn: "Hunts keep evidence in bookmarks and feed new detection rules, intelligence and incidents. Results are measured by verified hypotheses; legal evidence handling belongs to forensics."},
  {d: "IT7", q: "取得したディスクのデータを、後の民事・刑事の手続で証拠として使える状態に保ちたい。証拠の取得・保全・アクセスの各段階で守るべきことと、その実装例の組合せは？", qEn: "You want data acquired from a disk to remain usable as evidence in later civil or criminal proceedings. Which pairing of the principle to maintain at the acquisition, preservation and access stages and its implementation example is correct?", o: ["RPO の確保。スナップショットを毎時取得して、直近の状態へ戻せるようにし、復旧時のデータ損失を最小限にできるようにする", "ベースラインの学習。通常の行動のプロファイルを作り、逸脱にリスクスコアを付ける", "チェーン・オブ・カストディ。スナップショットを WORM に保存し、ハッシュ値を別の鍵保管庫に記録し、アクセスも記録する", "プレイブックの自動化。取得から保全までを自動で実行し、担当者の確認を省く"], oEn: ["Securing the RPO: take snapshots hourly so the most recent state can be restored", "Baseline learning: build profiles of normal behavior and assign risk scores to deviations", "Chain of custody: store the snapshot in WORM storage, record the hash value in a separate key vault, and log access", "Playbook automation: run acquisition through preservation automatically and skip staff confirmation"], a: 2, e: "法的要請に耐えるには、取得・保全・アクセスの各段階で証拠の管理の連鎖を保つ。スナップショットの不変保存、ハッシュ値の別保管、アクセス記録がその例である。", eEn: "To withstand legal requirements, chain of custody must be kept through acquisition, preservation and access: immutable snapshot storage, separately kept hashes and access logs are examples."},
  {d: "IT7", q: "インシデントレスポンス（CSIRT）とデジタルフォレンジックの役割の違いとして正しいのは？", qEn: "Which statement correctly describes the difference in roles between incident response (CSIRT) and digital forensics?", o: ["CSIRT は法的手続の証拠を作る専門職で、フォレンジックは被害拡大の防止と復旧の窓口である", "どちらも未検知の脅威を仮説で探す活動で、違いは対象が端末かクラウドかだけである", "フォレンジックは SIEM が使うツールで、CSIRT は SIEM の相関ルールの一種である", "CSIRT は封じ込めと復旧を進め、フォレンジックは取得したデータを証拠として保全し分析する"], oEn: ["CSIRT is a specialist role that builds evidence for legal proceedings, and forensics is the contact point for stopping damage and recovery", "Both are activities that hunt for undetected threats by hypothesis, differing only in whether the target is endpoints or cloud", "Forensics is a tool used by a SIEM, and CSIRT is a kind of SIEM correlation rule", "CSIRT drives containment and recovery, while forensics preserves and analyzes acquired data as evidence"], a: 3, e: "CSIRT は封じ込めと復旧を進め、フォレンジックは取得データを証拠として保全・分析する側面を担う。役割の入れ替えや、ハンティング・SIEM との混同は誤りである。", eEn: "CSIRT handles containment and recovery; forensics preserves and analyzes data as evidence. Swapping roles or confusing them with hunting or a SIEM is wrong."},
  {d: "IT7", q: "生成AI関連のインシデントで、プロンプトや出力のログを証拠として使う想定がある。事前に決めておくべきことは？", qEn: "You expect to use prompt and output logs as evidence in generative AI incidents. What should be decided in advance?", o: ["ログは調査のときだけ有効にし、保存期間は決めずに必要に応じて延ばす", "保存期間、改ざん防止、閲覧者の限定", "閲覧者を限定せず、全従業員が内容を確認できるようにして透明性を高める", "改ざん防止は不要とし、運用担当者が内容を修正できるようにしておく"], oEn: ["Enable logs only during investigations, and extend retention as needed without deciding it in advance", "Retention period, tamper prevention, and limiting who can view", "Do not limit viewers, and let all employees see the contents to increase transparency", "Treat tamper prevention as unnecessary and let operators correct the contents"], a: 1, e: "ログを証拠にするなら、保存期間、改ざん防止、閲覧者の限定を事前に決める。調査時だけの有効化、全員閲覧、運用担当者による修正は、証拠としての価値を損なう。", eEn: "Using logs as evidence requires deciding retention, tamper prevention and viewer limits beforehand. Enabling only during investigations, open viewing or operator edits would undermine their value."},
  {d: "IT7", q: "HA（高可用性）と DR（災害復旧）の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between HA (high availability) and DR (disaster recovery)?", o: ["HA は日常的な一時障害への耐性で、DR はまれで致命的な停止からの復旧を計画する部分", "HA は自然災害やランサムウェアなどのまれな停止からの復旧計画で、DR は日常的な一時障害への耐性", "HA は復旧後の再発防止策を指し、DR は事故の証拠を保全する手順を指す", "HA と DR は同じ意味で、違いはバックアップの世代数だけである"], oEn: ["HA is resilience to routine temporary failures, and DR is the part that plans recovery from rare, critical outages", "HA is the recovery plan from natural disasters or ransomware, and DR is resilience to routine temporary failures", "HA refers to measures preventing recurrence after recovery, and DR refers to procedures for preserving incident evidence", "HA and DR mean the same thing, differing only in the number of backup generations"], a: 0, e: "HA は日常の一時障害に耐える仕組み、DR は自然災害や重大な人為ミス、ランサムウェアなど、まれで致命的な停止からの復旧計画である。両者の入れ替えや同一視は誤り。", eEn: "HA withstands routine temporary failures; DR plans recovery from rare critical outages such as disasters, major human errors or ransomware. Swapping or equating them is wrong."},
  {d: "IT7", q: "ランサムウェアで業務システムが止まる事態に備え、「ダウンタイムが続いてよい最大時間」と「失ってよいデータの最大期間」を決めたい。それぞれを表す組合せは？", qEn: "To prepare for ransomware halting a business system, you want to set the maximum duration downtime may continue and the maximum period of data loss that is tolerable. Which pairing expresses them respectively?", o: ["RPO（ダウンタイムの最大継続時間）と RTO（許容できるデータ損失の最大期間）", "RTO（ダウンタイムの最大継続時間）と RPO（許容できるデータ損失の最大期間）", "HA（ダウンタイムの最大継続時間）と DR（許容できるデータ損失の最大期間の目標）", "BCP（ダウンタイムの最大継続時間）と HA（許容できるデータ損失の最大期間）"], oEn: ["RPO (maximum duration of downtime) and RTO (maximum tolerable period of data loss)", "RTO (maximum duration of downtime) and RPO (maximum tolerable period of data loss)", "HA (maximum duration of downtime) and DR (maximum tolerable period of data loss)", "BCP (maximum duration of downtime) and HA (maximum tolerable period of data loss)"], a: 1, e: "DR では、ダウンタイムの最大継続時間を RTO、許容できるデータ損失の最大期間を RPO として決める。RPO と RTO の入れ替えは誤りで、HA・BCP はこの目標値を指す語ではない。", eEn: "In DR, RTO is the maximum downtime duration and RPO the maximum tolerable data loss period. Swapping them is wrong, and HA and BCP are not terms for these targets."},
  {d: "IT7", q: "生成AIサービスを業務プロセスに組み込んだ。そのサービスが止まったときに備え、事前に決めておくべきことは？", qEn: "A generative AI service has been built into a business process. What should be decided in advance for when that service stops?", o: ["生成AIは補助にすぎないとして、停止時の目標は設けず利用者の判断に任せる", "停止はまれな事象なので DR の対象外とし、HA だけで扱う", "手作業への切り戻しの手順と、業務の重要度に応じた RTO・RPO", "すべての業務に、一律で最短の RTO を設定する"], oEn: ["Treat generative AI as merely auxiliary, set no targets for outages, and leave it to users' judgment", "Exclude it from DR because outages are rare, and handle it with HA alone", "Procedures for falling back to manual work, and RTO and RPO according to business importance", "Set the shortest RTO uniformly for every business process"], a: 2, e: "生成AIが止まる場合に備え、手作業への切り戻しと、業務の重要度に応じた RTO・RPO を決める。目標なしの放置や HA のみ、一律の最短 RTO は重要度による分類に反する。", eEn: "Prepare a manual fallback and RTO/RPO by business importance. Setting no targets, using HA alone, or one uniform shortest RTO conflicts with classifying by importance."},
  {d: "IT7", q: "「バックアップがあるからランサムウェアの被害は問題ない」という説明を受けた。DR の観点で確認すべきことは？", qEn: "You are told that ransomware damage is not a problem because backups exist. From a DR perspective, what should you check?", o: ["バックアップは HA の手段で DR の手段ではないため、DR の計画は別途不要である", "復元は一瞬で終わりデータ損失もないため、RPO・RTO の検討は要らない", "バックアップを取得した時点で BCP は完成し、手順書や訓練は省略してよい", "復元にはデータ損失と時間がかかるため、RPO・RTO を満たせるかを訓練で検証する"], oEn: ["Backups are a means of HA rather than DR, so no separate DR plan is needed", "Restoration finishes instantly with no data loss, so there is no need to consider RPO and RTO", "BCP is complete once a backup is taken, so procedures and drills may be omitted", "Restoration costs data loss and time, so verify through drills that the RPO and RTO can be met"], a: 3, e: "バックアップは DR の手段の一つだが、復元にはデータ損失と時間がかかる。RPO・RTO を決め、手順書を整え、訓練で検証する必要がある。", eEn: "Backups are one DR means, but restoration costs data loss and time. RPO and RTO must be set, procedures prepared, and everything verified in drills."},
  {d: "IT7", q: "検知ルールやハンティングクエリが、どの攻撃技術をカバーしていて、どこに抜けがあるかを行列で見える化したい。対応づけの軸にすべきものは？", qEn: "You want to visualize in a matrix which attack techniques your detection rules and hunting queries cover and where gaps are. What should be the axis for mapping?", o: ["MITRE ATT&CK の戦術と技術", "CIS Controls や NIST CSF のような、防御側の対策と成果の一覧", "EPP と EDR の、製品ごとの機能の一覧", "IPA の戦略的・運用的・戦術的という、脅威インテリジェンスの利用者別の区分"], oEn: ["The tactics and techniques of MITRE ATT&CK", "A list of defensive measures and outcomes, such as CIS Controls or NIST CSF", "A per-product list of EPP and EDR features", "IPA's strategic, operational and tactical divisions of threat intelligence by user"], a: 0, e: "検知ルールやクエリを ATT&CK の技術に対応づけ、有効な検知と未設定の検知を行列で重ねると抜けが分かる。防御側の対策一覧や製品機能一覧、IPA の区分は攻撃技術の軸ではない。", eEn: "Mapping rules and queries to ATT&CK techniques and overlaying enabled and missing detections in a matrix reveals gaps. Defensive lists, product features and IPA's divisions are not attack-technique axes."},
  {d: "IT7", q: "CIS Controls や NIST CSF と MITRE ATT&CK の違いとして正しいのは？", qEn: "Which statement correctly describes how MITRE ATT&CK differs from CIS Controls and NIST CSF?", o: ["前者は攻撃者の戦術と技術を一覧にし、ATT&CK は防御側の対策を成果で整理し、脅威モデルの作成には使わない", "ATT&CK は各社が想像で作る非公開の分類で、実際の観測は反映していない", "前者は防御側の対策や成果を整理し、ATT&CK は攻撃者の行動の側から整理して、脅威モデルや検知の点検に使う", "両者とも攻撃者の行動を整理しており、ATT&CK は IoC の配布形式にすぎない"], oEn: ["The former list attacker tactics and techniques, while ATT&CK organizes defensive measures by outcome", "ATT&CK is a non-public classification that each company imagines, and it does not reflect actual observations", "The former organize defensive measures and outcomes, while ATT&CK organizes from the attacker's behavior and is used for threat modeling and checking detection", "Both organize attacker behavior, and ATT&CK is merely a distribution format for IoCs"], a: 2, e: "CIS Controls と NIST CSF は防御側、ATT&CK は攻撃者の行動の側からの整理である。ATT&CK は実際の観測に基づく公開の知識ベースで、IoC の配布形式ではない。", eEn: "CIS Controls and NIST CSF are defender-side; ATT&CK is attacker-behavior-side. ATT&CK is a public knowledge base built from real observations, not an IoC distribution format."},
  {d: "IT7", q: "AI エージェントを狙う攻撃に対する、自社の検知の抜けを点検したい。ATT&CK を使った進め方として適切なのは？", qEn: "You want to check gaps in your detection against attacks targeting AI agents. What is an appropriate way to proceed using ATT&CK?", o: ["AI エージェント専用の攻撃分類が公開されるまで、点検を見送る", "AI には従来の攻撃技術が当てはまらないため、検知ルールの点検対象から外してよい", "生成AIの出力の誤りだけを対象にし、認証や権限には手を付けない", "認証情報の窃取や権限昇格などの既存の技術に当てはめて、検知の有無を点検する"], oEn: ["Postpone the check until an attack classification dedicated to AI agents is published", "Exclude it from detection-rule checks because conventional attack techniques do not apply to AI", "Cover only errors in generative AI output and leave authentication and privileges untouched", "Map it onto existing techniques such as credential theft and privilege escalation, and check whether detections exist"], a: 3, e: "AI エージェントを狙う攻撃も、認証情報の窃取や権限昇格などの既存の技術に当てはめれば、検知の抜けを点検できる。専用分類の公開待ちや対象外扱いは不要である。", eEn: "Attacks on AI agents can be mapped to existing techniques like credential theft and privilege escalation to check detection gaps. Waiting for a dedicated classification or excluding them is unnecessary."},
  {d: "IT7", q: "標的型攻撃メール訓練の結果を評価する指標として、開封率のほかに挙げられているものは？", qEn: "Besides open rate, which indicators are listed for evaluating the results of targeted-attack email training?", o: ["訓練メール内のリンクをクリックした従業員の氏名と、その回数の累計を部署別に集計し、順位表にした一覧", "適切な対処の達成率、報告が担当部門に届くまでの時間、CSIRT の対応フローの問題の有無", "訓練後に受けた研修の総時間と、教材の閲覧回数", "外部から見える資産の数と、診断で見つかった脆弱性の件数"], oEn: ["The names of employees who clicked links in the training emails and their cumulative counts", "The rate of appropriate handling, the time until reports reach the responsible department, and whether there were problems in the CSIRT response flow", "The total hours of post-training study and the number of times materials were viewed", "The number of externally visible assets and the number of vulnerabilities found by assessment"], a: 1, e: "開封率に加え、適切な対処の達成率、報告が担当部門に届くまでの時間、CSIRT の対応フローの問題の有無を指標にする。氏名の累計や研修時間、資産数は訓練の指標ではない。", eEn: "Open rate is joined by appropriate-handling rate, time for reports to reach the department, and CSIRT flow problems. Names, study hours and asset counts are not training metrics."},
  {d: "IT7", q: "標的型攻撃メール訓練の設計として適切なのは？", qEn: "Which is an appropriate design for targeted-attack email training?", o: ["送信元に直接返信して真偽を確認させ、実在する取引先を装った文面で現実味を高める", "部署の同僚に転送して相談させ、担当部門への報告は省く", "報告は求めず、開封率だけで合否を判定する", "受信者には送信元ではなく内部の担当部門へ報告させ、実在組織を装う訓練は避ける"], oEn: ["Have recipients reply directly to the sender to confirm authenticity, and add realism with text imitating real business partners", "Have recipients forward to colleagues in their department for advice, and skip reporting to the responsible department", "Do not request reports, and judge pass or fail by open rate alone", "Have recipients report to the internal responsible department rather than the sender, and avoid training that impersonates real organizations"], a: 3, e: "受信者は送信元ではなく内部の担当部門へ報告する。実在組織を装う訓練は避け、報告が届く時間や対応フローも確かめる。送信元への返信や同僚への転送、開封率だけの判定は不適切。", eEn: "Recipients report to the internal department, not the sender. Avoid impersonating real organizations, and verify report time and response flow. Replying, forwarding or open-rate-only judgment is inappropriate."},
  {d: "IT7", q: "脆弱性診断と標的型メール訓練の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between vulnerability assessment and targeted-email training?", o: ["診断は機器やシステムの欠陥を調べ、訓練は人の対処と報告の経路が有事に機能するかを確かめる", "診断は人の対処と報告の経路を調べ、訓練は機器やシステムの欠陥を調べる", "どちらも攻撃シナリオで目的を達成できるかを確かめる検査で、違いは対象が社内か社外かだけである", "診断は実在組織を装って従業員を試す活動で、訓練は Web アプリの設定を確認する活動である"], oEn: ["Assessment examines defects in equipment and systems, while training checks whether human handling and reporting routes work in an emergency", "Assessment examines human handling and reporting routes, while training examines defects in equipment and systems", "Both are tests that check whether an objective is achieved by an attack scenario, differing only in whether the target is inside or outside", "Assessment is an activity that tests employees by impersonating real organizations, and training is an activity that checks web application settings"], a: 0, e: "診断は機器やシステムの欠陥を調べ、訓練は人の対処と報告の経路が有事に機能するかを確かめる。両者の入れ替えや、同じ検査とする説明は誤りである。", eEn: "Assessment examines equipment and system defects; training checks whether human handling and reporting routes work. Swapping them or calling them the same test is wrong."},
  {d: "IT7", q: "生成AIの利用ルールを定着させるため、教育と訓練にどう組み込むのが適切か？", qEn: "How should generative AI usage rules be incorporated into education and training to make them stick?", o: ["生成AIは社内ルールの対象外とし、教育は従来の標的型メールの手口に限る", "利用ルールは文書で配布するだけにして、承認済みツールの説明も報告経路の確認も訓練には含めず、運用に任せる", "承認済みツールと入力してよい情報を教育内容に含め、誤用を見つけたときの報告経路も訓練で確かめる", "誤用を見つけたら本人に黙って修正し、担当部門には報告しない"], oEn: ["Exclude generative AI from internal rules and limit education to conventional targeted-email techniques", "Only distribute the usage rules as a document and leave the reporting route out of training", "Include approved tools and what information may be entered in the education, and verify the reporting route for misuse in training", "When misuse is found, quietly fix it with the person and do not report to the responsible department"], a: 2, e: "承認済みツールや入力してよい情報を教育に含め、誤用を見つけたときの報告経路も訓練で確かめる。文書の配布だけ、対象外扱い、非報告では有事に機能するか確認できない。", eEn: "Include approved tools and allowed inputs in education, and test the misuse reporting route in training. Document-only, exclusion or non-reporting cannot confirm it works in an emergency."},
  {d: "IT7", q: "総務省の用語集における CERT と CSIRT の説明として正しいのは？", qEn: "Which statement about CERT and CSIRT in the Ministry of Internal Affairs and Communications glossary is correct?", o: ["CERT は特定の企業内の監視担当者だけを指し、国際連携の対処には使われず、インシデントへの対応の活動自体も行わない", "CERT はインシデントに対応する活動を行う組織で、国際連携の対処にも使われる呼称。CSIRT は組織内の体制を指す", "CERT は検知後の対応を自動化する製品名で、CSIRT はその運用者である", "CERT は組織内の体制を指す呼称で、CSIRT は国際連携の対処にだけ使われる"], oEn: ["CERT refers only to monitoring staff within a specific company and is not used for international coordination", "CERT is a name for an organization that responds to incidents, also used for international coordination; CSIRT refers to a structure inside an organization", "CERT is the name of a product that automates post-detection response, and CSIRT is its operator", "CERT is a name for a structure inside an organization, and CSIRT is used only for international coordination"], a: 1, e: "CERT はインシデントに対応する組織で、国際連携の対処にも使われる呼称である。CSIRT は組織内の体制を指す。両者の入れ替えや、製品名とする説明は誤りである。", eEn: "CERT is a name for incident-responding organizations, also used in international coordination; CSIRT is an in-organization structure. Swapping them or calling CERT a product is wrong."},
  {d: "IT7", q: "経営層への情報伝達の遅れが初動を誤らせた例がある。CSIRT がインシデント対応の手順に組み込むべきことは？", qEn: "There are cases where delayed communication to management led to a wrong initial response. What should CSIRT build into its incident response procedures?", o: ["経営層へ誰がどの基準で伝えるかの、伝達ルールを事前に定める", "初動の判断は現場に任せ、経営層には復旧後にまとめて報告するだけにする", "伝達は SIEM のアラート優先度に任せ、人手では伝えない", "経営層への伝達は事故が公になってから始める"], oEn: ["Define in advance the communication rules for who tells management and by what criteria", "Leave initial decisions to the field and report to management all at once after recovery", "Leave communication to the SIEM alert priority and do not convey it manually", "Begin communicating to management only after the incident becomes public"], a: 0, e: "経営層への情報伝達の遅れが初動を誤らせた例があるため、伝達ルールを事前に定める。復旧後の一括報告や自動任せ、公になってからの伝達では遅れを防げない。", eEn: "Because delayed communication to management has misled initial response, rules should be set beforehand. Batch reports after recovery, automation-only or waiting until public cannot prevent delays."},
  {d: "IT7", q: "SOC と CSIRT の関係として正しいのは？", qEn: "Which statement about the relationship between SOC and CSIRT is correct?", o: ["役割は完全に分かれており、SOC は復旧だけ、CSIRT は監視だけを担うため、両者の間に重なる部分も共通の点もない", "SOC は CSIRT が使うツールの名称で、CSIRT は SIEM の別名である", "CSIRT は社外の組織の呼称で、SOC は社内には置けない", "監視の面で役割が重なる。SOC は SIEM などを道具に監視し、CSIRT は監視と原因解析の体制として説明される"], oEn: ["Their roles are completely separate: the SOC handles only recovery and the CSIRT handles only monitoring", "SOC is the name of a tool used by the CSIRT, and CSIRT is another name for a SIEM", "CSIRT is a name for an organization outside the company, and a SOC cannot be placed inside the company", "Their roles overlap in monitoring: the SOC monitors using tools such as a SIEM, and the CSIRT is described as a structure for monitoring and root-cause analysis"], a: 3, e: "SOC は SIEM などを道具に監視と対応を行うチームで、総務省は CSIRT を監視と原因解析の体制と説明するため、監視面で重なる。完全分担やツール名との同一視は誤り。", eEn: "A SOC monitors and responds using tools like a SIEM, and CSIRT is described as a monitoring and analysis structure, so they overlap. A complete split or equating with tools is wrong."},
  {d: "IT7", q: "アラートが多い SOC で、人が高度な脅威の調査に集中できるようにしたい。生成AI関連のアラートも含めて、適切な進め方は？", qEn: "In a SOC with many alerts, you want people to concentrate on investigating advanced threats. What is an appropriate approach, including generative-AI-related alerts?", o: ["生成AI関連のアラートは別の専用手順を人手で作り、定型の調査も含めて自動化の対象から外す", "SIEM の相関ルールを廃止し、すべてのアラートを人手で振り分ける", "定型の調査や対応を SOAR で自動化し、生成AI関連のアラートも同じ手順に乗せる", "自動化は高度な脅威の調査だけに限り、定型の調査は人手で続ける"], oEn: ["Create a separate dedicated manual procedure for generative-AI alerts and exclude them from automation", "Abolish the SIEM correlation rules and sort all alerts by hand", "Automate routine investigation and response with SOAR, and put generative-AI-related alerts through the same procedures", "Limit automation to investigating advanced threats and keep routine investigation manual"], a: 2, e: "定型の調査や対応を SOAR で自動化すれば、人は高度な脅威の調査に集中できる。生成AI関連のアラートも同じ手順に乗せられる。自動化の範囲を逆にするのは本来の狙いに反する。", eEn: "Automating routine investigation with SOAR lets people focus on advanced threats, and generative AI alerts can use the same procedures. Reversing the automation scope defeats the purpose."},
  {d: "IT7", q: "IPA の整理で、攻撃手法の理解やペネトレーションテストに使う脅威インテリジェンスは、どの区分に当たるか？", qEn: "In IPA's classification, which category of threat intelligence is used for understanding attack methods and for penetration testing?", o: ["戦略的インテリジェンス（経営層向けの判断材料）", "運用的インテリジェンス", "戦術的インテリジェンス（SOC 向けの悪性 IP やハッシュ値）", "収集・加工の段階で作る、分析前の生データ"], oEn: ["Strategic intelligence (decision material for executives)", "Operational intelligence", "Tactical intelligence (malicious IPs and hash values for SOC use)", "Raw data produced at the collection and processing stage, before analysis"], a: 1, e: "IPA は、経営層向けの戦略的、攻撃手法の理解やペネトレーションテストに使う運用的、SOC 向けの IoC などの戦術的に分ける。生データは区分ではなくサイクルの途中段階である。", eEn: "IPA divides intelligence into strategic (executives), operational (attack-method understanding and penetration testing) and tactical (IoCs for the SOC). Raw data is a cycle stage, not a category."},
  {d: "IT8", q: "デジタル庁によるゼロトラストの説明として正しいのは？", qEn: "Which is a correct description of zero trust according to the Digital Agency?", o: ["境界型やネットワーク対策を不要にする、新しいセキュリティ製品の総称", "境界の内側を信頼する前提を維持しつつ外部通信の監視だけを強める考え方", "特定ベンダーの製品を導入すれば実現できる、完成された仕組み", "境界型やネットワーク対策を否定せず、特定製品を指すものでもない考え方"], oEn: ["A collective name for new security products that make perimeter and network measures unnecessary", "A way of thinking that keeps the premise of trusting the inside of the perimeter while only strengthening monitoring of external traffic", "A finished mechanism that can be realized by introducing a specific vendor's product", "A way of thinking that does not deny perimeter or network measures and does not refer to any specific product"], a: 3, e: "デジタル庁は、ゼロトラストが境界型やネットワーク対策を否定せず、特定製品を指すものでもないと説明する。内側を信頼する前提は外す点が境界型との違い。", eEn: "The Digital Agency explains that zero trust neither denies perimeter or network measures nor refers to a specific product. It differs from perimeter defense by dropping the premise of trusting the inside."},
  {d: "IT8", q: "デジタル庁がゼロトラストの適用方針として示す六つに含まれるのは？", qEn: "Which is included among the six application policies for zero trust that the Digital Agency presents?", o: ["資源の状態確認やポリシー評価、資源とアクセスの観測", "資産の所有者が自社であることを根拠にした暗黙の信頼付与", "境界のファイアウォールの設置による、内部の信頼の確保", "特定製品の一括導入による構成の統一"], oEn: ["Checking the state of resources, policy evaluation, and observation of resources and access", "Granting implicit trust on the grounds that the asset is owned by the company", "Securing internal trust by installing a perimeter firewall", "Unifying the configuration through bulk introduction of a specific product"], a: 0, e: "六つは資源の識別、身元確認と当人認証、ネットワーク保護、資源の状態確認、ポリシー評価、資源とアクセスの観測。所有者や位置だけを根拠にする暗黙の信頼は与えない。", eEn: "The six are resource identification, identity verification and authentication, network protection, resource state checking, policy evaluation, and observation of resources and access. Implicit trust based only on ownership or location is not granted."},
  {d: "IT8", q: "生成AIサービスへのアクセス制御にゼロトラストの考え方を取り入れる進め方として適切なのは？", qEn: "What is an appropriate way to apply the zero trust approach to access control for generative AI services?", o: ["利用者や端末の状態を評価して許可する対象にし、考え方として段階的に進める", "ゼロトラスト対応を掲げる製品を一括導入し、導入完了をもって実現とみなして段階的な見直しは行わない", "社内ネットワークからのアクセスは暗黙に許可し、社外からのみ認証を求める", "既存の境界型対策を撤廃したうえで、一度にすべての資源へ適用する"], oEn: ["Evaluate the state of users and devices before permitting access, and proceed step by step as an approach", "Introduce a product that advertises zero trust support in bulk, regard completion of installation as realization and make no gradual review", "Implicitly permit access from the internal network and require authentication only from outside", "Abolish existing perimeter measures and then apply it to all resources at once"], a: 0, e: "生成AIサービスへのアクセスも、利用者や端末の状態を評価して許可できる。ゼロトラストは製品ではなく考え方なので段階的に進める。社内からの暗黙の許可は前提と逆。", eEn: "Access to generative AI services can also be permitted after evaluating user and device state. Zero trust is an approach, not a product, so proceed gradually. Implicit permission from inside is the opposite of the premise."},
  {d: "IT8", q: "境界型防御が前提としている考え方は？", qEn: "What premise does perimeter defense rest on?", o: ["内部も侵害されうると想定し、資源ごとにアクセスを評価する", "利用者と端末の認証・認可を経た資源だけを、ネットワーク上の位置に関係なく許可する", "防御の重点を静的な境界から利用者、資産、資源へ移す", "信頼できないものは内部に入らず、内部には信頼できるものだけが存在する"], oEn: ["Assume the inside can also be compromised and evaluate access resource by resource", "Permit only resources that have passed user and device authentication and authorization, regardless of location on the network", "Shift the defensive focus from the static perimeter to users, assets and resources", "Untrusted things do not enter the inside, and only trusted things exist inside"], a: 3, e: "境界型防御は、境界で内外を遮断し、内部には信頼できるものだけが存在する前提に立つ。内部も侵害されうるとして資源ごとに評価するのはゼロトラストの考え方。", eEn: "Perimeter defense blocks inside from outside at a boundary and assumes only trusted things exist inside. Assuming the inside may be compromised and evaluating per resource is the zero trust approach."},
  {d: "IT8", q: "境界型防御の弱みとされるのは？", qEn: "What is regarded as a weakness of perimeter defense?", o: ["送信元・宛先アドレスと特定ポートだけを許可するポリシーを設定できない", "外部からの攻撃を境界で遮断する効果がなく、内部の通信にしか使えない", "侵入された後に、内部での自由な移動を止めにくい", "境界を設けるために、利用者ごとの認証基盤の導入が必須になる"], oEn: ["It cannot set a policy that permits only specific source and destination addresses and ports", "It has no effect in blocking external attacks at the boundary and works only for internal traffic", "Once intruded, it is hard to stop free movement inside", "Setting up the boundary requires introducing an authentication platform for each user"], a: 2, e: "境界型は内側を信頼する前提のため、侵入された後の内部での自由な移動を止めにくいことが弱みとされる。アドレスとポートによる通信制御は、むしろこの考え方に当たる。", eEn: "Because it trusts the inside, perimeter defense is weak at stopping free movement after an intrusion. Controlling traffic by address and port is in fact an example of this approach."},
  {d: "IT8", q: "社内の境界型防御に頼った構成のまま、クラウドの生成AIサービスの利用が広がると、どのような懸念が生じるか？", qEn: "If the setup keeps relying on internal perimeter defense while use of cloud generative AI services spreads, what concern arises?", o: ["クラウドの生成AIサービスは境界の内側に置かれるため、内部の信頼前提が崩れる", "クラウド利用が広がるほど、境界のファイアウォールの許可ポリシーが不要になる", "サービスが社内境界の外にあり、境界型だけでは不十分になる恐れがある", "境界型防御は生成AIの通信だけを自動的に除外するため、監視対象が減る"], oEn: ["Cloud generative AI services are placed inside the perimeter, so the internal trust premise collapses", "The more cloud use spreads, the less the perimeter firewall's permission policies are needed", "The services lie outside the internal perimeter, so perimeter defense alone may become insufficient", "Perimeter defense automatically excludes only generative AI traffic, so the monitoring targets shrink"], a: 2, e: "クラウドの生成AIサービスは社内境界の外にあり、デジタル庁はクラウド利用が広がると境界型だけでは不十分になる恐れを指摘している。境界の内側に置かれるという前提は誤り。", eEn: "Cloud generative AI services sit outside the internal perimeter, and the Digital Agency warns that perimeter defense alone may fall short as cloud use grows. The premise that they sit inside is wrong."},
  {d: "IT8", q: "NIST CSF 2.0 のコアを構成する六つの機能の組合せとして正しいのは？", qEn: "Which combination correctly lists the six functions that make up the NIST CSF 2.0 core?", o: ["Govern、Identify、Protect、Detect、Respond、Recover", "Plan、Identify、Protect、Detect、Respond、Recover", "Govern、Identify、Protect、Detect、Respond、Audit", "Govern、Assessment、Protect、Detect、Respond、Recover"], oEn: ["Govern, Identify, Protect, Detect, Respond, Recover", "Plan, Identify, Protect, Detect, Respond, Recover", "Govern, Identify, Protect, Detect, Respond, Audit", "Govern, Assessment, Protect, Detect, Respond, Recover"], a: 0, e: "CSF 2.0 のコアは Govern、Identify、Protect、Detect、Respond、Recover の六つの機能で、同時並行かつ継続的に回す。Plan、Assessment、Audit は機能に含まれない。", eEn: "The CSF 2.0 core consists of Govern, Identify, Protect, Detect, Respond and Recover, run concurrently and continuously. Plan, Assessment and Audit are not functions."},
  {d: "IT8", q: "生成AIの導入に関する NIST の CSF 2.0 についての説明として正しいのは？", qEn: "Which statement about NIST's CSF 2.0 regarding generative AI adoption is correct?", o: ["AI 専用の機能がコアに追加され、七つ目の機能として生成AIを扱う", "AI を含むソフトの棚卸しは CSF の対象外で、別の規格で扱う必要がある", "第三者 AI ツールのリスク監視は、AI 向けに新設された専用の成果で定められており、GV.SC-07 のような既存の成果は使えない", "コアを AI 向けに更新する予定は今のところなく、GV.SC-07 や ID.AM-02 など既存の成果が使える"], oEn: ["An AI-specific function was added to the core, handling generative AI as a seventh function", "Inventory of software including AI is outside CSF and must be handled by another standard", "Risk monitoring of third-party AI tools is defined in an outcome newly created for AI, and existing outcomes such as GV.SC-07 cannot be used", "There is currently no plan to update the core for AI, and existing outcomes such as GV.SC-07 and ID.AM-02 can be used"], a: 3, e: "NIST は CSF コアを AI 向けに更新する予定は今のところないとし、第三者 AI ツールのリスク監視（GV.SC-07）や AI を含むソフトの棚卸し（ID.AM-02）など既存の成果が使えると説明する。", eEn: "NIST says it currently has no plan to update the CSF core for AI, and that existing outcomes such as third-party AI tool risk monitoring (GV.SC-07) and inventory of software including AI (ID.AM-02) can be used."},
  {d: "IT8", q: "現在の状態と目標を記述して比べ、対策の優先順位を付けたい。CSF 2.0 での進め方は？", qEn: "You want to describe the current state and the target, compare them, and prioritize measures. How does CSF 2.0 do this?", o: ["コアの六つの機能を一つずつ順番に完了させていく", "情報参照に挙げられた 50 以上の文書を、優先順位を付けずに順番にすべて実施する", "独立した第三者の審査を受けて認証を取得する", "組織プロファイルに現在の状態と目標を記述し、その差から優先順位を付ける"], oEn: ["Complete the six core functions one at a time in order", "Implement all of the 50 or more documents listed in informative references one after another without setting priorities", "Undergo review by an independent third party and obtain certification", "Describe the current state and the target in an organizational profile and set priorities from the gap"], a: 3, e: "CSF は組織プロファイルで現在の状態と目標を記述し、その差から優先順位を付ける。機能は同時並行かつ継続的に回し、多くの組織は自主的に利用する。", eEn: "CSF uses organizational profiles to describe the current state and target and sets priorities from the gap. The functions run concurrently and continuously, and most organizations use it voluntarily."},
  {d: "IT8", q: "ISO/IEC 27001 の説明として正しいのは？", qEn: "Which is a correct description of ISO/IEC 27001?", o: ["示された管理策の一覧のすべてを、組織が例外なく実施することを義務付ける", "個別製品の設定基準を Level 1・2 で示し、製品ごとに適合を判定する", "ISMS の要求事項を定め、管理策の一覧は示すが特定の管理策は義務付けない", "サービス提供組織の統制を、監査人が一定期間にわたり評価する報告書の形式"], oEn: ["It obliges the organization to implement every control in the presented list without exception", "It presents per-product configuration standards at Level 1 and 2 and judges conformity product by product", "It sets the requirements for an ISMS and presents a list of controls but does not mandate any particular control", "A report format in which an auditor evaluates a service organization's controls over a period"], a: 2, e: "ISO/IEC 27001 は ISMS の要求事項を定め、情報リスクを管理するための管理策の一覧を示すが、特定の管理策は義務付けない。製品設定基準は CIS Benchmarks、報告書は SOC 2。", eEn: "ISO/IEC 27001 sets ISMS requirements and presents a list of controls for managing information risk, without mandating particular ones. Product configuration standards are CIS Benchmarks and the report format is SOC 2."},
  {d: "IT8", q: "利用する生成AIサービスの提供事業者が ISMS 認証を取得している。利用企業が確認すべきことは？", qEn: "The provider of the generative AI service you use holds ISMS certification. What should the user company check?", o: ["事業者が認証を持てばサービス全体が対象になるため、範囲の確認は要らない", "事業者の認証があれば、自社は認証を取得しなくても同じ水準とみなせる", "認証は組織ごとに一つだけ取得されるため、サービス単位の確認は誤りになる", "認証の対象範囲に使うサービスが入っているか。自社の認証は別途必要になる"], oEn: ["If the provider holds certification the whole service is covered, so checking the scope is unnecessary", "With the provider's certification, the company can be regarded as at the same level without obtaining its own", "Certification is obtained only once per organization, so checking per service is mistaken", "Whether the service in use falls within the certification scope. The company's own certification is needed separately"], a: 3, e: "ISMS 認証は対象サービスの範囲ごとに取得されるため、使う生成AIサービスが範囲に入っているかを確認する。事業者の認証書は参考になるが、自社の認証は別途必要。", eEn: "ISMS certification is obtained per service scope, so confirm that the generative AI service you use is in scope. The provider's certificate is a reference, but your own certification is separately required."},
  {d: "IT8", q: "ISMS 認証を得る方法として正しいのは？", qEn: "Which describes correctly how ISMS certification is obtained?", o: ["組織が自ら要求事項への適合を宣言し、審査は受けない", "組織が独立した第三者の審査を受けて認証を得る", "運営委員会が登録の可否を判断し、毎年繰り返す", "監査人が統制の設計と運用の有効性を評価した報告書を受領する"], oEn: ["The organization declares its own conformity to the requirements and undergoes no review", "The organization undergoes review by an independent third party and obtains certification", "A steering committee decides on registration, repeated every year", "The organization receives a report in which an auditor evaluated the design and operating effectiveness of controls"], a: 1, e: "ISMS は、組織が独立した第三者の審査を受けて認証を得る。運営委員会による登録は ISMAP、監査人が統制の有効性を評価した報告書は SOC 2 の仕組み。", eEn: "An ISMS certificate is obtained through review by an independent third party. Registration decided by a committee is ISMAP, and a report evaluating control effectiveness by an auditor is SOC 2."},
  {d: "IT8", q: "CIS Controls の説明として正しいのは？", qEn: "Which is a correct description of CIS Controls?", o: ["非営利団体 CIS がコンセンサス方式で策定する管理策群で、NIST CSF や ISO 27000 シリーズなどに対応付けられている", "米国政府機関が法令に基づき策定し、政府調達の事業者に遵守を義務付けるとともに、NIST CSF や ISO 27000 シリーズの上位に位置づく管理策群", "個別製品の設定基準を Level 1・2 で定め、各推奨事項が管理策を参照する文書", "経営者が認識すべき3原則と、責任者に指示すべき重要10項目をまとめた文書"], oEn: ["A set of controls the non-profit CIS develops by consensus, mapped to standards such as NIST CSF and the ISO 27000 series", "A set of controls a US government agency drafts under law, obliging government contractors to comply and positioned above NIST CSF and the ISO 27000 series", "A document that sets per-product configuration standards at Level 1 and 2, whose recommendations reference controls", "A document summarizing three principles for executives and ten key items to instruct the responsible officer"], a: 0, e: "CIS Controls は非営利団体 CIS がコンセンサス方式で策定する管理策群で、NIST CSF や ISO 27000 シリーズなどに対応付けられる。製品設定基準は CIS Benchmarks。", eEn: "CIS Controls are a set of controls the non-profit CIS develops by consensus and maps to NIST CSF and the ISO 27000 series. Product configuration standards are CIS Benchmarks."},
  {d: "IT8", q: "個別の製品ごとに具体的な設定の基準を当てはめて、構成を確認したい。参照すべきものは？", qEn: "You want to apply concrete configuration standards product by product and verify the setup. What should you refer to?", o: ["NIST CSF 2.0（成果の枠組みで、具体的な行動は指定しない）", "SOC 2 報告書（サービス組織の統制を第三者が評価した報告）", "サイバーセキュリティ経営ガイドライン（経営者の責務と指示事項）", "CIS Benchmarks（Level 1・2 の設定基準）"], oEn: ["NIST CSF 2.0 (an outcome framework that does not specify concrete actions)", "A SOC 2 report (a third-party evaluation of a service organization's controls)", "The Cybersecurity Management Guidelines (executives' duties and instructions)", "CIS Benchmarks (Level 1 and 2 configuration standards)"], a: 3, e: "CIS Benchmarks は個別製品の設定基準（Level 1・2）で、各推奨事項が CIS Controls を参照する。CSF は成果の枠組み、SOC 2 は報告書、経営ガイドラインは経営者向けで、設定基準ではない。", eEn: "CIS Benchmarks are per-product configuration standards (Levels 1 and 2), each recommendation referencing CIS Controls. CSF is an outcome framework, SOC 2 is a report, and the management guidelines are for executives; none is a configuration standard."},
  {d: "IT8", q: "Microsoft の AI セキュリティ管理策（承認済みモデルの利用 AI-1、AI のレッドチーミング AI-7 など）が番号で対応付けられている管理策群は？", qEn: "To which control set are Microsoft's AI security controls (approved model use AI-1, AI red teaming AI-7, etc.) mapped by number?", o: ["ISMAP 管理基準（JIS Q 27000 シリーズなどを取り込んだ基準）", "CIS Controls v8.1（「3.11」のような節番号で参照）", "SOC 2 の五つの基準（セキュリティ、可用性など）", "サイバーセキュリティ経営ガイドラインの重要10項目"], oEn: ["ISMAP management standards (standards incorporating the JIS Q 27000 series and others)", "CIS Controls v8.1 (referenced by section numbers such as \"3.11\")", "SOC 2's five criteria (security, availability and others)", "The ten key items of the Cybersecurity Management Guidelines"], a: 1, e: "Microsoft のクラウドセキュリティベンチマークは、AI-1 や AI-7 を含む AI セキュリティ管理策を CIS Controls v8.1 の番号に対応付けている。", eEn: "Microsoft's cloud security benchmark maps its AI security controls, including AI-1 and AI-7, to CIS Controls v8.1 numbers."},
  {d: "IT8", q: "ISMS 認証と SOC 2 の違いとして正しいのは？", qEn: "Which statement correctly describes the difference between ISMS certification and SOC 2?", o: ["ISMS 認証は利用者が委託先のリスクを評価するための報告書で、SOC 2 は管理の仕組みを規格に照らして認証するもの", "ISMS 認証は管理の仕組みを規格に照らして認証し、SOC 2 は利用者が委託先のリスクを評価するための報告書", "どちらも政府のクラウド調達で登録されたサービスだけに発行される", "どちらも内部の担当者が自己評価して作成し、第三者は関与しない"], oEn: ["ISMS certification is a report for users to assess a vendor's risk, and SOC 2 certifies a management system against a standard", "ISMS certification certifies a management system against a standard, whereas SOC 2 is a report for users to assess a vendor's risk", "Both are issued only to services registered in government cloud procurement", "Both are prepared by internal staff through self-assessment, with no third party involved"], a: 1, e: "ISMS 認証は管理の仕組みを規格に照らして認証する。SOC 2 は利用者が委託先のリスクを評価するための報告書で、監査人が評価する。どちらも自己評価ではなく政府の登録制度でもない。", eEn: "ISMS certification certifies a management system against a standard. SOC 2 is a report, evaluated by an auditor, for users to assess a vendor's risk. Neither is self-assessment or a government registration scheme."},
  {d: "IT8", q: "委託先の統制が一定期間にわたり有効に運用されているかを確認したい。どの報告を求めるべきか？", qEn: "You want to confirm that a vendor's controls have operated effectively over a period. Which report should you request?", o: ["SOC 2 Type I 報告書（特定時点の統制の設計）", "経営者のブリッジレター（報告期間終了後から利用者の期末までの空白を補う）", "SOC 2 の例外事項への回答（報告書に載る個別の回答）", "SOC 2 Type II 報告書（一定期間にわたる設計と運用の有効性）"], oEn: ["A SOC 2 Type I report (design of controls at a point in time)", "A management bridge letter (covers the gap from the end of the reporting period to the user's fiscal year-end)", "Responses to SOC 2 exceptions (individual answers included in the report)", "A SOC 2 Type II report (design and operating effectiveness over a period)"], a: 3, e: "Type II は一定期間にわたる設計と運用の有効性を対象とする。Type I は特定時点の設計のみ。ブリッジレターは報告期間終了後から利用者の期末までの空白を補うもので、運用の有効性の証明ではない。", eEn: "Type II covers design and operating effectiveness over a period, while Type I covers design at a point in time. A bridge letter only fills the gap after the reporting period and does not prove operating effectiveness."},
  {d: "IT8", q: "生成AIサービスの SOC 2 報告書を受け取った。調達の判断で確認すべき点は？", qEn: "You received a SOC 2 report for a generative AI service. What should be checked in the procurement decision?", o: ["報告書が存在すれば、サービスの範囲や期間を問わず、利用者側の統制も含めてすべての統制が保証される", "報告書は監査人が作るため、利用者側で実施すべき統制は確認不要である", "例外事項は報告書に載らないため、別途ベンダーに口頭で確認すればよい", "報告書の対象範囲にそのサービスが入るか、対象期間、例外事項、利用者側で実施すべき統制"], oEn: ["If a report exists, all controls, including those on the user side, are assured regardless of the service's scope or period", "The report is prepared by an auditor, so controls the user side must implement need not be checked", "Exceptions are not in the report, so just confirm them orally with the vendor", "Whether the service is within the report's scope, the covered period, the exceptions, and the controls the user side must implement"], a: 3, e: "AI サービスの調達では、報告書の対象範囲にそのサービスが入るか、対象期間、例外事項、利用者側で実施すべき統制（User Entity Responsibilities）を確認する。例外事項への回答も報告書に載る。", eEn: "In AI service procurement, check whether the service is in scope, the period covered, exceptions, and the user-side controls (User Entity Responsibilities). Responses to exceptions are also included in the report."},
  {d: "IT8", q: "公共向けにクラウド型の生成AIサービスを提案する。政府機関等の調達を踏まえ、まず確認すべきことは？", qEn: "You are proposing a cloud-based generative AI service to the public sector. Given government procurement, what should be checked first?", o: ["ISMAP クラウドサービスリストに登録されているか。政府機関等は原則そこから調達する", "ISMS 認証と SOC 2 報告書の両方があれば、リストへの登録の有無は調達時に問われない", "ISMAP-LIU への登録があれば、あらゆる業務・情報に使える", "登録は一度受ければ更新が不要なため、過去の登録年度を確かめれば足りる"], oEn: ["Whether it is registered in the ISMAP Cloud Service List. Government bodies in principle procure from it", "With both ISMS certification and a SOC 2 report, registration in the list is not asked about at procurement", "Registration in ISMAP-LIU means it can be used for any work and information", "Registration needs no renewal once obtained, so checking the past registration year is enough"], a: 0, e: "政府機関等は原則として ISMAP クラウドサービスリストから調達するため、登録の有無が確認点。ISMAP-LIU は低リスクの業務・情報向け、登録は毎年繰り返す。ISMS や SOC 2 は民間の第三者評価。", eEn: "Government bodies in principle procure from the ISMAP Cloud Service List, so registration is the check point. ISMAP-LIU is for low-risk work and information, and registration repeats yearly. ISMS and SOC 2 are private third-party evaluations."},
  {d: "IT8", q: "ISMAP の登録の流れで、外部監査を行う機関と、登録の可否を判断する組織の組合せとして正しいのは？", qEn: "In the ISMAP registration flow, which combination correctly names the body that conducts the external audit and the body that decides on registration?", o: ["外部監査は運用支援機関（IPA）、登録の可否は登録監査機関", "外部監査は登録監査機関、登録の可否は運営委員会", "外部監査は運営委員会、登録の可否は運用支援機関（IPA）", "外部監査は登録監査機関、登録の可否は事業者の自己判断"], oEn: ["External audit by the operation support organization (IPA); the registration decision by the registered audit organization", "External audit by a registered audit organization; the registration decision by the steering committee", "External audit by the steering committee; the registration decision by the operation support organization (IPA)", "External audit by a registered audit organization; the registration decision left to the provider itself"], a: 1, e: "事業者は登録監査機関の外部監査と、運用支援機関（IPA）の審査を受け、登録の可否は運営委員会が判断する。これを毎年繰り返す。", eEn: "The provider undergoes an external audit by a registered audit organization and review by the operation support organization (IPA), and the steering committee decides on registration. This repeats every year."},
  {d: "IT8", q: "サイバーセキュリティ経営ガイドライン Ver 3.0 が示す、経営者が認識すべき3原則は？", qEn: "What are the three principles executives should recognize, as set out in the Cybersecurity Management Guidelines Ver 3.0?", o: ["経営者のリーダーシップ、自社システム内に限った対策、緊急時のみの社外への連絡", "責任者への全面委任、サプライチェーン全体への目配り、平時の社内だけのコミュニケーションと緊急時の外部への報告", "経営者のリーダーシップ、サプライチェーン全体への目配り、平時と緊急時の社内外とのコミュニケーション", "最新製品の優先導入、サプライチェーン全体への目配り、緊急時と平時の区別のない運用"], oEn: ["Executive leadership, measures limited to the company's own systems, and outside contact only in emergencies", "Full delegation to the responsible officer, attention to the entire supply chain, and communication only inside the company in normal times plus reports to the outside in emergencies", "Executive leadership, attention to the entire supply chain, and communication inside and outside the company in both normal times and emergencies", "Priority adoption of the latest products, attention to the entire supply chain, and operation with no distinction between emergencies and normal times"], a: 2, e: "3原則は、経営者のリーダーシップ、サプライチェーン全体への目配り、平時と緊急時の社内外とのコミュニケーション。責任者への全面委任や自社内限定の対策は原則に反する。", eEn: "The three principles are executive leadership, attention to the entire supply chain, and communication inside and outside the company in normal times and emergencies. Full delegation or company-only measures contradict them."},
  {d: "IT8", q: "生成AI導入に伴うリスクの方針、体制、緊急対応を経営層に説明し、承認を得る材料の枠として使えるのは？", qEn: "What can be used as a framework for explaining policies, structures and emergency response for generative AI risks to executives and gaining approval?", o: ["CIS Controls の節番号に沿った、個別の技術対策の一覧", "SOC 2 の五つの基準に沿った、利用者側の統制の一覧", "サイバーセキュリティ経営ガイドラインの重要10項目", "CIS Benchmarks の Level 1・2 に沿った、製品の設定基準"], oEn: ["A list of individual technical measures following the CIS Controls section numbers", "A list of user-side controls following SOC 2's five criteria", "The ten key items of the Cybersecurity Management Guidelines", "Product configuration standards following Level 1 and 2 of CIS Benchmarks"], a: 2, e: "生成AI導入のリスクの方針、体制、緊急対応は、責任者に指示すべき重要10項目の枠で経営層に説明できる。同ガイドラインは個別の技術対策を並べる管理策集ではなく、経営者の責務と指示事項を示す。", eEn: "Policies, structures and emergency response for generative AI risk can be explained to executives within the ten key items to instruct the responsible officer. The guideline is not a catalog of technical measures but sets executives' duties and instructions."},
  {d: "IT8", q: "脆弱性診断で技術的な欠陥の一覧が得られた。この結果を対応につなげるため、次に行うべきことは？", qEn: "A vulnerability assessment produced a list of technical flaws. What should be done next to turn the results into action?", o: ["結果を資産の重要度や脅威と合わせて評価し、対応の優先順位を決める", "欠陥の件数が多い順に、重要度にかかわらず同じ期限で修正する", "診断結果を受容の判断材料として、そのまま経営陣の承認を得て完了とする", "診断の対象を広げ、欠陥が出なくなるまで診断を繰り返す"], oEn: ["Evaluate the results together with asset importance and threats, and set priorities for action", "Fix flaws in descending order of count, with the same deadline regardless of importance", "Treat the results as grounds for acceptance and finish after obtaining management approval as is", "Widen the scope and repeat the assessment until no flaws are found"], a: 0, e: "脆弱性診断は技術的な欠陥を見つける手段で、リスクアセスメントはその結果を資産の重要度や脅威と合わせて優先順位を決める工程。件数順の一律修正や診断の反復では優先順位が付かない。", eEn: "A vulnerability assessment only finds technical flaws; risk assessment combines the results with asset importance and threats to set priorities. Fixing by count or repeating scans sets no priorities."},
  {d: "IT8", q: "詳細リスク分析を進める順序として正しいのは？", qEn: "What is the correct order for carrying out a detailed risk analysis?", o: ["リスク値の算定、資産の洗い出し、対策の決定の順", "対策の決定、資産の洗い出し、リスク値の算定の順", "資産の洗い出し、リスク値の算定、対策の決定の順", "資産の洗い出し、対策の決定、リスク値の算定の順"], oEn: ["Calculate risk values, identify assets, then decide on countermeasures", "Decide on countermeasures, identify assets, then calculate risk values", "Identify assets, calculate risk values, then decide on countermeasures", "Identify assets, decide on countermeasures, then calculate risk values"], a: 2, e: "詳細リスク分析は、資産の洗い出し、リスク値の算定、対策の決定の順に進む。リスク値は資産ごとの価値・脅威・脆弱性から求めるため資産が先で、対策の決定は算定結果を見て最後に行う。", eEn: "Detailed risk analysis goes: identify assets, calculate risk values, decide on countermeasures. Values come from each asset's value, threats and vulnerabilities, so assets come first and countermeasures last."},
  {d: "IT8", q: "生成AIの利用に伴うリスクを評価するとき、情報資産として洗い出す対象は？", qEn: "When assessing the risks of using generative AI, what should be identified as information assets?", o: ["生成AIサービスの利用料金と、契約期間の長さ", "利用者の人数と、各部署への配置状況の一覧", "モデルの学習に使われた文献の種類と量", "入力するデータの機密度と、連携先の範囲"], oEn: ["The usage fees of the generative AI service and the length of the contract", "The number of users and a list of their placement across departments", "The kinds and volume of documents used to train the model", "The confidentiality level of the input data and the range of connected systems"], a: 3, e: "生成AIでは、入力データの機密度や連携先の範囲を情報資産として洗い出し、リスク評価の対象にする。料金、人数、学習文献は、ここで資産として挙げられている対象ではない。", eEn: "For generative AI, the confidentiality of input data and the range of connected systems are identified as information assets. Fees, headcount and training documents are not the assets named."},
  {d: "IT8", q: "生成AIの利用ルール（利用可能なツール、入力してよい情報、承認手続）を定めたい。既存の規程体系との整合を保つ方法は？", qEn: "You want to set rules for generative AI use (permitted tools, information that may be entered, approval procedures). How do you keep them consistent with the existing policy framework?", o: ["既存の対策基準と実施手順に追記する", "規程体系とは別に、生成AI専用の独立した文書を新たに作成して運用する", "基本方針を書き換えて、ツールの名称や承認手続の細部まで盛り込む", "各部署が個別に定めた運用メモを、そのまま正式な規程として扱う"], oEn: ["Add them to the existing countermeasure standards and implementation procedures", "Create a separate, standalone document for generative AI and operate it apart from the policy framework", "Rewrite the basic policy to include tool names and the details of the approval procedure", "Treat the operating notes each department wrote on its own as the official rules as they are"], a: 0, e: "利用可能なツールや入力してよい情報は守るべき基準、承認手続は具体的な手順にあたる。新しい文書を別に作るより、既存の対策基準と実施手順への追記のほうが整合を保てる。", eEn: "Permitted tools and enterable information are standards, and approval is a procedure. Adding to the existing standards and procedures keeps them consistent better than creating a separate document."},
  {d: "IT8", q: "情報セキュリティポリシーの三つの層の関係として正しいのは？", qEn: "Which correctly describes the relationship among the three layers of an information security policy?", o: ["個別の実施手順を先に積み上げ、その集約を対策基準とし、さらに基本方針とする", "基本方針に基づき、リスク評価を踏まえて対策基準を定め、実施手順に落とし込む", "対策基準を最上位に置き、基本方針は各システムの手順の補足として整える", "基本方針と実施手順だけを定め、対策基準は監査の直前に作成する"], oEn: ["Pile up individual procedures first, aggregate them into the standards, and then into the basic policy", "Set standards based on the basic policy and the risk assessment, then turn them into implementation procedures", "Put the standards at the top and treat the basic policy as a supplement to each system's procedures", "Define only the basic policy and the procedures, and write the standards just before an audit"], a: 1, e: "基本方針に基づき、リスク評価の結果を踏まえて対策基準を定め、それを個別の業務・システムの実施手順に落とし込む。下から積み上げる順や対策基準を欠く構成は、この関係に反する。", eEn: "Standards are set from the basic policy and the risk assessment, then turned into procedures for each task and system. Building from the bottom up or omitting the standards contradicts this."},
  {d: "IT8", q: "自組織の対策基準を定めるとき、国の統一基準が示す対策と異なる手段を採ってよいのは？", qEn: "When setting your own countermeasure standards, when may you adopt measures different from those in the national unified standards?", o: ["自組織の業務に支障が出ると部門責任者が判断した場合", "統一基準の対策が自組織では費用に見合わないと試算された場合", "外部の認証を取得済みで、審査で指摘が出ていない場合", "統一基準と同等以上の水準が確保できる場合"], oEn: ["When a department head judges that the measures would hinder the organization's operations", "When estimates show that the unified standards' measures are not worth their cost to the organization", "When an external certification is already held and the audit raised no findings", "When a level equal to or higher than the unified standards is ensured"], a: 3, e: "国の統一基準は機関等が守る共通の遵守事項で、対策基準は自組織の特性に合わせて具体策を定める。同等以上の水準なら別の対策でもよく、業務の支障や費用だけでは理由にならない。", eEn: "The unified standards are common obligations; countermeasure standards tailor concrete measures to the organization. Alternatives are fine if the level is equal or higher; hindrance or cost alone is not a reason."},
  {d: "IT8", q: "委託先やクラウド事業者を台帳で管理する。台帳に記録する項目として挙げられているのは？", qEn: "You manage contractors and cloud providers in a register. Which items are listed as ones to record in it?", o: ["担当者の氏名、従業員数、直近の売上高と利益率、財務格付の推移と見通し", "契約金額、支払条件、請求書の発行日と送付先", "拠点の所在地、設立年、取締役の経歴と持株比率", "提供サービス、システムへのアクセスレベル、扱うデータの種類と場所"], oEn: ["Contact person's name, number of employees, latest revenue and profit margin, and credit rating trend", "Contract amount, payment terms, and invoice issue dates and recipients", "Office locations, year of founding, and directors' careers and shareholding ratios", "Services provided, level of access to systems, and the type and location of data handled"], a: 3, e: "サードパーティは台帳で管理し、提供サービス、システムへのアクセスレベル、扱うデータの種類と場所を記録して、重要度に応じてリスクを評価する。金額や企業の沿革は、リスク評価の記録項目として挙げられていない。", eEn: "Third parties are kept in a register recording services, level of system access, and the type and location of data, and risk is assessed by importance. Amounts and corporate history are not listed items."},
  {d: "IT8", q: "責任共有モデルと第三者リスク管理の違いとして正しいのは？", qEn: "Which correctly describes the difference between the shared responsibility model and third-party risk management?", o: ["前者はクラウド事業者と利用者の責任の分担を示し、後者は選定から契約終了までの管理の仕組み全体を指す", "前者は取引先の選定から契約終了までの管理を指し、後者はクラウド事業者と利用者の責任の分担を示す", "前者は国内の事業者だけを対象とし、後者は国外の事業者だけを対象とする、地域で分けた管理の枠組みである", "前者は契約前の評価だけを、後者は契約後の継続的な監視だけを受け持つ管理である"], oEn: ["The former shows how responsibility is divided between cloud provider and customer; the latter covers the whole management system from selection to termination", "The former covers management from partner selection to termination; the latter shows how responsibility is divided between provider and customer", "The former targets only domestic providers; the latter is a management framework only for overseas providers", "The former handles only pre-contract evaluation; the latter handles only continuous monitoring after contract"], a: 0, e: "責任共有モデルはクラウド事業者と利用者の責任の分担を示す。第三者リスク管理は取引先の選定、契約、監視、終了までの管理の仕組み全体を指す。国内外や契約前後で分ける区分はない。", eEn: "The shared responsibility model shows the division of responsibility; third-party risk management covers selection, contract, monitoring and termination. It does not split by domestic/overseas or pre/post-contract."},
  {d: "IT8", q: "AIモデルやSaaSを調達する。第三者リスク管理の評価項目にできるものは？", qEn: "You are procuring an AI model or SaaS. Which can be used as evaluation items in third-party risk management?", o: ["導入企業数の多さ、利用者の口コミ、無料トライアルの有無、サポート窓口の対応時間", "データの所在・保管・廃棄の取決め、再委託の手続、SOC 2 等の報告書の確認", "提供元の従業員数、本社の所在地、設立からの年数", "月額料金の安さ、画面の見やすさ、応答の速さ"], oEn: ["Number of adopting companies, user reviews, availability of a free trial, and support desk hours", "Arrangements on data location, storage and disposal, subcontracting procedures, and review of reports such as SOC 2", "The provider's headcount, headquarters location, and years since founding", "Low monthly fee, screen readability, and response speed"], a: 1, e: "AIモデルやSaaSの調達でも、データの所在・保管・廃棄の取決め、再委託の手続、SOC 2 等の第三者保証報告書の確認を評価項目にできる。人気や価格、使い勝手はこの観点にあたらない。", eEn: "Even for AI models and SaaS, data location/storage/disposal terms, subcontracting procedures and third-party assurance reports such as SOC 2 can be evaluation items. Popularity, price and usability are not."},
  {d: "IT8", q: "個人情報保護委員会のガイドラインの別添が示す、安全管理措置の種類として正しいのは？", qEn: "Which correctly lists the types of security control measures shown in the annex to the Personal Information Protection Commission guidelines?", o: ["組織的・法的・物理的・技術的の4つの措置", "組織的・人的・物理的・契約的の4つの措置", "組織的・人的・物理的・技術的の4つの措置", "人的・物理的・技術的・財務的の4つの措置"], oEn: ["Four measures: organizational, legal, physical and technical", "Four measures: organizational, human, physical and contractual", "Four measures: organizational, human, physical and technical", "Four measures: human, physical, technical and financial"], a: 2, e: "ガイドラインの別添は、基本方針の策定、取扱いの規律の整備、組織的・人的・物理的・技術的の4つの措置、外的環境の把握を示す。法的・契約的・財務的という区分は含まれない。", eEn: "The annex shows a basic policy, handling rules, four measures (organizational, human, physical, technical) and understanding the external environment. Legal, contractual and financial are not categories."},
  {d: "IT8", q: "ISMS 認証と、個人情報保護法の安全管理措置の違いとして正しいのは？", qEn: "Which correctly describes the difference between ISMS certification and the security control measures under the Personal Information Protection Act?", o: ["ISMS は事業者が任意で取得する認証で、安全管理措置は個人データを扱う事業者に法が求める", "ISMS は法が義務付ける認証で、安全管理措置は事業者が任意に取り組むものである", "どちらも任意だが、ISMS だけが漏えい等の際の委員会への報告を定めている", "どちらも法が求めるが、安全管理措置のほうが独立した第三者の審査を受けて認証を得る仕組みである"], oEn: ["ISMS is a certification obtained voluntarily; the control measures are required by law of businesses handling personal data", "ISMS is a legally mandated certification; the control measures are something businesses undertake voluntarily", "Both are voluntary, but only ISMS provides for reporting to the commission when a leak occurs", "Both are required by law, but the control measures are certified through third-party review"], a: 0, e: "ISMS は事業者の任意の認証。安全管理措置は個人データを扱う事業者に法が求めるもので、漏えい等が起きたときの委員会への報告も定められている。第三者の審査を受けるのは ISMS 側である。", eEn: "ISMS is a voluntary certification. The control measures are required by law of businesses handling personal data, with reporting to the commission on leaks. Third-party review applies to ISMS."},
  {d: "IT8", q: "個人データを海外で運用される外部のAIサービスに扱わせたい。安全管理措置の観点で論点になるのは？", qEn: "You want an externally operated overseas AI service to handle personal data. What becomes the issue from the standpoint of security control measures?", o: ["委託先の監督は不要で、国内の事業者と同じ運用を想定すれば足りるとする", "委員会へ事前に報告すれば、委託先の選定や契約の確認は省略できる", "手法例の全てを講じることが利用の条件で、一つでも欠ければ使えない", "委託先の監督と、外国で扱う場合のその国の制度の確認（外的環境の把握）"], oEn: ["Supervision is unnecessary; assuming the same operation as a domestic provider is enough", "If the commission is notified in advance, checking the contractor's selection and contract can be skipped", "Applying every example method is a condition of use, and missing even one rules the service out", "Supervision of the contractor, and checking the foreign country's regime (understanding the external environment)"], a: 3, e: "個人データを外部のAIサービスに扱わせるなら、委託先の監督と、外国で扱う場合の外的環境の把握（その国の制度の確認）が論点になる。手法例は全てを講じる必要はないが、監督は省けない。", eEn: "When an external AI service handles personal data, supervising the contractor and understanding the external environment abroad (checking that country's regime) are the issues. Not every example method is needed, but supervision cannot be skipped."},
  {d: "IT8", q: "金融分野のサイバーセキュリティガイドラインで、サイバーハイジーンなど基礎を指す区分と、大手等が参照すべき先進的な区分の組合せとして正しいのは？", qEn: "In the financial sector cybersecurity guideline, which pairs the category for basics such as cyber hygiene with the advanced category large institutions should consult?", o: ["基礎は「対応が望ましい事項」、先進的なものは「基本的な対応事項」", "基礎は「基本的な対応事項」、先進的なものは「対応が望ましい事項」", "基礎は「必須対応事項」、先進的なものは「推奨対応事項」", "区分はなく、全項目を大手等と同じ水準で一律に求める"], oEn: ["Basics are \"desirable response items\"; advanced ones are \"basic response items\"", "Basics are \"basic response items\"; advanced ones are \"desirable response items\"", "Basics are \"mandatory response items\"; advanced ones are \"recommended response items\"", "There is no categorization; every item is required uniformly at the level of large institutions"], a: 1, e: "各項目は、サイバーハイジーンなど基礎の「基本的な対応事項」と、大手等が参照すべき先進的な「対応が望ましい事項」に分かれる。いずれも一律ではなく、リスクに見合った対応が前提である。", eEn: "Items are split into \"basic response items\" for basics like cyber hygiene and \"desirable response items\" for advanced practices large institutions should consult. Neither is uniform; risk-appropriate measures are assumed."},
  {d: "IT8", q: "経営者向けに3原則と10項目を示すサイバーセキュリティ経営ガイドラインと比べた、金融分野ガイドラインの位置づけは？", qEn: "Compared with the Cybersecurity Management Guidelines, which present three principles and ten items for executives, how is the financial sector guideline positioned?", o: ["経営者の責務を3原則にまとめ、金融機関以外の全業種に全面適用を義務付けた規程", "個別の製品の設定基準を示し、金融機関が使うべき製品を指定したもの", "金融機関等を対象に、金融庁が検査・モニタリングで用いる着眼点を具体化したもの", "経済産業省とIPAが共同で公表し、実践のためのプラクティス集を兼ねたもの"], oEn: ["It summarizes executive duties in three principles and makes them mandatory for all non-financial industries", "It gives configuration standards for individual products and designates the products financial institutions must use", "It makes concrete the points the FSA uses in inspections and monitoring, aimed at financial institutions", "It was published jointly by METI and IPA and doubles as a practice collection for implementation"], a: 2, e: "経営ガイドラインが経営者向けの3原則と10項目を示すのに対し、金融分野のガイドラインは金融機関等を対象に、金融庁が検査・モニタリングで用いる着眼点を具体化する。", eEn: "While the management guidelines give executives three principles and ten items, the financial guideline targets financial institutions and makes concrete the points the FSA uses in inspections and monitoring."},
  {d: "IT8", q: "金融機関ではない企業が、生成AI導入の整備で金融分野ガイドラインを参照例にできる点は？", qEn: "A non-financial company is preparing for generative AI adoption. What in the financial sector guideline can it use as a reference?", o: ["年1回の外部監査の受審、新商品の提供前の金融庁への届出、サードパーティの全面的な禁止", "リスク評価を年1回行うこと、新商品・サービスで評価すること、サードパーティ管理の水準", "検査官の受け入れ頻度、役員報酬の開示範囲、取引所への報告時期", "資金決済の限度額の設定、預金者保護の基準、店舗の防犯設備の水準"], oEn: ["Undergoing an annual external audit, notifying the FSA before offering new products, and banning third parties entirely", "Assessing risk once a year, assessing for new products and services, and the level of third-party management", "Frequency of hosting inspectors, scope of executive pay disclosure, and timing of reports to exchanges", "Setting payment limits, depositor protection standards, and the level of branch security equipment"], a: 1, e: "金融機関以外でも、リスク評価を年1回行うこと、新商品・サービスで評価すること、サードパーティ管理の水準を測る参照例になる。外部監査や届出、第三者の禁止は挙げられていない。", eEn: "Even outside finance, it serves as a reference for annual risk assessment, assessment for new products and services, and the level of third-party management. External audits, notifications and bans are not listed."},
  {d: "IT8", q: "米国政府系の顧客が、要件を管理策の名称で示してきた。名称の出どころとして想定すべきものは？", qEn: "A US government-related customer states its requirements by control names. What should you assume those names come from?", o: ["NIST CSF 2.0（成果を体系化した枠組み）", "ISO/IEC 27701（プライバシー情報マネジメントの規格）", "NIST SP 800-53（個々の管理策を収めたカタログ）", "サイバーセキュリティ経営ガイドライン（経営者向けの文書）"], oEn: ["NIST CSF 2.0 (a framework organizing outcomes)", "ISO/IEC 27701 (a privacy information management standard)", "NIST SP 800-53 (a catalog containing individual controls)", "Cybersecurity Management Guidelines (a document for executives)"], a: 2, e: "SP 800-53 は個々の管理策を収めたカタログで、米国政府系の顧客やベンダーの説明は、この管理策名で示される。自社の管理策との対応づけに使える。CSF は成果の枠組みである。", eEn: "SP 800-53 is a catalog of individual controls, and US government-related customers and vendors state requirements by these control names. It can be mapped to your own controls. CSF is an outcomes framework."},
  {d: "IT8", q: "NIST SP 800-53 の Rev.5 での変更として正しいのは？", qEn: "Which is a correct change in NIST SP 800-53 Rev.5?", o: ["プライバシーの管理策が独立し、別のカタログとして切り出された", "管理策の記述が、満たす主体をシステムか組織かで厳密に分ける形に改められた", "管理策の選定プロセスが、カタログ本体の中に取り込まれた", "セキュリティとプライバシーの管理策が一つの統合カタログになった"], oEn: ["Privacy controls were split out into a separate catalog", "Control descriptions were revised to distinguish strictly whether the system or the organization satisfies them", "The control selection process was brought into the catalog itself", "Security and privacy controls became a single integrated catalog"], a: 3, e: "Rev.5 ではセキュリティとプライバシーの管理策が一つの統合カタログになった。記述は満たす主体に依らない成果ベースに改められ、選定プロセスは本体から分離された。", eEn: "In Rev.5, security and privacy controls became one integrated catalog. Descriptions became outcome-based regardless of who satisfies them, and the selection process was separated from the main text."},
  {d: "IT8", q: "SP 800-53 Rev.5 のサプライチェーンリスク管理（SCRM）の扱いとして正しいのは？", qEn: "How does SP 800-53 Rev.5 treat supply chain risk management (SCRM)?", o: ["既存のファミリーに一項目だけ追記され、他の管理策には反映されていない扱いである", "独立した管理策ファミリーが新設され、カタログ全体にもその観点が組み込まれた", "独立したファミリーは設けず、調達に関する別の文書に切り出された", "管理策ファミリーが新設されたが、カタログ全体には観点が組み込まれていない"], oEn: ["Only one item was added to an existing family and it is not reflected in other controls", "A dedicated control family was added, and the perspective was built into the whole catalog", "No dedicated family was created; it was moved into a separate procurement document", "A control family was added, but the perspective was not built into the rest of the catalog"], a: 1, e: "Rev.5 ではSCRM の管理策ファミリーが新設され、カタログ全体にもその観点が組み込まれた。SCRM が独立したことは、調達管理の参考になる。", eEn: "Rev.5 added a SCRM control family and built the perspective into the whole catalog. That SCRM stands on its own is a useful reference for procurement management."},
  {d: "IT8", q: "パブリッククラウドで個人情報（PII）を処理者として扱う事業者に求める保護の指針を確認したい。見るべき規格は？", qEn: "You want to check the protection guidance expected of a public cloud provider that processes personal information (PII) as a processor. Which standard should you look at?", o: ["ISO/IEC 27018（パブリッククラウドのPII保護）", "ISO/IEC 27017（クラウド固有の管理策の指針）", "ISO/IEC 27701（プライバシー情報マネジメントシステム）", "ISO/IEC 27001（情報セキュリティマネジメントシステム）"], oEn: ["ISO/IEC 27018 (PII protection in public clouds)", "ISO/IEC 27017 (guidance on cloud-specific controls)", "ISO/IEC 27701 (privacy information management system)", "ISO/IEC 27001 (information security management system)"], a: 0, e: "27018 は PII の処理者であるクラウド事業者向けで、パブリッククラウドの PII 保護を扱う。27017 はクラウド固有の管理策、27701 はプライバシー情報マネジメントを扱う。", eEn: "27018 is for cloud providers acting as PII processors and covers PII protection in public clouds. 27017 covers cloud-specific controls and 27701 privacy information management."},
  {d: "IT8", q: "ISO/IEC 27701 の認証の扱いとして正しいのは？", qEn: "Which correctly describes certification under ISO/IEC 27701?", o: ["27001 とは独立した規格で、単独で認証を取れる", "27018 の拡張であり、クラウド事業者だけが認証を取れる", "27001 の拡張であり、単独では認証を取れない", "27001 の拡張で、取得すれば GDPR 適合の証明になる"], oEn: ["It is independent of 27001 and can be certified on its own", "It extends 27018, and only cloud providers can be certified", "It extends 27001 and cannot be certified on its own", "It extends 27001, and obtaining it proves GDPR compliance"], a: 2, e: "27701 は 27001 の拡張で、単独では認証を取れない。27701 の認証は GDPR 適合の証明とはみなせない。27018 の拡張でもなく、クラウド事業者に限った認証でもない。", eEn: "27701 extends 27001 and cannot be certified alone. A 27701 certification cannot be regarded as proof of GDPR compliance. It does not extend 27018 or apply only to cloud providers."},
  {d: "IT8", q: "生成AIサービスの事業者が ISO/IEC 27017 の認証を持っている。選定での扱いとして適切なのは？", qEn: "A generative AI service provider holds ISO/IEC 27017 certification. How should this be handled in vendor selection?", o: ["認証があれば自社の利用構成も適合しているとみなし、自社側の評価を省く", "認証の対象範囲に使うサービスが入るかを確認し、自社の利用構成の評価は別に行う", "認証の有無だけを確認し、対象範囲は事業者全体に及ぶとみなして確認しない", "範囲は確認するが、27701 の認証がなくても GDPR 適合の証明として扱う"], oEn: ["If certified, assume your configuration also conforms and skip your own evaluation", "Confirm the service you use is in the certified scope, and evaluate your own configuration separately", "Check only whether certification exists and assume the scope covers the whole provider without checking", "Check the scope, but treat the provider as proven GDPR compliant even without 27701 certification"], a: 1, e: "認証の有無と対象サービスの範囲を確認する材料になるが、認証は自社の利用構成の適合を保証しない。自社側の評価は別に必要で、27701 の認証も GDPR 適合の証明とはみなせない。", eEn: "Certification and its scope are material for selection, but it does not guarantee that your own configuration conforms. Your own evaluation is still needed, and 27701 is not proof of GDPR compliance either."},
  {d: "IT8", q: "NIST の考え方で、ゼロトラストが防御の重点を移すのは？", qEn: "In NIST's thinking, where does zero trust shift the focus of defense?", o: ["利用者・資産・資源から、静的なネットワーク境界へ", "社内ネットワークの外側から、内側の全端末の一括管理へ", "特定の製品から、複数製品を束ねた統合基盤へ", "静的なネットワーク境界から、利用者・資産・資源へ"], oEn: ["From users, assets and resources to the static network perimeter", "From outside the corporate network to bulk management of all internal devices", "From a specific product to an integrated platform bundling several products", "From the static network perimeter to users, assets and resources"], a: 3, e: "NIST は、防御の重点を静的なネットワーク境界から利用者、資産、資源へ移す。ゼロトラストは特定製品を指さない考え方なので、製品から統合基盤へ移すという説明も当たらない。", eEn: "NIST shifts the focus from the static network perimeter to users, assets and resources. Zero trust is an idea, not a specific product, so a shift from products to a platform is not it either."},
  {d: "IT8", q: "送信元・宛先アドレスと特定ポートだけを許可する通信ポリシーは、どの考え方にあたるか？", qEn: "Which approach does a communication policy that permits only specific source/destination addresses and ports belong to?", o: ["ゼロトラスト。認証・認可を経て資源ごとにアクセスを許可する", "NIST CSF 2.0 の Protect 機能。成果を示すだけで行動は指定しない", "境界型防御。ネットワークで境界を設け、通信を制御する", "ISMS。管理策の一覧を示し、特定の管理策を義務付ける"], oEn: ["Zero trust, which grants access per resource after authentication and authorization", "The Protect function of NIST CSF 2.0, which shows only outcomes and specifies no actions", "Perimeter-based security, which sets a boundary with the network and controls traffic", "ISMS, which lists controls and mandates specific ones"], a: 2, e: "送信元・宛先アドレスと特定ポートだけを許可するポリシーは、ネットワークで境界を設けて通信を制御する境界型防御の考え方にあたる。ISMS は特定の管理策を義務付けない。", eEn: "A policy permitting only specific addresses and ports is perimeter-based security, which sets a boundary with the network and controls traffic. ISMS does not mandate specific controls."},
  {d: "IT8", q: "CSF 2.0 は達成すべき成果を示すだけで、具体的な行動は指定しない。実現手段を補うために使うのは？", qEn: "CSF 2.0 shows only outcomes to achieve and specifies no concrete actions. What is used to supplement the means of implementation?", o: ["SP 800-53 など50以上の文書への情報参照", "組織プロファイルに記述された現在の状態と目標", "六つの機能のうち Govern の下に置かれた手順書", "ISMS の認証審査で得られる是正の指示"], oEn: ["Informative references to more than 50 documents such as SP 800-53", "The current state and target described in an organizational profile", "Procedure manuals placed under the Govern function among the six functions", "Corrective instructions obtained through an ISMS certification audit"], a: 0, e: "CSF は成果を示すだけで、具体的な行動は指定しない。実現手段は SP 800-53 など50以上の文書への情報参照で補う。組織プロファイルは現状と目標の記述で、手段ではない。", eEn: "CSF shows outcomes only. Implementation means are supplemented by informative references to 50+ documents such as SP 800-53. An organizational profile describes current state and target, not means."},
  {d: "IT8", q: "SOC 2 報告の期間終了後から自社の期末までに空白がある。この空白を補うために受け取るのは？", qEn: "There is a gap between the end of a SOC 2 reporting period and your fiscal year end. What do you obtain to cover it?", o: ["監査人が追加で発行する Type I 報告書", "例外事項への回答をまとめた回答書", "利用者側で実施すべき統制の一覧表", "経営者が出すブリッジレター"], oEn: ["A Type I report additionally issued by the auditor", "A written response compiling answers to exceptions", "A list of controls the user entity should implement", "A bridge letter issued by management"], a: 3, e: "SOC 2 の報告期間の終了後から利用者の期末までの空白は、経営者のブリッジレターで補う。Type I は特定時点の設計を対象とし、空白期間の運用を示すものではない。", eEn: "The gap between the end of the SOC 2 period and the user's year end is covered by management's bridge letter. Type I covers design at a point in time, not operation during the gap."},
  {d: "IT8", q: "ISMS 認証・SOC 2 報告書と比べた、ISMAP の位置づけとして正しいのは？", qEn: "Compared with ISMS certification and SOC 2 reports, how is ISMAP positioned?", o: ["前二者は民間の第三者評価で、ISMAP は政府調達用のリスト登録制度", "前二者は政府調達用の登録制度で、ISMAP は民間の第三者評価", "三つとも政府調達のために国が運営するリスト登録制度であり、民間は関与しない", "三つとも民間の第三者評価で、政府調達とは関係がない"], oEn: ["The former two are private third-party evaluations; ISMAP is a list-registration scheme for government procurement", "The former two are government procurement registration schemes; ISMAP is a private third-party evaluation", "All three are registration schemes run by the state for government procurement", "All three are private third-party evaluations unrelated to government procurement"], a: 0, e: "ISMS 認証や SOC 2 報告書が民間の第三者評価なのに対し、ISMAP は政府調達用のリスト登録制度で、登録されたサービスは ISMAP クラウドサービスリストで公開される。", eEn: "ISMS certification and SOC 2 reports are private third-party evaluations, whereas ISMAP is a list-registration scheme for government procurement; registered services appear in the ISMAP cloud service list."},
  {d: "IT8", q: "ISMAP 管理基準が取り込んでいるものとして正しいのは？", qEn: "Which correctly lists what the ISMAP control standard incorporates?", o: ["ISO/IEC 27017、金融分野のガイドライン、CIS Controls", "JIS Q 27000 シリーズ、政府統一基準、NIST SP800-53", "NIST CSF 2.0、個人情報保護法のガイドライン、SOC 2 の基準", "JIS Q 27000 シリーズ、経営ガイドラインの10項目、CIS Benchmarks"], oEn: ["ISO/IEC 27017, the financial sector guideline, CIS Controls", "JIS Q 27000 series, the government unified standards, NIST SP800-53", "NIST CSF 2.0, the Personal Information Protection Act guidelines, SOC 2 criteria", "JIS Q 27000 series, the ten items of the management guidelines, CIS Benchmarks"], a: 1, e: "ISMAP 管理基準は、JIS Q 27000 シリーズ、政府統一基準、NIST SP800-53 を取り込んでいる。事業者はこの基準で統制を構築し、外部監査と IPA の審査を受ける。", eEn: "The ISMAP control standard incorporates the JIS Q 27000 series, the government unified standards and NIST SP800-53. Providers build controls on it and undergo external audit and IPA review."},
  {d: "IT8", q: "個別の技術対策を並べる管理策集ではなく、経営者の責務と指示事項を示す文書はどれか？", qEn: "Which document presents executives' responsibilities and instructions rather than being a collection of controls listing individual technical measures?", o: ["CIS Controls（非営利団体 CIS の管理策群）", "NIST SP 800-53（管理策のカタログ）", "サイバーセキュリティ経営ガイドライン", "CIS Benchmarks（個別製品の設定基準）"], oEn: ["CIS Controls (the control set from the nonprofit CIS)", "NIST SP 800-53 (a catalog of controls)", "Cybersecurity Management Guidelines", "CIS Benchmarks (configuration baselines for individual products)"], a: 2, e: "サイバーセキュリティ経営ガイドラインは、個別の技術対策を並べる CIS Controls などの管理策集ではなく、経営者の責務と指示事項を示す。IPA が実践のためのプラクティス集を別に公開する。", eEn: "The Cybersecurity Management Guidelines present executives' responsibilities and instructions, not a control collection like CIS Controls. IPA publishes a separate practice collection for implementation."},
];
